    $sizes = Read-YesNo 'Include share folder sizes (slow on big shares)?' $false
    $ntfs  = Read-YesNo 'Include NTFS permissions on share roots?' $true
    Invoke-Tool 'Audit-WindowsServers' ([ordered]@{ Servers = $servers; OutputPath = (Get-OutDir 'ServerAudit'); IncludeFolderSize = $sizes; IncludeNTFSPermissions = $ntfs }) | Out-Null
}

function Invoke-GPOAudit {
    Write-Title 'Group Policy audit'
    if (-not (Test-Module 'GroupPolicy')) { return }
    $cs = Get-CimInstance Win32_ComputerSystem
    $domain = Read-Default 'Domain FQDN' $cs.Domain
    $dc = Read-Default 'Specific DC to query (blank = auto)' ''
    Invoke-Tool 'Audit-GPOs' ([ordered]@{ Domain = $domain; Server = $dc; OutputPath = (Get-OutDir 'GPOAudit') }) | Out-Null
}

function Invoke-ADLastLogon {
    Write-Title 'AD users - true last logon (queries every DC)'
    if (-not (Test-Module 'ActiveDirectory')) { return }
    Import-Module ActiveDirectory
    $dcs   = @(Get-ADDomainController -Filter * | Select-Object -ExpandProperty HostName)
    $users = @(Get-ADUser -Filter 'Enabled -eq $true' -Properties LastLogonTimestamp)
    Write-Host "  $($users.Count) enabled users x $($dcs.Count) DC(s)..." -ForegroundColor DarkGray
    $i = 0
    $rows = foreach ($u in $users) {
        $i++; Write-Progress -Activity 'Querying last logon' -Status $u.SamAccountName -PercentComplete (($i / $users.Count) * 100)
        $t = [int64]$u.LastLogonTimestamp
        foreach ($dc in $dcs) {
            $l = (Get-ADUser $u.SamAccountName -Server $dc -Properties lastLogon -ErrorAction SilentlyContinue).lastLogon
            if ([int64]$l -gt $t) { $t = [int64]$l }
        }
        [pscustomobject]@{
            Name           = $u.Name
            SamAccountName = $u.SamAccountName
            LastLogon      = if ($t -gt 0) { [DateTime]::FromFileTime($t).ToString('yyyy-MM-dd HH:mm') } else { 'Never' }
        }
    }
    Write-Progress -Activity 'Querying last logon' -Completed
    $out = Join-Path (Get-OutDir 'AD') "ADUsersLastLogon_$(Get-Stamp).csv"
    $rows | Sort-Object LastLogon | Export-Csv -Path $out -NoTypeInformation
    $rows | Sort-Object LastLogon | Select-Object -First 25 | Format-Table -AutoSize
    Write-Host "  Full list ($($rows.Count) users) saved to $out" -ForegroundColor Green
}

function Invoke-BitLockerExport {
    Write-Title 'Export BitLocker recovery keys from AD'
    if (-not (Test-Module 'ActiveDirectory')) { return }
    $ou  = Read-Default 'Limit to OU distinguished name (blank = whole domain)' ''
    $out = Join-Path (Get-OutDir 'AD') "BitLockerKeys_$(Get-Stamp).csv"
    Invoke-Tool 'Export-Bitlockerkeys' ([ordered]@{ OutputPath = $out; OU = $ou }) | Out-Null
    Write-Host '  Treat this file as a secret - move it somewhere secure and delete it from this machine.' -ForegroundColor Yellow
}

function Invoke-LAPSExport {
    Write-Title 'Export LAPS passwords from AD'
    $out = Join-Path (Get-OutDir 'AD') "LAPS_$(Get-Stamp).csv"
    # Windows LAPS (2023+) stores passwords differently - use its own cmdlet when present.
    if (Get-Command Get-LapsADPassword -ErrorAction SilentlyContinue) {
        Write-Host '  Windows LAPS module found - checking Windows LAPS passwords first...' -ForegroundColor DarkGray
        try {
            $wl = Get-ADComputer -Filter * -ErrorAction Stop | ForEach-Object { Get-LapsADPassword -Identity $_.Name -AsPlainText -ErrorAction SilentlyContinue } | Where-Object { $_ }
            if ($wl) {
                $wl | Select-Object ComputerName, Account, Password, PasswordUpdateTime, ExpirationTimestamp | Export-Csv ($out -replace '\.csv$','_WindowsLAPS.csv') -NoTypeInformation
                Write-Host "  Windows LAPS: $(@($wl).Count) entries saved to $($out -replace '\.csv$','_WindowsLAPS.csv')" -ForegroundColor Green
            }
        } catch { Write-Host "  Windows LAPS query failed: $($_.Exception.Message)" -ForegroundColor DarkYellow }
    }
    Write-Host '  Checking legacy (Microsoft LAPS / ms-Mcs-AdmPwd) passwords...' -ForegroundColor DarkGray
    $q = "'" + ($out -replace "'", "''") + "'"
    Invoke-Tool 'Get-LAPSPasswords' @{} -Wrapper (". {0}; `$r = Get-LAPSPasswords; `$r | Format-Table -AutoSize; `$r | Export-Csv -Path $q -NoTypeInformation; Write-Host ('Saved to ' + $q) -ForegroundColor Green") | Out-Null
    Write-Host '  Treat these files as secrets - move them somewhere secure and delete them from this machine.' -ForegroundColor Yellow
}

function Invoke-ADSyncStatus {
    Write-Title 'Azure AD Connect / Entra Connect Sync (ADSync) status'
    $svc = Get-Service -Name ADSync -ErrorAction SilentlyContinue
    if (-not $svc) { Write-Host '  ADSync service is not installed on this machine.' -ForegroundColor DarkYellow; return }
    $svc | Format-Table Name, DisplayName, Status, StartType -AutoSize
    if ($svc.Status -ne 'Running') { Write-Host '  ADSync is NOT running.' -ForegroundColor Red }
    try {
        Import-Module ADSync -ErrorAction Stop
        Write-Sub 'Sync scheduler'
        Get-ADSyncScheduler | Format-List SyncCycleEnabled, SchedulerSuspended, SyncCycleInProgress, CurrentlyEffectiveSyncCycleInterval, NextSyncCycleStartTimeInUTC, StagingModeEnabled
        if (Get-Command Get-ADSyncRunProfileResult -ErrorAction SilentlyContinue) {
            Write-Sub 'Last 10 run profile results'
            Get-ADSyncRunProfileResult -NumberRequested 10 | Select-Object StartDate, EndDate, ConnectorName, RunProfileName, Result | Format-Table -AutoSize
        }
    } catch { Write-Host "  ADSync module not available: $($_.Exception.Message)" -ForegroundColor DarkYellow }
    Write-Sub 'ADSync errors in the Application log - last 3 days'
    Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'ADSync','Directory Synchronization'; Level = 1,2; StartTime = (Get-Date).AddDays(-3) } -MaxEvents 15 -ErrorAction SilentlyContinue |
        Select-Object TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
    Invoke-ADSyncRestart
}

function Invoke-AclExport {
    Write-Title 'Folder permissions (ACL) export'
    $folder = Read-Default 'Folder or share to report on (subfolders one level down)' ''
    if (-not $folder -or -not (Test-Path -LiteralPath $folder)) { Write-Host '  Path not found.' -ForegroundColor Red; return }
    $withSize = Read-YesNo 'Calculate folder sizes too (slow on big shares)?' $false
    $outDir = Get-OutDir 'Permissions'
    $stamp = Get-Stamp
    $out = Join-Path $outDir "PermissionExport_$stamp.csv"
    $errLog = Join-Path $outDir "AccessDenied_$stamp.txt"
    $Error.Clear()
    $folders = @(Get-Item -LiteralPath $folder) + @(Get-ChildItem -LiteralPath $folder -Directory -ErrorAction SilentlyContinue)
    $results = foreach ($f in $folders) {
        $size = if ($withSize) { [math]::Round(((Get-ChildItem -LiteralPath $f.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum)/1MB, 2) } else { $null }
        $acl = Get-Acl -LiteralPath $f.FullName -ErrorAction SilentlyContinue
        foreach ($a in $acl.Access) {
            $id = $a.IdentityReference.ToString()
            if ($id -in 'BUILTIN\Administrators','CREATOR OWNER','NT AUTHORITY\SYSTEM' -or $id -like 'S-1-*' -or "$($a.FileSystemRights)" -like '-*' -or "$($a.FileSystemRights)" -eq '268435456') { continue }
            [pscustomobject]@{
                FolderName = $f.Name; FolderPath = $f.FullName; IdentityReference = $id; SizeMB = $size
                Permissions = $a.FileSystemRights; AccessControlType = $a.AccessControlType; IsInherited = $a.IsInherited
            }
        }
    }
    $results | Export-Csv -Path $out -NoTypeInformation
    if ($Error.Count) { $Error | ForEach-Object { $_.Exception.Message } | Out-File $errLog; Write-Host "  Access-denied paths logged to $errLog" -ForegroundColor DarkYellow }
    $results | Where-Object { -not $_.IsInherited } | Format-Table FolderName, IdentityReference, Permissions, AccessControlType -AutoSize
    Write-Host "  $(@($results).Count) ACL entries saved to $out (table above shows only explicit, non-inherited entries)." -ForegroundColor Green
}

function Invoke-IllegalNameCheck {
    Write-Title 'SharePoint / OneDrive migration - file & folder name check'
    $path = Read-Default 'Folder or UNC share to scan' ''
    if (-not $path -or -not (Test-Path -LiteralPath $path)) { Write-Host '  Path not found.' -ForegroundColor Red; return }
    $prefix = Read-Default 'Destination URL prefix length to allow for (characters)' 80
    Write-Host '  Scanning...' -ForegroundColor DarkGray
    $illegal = '[~"#%&*:<>?/\\{|}]'
    $items = Get-ChildItem -LiteralPath $path -Recurse -Force -ErrorAction SilentlyContinue
    $issues = foreach ($i in $items) {
        $problems = @()
        $m = [regex]::Matches($i.Name, $illegal) | ForEach-Object { $_.Value } | Select-Object -Unique
        if ($m) { $problems += "Illegal character(s): $($m -join ' ')" }
        if ($i.Name.StartsWith('.')) { $problems += 'Starts with a period' }
        if ($i.Name.EndsWith('.'))   { $problems += 'Ends with a period' }
        if ($i.Name.Contains('..'))  { $problems += 'Contains double periods' }
        if ($i.Name -ne $i.Name.Trim()) { $problems += 'Leading/trailing space' }
        if ($i.Name -match '^(CON|PRN|AUX|NUL|COM\d|LPT\d|_vti_|desktop\.ini)$' -or $i.Name -like '~$*') { $problems += 'Reserved/blocked name' }
        $rel = $i.FullName.Substring($path.TrimEnd('\').Length)
        if (-not $i.PSIsContainer -and $i.Extension -match '^\.(qbw|qbb|qbm|qbo|tlg|nd|dsn|mdb|accdb|ldb|laccdb|pst|ost|mdf|ldf|vhd|vhdx)$') { $problems += "Database/live-data file ($($i.Extension)) - don't sync via SharePoint/OneDrive; keep on a file share" }
        if (-not $i.PSIsContainer -and $i.Length -gt 250GB) { $problems += 'Larger than 250 GB (SharePoint limit)' }
        if (($rel.Length + [int]$prefix) -gt 400) { $problems += "Path too long (~$($rel.Length + [int]$prefix) of 400 chars)" }
        if ($problems) {
            [pscustomobject]@{ Type = $(if ($i.PSIsContainer) { 'Folder' } else { 'File' }); Name = $i.Name; Path = $i.FullName; Issues = $problems -join '; '; Item = $i }
        }
    }
    $out = Join-Path (Get-OutDir 'SharePointMigration') "NameIssues_$(Get-Stamp).csv"
    $issues | Select-Object Type, Name, Path, Issues | Export-Csv -Path $out -NoTypeInformation
    Write-Host "  Scanned $(@($items).Count) items - $(@($issues).Count) with issues. Report: $out" -ForegroundColor $(if ($issues) { 'Yellow' } else { 'Green' })
    $issues | Select-Object -First 30 Type, Name, Issues | Format-Table -AutoSize -Wrap

    $blk = @($issues | Where-Object { $_.Issues -match 'Database/live-data' })
    if ($blk) { Write-Host "`n  $($blk.Count) database/QuickBooks/Access/PST files found - migration blockers, see the CSV." -ForegroundColor Yellow }
    $fixable = @($issues | Where-Object { $_.Issues -match 'Illegal character|period' })
    if ($fixable.Count -and (Read-YesNo "Auto-rename $($fixable.Count) item(s)? (& -> and, { } -> ( ), ~ -> -, # % removed, stray periods trimmed)" $false)) {
        if (-not (Confirm-Change "Rename $($fixable.Count) files/folders under $path")) { return }
        $renLog = Join-Path (Get-OutDir 'SharePointMigration') "Renamed_$(Get-Stamp).csv"
        # Deepest paths first so renaming a folder never invalidates a child path still to be processed
        foreach ($f in ($fixable | Sort-Object { $_.Path.Length } -Descending)) {
            $n = $f.Name -replace '&','and' -replace '\{','(' -replace '\}',')' -replace '~','-' -replace '[#%]',''
            while ($n.Contains('..')) { $n = $n.Replace('..','.') }
            $n = $n.Trim().TrimStart('.').TrimEnd('.')
            if ($n -and $n -ne $f.Name) {
                try {
                    Rename-Item -LiteralPath $f.Path -NewName $n -ErrorAction Stop
                    [pscustomobject]@{ OldPath = $f.Path; NewName = $n; Result = 'Renamed' } | Export-Csv $renLog -NoTypeInformation -Append
                } catch {
                    [pscustomobject]@{ OldPath = $f.Path; NewName = $n; Result = $_.Exception.Message } | Export-Csv $renLog -NoTypeInformation -Append
                }
            }
        }
        Write-Host "  Rename log: $renLog" -ForegroundColor Green
    }
}

