function Invoke-NCentralHunt {
    Write-Title 'N-central compromise IOC hunt (Take Control / cloudflared / svchost-in-Documents / IOC IPs)'
    $days = Read-Int 'Flag services created in the last N days' 14
    Invoke-Tool 'Hunt-NCentralCompromise' ([ordered]@{ OutputPath = (Get-OutDir 'NCentralHunt'); RecentServiceDays = $days }) | Out-Null
}

function Invoke-TakeControlDiag {
    Write-Title 'N-able Take Control / agent service diagnostics'
    $target = Read-Default 'Computer to check' $env:COMPUTERNAME
    $like   = Read-Default 'Service name/display name filter' '*Take Control*'
    $ncHost = Read-Default 'N-central server hostname to test port 443 against' 'www.n-able.com'
    $remote = $target -ne $env:COMPUTERNAME -and $target -notin 'localhost','.'
    $ic = @{}
    if ($remote) {
        $ic.ComputerName = $target
        if (Read-YesNo "Use different credentials for $target?" $false) { $ic.Credential = Get-Credential -Message "Admin on $target" }
    }
    $sb = {
        param($like, $ncHost)
        Write-Host '== Service registration ==' -ForegroundColor Cyan
        $svcs = Get-CimInstance Win32_Service | Where-Object { $_.Name -like $like -or $_.DisplayName -like $like }
        if (-not $svcs) { Write-Warning "No service matches '$like'." }
        $svcs | Select-Object Name, DisplayName, State, StartMode, StartName, PathName | Format-List | Out-String | Write-Host
        Write-Host '== Binary present / install folder ==' -ForegroundColor Cyan
        $svc = $svcs | Select-Object -First 1
        if ($svc -and $svc.PathName) {
            $exe = ($svc.PathName -replace '^"?([^"]+\.exe)"?.*$', '$1')
            if (Test-Path $exe) {
                Get-Item $exe | Select-Object FullName, Length, LastWriteTime, @{n='Version';e={$_.VersionInfo.FileVersion}} | Format-List | Out-String | Write-Host
                Get-ChildItem (Split-Path $exe) | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize | Out-String | Write-Host
            } else { Write-Warning "Binary not found at '$exe' - install is incomplete/corrupt; reinstall." }
        }
        Write-Host '== Application crashes (Event 1000) ==' -ForegroundColor Cyan
        Get-WinEvent -FilterHashtable @{ LogName = 'Application'; Id = 1000 } -MaxEvents 200 -ErrorAction SilentlyContinue |
            Where-Object { $_.Message -match 'TakeControl|N-able|N-central|BASup|MspPlatform|agent\.exe' } |
            Select-Object -First 10 TimeCreated, @{n='Message';e={$_.Message.Substring(0,[Math]::Min(400,$_.Message.Length))}} | Format-List | Out-String | Write-Host
        Write-Host '== Service Control Manager events ==' -ForegroundColor Cyan
        Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Service Control Manager' } -MaxEvents 300 -ErrorAction SilentlyContinue |
            Where-Object { $_.Message -match 'Take Control|N-central|N-able|Windows Agent' } |
            Select-Object -First 10 TimeCreated, Id, Message | Format-Table -Wrap | Out-String | Write-Host
        Write-Host '== WER crash reports ==' -ForegroundColor Cyan
        Get-ChildItem "$env:ProgramData\Microsoft\Windows\WER\ReportQueue", "$env:ProgramData\Microsoft\Windows\WER\ReportArchive" -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match 'TakeControl|BASup|N-central|agent' } | Select-Object Name, LastWriteTime | Format-Table -AutoSize | Out-String | Write-Host
        Write-Host "== Outbound 443 to $ncHost ==" -ForegroundColor Cyan
        Test-NetConnection -ComputerName $ncHost -Port 443 -WarningAction SilentlyContinue | Select-Object ComputerName, RemoteAddress, TcpTestSucceeded | Format-Table -AutoSize | Out-String | Write-Host
    }
    if ($remote) { Invoke-Command @ic -ScriptBlock $sb -ArgumentList $like, $ncHost }
    else         { & $sb $like $ncHost }
}

