function Invoke-DotNetVersion {
    Write-Title 'Runtime versions'
    $release = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -Name Release -ErrorAction SilentlyContinue).Release
    $version = switch ($release) {
        { $_ -ge 533320 } { '4.8.1 or later'; break }
        { $_ -ge 528040 } { '4.8'; break }
        { $_ -ge 461808 } { '4.7.2'; break }
        { $_ -ge 461308 } { '4.7.1'; break }
        { $_ -ge 460798 } { '4.7'; break }
        { $_ -ge 394802 } { '4.6.2'; break }
        { $_ -ge 394254 } { '4.6.1'; break }
        { $_ -ge 393295 } { '4.6'; break }
        { $_ -ge 379893 } { '4.5.2'; break }
        { $_ -ge 378675 } { '4.5.1'; break }
        { $_ -ge 378389 } { '4.5'; break }
        default { $null }
    }
    if ($version) { Write-Host "  .NET Framework 4.x: $version (release $release)" -ForegroundColor Green }
    else { Write-Host '  .NET Framework 4.5 or later is not detected.' -ForegroundColor Yellow }
    $v35 = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v3.5' -Name Install -ErrorAction SilentlyContinue).Install
    Write-Host "  .NET Framework 3.5: $(if ($v35 -eq 1) { 'installed' } else { 'not installed' })"
    if (Get-Command dotnet -ErrorAction SilentlyContinue) {
        Write-Sub '.NET (Core) runtimes'
        dotnet --list-runtimes
    }
    Write-Sub 'Other runtimes (Node.js, Java, Python) - apps pinned to old versions break when these self-update'
    foreach ($c in @(@{N='Node.js';C='node';A='--version'}, @{N='npm';C='npm.cmd';A='--version'}, @{N='Java';C='java';A='-version'}, @{N='Python';C='python';A='--version'})) {
        $cmd = Get-Command $c.C -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($cmd) { $v = (& $cmd.Source $c.A 2>&1 | Select-Object -First 1); Write-Host ("  {0,-8} {1}  ({2})" -f $c.N, $v, $cmd.Source) }
        else { Write-Host ("  {0,-8} not found on PATH" -f $c.N) -ForegroundColor DarkGray }
    }
    Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -match '^(Node\.js|Java|Python|Microsoft Visual C\+\+)' } |
        Select-Object DisplayName, DisplayVersion, InstallDate | Sort-Object DisplayName | Format-Table -AutoSize
}

function Invoke-CitrixState {
    Write-Title 'Citrix Workspace app - install state'
    Write-Sub 'reg.exe: HKLM\SOFTWARE\Citrix'
    reg query "HKLM\SOFTWARE\Citrix" 2>&1 | Write-Host
    Write-Sub 'reg.exe: HKLM\SOFTWARE\WOW6432Node\Citrix'
    reg query "HKLM\SOFTWARE\WOW6432Node\Citrix" 2>&1 | Write-Host
    Write-Sub 'Installed programs matching Citrix'
    Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -like '*Citrix*' } | Select-Object DisplayName, DisplayVersion, InstallDate | Format-Table -AutoSize
    Write-Sub 'Running Citrix processes'
    Get-Process | Where-Object { $_.ProcessName -match 'SelfService|Receiver|CitrixWorkspace|wfcrun32|wfica32|AuthManSvr' } | Select-Object ProcessName, Id, Path | Format-Table -AutoSize
    Write-Sub 'Citrix services'
    Get-Service | Where-Object { $_.DisplayName -like '*Citrix*' -or $_.Name -like '*Citrix*' } | Select-Object Name, DisplayName, Status | Format-Table -AutoSize
}

