    }
}

function Invoke-WUDriverBlock {
    Write-Title 'Windows Update driver updates - block / allow'
    $wuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
    $dsKey = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching'
    $mdKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DriverSearching'
    $cur = [pscustomobject]@{
        ExcludeWUDriversInQualityUpdate = (Get-ItemProperty $wuKey -ErrorAction SilentlyContinue).ExcludeWUDriversInQualityUpdate
        SearchOrderConfig               = (Get-ItemProperty $dsKey -ErrorAction SilentlyContinue).SearchOrderConfig
        DontSearchWindowsUpdate_Policy  = (Get-ItemProperty $mdKey -ErrorAction SilentlyContinue).DontSearchWindowsUpdate
    }
    Write-Sub 'Current settings (1 / 0 / 1 = drivers blocked)'
    $cur | Format-List
    Write-Sub 'Drivers installed by Windows Update (last 60 days)'
    try {
        $s = (New-Object -ComObject Microsoft.Update.Session).CreateUpdateSearcher()
        $n = $s.GetTotalHistoryCount()
        if ($n -gt 0) { $s.QueryHistory(0, [math]::Min($n, 300)) | Where-Object { $_.Date -ge (Get-Date).AddDays(-60) -and $_.Title -match 'Driver|Firmware' } |
            Select-Object @{n='Date';e={$_.Date.ToLocalTime()}}, Title | Format-Table -AutoSize -Wrap }
    } catch { Write-Host '  Could not read Windows Update history.' -ForegroundColor DarkGray }
    $mode = (Read-Default '  B = block driver updates, A = allow again, blank = no change' '').ToString().ToUpper()
    if ($mode -eq 'B') {
        if (-not (Confirm-Change 'Stop Windows Update and automatic device installs from downloading drivers (OEM tools like Dell Command Update still work).')) { return }
        foreach ($k in $wuKey, $dsKey, $mdKey) { if (-not (Test-Path $k)) { New-Item $k -Force | Out-Null } }
        Set-ItemProperty $wuKey -Name ExcludeWUDriversInQualityUpdate -Value 1 -Type DWord
        Set-ItemProperty $dsKey -Name SearchOrderConfig -Value 0 -Type DWord
        Set-ItemProperty $mdKey -Name DontSearchWindowsUpdate -Value 1 -Type DWord
        Write-Host '  Driver updates from Windows Update are now BLOCKED. Install drivers with the OEM tool (Dell Command Update, Lenovo Vantage, HP Image Assistant).' -ForegroundColor Green
        Write-Host '  Note: an RMM/Intune/GPO policy can override these values - set it there too for a permanent fleet setting.' -ForegroundColor DarkYellow
    } elseif ($mode -eq 'A') {
        if (-not (Confirm-Change 'Allow Windows Update to install drivers again.')) { return }
        Remove-ItemProperty $wuKey -Name ExcludeWUDriversInQualityUpdate -ErrorAction SilentlyContinue
        Set-ItemProperty $dsKey -Name SearchOrderConfig -Value 1 -Type DWord -ErrorAction SilentlyContinue
        Remove-ItemProperty $mdKey -Name DontSearchWindowsUpdate -ErrorAction SilentlyContinue
        Write-Host '  Windows Update driver updates ALLOWED again.' -ForegroundColor Green
    } else { Write-Host '  No change made.' -ForegroundColor DarkGray }
}

function Invoke-PowerSettings {
    Write-Title '[!] Power settings - never sleep / hibernate / turn off display or disks'
    Write-Host '  Current active scheme:'; powercfg /getactivescheme
    if (-not (Confirm-Change 'Set sleep, hibernate, monitor and disk timeouts to Never (AC + battery) and disable USB selective suspend.')) { return }
    $gpu = Join-Path $env:SystemRoot 'System32\GroupPolicyUsers'
    if ((Test-Path $gpu) -and (Read-YesNo "Also reset LOCAL per-user group policy ($gpu) and run gpupdate? (clears local policies that can force sleep settings)" $false)) {
        Remove-Item -LiteralPath $gpu -Recurse -Force -ErrorAction SilentlyContinue
        gpupdate /force
    }
    # USB selective suspend = disabled
    powercfg -setacvalueindex SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0
    powercfg -setdcvalueindex SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0
    # Lid/power-button related setting from the original script (sub group 4f971e89 / setting 5ca83367 = Lid close action -> Do nothing)
    powercfg -setdcvalueindex SCHEME_CURRENT 4f971e89-eebd-4455-a8de-9e59040e7347 5ca83367-6e45-459f-a27b-476b1d01c936 0
    powercfg -setacvalueindex SCHEME_CURRENT 4f971e89-eebd-4455-a8de-9e59040e7347 5ca83367-6e45-459f-a27b-476b1d01c936 0
    foreach ($x in 'standby-timeout','hibernate-timeout','monitor-timeout','disk-timeout') {
        powercfg /change "$x-ac" 0
        powercfg /change "$x-dc" 0
    }
    powercfg /setactive SCHEME_CURRENT
    Write-Host '  Done.' -ForegroundColor Green
}


# ---------- Added from past troubleshooting -------------------------------------

function Invoke-DeviceJoinStatus {
    Write-Title 'Device join / Entra ID / Workplace join status (dsregcmd)'
    $raw = dsregcmd /status 2>&1
    $get = { param($k) ($raw | Where-Object { $_ -match "^\s*$k\s*:" } | Select-Object -First 1) -replace '^\s*[^:]+:\s*', '' }
    $s = [ordered]@{
        AzureAdJoined     = & $get 'AzureAdJoined'
        DomainJoined      = & $get 'DomainJoined'
        DomainName        = & $get 'DomainName'
        WorkplaceJoined   = & $get 'WorkplaceJoined'
        EnterpriseJoined  = & $get 'EnterpriseJoined'
        TenantName        = & $get 'TenantName'
        TenantId          = & $get 'TenantId'
        MdmUrl            = & $get 'MdmUrl'
        AzureAdPrt        = & $get 'AzureAdPrt'
        NgcSet            = & $get 'NgcSet'
        WorkplaceTenant   = & $get 'WorkplaceTenantName'
    }
    [pscustomobject]$s | Format-List
    Write-Sub 'Signed-in Windows account type'
    $u = (Get-CimInstance Win32_ComputerSystem).UserName
    Write-Host "  Console user: $u"
    $msa = Get-ChildItem 'HKCU:\Software\Microsoft\IdentityCRL\StoredIdentities' -ErrorAction SilentlyContinue | Select-Object -ExpandProperty PSChildName
    if ($msa) { Write-Host "  Microsoft (personal) account(s) stored for this user: $($msa -join ', ')" -ForegroundColor Yellow }
    Write-Sub 'Findings'
    $found = $false
    if ($s.WorkplaceJoined -eq 'YES' -and $s.AzureAdJoined -ne 'YES') {
        Write-Host '  * Workplace-joined (registered) but NOT Entra-joined - a stray "Access work or school" registration.' -ForegroundColor Yellow
        Write-Host '    Common cause of broken Windows Hello PIN ("isn''t working for your organization''s resources").' -ForegroundColor Yellow
        Write-Host '    Fix: Settings > Accounts > Access work or school > Disconnect (or proper Entra join).' -ForegroundColor Yellow
        $found = $true
    }
    if ($s.AzureAdJoined -eq 'YES' -and $s.AzureAdPrt -ne 'YES') { Write-Host '  * Entra-joined but no Primary Refresh Token - SSO to M365 will prompt / fail. Check time sync, network to login.microsoftonline.com, user sign-out/in.' -ForegroundColor Yellow; $found = $true }
    if ($s.AzureAdJoined -eq 'YES' -and -not $s.MdmUrl) { Write-Host '  * Entra-joined but no MDM URL - device is not Intune-enrolled.' -ForegroundColor Yellow; $found = $true }
    if ($msa) { Write-Host '  * A personal Microsoft account is stored on this profile - check it isn''t shared with another device/user.' -ForegroundColor Yellow; $found = $true }
    if (-not $found) { Write-Host '  Nothing unusual.' -ForegroundColor Green }
    $task = Get-ScheduledTask -TaskName 'Automatic-Device-Join' -TaskPath '\Microsoft\Windows\Workplace Join\' -ErrorAction SilentlyContinue
    if ($task) { $ti = $task | Get-ScheduledTaskInfo; Write-Host ("  Hybrid join task (Automatic-Device-Join): state {0}, last run {1}, result 0x{2:X}" -f $task.State, $ti.LastRunTime, $ti.LastTaskResult) -ForegroundColor DarkGray }
    if ($s.DomainJoined -eq 'YES' -and $s.AzureAdJoined -ne 'YES') { Write-Host '  * Domain joined but NOT hybrid Entra joined - use "Force a Hybrid Entra ID join attempt" in the M365 section.' -ForegroundColor Yellow }
    $out = Join-Path (Get-OutDir 'Identity') "dsregcmd_$(Get-Stamp).txt"
    $raw | Out-File $out
    Write-Host "  Full dsregcmd output: $out" -ForegroundColor DarkGray
}

function Invoke-EventLogBloat {
    Write-Title 'Event log size / archived log (Archive-*.evtx) bloat check'
    $dir = Join-Path $env:SystemRoot 'System32\winevt\Logs'
    $files = Get-ChildItem $dir -File -Force -ErrorAction SilentlyContinue
    $total = ($files | Measure-Object Length -Sum).Sum
    $arch  = @($files | Where-Object Name -like 'Archive-*.evtx')
    $archSum = ($arch | Measure-Object Length -Sum).Sum
    Write-Host ("  {0}: {1:N2} GB in {2} files" -f $dir, ($total/1GB), $files.Count)
    Write-Host ("  Archived logs (Archive-*.evtx): {0} files, {1:N2} GB" -f $arch.Count, ($archSum/1GB)) -ForegroundColor $(if ($archSum -gt 1GB) { 'Yellow' } else { 'Green' })
    if ($arch) {
        $arch | Group-Object { ($_.Name -replace '^Archive-(.+)-\d{4}-\d{2}-\d{2}.*$', '$1') } |
            Select-Object @{n='Log';e={$_.Name}}, Count, @{n='GB';e={[math]::Round((($_.Group | Measure-Object Length -Sum).Sum)/1GB,2)}},
                @{n='Oldest';e={($_.Group | Sort-Object LastWriteTime | Select-Object -First 1).LastWriteTime}},
                @{n='Newest';e={($_.Group | Sort-Object LastWriteTime | Select-Object -Last 1).LastWriteTime}} | Format-Table -AutoSize
    }
    Write-Sub 'Logs set to auto-archive (AutoBackupLogFiles = 1)'
    $auto = Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services\EventLog' -ErrorAction SilentlyContinue | ForEach-Object {
        $v = (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).AutoBackupLogFiles
        if ($v -eq 1) { $_.PSChildName }
    }
    if ($auto) { Write-Host "  $($auto -join ', ')" -ForegroundColor Yellow } else { Write-Host '  None.' -ForegroundColor Green }
    Write-Sub 'Largest live logs'
    Get-WinEvent -ListLog * -ErrorAction SilentlyContinue | Sort-Object FileSize -Descending | Select-Object -First 10 LogName, LogMode,
        @{n='SizeMB';e={[math]::Round($_.FileSize/1MB)}}, @{n='MaxMB';e={[math]::Round($_.MaximumSizeInBytes/1MB)}}, RecordCount | Format-Table -AutoSize
    Write-Host '  Tip: top writers of the Application log are listed by menu option "Export event logs".' -ForegroundColor DarkGray

    if ($arch -and (Read-YesNo 'Delete archived logs older than N days?' $false)) {
        $days = Read-Int 'Keep archives newer than (days)' 30
        $old = $arch | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-$days) }
        $gb = [math]::Round((($old | Measure-Object Length -Sum).Sum)/1GB, 2)
        if ($old -and (Confirm-Change "Delete $(@($old).Count) archived .evtx files ($gb GB) older than $days days. Consider exporting first if you need them for an investigation.")) {
            $old | Remove-Item -Force -ErrorAction SilentlyContinue
            Write-Host "  Deleted. Freed about $gb GB." -ForegroundColor Green
        }
    }
    if ($auto -and (Read-YesNo 'Switch auto-archiving logs back to overwrite-as-needed (stops new Archive files)?' $false)) {
        if (Confirm-Change "Set AutoBackupLogFiles=0 and Retention=0 (overwrite) on: $($auto -join ', ')") {
            foreach ($l in $auto) {
                Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\EventLog\$l" -Name AutoBackupLogFiles -Value 0 -Type DWord
                wevtutil sl "$l" /rt:false /ab:false 2>$null
                Write-Host "  $l -> overwrite as needed" -ForegroundColor Green
            }
        }
    }
}

function Invoke-HVIntegrationServices {
    Write-Title 'Hyper-V HOST: integration services check / enable'
    if (-not (Get-Command Get-VMIntegrationService -ErrorAction SilentlyContinue)) { Write-Host '  Hyper-V module not found - run on the Hyper-V HOST.' -ForegroundColor Red; return }
    $all = Get-VM | ForEach-Object { Get-VMIntegrationService -VM $_ } |
        Select-Object VMName, Name, Enabled, PrimaryStatusDescription, SecondaryStatusDescription
    $all | Sort-Object VMName, Name | Format-Table -AutoSize
    $off = @($all | Where-Object { -not $_.Enabled -and $_.Name -notmatch 'Guest Service Interface' })
    if (-not $off) { Write-Host '  All core integration services are enabled on every VM.' -ForegroundColor Green; return }
    Write-Host "  $($off.Count) disabled service(s) found. Disabled Time Synchronization / VSS / Heartbeat are a known cause" -ForegroundColor Yellow
    Write-Host '  of overnight guest hangs during host backups, and of the host reporting the VM as unresponsive.' -ForegroundColor Yellow
    if (Confirm-Change ("Enable: " + (($off | ForEach-Object { "$($_.VMName)/$($_.Name)" }) -join ', '))) {
        foreach ($o in $off) {
            try { Enable-VMIntegrationService -VMName $o.VMName -Name $o.Name -ErrorAction Stop; Write-Host "  Enabled $($o.VMName) / $($o.Name)" -ForegroundColor Green }
            catch { Write-Host "  Failed $($o.VMName) / $($o.Name): $($_.Exception.Message)" -ForegroundColor Red }
        }
        Write-Host '  Inside each guest, confirm vmictimesync / vmicvss / vmicheartbeat services are running.' -ForegroundColor DarkGray
    }
}

function Invoke-SmtpTest {
    Write-Title 'SMTP / scan-to-email relay test (+ SPF / DMARC / MX lookup)'
    $server = Read-Default 'SMTP server (e.g. smtp.office365.com, <tenant>-com.mail.protection.outlook.com, your relay)' ''
    if (-not $server) { return }
    $port = Read-Int 'Port' 25
    Write-Sub "TCP $port to $server"
    $tnc = Test-NetConnection -ComputerName $server -Port $port -WarningAction SilentlyContinue
    $tnc | Select-Object ComputerName, RemoteAddress, SourceAddress, TcpTestSucceeded | Format-Table -AutoSize
    try { $pub = (Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec 8); Write-Host "  This site's public IP (what SPF / connectors must allow): $pub" -ForegroundColor Cyan } catch { }
    $from = Read-Default 'From address (blank = skip sending a test message)' ''
    if ($from) {
        $domain = $from.Split('@')[-1]
        Write-Sub "DNS for $domain"
        $mx = Resolve-DnsName -Name $domain -Type MX -ErrorAction SilentlyContinue | Where-Object Type -eq 'MX'
        $mx | Select-Object NameExchange, Preference | Format-Table -AutoSize
        $spf = (Resolve-DnsName -Name $domain -Type TXT -ErrorAction SilentlyContinue | Where-Object { $_.Strings -match '^v=spf1' }).Strings -join ''
        $dmarc = (Resolve-DnsName -Name "_dmarc.$domain" -Type TXT -ErrorAction SilentlyContinue).Strings -join ''
        Write-Host "  SPF:   $(if ($spf) { $spf } else { 'NONE' })"
        Write-Host "  DMARC: $(if ($dmarc) { $dmarc } else { 'NONE' })"
        if ($pub -and $spf -and $spf -notmatch [regex]::Escape($pub) -and $spf -notmatch 'include:') { Write-Host "  SPF does not list $pub - mail sent directly from this site may fail SPF/DMARC (quarantine)." -ForegroundColor Yellow }

        $to = Read-Default 'To address' ''
        if ($to) {
            $ssl  = Read-YesNo 'Use STARTTLS/SSL?' ($port -eq 587)
            $auth = Read-YesNo 'Authenticate (username/password)?' ($port -eq 587)
            try {
                $msg = New-Object System.Net.Mail.MailMessage($from, $to, "SMTP test from $env:COMPUTERNAME", "Test sent by the Sigma Data Systems INC ToolKit at $(Get-Date) from $env:COMPUTERNAME ($pub) via ${server}:$port.")
                $smtp = New-Object System.Net.Mail.SmtpClient($server, $port)
                $smtp.EnableSsl = $ssl
                if ($auth) { $smtp.UseDefaultCredentials = $false; $smtp.Credentials = (Get-Credential -Message "SMTP login for $server").GetNetworkCredential() }
                $smtp.Send($msg)
                Write-Host "  SUCCESS - accepted by $server. If it never arrives, check the recipient's quarantine (SPF/DMARC) and spam." -ForegroundColor Green
            } catch {
                Write-Host "  FAILED: $($_.Exception.InnerException.Message) $($_.Exception.Message)" -ForegroundColor Red
            }
        }
    }
}

function Invoke-ZipBrowserRepair {
    Write-Title '[!] Repair .zip association / reset default browser'
    $cu = (Get-CimInstance Win32_ComputerSystem).UserName
    if ($cu -and $cu -ne "$env:USERDOMAIN\$env:USERNAME") {
        Write-Host "  NOTE: these are per-user settings. You are running as $env:USERDOMAIN\$env:USERNAME but the console user is $cu." -ForegroundColor Yellow
        Write-Host '  Run the toolkit inside the affected user''s session for the HKCU part to apply to them.' -ForegroundColor Yellow
    }
    if (Read-YesNo 'Repair .zip files (re-register zipfldr.dll, clear broken UserChoice, reset to Compressed Folder)?' $true) {
        if (Confirm-Change 'Reset the .zip file association for the current user.') {
            Start-Process regsvr32.exe -ArgumentList '/s zipfldr.dll' -Wait -NoNewWindow
            $uc = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts\.zip\UserChoice'
            if (Test-Path $uc) { Remove-Item $uc -Recurse -Force -ErrorAction SilentlyContinue; Write-Host '  Removed UserChoice override.' -ForegroundColor Green }
            New-Item 'HKCU:\Software\Classes\.zip' -Force | Out-Null
            Set-ItemProperty 'HKCU:\Software\Classes\.zip' -Name '(default)' -Value 'CompressedFolder'
            Write-Host '  .zip reset to the built-in Compressed Folder handler.' -ForegroundColor Green
        }
    }
    if (Read-YesNo 'Set the default browser?' $false) {
        $b = (Read-Default 'Browser: Chrome / Edge / Firefox' 'Chrome').ToLower()
        $progId = switch -Wildcard ($b) { 'ch*' { 'ChromeHTML' } 'ed*' { 'MSEdgeHTM' } 'fi*' { 'FirefoxURL-308046B0AF4A39CB' } default { 'ChromeHTML' } }
        $regName = switch -Wildcard ($b) { 'ch*' { 'Google%20Chrome' } 'ed*' { 'Microsoft%20Edge' } 'fi*' { 'Firefox-308046B0AF4A39CB' } default { 'Google%20Chrome' } }
        $fta = Read-Default 'Path to SetUserFTA.exe for a silent change (blank = open the Default Apps picker)' ''
        if ($fta -and (Test-Path $fta)) {
            foreach ($x in '.htm','.html','http','https') { & $fta $x $progId }
            Write-Host '  Done - sign out/in for Explorer to pick it up.' -ForegroundColor Green
        } else {
            Write-Host '  Windows blocks silent default-browser changes via registry - opening Default Apps for a one-click confirm.' -ForegroundColor Yellow
            Start-Process "ms-settings:defaultapps?registeredAppUser=$regName"
        }
    }
}

function Invoke-AdwareHunt {
    Write-Title 'Unknown / adware program investigation (Prefetch, notifications, startup)'
    $name = Read-Default 'Program/exe name to look for (blank = general sweep)' ''
    if ($name) {
        Write-Sub "Prefetch entries for '$name' (proves execution even if the file is gone)"
        Get-ChildItem "$env:SystemRoot\Prefetch" -Filter "*$name*.pf" -ErrorAction SilentlyContinue |
            Select-Object Name, CreationTime, LastWriteTime | Sort-Object CreationTime | Format-Table -AutoSize
        Write-Sub "Files named like '$name' in user profiles, ProgramData, Temp"
        foreach ($r in @("$env:SystemDrive\Users", $env:ProgramData, "$env:SystemRoot\Temp")) {
            Get-ChildItem $r -Recurse -Force -File -Filter "*$name*" -ErrorAction SilentlyContinue | Select-Object FullName, Length, CreationTime, LastWriteTime | Format-Table -AutoSize
        }
        Write-Host '  For full uninstall-key / MSI / service / task evidence use the "Install provenance" option.' -ForegroundColor DarkGray
    }

    Write-Sub 'Browser push-notification grants (common adware / fake-alert vector)'
    $rows = foreach ($p in Get-ChildItem "$env:SystemDrive\Users" -Directory -ErrorAction SilentlyContinue) {
        foreach ($b in @(@{N='Chrome';P='AppData\Local\Google\Chrome\User Data'}, @{N='Edge';P='AppData\Local\Microsoft\Edge\User Data'})) {
            $ud = Join-Path $p.FullName $b.P
            if (-not (Test-Path $ud)) { continue }
            foreach ($pref in Get-ChildItem $ud -Recurse -Depth 1 -Filter 'Preferences' -File -ErrorAction SilentlyContinue) {
                try { $j = Get-Content $pref.FullName -Raw -ErrorAction Stop | ConvertFrom-Json } catch { continue }
                $n = $j.profile.content_settings.exceptions.notifications
                if (-not $n) { continue }
                foreach ($site in $n.PSObject.Properties) {
                    if ($site.Value.setting -eq 1) {
                        $lm = $null
                        if ($site.Value.last_modified) { try { $lm = [DateTime]::FromFileTimeUtc(([int64]$site.Value.last_modified) * 10).ToLocalTime() } catch { } }
                        [pscustomobject]@{ User = $p.Name; Browser = $b.N; Profile = $pref.Directory.Name; Site = ($site.Name -replace ',\*$',''); Granted = $lm }
                    }
                }
            }
        }
    }
    if ($rows) { $rows | Sort-Object Granted -Descending | Format-Table -AutoSize } else { Write-Host '  No allowed notification sites found.' -ForegroundColor Green }

    Write-Sub 'Startup entries (Run keys, Startup folders) and non-Microsoft scheduled tasks'
    $run = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce','HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
    $startup = foreach ($k in $run) {
        $props = Get-ItemProperty $k -ErrorAction SilentlyContinue
        if ($props) { $props.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' } | ForEach-Object { [pscustomobject]@{ Location = $k; Name = $_.Name; Command = $_.Value } } }
    }
    $startup | Format-Table -AutoSize -Wrap
    Get-ChildItem "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\Startup", "$env:SystemDrive\Users\*\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup" -File -ErrorAction SilentlyContinue | Select-Object FullName, CreationTime | Format-Table -AutoSize
    Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskPath -notlike '\Microsoft\*' -and $_.State -ne 'Disabled' } |
        Select-Object TaskPath, TaskName, State, @{n='Action';e={($_.Actions | ForEach-Object { "$($_.Execute) $($_.Arguments)" }) -join '; '}} | Format-Table -AutoSize -Wrap

    $out = Join-Path (Get-OutDir 'Security') "AdwareHunt_$(Get-Stamp).csv"
    $rows | Export-Csv $out -NoTypeInformation
    Write-Host "  Notification grants saved to $out. Check the EDR console (e.g. SentinelOne) for the original path/hash/parent process." -ForegroundColor DarkGray
}

function Invoke-IRLogCollection {
    Write-Title 'Incident response log collection for a time window'
    $start = [datetime](Read-Default 'Window START (e.g. 2026-08-26 12:00)' (Get-Date).AddHours(-24).ToString('yyyy-MM-dd HH:mm'))
    $end   = [datetime](Read-Default 'Window END' (Get-Date).ToString('yyyy-MM-dd HH:mm'))
    $hunt  = Read-Default 'Extra keyword to search process-creation events for (e.g. rundll32, powershell -enc)' 'rundll32'
    $out = Get-OutDir ("IR\{0}_{1}" -f $env:COMPUTERNAME, (Get-Stamp))
    Write-Host "  Output: $out" -ForegroundColor DarkGray

    auditpol /get /subcategory:"Process Creation" | Out-File "$out\audit-policy.txt"
    $cmdLine = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\Audit' -ErrorAction SilentlyContinue).ProcessCreationIncludeCmdLine_Enabled
    "ProcessCreationIncludeCmdLine_Enabled: $cmdLine" | Add-Content "$out\audit-policy.txt"
    if ($cmdLine -ne 1) { Write-Host '  Process command-line auditing is OFF - 4688 events will not show command lines.' -ForegroundColor Yellow }

    $grab = {
        param($Log, $Ids, $File, [switch]$All)
        $f = @{ LogName = $Log }
        if (-not $All) { $f.StartTime = $start; $f.EndTime = $end }
        if ($Ids) { $f.Id = $Ids }
        $ev = Get-WinEvent -FilterHashtable $f -ErrorAction SilentlyContinue
        if ($ev) { $ev | Select-Object TimeCreated, Id, ProviderName, Message | Export-Csv (Join-Path $out $File) -NoTypeInformation }
        Write-Host ("  {0,-70} {1,6} events" -f "$Log $(if ($Ids) { "($($Ids -join ','))" })", @($ev).Count)
        $ev
    }
    $p4688 = & $grab 'Security' 4688 'security-4688-window.csv'
    & $grab 'Security' @(4624,4625,4648,4672,4720,4728,4732,4756) 'security-logons-accounts-window.csv' | Out-Null
    if ($hunt) {
        $hit = Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4688 } -ErrorAction SilentlyContinue | Where-Object { $_.Message -like "*$hunt*" }
        $hit | Select-Object TimeCreated, Message | Format-List | Out-File "$out\security-4688-$($hunt -replace '\W','_')-alltime.txt"
        Write-Host "  4688 events mentioning '$hunt' (all time): $(@($hit).Count)"
    }
    & $grab 'Microsoft-Windows-PowerShell/Operational' $null 'powershell-operational-window.csv' | Out-Null
    & $grab 'Windows PowerShell' $null 'windows-powershell-window.csv' | Out-Null
    & $grab 'Microsoft-Windows-Windows Defender/Operational' $null 'defender-window.csv' | Out-Null
    & $grab 'Microsoft-Windows-WMI-Activity/Operational' $null 'wmi-window.csv' | Out-Null
    & $grab 'Microsoft-Windows-TaskScheduler/Operational' $null 'taskscheduler-window.csv' | Out-Null
    & $grab 'Microsoft-Windows-TerminalServices-LocalSessionManager/Operational' $null 'rdp-sessions-window.csv' | Out-Null
    & $grab 'System' 7045 'system-7045-service-installs-alltime.csv' -All | Out-Null
    foreach ($l in 'Microsoft-Windows-Application-Experience/Program-Inventory','Microsoft-Windows-Application-Experience/Program-Compatibility-Assistant') {
        & $grab $l $null (($l -replace '[/\\]','-') + '.csv') -All | Out-Null
    }
    wevtutil el | Out-File "$out\available-logs.txt"
    foreach ($l in 'Security','System','Application','Microsoft-Windows-PowerShell/Operational') {
        wevtutil epl "$l" (Join-Path $out (($l -replace '[/\\]','-') + '.evtx')) /ow:true 2>$null
    }
    try { Compress-Archive -Path "$out\*" -DestinationPath "$out.zip" -Force; Write-Host "  Zipped: $out.zip" -ForegroundColor Green } catch { }
    Write-Host "  Done: $out" -ForegroundColor Green
}

function Invoke-ADSyncRestart {
    $svc = Get-Service -Name ADSync -ErrorAction SilentlyContinue
    if (-not $svc) { return }
    if ($svc.StartType -ne 'Automatic' -or $svc.Status -ne 'Running') {
        if (Read-YesNo 'ADSync is not Automatic/Running - set it to Automatic and start it?' $true) {
            if (Confirm-Change 'Set ADSync to Automatic and start it.') {
                Set-Service ADSync -StartupType Automatic
                Start-Service ADSync -ErrorAction SilentlyContinue
                Get-Service ADSync | Format-Table Name, Status, StartType -AutoSize
            }
        }
    }
    if ((Get-Command Start-ADSyncSyncCycle -ErrorAction SilentlyContinue) -and (Read-YesNo 'Run a delta sync now?' $false)) {
        Start-ADSyncSyncCycle -PolicyType Delta
    }
}


# ---------- REMOTE DESKTOP ---------------------------------------------------------

function Invoke-RdpRedirectionPopup {
    Write-Title '[!] RDP "Unknown publisher" / redirection warning popup (clipboard, drives... checkboxes)'
    Write-Host '  Since the April 2025+ security updates, opening a .rdp file shows a security dialog asking the user'
    Write-Host '  to tick which local resources (clipboard, drives, printers...) to share - and it unticks them every time.'
    Write-Host '  Stopgap: RedirectionWarningDialogVersion = 1 restores the older single-warning dialog. Run on the CLIENT PCs.'
    $key = 'HKLM:\Software\Policies\Microsoft\Windows NT\Terminal Services\Client'
    $cur = (Get-ItemProperty $key -Name RedirectionWarningDialogVersion -ErrorAction SilentlyContinue).RedirectionWarningDialogVersion
    Write-Host "`n  Current value: $(if ($null -ne $cur) { $cur } else { 'not set (new dialog in use)' })"
    $act = (Read-Default 'A = apply stopgap, R = remove it (back to Windows default), blank = leave as is' '').ToString().ToUpper()
    if ($act -eq 'A' -and (Confirm-Change "Set $key\RedirectionWarningDialogVersion = 1")) {
        if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
        Set-ItemProperty -Path $key -Name RedirectionWarningDialogVersion -Value 1 -Type DWord -Force
        $v = (Get-ItemProperty $key -Name RedirectionWarningDialogVersion).RedirectionWarningDialogVersion
        if ($v -eq 1) { Write-Host '  SUCCESS - value is 1. Takes effect the next time an .rdp file is opened.' -ForegroundColor Green } else { Write-Host "  FAIL - value is $v" -ForegroundColor Red }
        Write-Host '  Long-term fix: sign the .rdp files (rdpsign.exe) with a trusted cert and deploy the publisher thumbprint via GPO.' -ForegroundColor DarkGray
    } elseif ($act -eq 'R' -and (Confirm-Change "Remove $key\RedirectionWarningDialogVersion")) {
        Remove-ItemProperty -Path $key -Name RedirectionWarningDialogVersion -ErrorAction SilentlyContinue
        Write-Host '  Removed.' -ForegroundColor Green
    }
}

function Invoke-RdsHealth {
    Write-Title 'RDP / RDS server health (incl. September 2026 update RDS hang)'
    $cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    Write-Host ("  {0}  build {1}.{2}" -f $cv.ProductName, $cv.CurrentBuild, $cv.UBR)

    Write-Sub 'RDP services'
    $svcs = Get-Service TermService, SessionEnv, UmRdpService -ErrorAction SilentlyContinue
    $svcs | Format-Table Name, DisplayName, Status, StartType -AutoSize
    $stuck = $svcs | Where-Object { $_.Status -in 'StopPending','StartPending' }
    if ($stuck) { Write-Host "  $($stuck.Name -join ', ') is stuck in $($stuck.Status -join '/') - classic sign of the September 2026 RDS hang." -ForegroundColor Red }
    $fDeny = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -Name fDenyTSConnections -ErrorAction SilentlyContinue).fDenyTSConnections
    $port  = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name PortNumber -ErrorAction SilentlyContinue).PortNumber
    $nla   = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name UserAuthentication -ErrorAction SilentlyContinue).UserAuthentication
    Write-Host ("  Remote Desktop enabled: {0}   Port: {1}   NLA required: {2}" -f ($fDeny -eq 0), $port, ($nla -eq 1))
    $listen = Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue
    Write-Host ("  Listening on {0}: {1}" -f $port, [bool]$listen) -ForegroundColor $(if ($listen) { 'Green' } else { 'Red' })

    Write-Sub 'Sessions'
    quser 2>&1 | Write-Host

    Write-Sub 'Updates installed since 2026-09-01'
    $hf = Get-HotFix -ErrorAction SilentlyContinue | Where-Object { $_.InstalledOn -and $_.InstalledOn -ge [datetime]'2026-09-01' } | Sort-Object InstalledOn
    if ($hf) { $hf | Format-Table HotFixID, Description, InstalledOn -AutoSize } else { Write-Host '  None.' }
    # September 2026 regression (Microsoft-confirmed RDS instability) and the 9/14 out-of-band fixes, as reported
    # by LazyAdmin / Abdalla Elmorsi. Verify the exact KB for your OS in the Update Catalog before relying on it.
    $kbMap = @{
        '14393' = @{ Bad = 'KB5123099'; Fix = 'KB5129239'; Os = 'Server 2016' }
        '17763' = @{ Bad = 'KB5122876'; Fix = 'KB5129238'; Os = 'Server 2019' }
        '20348' = @{ Bad = 'KB5122882'; Fix = 'KB5129237'; Os = 'Server 2022' }
        '26100' = @{ Bad = 'KB5122871'; Fix = 'KB5129235'; Os = 'Server 2025 / Win11 24H2' }
    }
    $m = $kbMap[$cv.CurrentBuild]
    $ids = @(Get-HotFix -ErrorAction SilentlyContinue | Select-Object -ExpandProperty HotFixID)
    if ($m) {
        $hasBad = $ids -contains $m.Bad; $hasFix = $ids -contains $m.Fix
        Write-Host ("  {0}: Sept CU {1} installed: {2}   Out-of-band fix {3} installed: {4}" -f $m.Os, $m.Bad, $hasBad, $m.Fix, $hasFix) -ForegroundColor $(if ($hasBad -and -not $hasFix) { 'Yellow' } else { 'Green' })
        if ($hasBad -and -not $hasFix) { Write-Host "  -> Install $($m.Fix) (Microsoft Update Catalog) and reboot - that is the real fix." -ForegroundColor Yellow }
    }

    Write-Sub 'Hang signatures - last 7 days'
    $since = (Get-Date).AddDays(-7)
    $e1 = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-TerminalServices-RemoteConnectionManager/Admin'; Id = 20498; StartTime = $since } -ErrorAction SilentlyContinue
    $e2 = Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Winlogon'; Id = 6005; StartTime = $since } -ErrorAction SilentlyContinue
    $e3 = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-TerminalServices-LocalSessionManager/Operational'; Level = 2,3; StartTime = $since } -ErrorAction SilentlyContinue
    Write-Host ("  RCM 20498 (connection timeout): {0}   Winlogon 6005 (SessionEnv/notification timeout): {1}   LSM warnings/errors: {2}" -f @($e1).Count, @($e2).Count, @($e3).Count)
    @($e1) + @($e2) | Where-Object { $_ } | Sort-Object TimeCreated -Descending | Select-Object -First 10 TimeCreated, Id, @{n='Msg';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap

    Write-Sub 'Licensing (RD Session Host)'
    $lic = Get-CimInstance -Namespace root\cimv2\TerminalServices -ClassName Win32_TerminalServiceSetting -ErrorAction SilentlyContinue
    if ($lic) {
        $modes = @{ 0='Not configured';1='Personal Desktop';2='Per Device';4='Per User';5='Not configured (5)' }
        Write-Host ("  Licensing mode: {0}   License servers: {1}" -f $modes[[int]$lic.LicensingType], (($lic.GetSpecifiedLicenseServerList().SpecifiedLSList) -join ', '))
        $grace = Get-CimInstance -Namespace root\cimv2\TerminalServices -ClassName Win32_TerminalServiceSetting -ErrorAction SilentlyContinue | Invoke-CimMethod -MethodName GetGracePeriodDays -ErrorAction SilentlyContinue
        if ($grace) { Write-Host "  Grace period days left: $($grace.DaysLeft)" }
    }
}

function Invoke-RdsSeptemberFix {
    Write-Title '[!] RDS fix - September 2026 update hang (RDP hangs at Connecting / "Please wait for Remote Desktop Configuration")'
    Write-Host '  1. Restart Remote Desktop Services (kills the TermService svchost if it is stuck in StopPending)'
    Write-Host '  2. Install the out-of-band fix from a downloaded .msu  (the proper fix)'
    Write-Host '  3. Apply the reported feature-flag override 3802373433 (stopgap if you cannot install the OOB yet; backs up first)'
    Write-Host '  4. Remove the feature-flag override (undo 3)'
    $c = Read-Default 'Choose 1-4 (blank = cancel)' ''
    switch ("$c") {
        '1' {
            if (-not (Confirm-Change 'Restart TermService - ALL RDP sessions on this server will be disconnected.')) { return }
            $svc = Get-CimInstance Win32_Service -Filter "Name='TermService'"
            if ($svc.State -ne 'Running' -or (Get-Service TermService).Status -eq 'StopPending') {
                Write-Host "  Killing stuck TermService host process (PID $($svc.ProcessId))..." -ForegroundColor Yellow
                if ($svc.ProcessId) { Stop-Process -Id $svc.ProcessId -Force -ErrorAction SilentlyContinue }
                Start-Sleep -Seconds 3
                Start-Service TermService -ErrorAction SilentlyContinue
            } else {
                Restart-Service TermService -Force -ErrorAction SilentlyContinue
            }
            Start-Service UmRdpService, SessionEnv -ErrorAction SilentlyContinue
            Get-Service TermService, UmRdpService, SessionEnv | Format-Table Name, Status -AutoSize
        }
        '2' {
            $msu = Read-Default 'Full path to the downloaded .msu (Microsoft Update Catalog)' ''
            if (-not $msu -or -not (Test-Path $msu)) { Write-Host '  File not found.' -ForegroundColor Red; Start-Process 'https://www.catalog.update.microsoft.com/'; return }
            if (Confirm-Change "Install $msu (no automatic restart).") {
                $p = Start-Process wusa.exe -ArgumentList "`"$msu`" /quiet /norestart" -Wait -PassThru
                Write-Host "  wusa exit code: $($p.ExitCode)  (3010 = installed, reboot required; 2359302 = already installed)" -ForegroundColor Cyan
                if (Read-YesNo 'Reboot now?' $false) { Restart-Computer -Force }
            }
        }
        '3' {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\FeatureManagement\Overrides\4\3802373433'
            if (-not (Confirm-Change "Back up FeatureManagement\Overrides to the output folder, create $k (EnabledState=1, EnabledStateOptions=0), restart TermService.")) { return }
            $bk = Join-Path (Get-OutDir 'RDS') "FeatureOverrides-backup_$(Get-Stamp).reg"
            reg export "HKLM\SYSTEM\CurrentControlSet\Control\FeatureManagement\Overrides" "$bk" /y | Out-Null
            Write-Host "  Backup: $bk" -ForegroundColor DarkGray
            New-Item -Path $k -Force | Out-Null
            Set-ItemProperty -Path $k -Name EnabledState -Value 1 -Type DWord
            Set-ItemProperty -Path $k -Name EnabledStateOptions -Value 0 -Type DWord
            Restart-Service TermService -Force -ErrorAction SilentlyContinue
            Get-Service TermService | Format-Table Name, Status -AutoSize
            Write-Host '  Applied. Remove it (option 4) once the out-of-band update is installed.' -ForegroundColor Green
        }
        '4' {
            $k = 'HKLM:\SYSTEM\CurrentControlSet\Control\FeatureManagement\Overrides\4\3802373433'
            if ((Test-Path $k) -and (Confirm-Change "Delete $k and restart TermService.")) {
                Remove-Item $k -Recurse -Force; Restart-Service TermService -Force -ErrorAction SilentlyContinue; Write-Host '  Removed.' -ForegroundColor Green
            } elseif (-not (Test-Path $k)) { Write-Host '  Override is not present.' }
        }
    }
}


# ---------- MORE HEALTH / SECURITY CHECKS -----------------------------------------
# Ideas drawn from open-source admin toolkits on GitHub (MIT): bcwilhite/PendingReboot,
# MahmoudNoureddine/SysAdmin-PS-Toolkit, steviecoaster/PSSysadminToolkit - rewritten here.

function Get-PendingRebootDetail {
    $r = [ordered]@{}
    $r.ComponentBasedServicing = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'
    $r.WindowsUpdate           = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'
    $r.PendingFileRename       = [bool](Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations
    $active  = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -ErrorAction SilentlyContinue).ComputerName
    $pending = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction SilentlyContinue).ComputerName
    $r.PendingComputerRename   = ($active -and $pending -and $active -ne $pending)
    $r.PendingDomainJoin       = (Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\JoinDomain') -or (Test-Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\AvoidSpnSet')
    $r.ConfigMgrClient         = $false
    try {
        $ccm = Invoke-CimMethod -Namespace root\ccm\ClientSDK -ClassName CCM_ClientUtilities -MethodName DetermineIfRebootPending -ErrorAction Stop
        $r.ConfigMgrClient = [bool]($ccm.RebootPending -or $ccm.IsHardRebootPending)
    } catch { }
    [pscustomobject]$r
}

function Invoke-PendingReboot {
    Write-Title 'Pending reboot - detailed check'
    $d = Get-PendingRebootDetail
    $d | Format-List
    $any = $d.PSObject.Properties | Where-Object { $_.Value -eq $true }
    if ($any) { Write-Host "  REBOOT PENDING: $($any.Name -join ', ')" -ForegroundColor Yellow } else { Write-Host '  No reboot pending.' -ForegroundColor Green }
    if ($d.PendingFileRename) {
        Write-Sub 'Pending file rename/delete operations (first 20)'
        (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager').PendingFileRenameOperations | Where-Object { $_ } | Select-Object -First 20 | ForEach-Object { Write-Host "  $_" }
    }
    $os = Get-CimInstance Win32_OperatingSystem
    Write-Host ("  Last boot: {0}  (up {1:%d}d {1:hh}h)" -f $os.LastBootUpTime, ((Get-Date) - $os.LastBootUpTime))
}

function Invoke-SecurityPosture {
    Write-Title 'Security posture check'
    $out = @()
    function Add-Row($Area, $Item, $Value, $Status) { $script:secRows += [pscustomobject]@{ Area = $Area; Item = $Item; Value = "$Value"; Status = $Status } }
    $script:secRows = @()

    # Antivirus (SecurityCenter2 on workstations; Defender cmdlets everywhere)
    $av = Get-CimInstance -Namespace root\SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction SilentlyContinue
    foreach ($a in $av) {
        $hex = '{0:X6}' -f $a.productState
        $on  = $hex.Substring(2,2) -in '10','11'
        $cur = $hex.Substring(4,2) -eq '00'
        Add-Row 'Antivirus' $a.displayName ("enabled={0} up-to-date={1}" -f $on, $cur) $(if ($on -and $cur) { 'OK' } else { 'CHECK' })
    }
    $mp = Get-MpComputerStatus -ErrorAction SilentlyContinue
    if ($mp) {
        Add-Row 'Defender' 'Real-time protection' $mp.RealTimeProtectionEnabled $(if ($mp.RealTimeProtectionEnabled) { 'OK' } else { 'INFO (normal if another EDR is primary)' })
        Add-Row 'Defender' 'Signature age (days)' $mp.AntivirusSignatureAge $(if ($mp.AntivirusSignatureAge -le 3) { 'OK' } else { 'CHECK' })
        Add-Row 'Defender' 'Tamper protection' $mp.IsTamperProtected 'INFO'
    }
    # Firewall
    Get-NetFirewallProfile -ErrorAction SilentlyContinue | ForEach-Object { Add-Row 'Firewall' "$($_.Name) profile" $_.Enabled $(if ($_.Enabled) { 'OK' } else { 'CHECK' }) }
    # BitLocker / TPM / Secure Boot
    Get-BitLockerVolume -ErrorAction SilentlyContinue | ForEach-Object {
        Add-Row 'BitLocker' $_.MountPoint ("{0}, {1}%, protectors: {2}" -f $_.ProtectionStatus, $_.EncryptionPercentage, (($_.KeyProtector.KeyProtectorType) -join '+')) $(if ($_.ProtectionStatus -eq 'On') { 'OK' } else { 'CHECK' })
    }
    $tpm = Get-Tpm -ErrorAction SilentlyContinue
    if ($tpm) { Add-Row 'Hardware' 'TPM present / ready' "$($tpm.TpmPresent) / $($tpm.TpmReady)" $(if ($tpm.TpmReady) { 'OK' } else { 'CHECK' }) }
    try { $sb = Confirm-SecureBootUEFI -ErrorAction Stop; Add-Row 'Hardware' 'Secure Boot' $sb $(if ($sb) { 'OK' } else { 'CHECK' }) } catch { Add-Row 'Hardware' 'Secure Boot' 'not supported / legacy BIOS' 'INFO' }
    # Protocols / hardening
    $smb1 = (Get-SmbServerConfiguration -ErrorAction SilentlyContinue).EnableSMB1Protocol
    Add-Row 'Hardening' 'SMBv1 server enabled' $smb1 $(if ($smb1) { 'RISK' } else { 'OK' })
    $nla = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name UserAuthentication -ErrorAction SilentlyContinue).UserAuthentication
    $rdpOn = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -Name fDenyTSConnections -ErrorAction SilentlyContinue).fDenyTSConnections -eq 0
    Add-Row 'Hardening' 'RDP enabled / NLA required' "$rdpOn / $($nla -eq 1)" $(if ($rdpOn -and $nla -ne 1) { 'RISK' } else { 'OK' })
    $llmnr = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Name EnableMulticast -ErrorAction SilentlyContinue).EnableMulticast
    Add-Row 'Hardening' 'LLMNR disabled by policy' ($llmnr -eq 0) $(if ($llmnr -eq 0) { 'OK' } else { 'INFO' })
    $lapsLegacy = Test-Path 'HKLM:\SOFTWARE\Policies\Microsoft Services\AdmPwd'
    $lapsNew = Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS'
    Add-Row 'Hardening' 'LAPS policy present (legacy / Windows LAPS)' "$lapsLegacy / $lapsNew" 'INFO'
    $uac = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -Name EnableLUA -ErrorAction SilentlyContinue).EnableLUA
    Add-Row 'Hardening' 'UAC enabled' ($uac -eq 1) $(if ($uac -eq 1) { 'OK' } else { 'RISK' })
    # Local admins
    try {
        $admins = Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction Stop | Select-Object -ExpandProperty Name
        Add-Row 'Accounts' 'Local Administrators members' ($admins -join '; ') 'REVIEW'
    } catch { Add-Row 'Accounts' 'Local Administrators members' ((net localgroup Administrators | Select-Object -Skip 6 | Where-Object { $_ -and $_ -notmatch 'command completed' }) -join '; ') 'REVIEW' }
    $guest = Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.SID -like '*-501' }
    if ($guest) { Add-Row 'Accounts' 'Guest account enabled' $guest.Enabled $(if ($guest.Enabled) { 'RISK' } else { 'OK' }) }
    # Certificates expiring
    Get-ChildItem Cert:\LocalMachine\My -ErrorAction SilentlyContinue | Where-Object { $_.NotAfter -lt (Get-Date).AddDays(45) } | ForEach-Object {
        Add-Row 'Certificates' $_.Subject ("expires {0:yyyy-MM-dd}" -f $_.NotAfter) $(if ($_.NotAfter -lt (Get-Date)) { 'EXPIRED' } else { 'EXPIRING' })
    }
    # Activation
    $lic = Get-CimInstance SoftwareLicensingProduct -Filter "PartialProductKey IS NOT NULL AND ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f'" -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($lic) { $st = @{0='Unlicensed';1='Licensed';2='OOB grace';3='OOT grace';4='Non-genuine grace';5='Notification';6='Extended grace'}[[int]$lic.LicenseStatus]; Add-Row 'Windows' 'Activation' $st $(if ($lic.LicenseStatus -eq 1) { 'OK' } else { 'CHECK' }) }

    $script:secRows | Format-Table Area, Item, Value, Status -AutoSize -Wrap
    $csv = Join-Path (Get-OutDir 'Security') "SecurityPosture_$(Get-Stamp).csv"
    $script:secRows | Export-Csv $csv -NoTypeInformation
    $bad = @($script:secRows | Where-Object { $_.Status -in 'RISK','CHECK','EXPIRED' })
    Write-Host "  $($bad.Count) item(s) need attention. Saved to $csv" -ForegroundColor $(if ($bad) { 'Yellow' } else { 'Green' })
}

function Invoke-HardwareHealth {
    Write-Title 'Hardware health (disks / SMART, battery, drivers, temperatures)'
    Write-Sub 'Physical disks'
    Get-PhysicalDisk -ErrorAction SilentlyContinue | ForEach-Object {
        $rc = $_ | Get-StorageReliabilityCounter -ErrorAction SilentlyContinue
        [pscustomobject]@{
            Disk = $_.FriendlyName; Media = $_.MediaType; Bus = $_.BusType; SizeGB = [math]::Round($_.Size/1GB)
            Health = $_.HealthStatus; Status = ($_.OperationalStatus -join ','); Wear = $rc.Wear; TempC = $rc.Temperature
            ReadErrors = $rc.ReadErrorsUncorrected; WriteErrors = $rc.WriteErrorsUncorrected; PowerOnHours = $rc.PowerOnHours
        }
    } | Format-Table -AutoSize
    $smart = Get-CimInstance -Namespace root\wmi -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction SilentlyContinue
    if ($smart | Where-Object PredictFailure) { Write-Host '  SMART PREDICTS FAILURE on at least one disk - back up and replace!' -ForegroundColor Red }
    Write-Sub 'Disk / NTFS / controller errors in the System log (last 30 days)'
    Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'disk','Ntfs','storahci','stornvme','iaStorA','iaStorAC','volmgr'; Level = 1,2,3; StartTime = (Get-Date).AddDays(-30) } -ErrorAction SilentlyContinue |
        Group-Object ProviderName, Id | Sort-Object Count -Descending | Select-Object Count, Name | Format-Table -AutoSize
    Write-Sub 'Devices with driver problems'
    $bad = Get-CimInstance Win32_PnPEntity -Filter 'ConfigManagerErrorCode <> 0' -ErrorAction SilentlyContinue
    if ($bad) { $bad | Select-Object Name, ConfigManagerErrorCode, DeviceID | Format-Table -AutoSize -Wrap } else { Write-Host '  None.' -ForegroundColor Green }
    Write-Sub 'Thermal zones (if the firmware exposes them)'
    Get-CimInstance -Namespace root\wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction SilentlyContinue |
        Select-Object InstanceName, @{n='TempC';e={[math]::Round($_.CurrentTemperature/10 - 273.15,1)}} | Format-Table -AutoSize
    if (Get-CimInstance Win32_Battery -ErrorAction SilentlyContinue) {
        Write-Sub 'Battery'
        $bat = Join-Path (Get-OutDir 'Hardware') "BatteryReport_$(Get-Stamp).html"
        powercfg /batteryreport /output "$bat" | Out-Null
        $full = (Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction SilentlyContinue | Select-Object -First 1).FullChargedCapacity
        $design = (Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction SilentlyContinue | Select-Object -First 1).DesignedCapacity
        if ($full -and $design) { $pct = [math]::Round($full / $design * 100); Write-Host "  Battery health: $pct% of design capacity" -ForegroundColor $(if ($pct -lt 60) { 'Yellow' } else { 'Green' }) }
        Write-Host "  Full battery report: $bat"
    }
}

function Invoke-TimeSync {
    Write-Title 'Time sync (w32time) check / resync'
    $src = w32tm /query /source 2>&1
    Write-Host "  Time source: $src"
    w32tm /query /status 2>&1 | Write-Host
    $cs = Get-CimInstance Win32_ComputerSystem
    if ($cs.PartOfDomain) {
        $dc = ((nltest /dsgetdc:$($cs.Domain) 2>$null) | Select-String 'DC: \\\\(.+)' | ForEach-Object { $_.Matches[0].Groups[1].Value }) | Select-Object -First 1
        if ($dc) { Write-Sub "Offset vs $dc"; w32tm /stripchart /computer:$dc /samples:3 /dataonly 2>&1 | Write-Host }
    } else {
        Write-Sub 'Offset vs time.windows.com'; w32tm /stripchart /computer:time.windows.com /samples:3 /dataonly 2>&1 | Write-Host
    }
    if (Read-YesNo 'Force a resync now?' $false) {
        if (Confirm-Change 'Restart w32time and force a time resync.') {
            Restart-Service w32time -Force -ErrorAction SilentlyContinue
            w32tm /resync /force 2>&1 | Write-Host
        }
    }
}

function Invoke-GPResult {
    Write-Title 'Group Policy results (gpresult HTML)'
    $out = Join-Path (Get-OutDir 'GroupPolicy') "GPResult_${env:COMPUTERNAME}_$(Get-Stamp).html"
    gpresult /h "$out" /f 2>&1 | Write-Host
    if (Test-Path $out) { Write-Host "  Saved: $out" -ForegroundColor Green; if (Read-YesNo 'Open it now?' $false) { Start-Process $out } }
    Write-Sub 'Last Group Policy processing errors (last 7 days)'
    Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-GroupPolicy'; Level = 1,2,3; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 15 -ErrorAction SilentlyContinue |
        Select-Object TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
}

function Invoke-SoftwareInventory {
    Write-Title 'Installed software inventory'
    $rows = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -and -not $_.SystemComponent } |
        Select-Object DisplayName, DisplayVersion, Publisher, InstallDate, InstallLocation, @{n='Scope';e={ if ($_.PSPath -like '*HKEY_CURRENT_USER*') { 'User' } elseif ($_.PSPath -like '*WOW6432Node*') { '32-bit' } else { '64-bit' } }} |
        Sort-Object DisplayName -Unique
    $out = Join-Path (Get-OutDir 'Software') "SoftwareInventory_${env:COMPUTERNAME}_$(Get-Stamp).csv"
    $rows | Export-Csv $out -NoTypeInformation
    $filter = Read-Default 'Filter the list on screen (blank = show newest 25 installs)' ''
    if ($filter) { $rows | Where-Object { $_.DisplayName -like "*$filter*" -or $_.Publisher -like "*$filter*" } | Format-Table DisplayName, DisplayVersion, Publisher, InstallDate -AutoSize }
    else { $rows | Sort-Object InstallDate -Descending | Select-Object -First 25 | Format-Table DisplayName, DisplayVersion, Publisher, InstallDate -AutoSize }
    Write-Host "  $(@($rows).Count) programs saved to $out" -ForegroundColor Green
}

function Invoke-ProfileRebuild {
    Write-Title 'Rebuild a corrupted Windows user profile (back up -> reset -> copy data back)'
    Write-Host '  Step 1 RESET : user signed out -> old profile renamed to <name>.old_<date>, its registry entry removed (exported first).' -ForegroundColor Gray
    Write-Host '                 The user then signs in and gets a brand-new profile.' -ForegroundColor Gray
    Write-Host '  Step 2 RESTORE: copies files, bookmarks, signatures, Sticky Notes from the .old folder into the new profile' -ForegroundColor Gray
    Write-Host '                 and lists the old mapped drives / printers.' -ForegroundColor Gray
    $mode = (Read-Default '  1 = RESET a profile, 2 = RESTORE data into the new profile, blank = cancel' '').ToString()
    if (-not $mode) { return }
    $plKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
    $dir = Get-OutDir 'ProfileRebuild'; $stamp = Get-Stamp

    if ($mode -eq '1') {
        $profs = @(Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special -and $_.LocalPath -like '*\Users\*' } | Sort-Object LastUseTime -Descending)
        for ($i = 0; $i -lt $profs.Count; $i++) {
            $u = try { (New-Object Security.Principal.SecurityIdentifier($profs[$i].SID)).Translate([Security.Principal.NTAccount]).Value } catch { $profs[$i].SID }
            $profs[$i] | Add-Member NoteProperty Account $u -Force
            Write-Host ("   {0,2}. {1,-35} {2,-30} Loaded: {3,-5} LastUse: {4}" -f ($i + 1), $u, $profs[$i].LocalPath, $profs[$i].Loaded, $profs[$i].LastUseTime)
        }
        $n = Read-Int '  Profile number to RESET (0 = cancel)' 0
        if ($n -lt 1 -or $n -gt $profs.Count) { return }
        $p = $profs[$n - 1]
        if ($p.LocalPath -ieq $env:USERPROFILE) { Write-Host '  You are signed in as this user - run this from a different admin account.' -ForegroundColor Red; return }
        if ($p.Loaded) {
            Write-Host "  $($p.Account) is still loaded (signed in, or a process is holding the registry)." -ForegroundColor Red
            Write-Host '  Sign the user out (or restart the PC and sign in ONLY as an admin), then run this again.' -ForegroundColor Yellow
            return
        }
        $sizeGB = [math]::Round(((Get-ChildItem $p.LocalPath -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum)/1GB, 2)
        $free = [math]::Round((Get-PSDrive ($p.LocalPath.Substring(0,1))).Free/1GB, 1)
        Write-Host "  Profile size: $sizeGB GB   Free on drive: $free GB (renaming needs no extra space; restoring copies the data)" -ForegroundColor Gray
        $newName = "$($p.LocalPath).old_$stamp"
        if (-not (Confirm-Change "Reset profile of $($p.Account): rename $($p.LocalPath) -> $newName and remove its ProfileList registry key (backup in $dir).")) { return }
        & reg.exe export ("HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\" + $p.SID) "$dir\ProfileList_$($p.SID)_$stamp.reg" /y | Out-Null
        try { Rename-Item -LiteralPath $p.LocalPath -NewName (Split-Path $newName -Leaf) -ErrorAction Stop }
        catch {
            Write-Host "  Rename FAILED: $($_.Exception.Message)" -ForegroundColor Red
            Write-Host '  Something still has files open in the profile. Restart the PC, sign in ONLY as an admin, and run this again. Nothing was changed.' -ForegroundColor Yellow
            return
        }
        $guid = (Get-ItemProperty "$plKey\$($p.SID)" -ErrorAction SilentlyContinue).Guid
        Remove-Item "$plKey\$($p.SID)" -Recurse -Force -ErrorAction SilentlyContinue
        Get-ChildItem $plKey -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -like "$($p.SID).bak" } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        if ($guid) { Remove-Item "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileGuid\$guid" -Recurse -Force -ErrorAction SilentlyContinue }
        "$($p.Account)|$($p.SID)|$newName|$(Get-Date)" | Add-Content "$dir\ProfileRebuild_log.txt"
        Write-Host "`n  Done. Old profile is now: $newName" -ForegroundColor Green
        Write-Host '  NEXT: have the user sign in (domain users need line-of-sight to a DC / VPN). Windows builds a new profile.' -ForegroundColor Cyan
        Write-Host '  Once they reach the desktop, run this option again and pick 2 = RESTORE.' -ForegroundColor Cyan
        return
    }

    if ($mode -eq '2') {
        $olds = @(Get-ChildItem (Split-Path $env:PUBLIC -Parent) -Directory -Filter '*.old_*' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
        if (-not $olds) { Write-Host '  No <name>.old_<date> profile folders found under C:\Users.' -ForegroundColor Red; return }
        for ($i = 0; $i -lt $olds.Count; $i++) { Write-Host ("   {0,2}. {1}" -f ($i + 1), $olds[$i].FullName) }
        $n = Read-Int '  Old profile to restore FROM (0 = cancel)' 1
        if ($n -lt 1 -or $n -gt $olds.Count) { return }
        $src = $olds[$n - 1].FullName
        $guess = Join-Path (Split-Path $src -Parent) (($olds[$n - 1].Name) -replace '\.old_\d{8}_\d{6}$', '')
        $dst = Read-Default '  New profile to restore INTO' $guess
        if (-not (Test-Path $dst)) { Write-Host "  $dst does not exist yet - the user must sign in once first." -ForegroundColor Red; return }

        # Read the old registry hive: folder redirection (OneDrive), mapped drives, printers
        $hive = 'HKU\SDSI_OldProfile'; $redirected = @(); $redirTargets = @(); $info = @()
        if (Test-Path "$src\NTUSER.DAT") {
            & reg.exe load $hive "$src\NTUSER.DAT" 2>$null | Out-Null
            if ($LASTEXITCODE -eq 0) {
                $sf = Get-ItemProperty 'Registry::HKEY_USERS\SDSI_OldProfile\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' -ErrorAction SilentlyContinue
                foreach ($k in @{ Desktop = 'Desktop'; Personal = 'Documents'; 'My Pictures' = 'Pictures' }.GetEnumerator()) { if ("$($sf.($k.Key))" -match 'OneDrive|^\\\\') { $redirected += $k.Value; $redirTargets += [pscustomobject]@{ Folder = $k.Value; Target = "$($sf.($k.Key))" } } }
                Get-ChildItem 'Registry::HKEY_USERS\SDSI_OldProfile\Network' -ErrorAction SilentlyContinue | ForEach-Object { $info += [pscustomobject]@{ Type = 'Mapped drive'; Item = "$($_.PSChildName): -> $((Get-ItemProperty $_.PSPath).RemotePath)" } }
                Get-ChildItem 'Registry::HKEY_USERS\SDSI_OldProfile\Printers\Connections' -ErrorAction SilentlyContinue | ForEach-Object { $info += [pscustomobject]@{ Type = 'Printer'; Item = ($_.PSChildName -replace ',', '\') } }
                $defPrn = (Get-ItemProperty 'Registry::HKEY_USERS\SDSI_OldProfile\Software\Microsoft\Windows NT\CurrentVersion\Windows' -ErrorAction SilentlyContinue).Device
                if ($defPrn) { $info += [pscustomobject]@{ Type = 'Default printer'; Item = ($defPrn -split ',')[0] } }
                $sf = $null; [gc]::Collect(); Start-Sleep 1
                & reg.exe unload $hive 2>$null | Out-Null
            } else { Write-Host '  Could not load the old NTUSER.DAT (corrupt or in use) - skipping drive/printer list.' -ForegroundColor DarkYellow }
        }
        if ($redirected) {
            Write-Host '  These folders were REDIRECTED in the old profile - their files are NOT in the old folder and are NOT copied:' -ForegroundColor Yellow
            $redirTargets | Format-Table -AutoSize -Wrap
            if ($redirTargets | Where-Object { $_.Target -match '^\\\\' }) {
                Write-Host '  Network (server) redirection: the files are on the server. The new profile gets them back when the folder-redirection' -ForegroundColor Cyan
                Write-Host '  Group Policy applies - user on the office network, gpupdate /force, then sign out/in (can take 2 sign-ins).' -ForegroundColor Cyan
                Write-Host '  Do NOT clear the Offline Files (CSC) cache - it may hold changes not yet synced to the server (check Sync Center).' -ForegroundColor DarkYellow
                $newSid = (Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue | Where-Object { $_.LocalPath -ieq $dst }).SID
                if ($newSid) { $null = Show-FolderRedirectionSource -Sid $newSid -Account (Split-Path $dst -Leaf) }
                Write-Host '  If the redirection is NOT wanted: stop the GPO for this user first, then use "Folder redirection - point back to local".' -ForegroundColor Cyan
            }
            if ($redirTargets | Where-Object { $_.Target -match 'OneDrive' }) { Write-Host '  OneDrive redirection: sign the user in to OneDrive and turn on folder backup - files re-sync from the cloud.' -ForegroundColor Cyan }
        }
        $oneDrive = Get-ChildItem $src -Directory -Filter 'OneDrive*' -ErrorAction SilentlyContinue
        if ($oneDrive) { Write-Host "  Skipping $($oneDrive.Name -join ', ') - OneDrive will re-sync it. (Copy manually only if there were un-synced files.)" -ForegroundColor Yellow }

        $items = @(
            'Desktop','Documents','Downloads','Pictures','Music','Videos','Favorites','Links','Contacts'
            'AppData\Roaming\Microsoft\Signatures'
            'AppData\Roaming\Microsoft\Templates'
            'AppData\Roaming\Microsoft\UProof'
            'AppData\Roaming\Microsoft\Proof'
            'AppData\Local\Microsoft\Edge\User Data\Default\Bookmarks'
            'AppData\Local\Google\Chrome\User Data\Default\Bookmarks'
            'AppData\Local\Packages\Microsoft.MicrosoftStickyNotes_8wekyb3d8bbwe\LocalState'
            'AppData\Roaming\Microsoft\Sticky Notes'
        ) | Where-Object { $redirected -notcontains $_ }
        $pst = Get-ChildItem $src -Recurse -Filter *.pst -File -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '\\OneDrive' }
        # Full browser data (all profiles, extensions, history, settings) - optional
        $browsers = @(
            [pscustomobject]@{ Name = 'Chrome';  Proc = 'chrome';  Rel = 'AppData\Local\Google\Chrome\User Data' }
            [pscustomobject]@{ Name = 'Edge';    Proc = 'msedge';  Rel = 'AppData\Local\Microsoft\Edge\User Data' }
            [pscustomobject]@{ Name = 'Firefox'; Proc = 'firefox'; Rel = 'AppData\Roaming\Mozilla\Firefox' }
        ) | Where-Object { Test-Path -LiteralPath (Join-Path $src $_.Rel) }
        $fullBrowser = $false
        if ($browsers) {
            Write-Host "`n  Browser data found in the old profile: $($browsers.Name -join ', ')" -ForegroundColor Gray
            Write-Host '  FULL copy = every browser profile, extensions, history, settings, open tabs (caches skipped).' -ForegroundColor Gray
            Write-Host '  Chrome/Edge saved passwords usually do NOT survive (Windows ties them to the old profile) - use browser sync for those.' -ForegroundColor DarkYellow
            Write-Host '  Firefox saved passwords DO carry over.  No = bookmarks only (Chrome/Edge default profile).' -ForegroundColor Gray
            $fullBrowser = Read-YesNo '  Copy FULL browser data?' $true
            if ($fullBrowser) { $items = $items | Where-Object { $_ -notmatch '\\Bookmarks$' } }
        }
        Write-Host "`n  Will copy (only what exists): $($items -join '; ')$(if ($fullBrowser) { '; FULL ' + ($browsers.Name -join '/') + ' browser data' })" -ForegroundColor Gray
        if ($pst) { Write-Host "  PST files found (copied to the same relative place; re-attach in Outlook): $($pst.Name -join ', ')" -ForegroundColor Gray }
        if (-not (Confirm-Change "Copy user data from $src into $dst (nothing in $src is deleted; ask the user to close Edge/Chrome/Sticky Notes first).")) { return }
        $logf = "$dir\Restore_$((Split-Path $dst -Leaf))_$stamp.log"
        foreach ($it in $items) {
            $s = Join-Path $src $it; $d = Join-Path $dst $it
            if (Test-Path -LiteralPath $s -PathType Container) {
                & robocopy.exe $s $d /E /XJ /R:1 /W:1 /COPY:DAT /DCOPY:T /XF desktop.ini /NP /NFL /NDL /LOG+:"$logf" | Out-Null
                Write-Host "  Copied $it" -ForegroundColor Green
            } elseif (Test-Path -LiteralPath $s -PathType Leaf) {
                Ensure-Dir (Split-Path $d -Parent) | Out-Null
                if (Test-Path -LiteralPath $d) { Copy-Item -LiteralPath $d "$d.new_$stamp" -Force }
                Copy-Item -LiteralPath $s $d -Force; Write-Host "  Copied $it" -ForegroundColor Green
            }
        }
        if ($fullBrowser) {
            $dstUser = Split-Path $dst -Leaf
            $running = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $browsers.Proc -contains ($_.Name -replace '\.exe$','') } |
                Where-Object { $o = Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction SilentlyContinue; $o.User -ieq $dstUser })
            if ($running -and (Confirm-Change "Close $(@($running.Name | Sort-Object -Unique) -join ', ') for $dstUser (browser must be closed to copy its data).")) {
                $running | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }; Start-Sleep 2
            }
            foreach ($b in $browsers) {
                $s = Join-Path $src $b.Rel; $d = Join-Path $dst $b.Rel
                & robocopy.exe $s $d /E /XJ /R:1 /W:1 /COPY:DAT /DCOPY:T /NP /NFL /NDL /LOG+:"$logf" /XD 'Cache' 'Code Cache' 'GPUCache' 'ShaderCache' 'GrShaderCache' 'GraphiteDawnCache' 'DawnCache' 'DawnWebGPUCache' 'CacheStorage' 'ScriptCache' 'Crashpad' 'cache2' 'startupCache' /XF 'lock' 'parent.lock' 'LOCK' 'SingletonLock' 'SingletonCookie' 'SingletonSocket' | Out-Null
                if ($LASTEXITCODE -lt 8) { Write-Host "  Copied FULL $($b.Name) data" -ForegroundColor Green } else { Write-Host "  $($b.Name) copy had errors (exit $LASTEXITCODE) - see $logf" -ForegroundColor Red }
            }
            Write-Host '  Have the user open each browser and check bookmarks/extensions; if Chrome/Edge passwords are blank, sign in to browser sync.' -ForegroundColor Cyan
        }
        foreach ($f in $pst) { $rel = $f.FullName.Substring($src.Length).TrimStart('\'); $d = Join-Path $dst $rel; Ensure-Dir (Split-Path $d -Parent) | Out-Null; Copy-Item -LiteralPath $f.FullName $d -Force; Write-Host "  Copied $rel" -ForegroundColor Green }
        Write-Sub 'Re-create these for the user (from the OLD profile)'
        if ($info) { $info | Format-Table -AutoSize -Wrap; $info | Export-Csv "$dir\OldDrivesPrinters_$((Split-Path $dst -Leaf))_$stamp.csv" -NoTypeInformation } else { Write-Host '  None recorded (or GPO maps them automatically).' }
        Write-Host "`n  Restore log: $logf" -ForegroundColor Green
        Write-Host '  Then: sign in to OneDrive + Outlook (new Outlook profile builds automatically for M365), check browser bookmarks,' -ForegroundColor Cyan
        Write-Host "  re-attach any PSTs. Keep $src for a couple of weeks, then delete it." -ForegroundColor Cyan
    }
}

function Get-FolderRedirectionSource {
    # Finds which GPO(s) redirect folders for a user and WHICH GROUP grants them "Apply group policy".
    # Uses only ADSI + SYSVOL (no RSAT / GroupPolicy module needed). Works for domain users only.
    param([Parameter(Mandatory)][string]$Sid)
    $fdCse = '{25537BA6-77A8-11D2-9B6C-0000F8080861}'
    $applyRight = 'edacfd8f-ffb3-11d1-b41d-00a0c968f939'
    $out = @()
    try { $cs = Get-CimInstance Win32_ComputerSystem; if (-not $cs.PartOfDomain) { return $out }; $dom = $cs.Domain } catch { return $out }
    # 1. GPOs this PC last applied to the user (Group Policy state)
    $applied = @{}
    Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\State\$Sid\GPO-List" -ErrorAction SilentlyContinue | ForEach-Object {
        $g = Get-ItemProperty $_.PSPath
        if ("$($g.Extensions)" -match [regex]::Escape($fdCse)) { $applied[("$($g.GPOName)").ToUpper()] = "$($g.DisplayName)" }
    }
    # 2. Every GPO in SYSVOL that has folder redirection configured
    $cands = @{}
    Get-ChildItem "\\$dom\SYSVOL\$dom\Policies" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
        if (Get-ChildItem (Join-Path $_.FullName 'User\Documents & Settings') -Filter 'fdeploy*.ini' -ErrorAction SilentlyContinue) { $cands[$_.Name.ToUpper()] = $_.FullName }
    }
    foreach ($k in $applied.Keys) { if (-not $cands.ContainsKey($k)) { $cands[$k] = $null } }
    # 3. The user's groups (nested, via tokenGroups)
    $userGroups = @{}; $userName = $Sid
    try {
        $u = [adsi]"LDAP://<SID=$Sid>"; $userName = "$($u.sAMAccountName)"
        $u.RefreshCache(@('tokenGroups'))
        foreach ($b in $u.Properties['tokenGroups']) { $gs = (New-Object Security.Principal.SecurityIdentifier($b, 0)).Value; $userGroups[$gs] = $true }
        $userGroups[$Sid] = $true
        $userGroups['S-1-5-11'] = $true   # Authenticated Users
    } catch {}
    $root = try { ([adsi]"LDAP://RootDSE").defaultNamingContext } catch { $null }
    foreach ($guid in $cands.Keys) {
        $name = $applied[$guid]; $via = @(); $status = ''
        if ($root) {
            try {
                $g = [adsi]"LDAP://CN=$guid,CN=Policies,CN=System,$root"
                if (-not $name) { $name = "$($g.displayName)" }
                $flags = [int]"$($g.flags)"; $status = @{0='Enabled';1='User settings disabled';2='Computer settings disabled';3='All settings disabled'}[$flags]
                foreach ($ace in $g.psbase.ObjectSecurity.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
                    if ($ace.AccessControlType -ne 'Allow' -or "$($ace.ObjectType)" -ne $applyRight) { continue }
                    $s = $ace.IdentityReference.Value
                    if ($userGroups.ContainsKey($s)) { $via += try { (New-Object Security.Principal.SecurityIdentifier($s)).Translate([Security.Principal.NTAccount]).Value } catch { $s } }
                }
            } catch {}
        }
        $paths = ''
        if ($cands[$guid]) {
            $ini = Get-ChildItem (Join-Path $cands[$guid] 'User\Documents & Settings') -Filter 'fdeploy*.ini' -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($ini) { $paths = ((Get-Content $ini.FullName -ErrorAction SilentlyContinue | Where-Object { $_ -match '^\s*s-1-|=\\\\|\\\\' } | ForEach-Object { ($_ -split '=', 2)[-1] } | Where-Object { $_ -match '^\\\\' } | Select-Object -Unique) -join '; ') }
        }
        $out += [pscustomobject]@{
            GPO = $(if ($name) { $name } else { $guid }); Guid = $guid; GpoStatus = $status
            AppliedToUserLastTime = $applied.ContainsKey($guid)
            AppliesVia = $(if ($via) { ($via | Select-Object -Unique) -join ', ' } elseif ($userGroups.Count) { '(user not in filter)' } else { '(could not read AD)' })
            Targets = $paths
        }
    }
    $out | Sort-Object @{e={$_.AppliedToUserLastTime}; Descending=$true}, @{e={$_.AppliesVia -notmatch '^\('}; Descending=$true}
}

function Show-FolderRedirectionSource([string]$Sid, [string]$Account) {
    Write-Sub "Which GPO / group redirects folders for $Account"
    $src = @(Get-FolderRedirectionSource -Sid $Sid)
    if (-not $src) { Write-Host '  No folder-redirection GPO found (not domain-joined, SYSVOL unreachable, or none configured).' -ForegroundColor DarkGray; return $src }
    $src | Format-Table GPO, GpoStatus, AppliedToUserLastTime, AppliesVia, Targets -AutoSize -Wrap | Out-Host
    $hit = @($src | Where-Object { $_.AppliedToUserLastTime -or $_.AppliesVia -notmatch '^\(' })
    foreach ($h in $hit) {
        Write-Host "  -> '$($h.GPO)' applies to $Account via: $($h.AppliesVia)" -ForegroundColor Yellow
        if ($h.GPO -match 'SBS|Small Business') { Write-Host '     Legacy SBS policy - if folders should not be redirected, remove the user from that group (or retire the GPO).' -ForegroundColor Yellow }
    }
    if ($hit) {
        Write-Host '  To stop it for this user: remove them from the group above in AD Users & Computers (or add a Deny "Apply group policy"' -ForegroundColor Cyan
        Write-Host '  for them on the GPO''s Delegation tab). Then point folders back (this option) and sign out/in.' -ForegroundColor Cyan
        Write-Host '  GPO Policy Removal default = "Leave folder in new location" - unlinking alone does NOT bring folders back.' -ForegroundColor DarkYellow
    }
    return $src
}

function Invoke-FolderRedirectionReset {
    Write-Title 'Folder redirection - show source GPO / point folders back to the local profile'
    Write-Host '  Use when a user''s Desktop/Documents are redirected to a server share and should not be.' -ForegroundColor Gray
    Write-Host '  FIRST stop the GPO (unlink / security-filter / set "redirect back on policy removal"), or it re-redirects at next sign-in.' -ForegroundColor DarkYellow
    $profs = @(Get-CimInstance Win32_UserProfile | Where-Object { -not $_.Special -and $_.LocalPath -like '*\Users\*' -and $_.LocalPath -notmatch '\.old_' } | Sort-Object LastUseTime -Descending)
    for ($i = 0; $i -lt $profs.Count; $i++) {
        $u = try { (New-Object Security.Principal.SecurityIdentifier($profs[$i].SID)).Translate([Security.Principal.NTAccount]).Value } catch { $profs[$i].SID }
        $profs[$i] | Add-Member NoteProperty Account $u -Force
        Write-Host ("   {0,2}. {1,-35} {2,-28} Signed in: {3}" -f ($i + 1), $u, $profs[$i].LocalPath, $profs[$i].Loaded)
    }
    $n = Read-Int '  User number (0 = cancel)' 0
    if ($n -lt 1 -or $n -gt $profs.Count) { return }
    $p = $profs[$n - 1]; $loadedHere = $false
    $root = "Registry::HKEY_USERS\$($p.SID)"
    if (-not (Test-Path $root)) {
        & reg.exe load "HKU\SDSI_FR" "$($p.LocalPath)\NTUSER.DAT" 2>$null | Out-Null
        if ($LASTEXITCODE -ne 0) { Write-Host '  Could not load the user''s registry hive.' -ForegroundColor Red; return }
        $root = 'Registry::HKEY_USERS\SDSI_FR'; $loadedHere = $true
    }
    try {
        $usf = "$root\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"
        $shf = "$root\Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"
        $map = [ordered]@{ Desktop = 'Desktop'; Personal = 'Documents'; 'My Pictures' = 'Pictures'; 'My Music' = 'Music'; 'My Video' = 'Videos'; Favorites = 'Favorites'
                           '{374DE290-123F-4565-9164-39C4925E467B}' = 'Downloads'; AppData = 'AppData\Roaming'; 'Start Menu' = 'AppData\Roaming\Microsoft\Windows\Start Menu' }
        $cur = Get-ItemProperty $usf -ErrorAction SilentlyContinue
        $rows = foreach ($k in $map.Keys) { $v = "$($cur.$k)"; if ($v) { [pscustomobject]@{ Folder = $map[$k]; Key = $k; Target = $v; Redirected = ($v -match '^\\\\') } } }
        Write-Sub "Folder locations for $($p.Account)"
        $rows | Format-Table Folder, Target, Redirected -AutoSize -Wrap
        $red = @($rows | Where-Object Redirected)
        $null = Show-FolderRedirectionSource -Sid $p.SID -Account $p.Account
        if (-not $red) { Write-Host '  Nothing is redirected to a network share right now (a GPO listed above as applying will redirect at next sign-in).' -ForegroundColor Green; return }
        Write-Host '  Manual cross-check: as the user  gpresult /h C:\temp\gp.html  ("Folder Redirection" section).' -ForegroundColor DarkGray

        if (-not (Confirm-Change "Point $(($red.Folder) -join ', ') for $($p.Account) back to $($p.LocalPath) (copy files from the server first if you choose).")) { return }
        $copy = Read-YesNo '  Copy the files from the server locations into the local folders first?' $true
        $logf = Join-Path (Get-OutDir 'ProfileRebuild') "FolderRedirReset_$((Split-Path $p.LocalPath -Leaf))_$(Get-Stamp).log"
        foreach ($r in $red) {
            $local = Join-Path $p.LocalPath $map[$r.Key]
            Ensure-Dir $local | Out-Null
            $srcPath = [Environment]::ExpandEnvironmentVariables(($r.Target -replace '%USERNAME%', (Split-Path $p.LocalPath -Leaf)))
            if ($copy) {
                if (Test-Path -LiteralPath $srcPath) {
                    & robocopy.exe $srcPath $local /E /XJ /R:1 /W:1 /COPY:DAT /DCOPY:T /XF desktop.ini /NP /NFL /NDL /LOG+:"$logf" | Out-Null
                    Write-Host "  Copied $srcPath -> $local (robocopy exit $LASTEXITCODE)" -ForegroundColor $(if ($LASTEXITCODE -lt 8) { 'Green' } else { 'Red' })
                } else { Write-Host "  Cannot reach $srcPath - folder repointed but nothing copied (copy it later)." -ForegroundColor Yellow }
            }
            Set-ItemProperty $usf -Name $r.Key -Value ('%USERPROFILE%\' + $map[$r.Key]) -Type ExpandString
            Set-ItemProperty $shf -Name $r.Key -Value $local -ErrorAction SilentlyContinue
        }
        Write-Host "`n  Done. Sign the user out and back in. Copy log: $logf" -ForegroundColor Green
        Write-Host '  If folders go back to the server after sign-in, the GPO is still applying to this user - fix the GPO first.' -ForegroundColor DarkYellow
        Write-Host '  Offline Files: if CSC is enabled only for redirection, you can disable it later (Sync Center > Manage offline files) once data is verified.' -ForegroundColor Gray
    } finally {
        if ($loadedHere) { $cur = $null; [gc]::Collect(); Start-Sleep 1; & reg.exe unload 'HKU\SDSI_FR' 2>$null | Out-Null }
    }
}

function Invoke-UserProfiles {
    Write-Title 'User profiles - size and last use'
    $sizes = Read-YesNo 'Calculate profile sizes (can be slow)?' $true
    $rows = Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue | Where-Object { -not $_.Special } | ForEach-Object {
        $name = try { (New-Object System.Security.Principal.SecurityIdentifier($_.SID)).Translate([System.Security.Principal.NTAccount]).Value } catch { $_.SID }
        [pscustomobject]@{
            User     = $name
            Path     = $_.LocalPath
            LastUsed = $_.LastUseTime
            Loaded   = $_.Loaded
            SizeGB   = if ($sizes) { [math]::Round(((Get-ChildItem -LiteralPath $_.LocalPath -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum)/1GB, 2) } else { $null }
        }
    }
    $rows | Sort-Object LastUsed | Format-Table -AutoSize
    $out = Join-Path (Get-OutDir 'Software') "UserProfiles_$(Get-Stamp).csv"
    $rows | Export-Csv $out -NoTypeInformation
    Write-Host "  Saved to $out. Remove stale profiles via System Properties > User Profiles (never delete C:\Users folders by hand)." -ForegroundColor DarkGray
}

function Invoke-WindowsUpdateList {
    Write-Title 'Windows Update - available updates (and optional install)'
    Write-Host '  Searching for updates (can take a few minutes)...' -ForegroundColor DarkGray
    try {
        $session  = New-Object -ComObject Microsoft.Update.Session
        $searcher = $session.CreateUpdateSearcher()
        $result   = $searcher.Search("IsInstalled=0 and IsHidden=0")
    } catch { Write-Host "  Windows Update search failed: $($_.Exception.Message)" -ForegroundColor Red; return }
    $list = foreach ($u in $result.Updates) {
        [pscustomobject]@{ KB = ($u.KBArticleIDs | ForEach-Object { "KB$_" }) -join ','; Title = $u.Title; SizeMB = [math]::Round($u.MaxDownloadSize/1MB); Severity = $u.MsrcSeverity; Downloaded = $u.IsDownloaded }
    }
    if (-not $list) { Write-Host '  No updates available.' -ForegroundColor Green }
    else { $list | Format-Table -AutoSize -Wrap }
    Write-Sub 'Last 10 update installs (history)'
    try {
        $count = $searcher.GetTotalHistoryCount()
        if ($count -gt 0) {
            $searcher.QueryHistory(0, [math]::Min(10, $count)) | ForEach-Object {
                [pscustomobject]@{ Date = $_.Date.ToLocalTime(); Result = @{1='InProgress';2='Succeeded';3='SucceededWithErrors';4='Failed';5='Aborted'}[[int]$_.ResultCode]; HResult = ('0x{0:X8}' -f $_.HResult); Title = $_.Title }
            } | Format-Table -AutoSize -Wrap
        }
    } catch { }
    if ($list -and (Read-YesNo "Download and install these $(@($list).Count) update(s) now?" $false)) {
        if (-not (Confirm-Change 'Download and install all listed Windows updates (no automatic reboot).')) { return }
        $coll = New-Object -ComObject Microsoft.Update.UpdateColl
        foreach ($u in $result.Updates) { if (-not $u.EulaAccepted) { $u.AcceptEula() }; [void]$coll.Add($u) }
        Write-Host '  Downloading...' -ForegroundColor Cyan
        $dl = $session.CreateUpdateDownloader(); $dl.Updates = $coll; [void]$dl.Download()
        Write-Host '  Installing...' -ForegroundColor Cyan
        $inst = $session.CreateUpdateInstaller(); $inst.Updates = $coll; $res = $inst.Install()
        Write-Host ("  Result code: {0}  Reboot required: {1}" -f $res.ResultCode, $res.RebootRequired) -ForegroundColor $(if ($res.ResultCode -eq 2) { 'Green' } else { 'Yellow' })
        if ($res.RebootRequired -and (Read-YesNo 'Reboot now?' $false)) { Restart-Computer -Force }
    }
}

# ---------- QUICK FIXES ---------------------------------------------------------------

function Invoke-SfcDism {
    Write-Title '[!] System file repair (DISM RestoreHealth + SFC)'
    if (-not (Confirm-Change 'Run DISM /RestoreHealth then SFC /scannow (15-45 minutes).')) { return }
    $log = Join-Path (Get-OutDir 'Repair') "SFC-DISM_$(Get-Stamp).log"
    Write-Host '  DISM /RestoreHealth...' -ForegroundColor Cyan
    Dism.exe /Online /Cleanup-Image /RestoreHealth 2>&1 | Tee-Object -FilePath $log -Append | Write-Host
    Write-Host '  SFC /scannow...' -ForegroundColor Cyan
    sfc.exe /scannow 2>&1 | ForEach-Object { ($_ -replace "`0", '') } | Where-Object { $_.Trim() } | Tee-Object -FilePath $log -Append | Write-Host
    Write-Host "  Log: $log  (SFC details: C:\Windows\Logs\CBS\CBS.log)" -ForegroundColor Green
}

function Invoke-PostUpdateBlackScreen {
    Write-Title 'Black screen / stuck sign-in after a Windows Update (AppReadiness, Explorer, pending servicing)'
    $since = (Get-Date).AddDays(-2)
    $hits = New-Object System.Collections.ArrayList
    Write-Sub 'Recent reboots and how long the PC had been up before them'
    $up = Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'EventLog'; Id = 6013; StartTime = (Get-Date).AddDays(-14) } -ErrorAction SilentlyContinue |
        ForEach-Object { [pscustomobject]@{ Time = $_.TimeCreated; UptimeDays = [math]::Round([int]($_.Properties[4].Value)/86400, 1) } } | Sort-Object Time
    $maxUp = ($up | Measure-Object UptimeDays -Maximum).Maximum
    if ($maxUp) { Write-Host "  Longest uptime seen in the last 14 days: $maxUp days" }
    if ($maxUp -ge 30) { [void]$hits.Add("PC ran $maxUp days without a reboot - months of staged updates applied at once (slow, multiple reboots, heavy first sign-in).") }
    Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'User32'; Id = 1074; StartTime = $since } -ErrorAction SilentlyContinue |
        Select-Object -First 8 TimeCreated, @{n='By';e={($_.Properties[0].Value -split '\\')[-1]}}, @{n='User';e={$_.Properties[6].Value}}, @{n='Type';e={$_.Properties[4].Value}} | Format-Table -AutoSize | Out-Host

    Write-Sub 'Updates installed by servicing in the last 2 days'
    Get-WinEvent -FilterHashtable @{ LogName = 'Setup'; StartTime = $since } -ErrorAction SilentlyContinue |
        ForEach-Object { if ($_.ToXml() -match '(KB\d{6,8})') { [pscustomobject]@{ Time = $_.TimeCreated; KB = $Matches[1]; Id = $_.Id } } } |
        Sort-Object KB -Unique | Format-Table -AutoSize | Out-Host
    $pend = @()
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $pend += 'CBS' }
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $pend += 'Windows Update' }
    if ($pend) { [void]$hits.Add("Another reboot is still pending ($($pend -join ', ')) - do a full RESTART (not Shut down) so servicing can finish.") }
    $hb = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' -ErrorAction SilentlyContinue).HiberbootEnabled
    if ($hb -eq 1) { Write-Host '  Fast Startup is ON - "Shut down" does not fully restart Windows; use Restart.' -ForegroundColor DarkYellow }

    Write-Sub 'AppReadiness (prepares apps at first sign-in after an update - the usual cause of a black screen)'
    $ar = Get-Service AppReadiness -ErrorAction SilentlyContinue
    if ($ar) { Write-Host "  AppReadiness service: $($ar.Status)" }
    $arEv = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 7011, 10029; StartTime = $since } -ErrorAction SilentlyContinue | Where-Object { $_.Message -match 'AppReadiness' })
    if ($arEv) {
        Write-Host "  AppReadiness timeout/hang events: $($arEv.Count) (first $($arEv[-1].TimeCreated), last $($arEv[0].TimeCreated))" -ForegroundColor Yellow
        [void]$hits.Add("AppReadiness is hung ($($arEv.Count) timeout events) - Explorer/Start can't load, so users get a black screen after sign-in.")
    }
    $arLog = Get-WinEvent -LogName 'Microsoft-Windows-AppReadiness/Admin' -MaxEvents 200 -ErrorAction SilentlyContinue | Where-Object { $_.TimeCreated -ge $since -and $_.Level -le 2 }
    if ($arLog) { $arLog | Select-Object -First 8 TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap | Out-Host }

    Write-Sub 'Signed-in sessions and whether Explorer is running in them'
    $sess = Get-CimInstance Win32_Process -Filter "Name='winlogon.exe'" -ErrorAction SilentlyContinue | Select-Object -ExpandProperty SessionId -Unique
    $exp = Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction SilentlyContinue
    foreach ($s in $sess) {
        $e = $exp | Where-Object SessionId -eq $s | Select-Object -First 1
        $own = if ($e) { $o = Invoke-CimMethod -InputObject $e -MethodName GetOwner -ErrorAction SilentlyContinue; "$($o.Domain)\$($o.User)" } else { '' }
        $logon = Get-CimInstance Win32_Process -Filter "Name='LogonUI.exe' AND SessionId=$s" -ErrorAction SilentlyContinue
        Write-Host ("  Session {0}: Explorer {1} {2} {3}" -f $s, $(if ($e) { 'RUNNING' } else { 'NOT running' }), $own, $(if ($logon) { '(at sign-in screen)' } else { '' }))
        if (-not $e -and -not $logon -and $s -ne 0) { [void]$hits.Add("Session $s is signed in but Explorer is not running - that is the black screen.") }
    }
    $os = Get-CimInstance Win32_OperatingSystem
    $memPct = [math]::Round((($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / $os.TotalVisibleMemorySize) * 100)
    if ($memPct -ge 90) { [void]$hits.Add("RAM is $memPct% used of $([math]::Round($os.TotalVisibleMemorySize/1MB,1)) GB - first sign-in after updates will be very slow.") }
    $gpu = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($gpu) { Write-Host "  Graphics: $($gpu.Name) driver $($gpu.DriverVersion)" -ForegroundColor Gray }

    Write-Sub 'LIKELY CAUSES'
    if ($hits.Count) { $hits | ForEach-Object { Write-Host "  - $_" -ForegroundColor Yellow } } else { Write-Host '  Nothing obvious from here.' -ForegroundColor Green }
    Write-Host "`n  At the PC: Ctrl+Shift+Esc > Run new task > explorer.exe brings the desktop back for that session." -ForegroundColor Cyan

    Write-Host "`n  Fixes (each asks first):" -ForegroundColor Cyan
    Write-Host '   1. Restart the AppReadiness service (kills it if hung)'
    Write-Host '   2. Re-register the Start menu / shell apps for all users (StartMenuExperienceHost, ShellExperienceHost, Search)'
    Write-Host '   3. Full restart now (not Shut down) so pending servicing finishes'
    $pick = Read-List '  Fix numbers (comma separated, blank = none)' ''
    foreach ($p in $pick) {
        switch ($p) {
            '1' { if (Confirm-Change 'Stop (force) and start the AppReadiness service.') {
                    $svc = Get-CimInstance Win32_Service -Filter "Name='AppReadiness'"
                    if ($svc.ProcessId) { Stop-Process -Id $svc.ProcessId -Force -ErrorAction SilentlyContinue }
                    Stop-Service AppReadiness -Force -ErrorAction SilentlyContinue; Start-Sleep 2; Start-Service AppReadiness -ErrorAction SilentlyContinue
                    Write-Host "  AppReadiness: $((Get-Service AppReadiness).Status). Have the user sign out/in (or start explorer.exe from Task Manager)." -ForegroundColor Green } }
            '2' { if (Confirm-Change 'Re-register Start menu / shell / search system apps for all users.') {
                    foreach ($n in 'Microsoft.Windows.StartMenuExperienceHost', 'Microsoft.Windows.ShellExperienceHost', 'MicrosoftWindows.Client.CBS', 'Microsoft.Windows.Search', 'Microsoft.UI.Xaml.CBS') {
                        Get-AppxPackage -AllUsers -Name $n -ErrorAction SilentlyContinue | ForEach-Object {
                            try { Add-AppxPackage -Register (Join-Path $_.InstallLocation 'AppxManifest.xml') -DisableDevelopmentMode -ForceApplicationShutdown -ErrorAction Stop; Write-Host "  Re-registered $($_.Name)" -ForegroundColor Green }
                            catch { Write-Host "  $($_.Exception.Message)" -ForegroundColor DarkYellow } } }
                    Write-Host '  Note: registration from an admin/SYSTEM session applies to that account; for the user, sign them out/in afterwards.' -ForegroundColor Gray } }
            '3' { if (Confirm-Change 'Restart this PC NOW (users lose unsaved work).') { & shutdown.exe /r /t 5 /c 'SDSI ToolKit: restart to finish Windows Update' } }
        }
    }
}

function Invoke-SpoolerReset {
    Write-Title '[!] Print spooler reset (clear stuck print jobs)'
    $jobs = @(Get-ChildItem "$env:SystemRoot\System32\spool\PRINTERS" -File -ErrorAction SilentlyContinue)
    Write-Host "  Spooled job files waiting: $($jobs.Count)"
    Get-Printer -ErrorAction SilentlyContinue | Select-Object Name, DriverName, PortName, PrinterStatus, JobCount | Format-Table -AutoSize
    if (Confirm-Change 'Stop the Print Spooler, delete ALL queued print jobs, start it again.') {
        Stop-Service Spooler -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
        Remove-Item "$env:SystemRoot\System32\spool\PRINTERS\*" -Force -ErrorAction SilentlyContinue
        Start-Service Spooler -ErrorAction SilentlyContinue
        Get-Service Spooler | Format-Table Name, Status -AutoSize
    }
}

function Invoke-NetworkReset {
    Write-Title '[!] Network quick fixes'
    Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.NetAdapter.Status -eq 'Up' } |
        Select-Object InterfaceAlias, @{n='IPv4';e={$_.IPv4Address.IPAddress -join ','}}, @{n='Gateway';e={$_.IPv4DefaultGateway.NextHop -join ','}}, @{n='DNS';e={$_.DNSServer.ServerAddresses -join ','}} | Format-Table -AutoSize
    Write-Host '  1. Light: flush DNS cache + re-register DNS (safe, no disconnect)'
    Write-Host '  2. Renew: release/renew DHCP (drops the connection briefly - do NOT pick this over remote control unless you can wait)'
    Write-Host '  3. Full: Winsock + TCP/IP reset (needs a REBOOT; resets static IPs on some adapters)'
    switch ("$(Read-Default 'Choose 1-3 (blank = cancel)' '')") {
        '1' { ipconfig /flushdns | Write-Host; ipconfig /registerdns | Write-Host; Clear-DnsClientCache -ErrorAction SilentlyContinue; Write-Host '  Done.' -ForegroundColor Green }
        '2' { if (Confirm-Change 'Release and renew DHCP leases (connection drops for a few seconds).') { ipconfig /release | Out-Null; ipconfig /renew | Write-Host } }
        '3' {
            if (Confirm-Change 'Reset Winsock and the TCP/IP stack - REBOOT REQUIRED. Note any static IP settings first!') {
                $bk = Join-Path (Get-OutDir 'Network') "IPConfig_before_reset_$(Get-Stamp).txt"
                ipconfig /all | Out-File $bk; Write-Host "  Current IP config saved to $bk"
                netsh winsock reset | Write-Host
                netsh int ip reset | Write-Host
                if (Read-YesNo 'Reboot now?' $false) { Restart-Computer -Force }
            }
        }
    }
}

function Invoke-TeamsCacheClear {
    Write-Title '[!] Microsoft Teams cache clear (classic + new Teams, current user)'
    $paths = @("$env:APPDATA\Microsoft\Teams", "$env:LOCALAPPDATA\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\MSTeams")
    $paths | ForEach-Object { Write-Host ("  {0}  exists: {1}" -f $_, (Test-Path $_)) }
    Write-Host "  Runs for: $env:USERNAME (run the toolkit as the affected user)." -ForegroundColor DarkGray
    if (Confirm-Change 'Close Teams and delete its cache folders for this user (chats are in the cloud, nothing is lost).') {
        Get-Process -Name 'Teams','ms-teams','msteams' -ErrorAction SilentlyContinue | Stop-Process -Force
        Start-Sleep -Seconds 3
        foreach ($p in $paths) { if (Test-Path $p) { Remove-Item "$p\*" -Recurse -Force -ErrorAction SilentlyContinue; Write-Host "  Cleared $p" -ForegroundColor Green } }
        Write-Host '  Start Teams again - first launch will be slower while it rebuilds.' -ForegroundColor DarkGray
    }
}

function Invoke-OutlookLoadingProfile {
    Write-Title 'Outlook stuck on "Loading Profile" - diagnose + fix'
    # Work on the signed-in user (the ToolKit usually runs elevated as a different admin account)
    $exp = Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction SilentlyContinue | Select-Object -First 1
    $owner = if ($exp) { Invoke-CimMethod -InputObject $exp -MethodName GetOwner -ErrorAction SilentlyContinue } else { $null }
    $acct = if ($owner -and $owner.User) { "$($owner.Domain)\$($owner.User)" } else { "$env:USERDOMAIN\$env:USERNAME" }
    $sid = try { (New-Object Security.Principal.NTAccount($acct)).Translate([Security.Principal.SecurityIdentifier]).Value } catch { $null }
    $hku = if ($sid -and (Test-Path "Registry::HKEY_USERS\$sid")) { "Registry::HKEY_USERS\$sid" } else { 'HKCU:' }
    $prof = if ($sid) { (Get-CimInstance Win32_UserProfile -Filter "SID='$sid'" -ErrorAction SilentlyContinue).LocalPath } else { $env:USERPROFILE }
    Write-Host "  Signed-in user: $acct   Profile: $prof" -ForegroundColor Gray
    $off = "$hku\Software\Microsoft\Office\16.0"
    $hits = New-Object System.Collections.ArrayList

    Write-Sub 'Outlook processes'
    $ol = Get-CimInstance Win32_Process -Filter "Name='OUTLOOK.EXE'" -ErrorAction SilentlyContinue
    if ($ol) {
        $ol | ForEach-Object { $o = Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction SilentlyContinue
            [pscustomobject]@{ PID = $_.ProcessId; User = "$($o.Domain)\$($o.User)"; Started = $_.CreationDate; CommandLine = $_.CommandLine } } | Format-Table -AutoSize -Wrap
        if (@($ol).Count -gt 1) { [void]$hits.Add('More than one OUTLOOK.EXE running - a hung background copy blocks the profile. Kill them all and retry.') }
    } else { Write-Host '  Outlook is not running.' }

    Write-Sub 'Compatibility mode / run-as-admin flags on OUTLOOK.EXE'
    $layers = foreach ($root in "$hku\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers", 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers') {
        $p = Get-ItemProperty $root -ErrorAction SilentlyContinue
        if ($p) { $p.PSObject.Properties | Where-Object { $_.Name -match 'OUTLOOK\.EXE$' } | ForEach-Object { [pscustomobject]@{ Key = $root -replace '^Registry::',''; Exe = $_.Name; Flags = $_.Value } } }
    }
    if ($layers) { $layers | Format-Table -AutoSize -Wrap; [void]$hits.Add('OUTLOOK.EXE has compatibility / run-as-admin flags - a classic "Loading Profile" hang. Remove them (fix option 1).') } else { Write-Host '  None (good).' }

    Write-Sub 'Microsoft 365 sign-in broker (WAM / AAD.BrokerPlugin)'
    $bp = Get-AppxPackage -AllUsers -Name Microsoft.AAD.BrokerPlugin -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($bp) { Write-Host "  BrokerPlugin $($bp.Version)  Status: $($bp.Status)" } else { Write-Host '  Microsoft.AAD.BrokerPlugin NOT found - Microsoft 365 sign-in cannot work.' -ForegroundColor Red; [void]$hits.Add('AAD BrokerPlugin missing - re-register it (fix option 2).') }
    $bpErr = Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Microsoft-Windows-AppModel-State'; StartTime = (Get-Date).AddDays(-7) } -ErrorAction SilentlyContinue | Where-Object { $_.Message -match 'AAD\.BrokerPlugin' }
    $aadErr = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-AAD/Operational'; Level = 2; StartTime = (Get-Date).AddDays(-2) } -MaxEvents 200 -ErrorAction SilentlyContinue
    if ($bpErr) { [void]$hits.Add("BrokerPlugin settings write failures x$(@($bpErr).Count) in 7 days - the sign-in broker's local data is likely corrupt (fix option 2).") }
    if ($aadErr) { Write-Host "  AAD/Operational errors (48h): $(@($aadErr).Count)"; $aadErr | Select-Object -First 5 TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0..1] -join ' '}} | Format-Table -AutoSize -Wrap; if (@($aadErr).Count -ge 5) { [void]$hits.Add("Many Entra sign-in errors (AAD/Operational x$(@($aadErr).Count)) - token/broker problem (fix option 2).") } }
    $ds = (& dsregcmd /status) 2>$null
    $prt = ($ds | Select-String 'AzureAdPrt\s*:\s*(\w+)').Matches.Groups[1].Value
    if ($prt) { Write-Host "  AzureAdPrt: $prt  (from the context this ran in)" }

    Write-Sub 'Outlook profiles / OST / PST'
    $profKey = "$off\Outlook\Profiles"
    $profiles = @(Get-ChildItem $profKey -ErrorAction SilentlyContinue | Select-Object -ExpandProperty PSChildName)
    $def = (Get-ItemProperty "$off\Outlook" -ErrorAction SilentlyContinue).DefaultProfile
    Write-Host "  Profiles: $(if ($profiles) { $profiles -join ', ' } else { '(none)' })   Default: $def"
    if ($prof) {
        Get-ChildItem "$prof\AppData\Local\Microsoft\Outlook" -Include *.ost, *.pst -Recurse -ErrorAction SilentlyContinue |
            Select-Object Name, @{n='GB';e={[math]::Round($_.Length/1GB,2)}}, LastWriteTime | Format-Table -AutoSize
        $big = Get-ChildItem "$prof\AppData\Local\Microsoft\Outlook" -Include *.ost, *.pst -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Length -gt 45GB }
        if ($big) { [void]$hits.Add('An OST/PST is over 45 GB - near the 50 GB limit; Outlook can hang opening it.') }
    }

    Write-Sub 'Add-ins set to load at startup'
    $addins = foreach ($r in "$hku\Software\Microsoft\Office\Outlook\Addins", 'HKLM:\SOFTWARE\Microsoft\Office\Outlook\Addins', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Office\Outlook\Addins') {
        Get-ChildItem $r -ErrorAction SilentlyContinue | ForEach-Object { $p = Get-ItemProperty $_.PSPath; if ($p.LoadBehavior -eq 3) { [pscustomobject]@{ AddIn = $_.PSChildName; Name = $p.FriendlyName } } }
    }
    if ($addins) { $addins | Format-Table -AutoSize } else { Write-Host '  None found in registry.' }

    Write-Sub 'Hardware graphics acceleration (hangs after graphics driver changes)'
    $hw = (Get-ItemProperty "$off\Common\Graphics" -ErrorAction SilentlyContinue).DisableHardwareAcceleration
    Write-Host "  DisableHardwareAcceleration = $(if ($null -eq $hw) { '(not set = acceleration ON)' } else { $hw })"

    Write-Sub 'Connectivity to Microsoft 365'
    foreach ($h in 'outlook.office365.com', 'login.microsoftonline.com', 'autodiscover-s.outlook.com') {
        $t = Test-NetConnection $h -Port 443 -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
        Write-Host ("  {0,-32} {1}" -f $h, $(if ($t.TcpTestSucceeded) { 'OK' } else { 'FAILED' })) -ForegroundColor $(if ($t.TcpTestSucceeded) { 'Green' } else { 'Red' })
        if (-not $t.TcpTestSucceeded) { [void]$hits.Add("Cannot reach $h on 443 - check DNS / proxy / firewall.") }
    }

    Write-Sub 'LIKELY CAUSES'
    if ($hits.Count) { $hits | ForEach-Object { Write-Host "  - $_" -ForegroundColor Yellow } } else { Write-Host '  Nothing obvious - try options 3-5 in order.' -ForegroundColor Green }

    Write-Host "`n  Fixes (Outlook is closed first; each asks before changing anything):" -ForegroundColor Cyan
    Write-Host '   1. Remove compatibility / run-as-admin flags from OUTLOOK.EXE'
    Write-Host '   2. Repair Microsoft 365 sign-in (re-register AAD BrokerPlugin + clear Office identity cache) - user signs in again'
    Write-Host '   3. Turn off Outlook hardware graphics acceleration'
    Write-Host '   4. Start Outlook in Safe Mode (no add-ins) / reset navigation pane (/resetnavpane)'
    Write-Host '   5. Rename the OST so it rebuilds (re-downloads mail)'
    Write-Host '   6. Create a new Outlook profile (opens Mail control panel)'
    $pick = Read-List '  Pick fix numbers (comma separated, blank = none)' ''
    if (-not $pick) { return }
    $stopOutlook = { Get-Process OUTLOOK -ErrorAction SilentlyContinue | Stop-Process -Force; Start-Sleep 2 }
    foreach ($p in $pick) {
        switch ($p) {
            '1' { if (Confirm-Change 'Delete AppCompat Layers values for OUTLOOK.EXE.') {
                    foreach ($l in $layers) { Remove-ItemProperty -Path ("Registry::" + ($l.Key -replace '^HKLM:\\','HKEY_LOCAL_MACHINE\')) -Name $l.Exe -ErrorAction SilentlyContinue }
                    Write-Host '  Compatibility flags removed.' -ForegroundColor Green } }
            '2' { if (Confirm-Change "Close Outlook/Office, re-register AAD BrokerPlugin, clear Office identity cache for $acct (user must sign in to Office again).") {
                    & $stopOutlook
                    if ($prof) {
                        foreach ($d in "$prof\AppData\Local\Microsoft\IdentityCache", "$prof\AppData\Local\Microsoft\OneAuth", "$prof\AppData\Local\Packages\Microsoft.AAD.BrokerPlugin_cw5n1h2txyewy\AC\TokenBroker\Accounts") {
                            if (Test-Path $d) { Rename-Item $d "$(Split-Path $d -Leaf).old_$(Get-Stamp)" -ErrorAction SilentlyContinue; Write-Host "  Renamed $d" } }
                    }
                    Remove-Item "$off\Common\Identity\Identities\*" -Recurse -Force -ErrorAction SilentlyContinue
                    $pkg = Get-AppxPackage -AllUsers -Name Microsoft.AAD.BrokerPlugin -ErrorAction SilentlyContinue | Select-Object -First 1
                    $man = if ($pkg) { Join-Path $pkg.InstallLocation 'AppxManifest.xml' } else { "$env:SystemRoot\SystemApps\Microsoft.AAD.BrokerPlugin_cw5n1h2txyewy\AppxManifest.xml" }
                    if ($acct -ieq "$env:USERDOMAIN\$env:USERNAME") { Add-AppxPackage -Register $man -DisableDevelopmentMode -ForceApplicationShutdown -ErrorAction SilentlyContinue; Write-Host '  BrokerPlugin re-registered.' -ForegroundColor Green }
                    else { Write-Host "  Re-register must run AS THE USER: Add-AppxPackage -Register `"$man`" -DisableDevelopmentMode -ForceApplicationShutdown" -ForegroundColor DarkYellow }
                    Write-Host '  Have the user open Outlook and sign in when prompted.' -ForegroundColor Green } }
            '3' { if (Confirm-Change 'Set Office DisableHardwareAcceleration = 1 for the signed-in user.') {
                    New-Item "$off\Common\Graphics" -Force | Out-Null; Set-ItemProperty "$off\Common\Graphics" -Name DisableHardwareAcceleration -Value 1 -Type DWord
                    Write-Host '  Hardware acceleration OFF.' -ForegroundColor Green } }
            '4' { & $stopOutlook; $exe = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\OUTLOOK.EXE' -ErrorAction SilentlyContinue).'(default)'
                  if (-not $exe) { Write-Host '  OUTLOOK.EXE not found.' -ForegroundColor Red; break }
                  $sw = if (Read-YesNo '  Also reset the navigation pane (/resetnavpane)?' $false) { '/safe /resetnavpane' } else { '/safe' }
                  Write-Host "  Run AS THE USER (not elevated): `"$exe`" $sw" -ForegroundColor Cyan
                  if ($acct -ieq "$env:USERDOMAIN\$env:USERNAME" -and -not (Test-IsAdmin)) { Start-Process $exe $sw } }
            '5' { if (Confirm-Change 'Close Outlook and rename every .ost so Outlook rebuilds it (mail re-downloads from Microsoft 365).') {
                    & $stopOutlook
                    Get-ChildItem "$prof\AppData\Local\Microsoft\Outlook" -Filter *.ost -ErrorAction SilentlyContinue | ForEach-Object { Rename-Item $_.FullName "$($_.Name).old_$(Get-Stamp)"; Write-Host "  Renamed $($_.Name)" } } }
            '6' { Write-Host '  Opening Mail control panel - Show Profiles > Add, then set "Always use this profile".' -ForegroundColor Cyan
                  $mlcfg = Get-ChildItem "${env:ProgramFiles}\Microsoft Office\root\Office16\MLCFG32.CPL", "${env:ProgramFiles(x86)}\Microsoft Office\root\Office16\MLCFG32.CPL" -ErrorAction SilentlyContinue | Select-Object -First 1
                  if ($mlcfg) { Start-Process control.exe "`"$($mlcfg.FullName)`"" } else { Start-Process control.exe 'mlcfg32.cpl' } }
        }
    }
}

function Invoke-OfficeRepair {
    Write-Title '[!] Microsoft 365 Apps / Office - quick or online repair'
    $c2r = "$env:ProgramFiles\Common Files\Microsoft Shared\ClickToRun\OfficeClickToRun.exe"
    $cfg = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
    if (-not (Test-Path $c2r) -or -not $cfg) { Write-Host '  Click-to-Run Office not found on this machine.' -ForegroundColor Red; return }
    Write-Host ("  Version {0}  Channel {1}  Platform {2}  Products {3}" -f $cfg.VersionToReport, ($cfg.UpdateChannel -replace '.*/',''), $cfg.Platform, $cfg.ProductReleaseIds)
    $type = "$(Read-Default 'Q = Quick repair (offline, minutes)  O = Online repair (re-downloads Office)  blank = cancel' '')".ToUpper()
    if ($type -notin 'Q','O') { return }
    $rt = if ($type -eq 'Q') { 'QuickRepair' } else { 'FullRepair' }
    if (Confirm-Change "Run Office $rt - all Office apps will be CLOSED.") {
        $culture = (($cfg.ClientCulture) -split ',')[0]; if (-not $culture) { $culture = 'en-us' }
        Start-Process -FilePath $c2r -ArgumentList "scenario=Repair platform=$($cfg.Platform) culture=$culture forceappshutdown=True RepairType=$rt DisplayLevel=True" -Wait
        Write-Host '  Repair launched/completed - follow the Office repair window.' -ForegroundColor Green
    }
}

function Invoke-OneDriveReset {
    Write-Title '[!] OneDrive reset (current user)'
    $exe = @("$env:LOCALAPPDATA\Microsoft\OneDrive\OneDrive.exe", "$env:ProgramFiles\Microsoft OneDrive\OneDrive.exe", "${env:ProgramFiles(x86)}\Microsoft OneDrive\OneDrive.exe") | Where-Object { Test-Path $_ } | Select-Object -First 1
    if (-not $exe) { Write-Host '  OneDrive.exe not found.' -ForegroundColor Red; return }
    Write-Host "  $exe  (version $((Get-Item $exe).VersionInfo.FileVersion))"
    Get-ChildItem 'HKCU:\Software\Microsoft\OneDrive\Accounts' -ErrorAction SilentlyContinue | ForEach-Object { $p = Get-ItemProperty $_.PSPath; if ($p.UserEmail) { Write-Host "  Account: $($p.UserEmail)  Folder: $($p.UserFolder)" } }
    if (Confirm-Change 'Reset OneDrive for this user (re-syncs everything; files are NOT deleted).') {
        Start-Process $exe -ArgumentList '/reset' -Wait
        Start-Sleep -Seconds 5
        # Start through explorer.exe so OneDrive is NOT elevated (an elevated OneDrive breaks file opens)
        if (-not (Get-Process OneDrive -ErrorAction SilentlyContinue)) { Start-Process -FilePath "$env:SystemRoot\explorer.exe" -ArgumentList "`"$exe`"" }
        Write-Host '  Reset done - OneDrive will re-sync. Large libraries can take a while.' -ForegroundColor Green
    }
}

function Invoke-OneDriveFileAccess {
    Write-Title 'OneDrive "can''t open file" errors - diagnose + repair'
    Write-Host '  For Explorer errors on OneDrive/SharePoint files such as:' -ForegroundColor DarkGray
    Write-Host '    "The data area passed to a system call is too small" (0x8007007A)' -ForegroundColor DarkGray
    Write-Host '    "The cloud file provider is not running" (0x8007016A) / "The cloud operation was unsuccessful"' -ForegroundColor DarkGray
    $test = Read-Default 'Full path of a file that gave the error (blank = skip the test open)' ''
    $scan = if ($Script:Auto) { $false } else { Read-YesNo 'Scan the sync folders (online-only / stuck / long paths / bad names)?' $true }
    Invoke-Tool 'Repair-OneDriveFileAccess' ([ordered]@{
        OutputPath = (Get-OutDir 'OneDrive'); TestPath = $test; ScanFiles = $scan; ReportOnly = [bool]$Script:Auto
    }) | Out-Null
}

# ---------- MICROSOFT / SYSINTERNALS / NIRSOFT TOOLS ------------------------------------
# Tools are DOWNLOADED from their official sites when you pick them (nothing third-party is
# bundled in this file) into C:\temp\Tools. Sysinternals tools are Microsoft-licensed (the
# command-line ones are run with -accepteula); NirSoft tools are freeware by Nir Sofer.
# NirSoft password-recovery tools are deliberately NOT included - EDR (SentinelOne etc.)
# flags them as hack tools.

$Script:ToolLinks = [ordered]@{
    'Sysinternals Suite (all tools)'   = 'https://download.sysinternals.com/files/SysinternalsSuite.zip'
    'Sysinternals live (single tools)' = 'https://live.sysinternals.com/'
    'Sysinternals docs'                = 'https://learn.microsoft.com/sysinternals/downloads/'
    'NirSoft utilities'                = 'https://www.nirsoft.net/utils/index.html'
    'Microsoft TSS (support logs)'     = 'https://aka.ms/getTSS'
    'Microsoft SetupDiag'              = 'https://go.microsoft.com/fwlink/?linkid=870142'
    'Microsoft Update Catalog'         = 'https://www.catalog.update.microsoft.com/'
    'Microsoft SaRA / Get Help'        = 'https://aka.ms/SaRA-FirstScreen'
    'WizTree (disk space, free personal use)' = 'https://diskanalyzer.com/download'
    'Ookla Speedtest CLI'              = 'https://www.speedtest.net/apps/cli'
}

function Get-ToolsDir([string]$Sub) { Get-OutDir ("Tools\" + $Sub) }

function Get-WebFile([string]$Url, [string]$Dest) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    try {
        $ProgressPreference = 'SilentlyContinue'
        Invoke-WebRequest -Uri $Url -OutFile $Dest -UseBasicParsing -ErrorAction Stop
        return (Test-Path $Dest) -and ((Get-Item $Dest).Length -gt 0)
    } catch { Write-Host "  Download failed ($Url): $($_.Exception.Message)" -ForegroundColor Red; return $false }
}

function Get-SysinternalsTool([string]$Exe) {
    $dir = Get-ToolsDir 'Sysinternals'
    $path = Join-Path $dir $Exe
    if (Test-Path $path) { return $path }
    # Prefer a copy already on the machine (e.g. an extracted Sysinternals Suite)
    $local = Get-Command $Exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($local) { return $local.Source }
    Write-Host "  Downloading $Exe from live.sysinternals.com..." -ForegroundColor DarkGray
    if (Get-WebFile "https://live.sysinternals.com/$Exe" $path) { return $path }
    return $null
}

function Get-NirSoftTool([string]$Name, [string]$Exe) {
    $dir = Get-ToolsDir "NirSoft\$Name"
    $exePath = Join-Path $dir $Exe
    if (Test-Path $exePath) { return $exePath }
    $zip = Join-Path $dir "$Name.zip"
    $urls = @()
    if ([Environment]::Is64BitOperatingSystem) { $urls += "https://www.nirsoft.net/utils/$Name-x64.zip" }
    $urls += "https://www.nirsoft.net/utils/$Name.zip"
    foreach ($u in $urls) {
        Write-Host "  Downloading $u ..." -ForegroundColor DarkGray
        if (Get-WebFile $u $zip) {
            try { Expand-Archive -Path $zip -DestinationPath $dir -Force -ErrorAction Stop } catch { Write-Host "  Unzip failed: $($_.Exception.Message)" -ForegroundColor Red; continue }
            Remove-Item $zip -Force -ErrorAction SilentlyContinue
            $found = Get-ChildItem $dir -Filter $Exe -Recurse -File | Select-Object -First 1
            if ($found) { return $found.FullName }
        }
    }
    Write-Host "  Could not get $Name - download it manually from https://www.nirsoft.net/utils/ and put $Exe in $dir" -ForegroundColor Yellow
    return $null
}

function Confirm-Sysinternals {
    if ($Script:SysinternalsOk) { return $true }
    Write-Host '  Sysinternals tools are licensed by Microsoft (https://learn.microsoft.com/sysinternals/license-terms).' -ForegroundColor DarkGray
    $Script:SysinternalsOk = Read-YesNo 'Download/run Sysinternals tools and accept their license?' $true
    return $Script:SysinternalsOk
}

function Invoke-AutorunsReport {
    Write-Title 'Sysinternals Autoruns - startup / persistence report (non-Microsoft, signature-checked)'
    if (-not (Confirm-Sysinternals)) { return }
    $exe = Get-SysinternalsTool $(if ([Environment]::Is64BitOperatingSystem) { 'autorunsc64.exe' } else { 'autorunsc.exe' })
    if (-not $exe) { return }
    $csv = Join-Path (Get-OutDir 'Security') "Autoruns_${env:COMPUTERNAME}_$(Get-Stamp).csv"
    Write-Host '  Scanning all autostart locations (1-3 minutes)...' -ForegroundColor DarkGray
    # -a * all locations, -m hide Microsoft-signed, -s verify signatures, -h hashes, -c CSV, * all user profiles
    $raw = & $exe -accepteula -nobanner -a * -m -s -h -c '*' 2>$null
    $raw | Out-File $csv -Encoding UTF8
    $rows = $raw | ConvertFrom-Csv -ErrorAction SilentlyContinue
    $unsigned = $rows | Where-Object { $_.Signer -match 'Not verified|^\(Not verified\)' -or [string]::IsNullOrWhiteSpace($_.Signer) } | Where-Object { $_.'Image Path' }
    Write-Host "  $(@($rows).Count) non-Microsoft autostart entries; $(@($unsigned).Count) NOT signature-verified:" -ForegroundColor $(if ($unsigned) { 'Yellow' } else { 'Green' })
    $unsigned | Select-Object -First 40 Category, Entry, 'Image Path', Signer | Format-Table -AutoSize -Wrap
    Write-Host "  Full report: $csv  (open in Excel; or run Autoruns64.exe GUI from the tools menu)" -ForegroundColor Green
}

function Invoke-SigcheckScan {
    Write-Title 'Sysinternals Sigcheck - unsigned executables in user-writable folders'
    if (-not (Confirm-Sysinternals)) { return }
    $exe = Get-SysinternalsTool $(if ([Environment]::Is64BitOperatingSystem) { 'sigcheck64.exe' } else { 'sigcheck.exe' })
    if (-not $exe) { return }
    $roots = Read-List 'Folders to scan' "$env:SystemDrive\Users,$env:ProgramData,$env:SystemRoot\Temp"
    $csv = Join-Path (Get-OutDir 'Security') "UnsignedFiles_${env:COMPUTERNAME}_$(Get-Stamp).csv"
    $all = foreach ($r in $roots) {
        if (-not (Test-Path $r)) { continue }
        Write-Host "  Scanning $r ..." -ForegroundColor DarkGray
        # -u unsigned only, -e executable images only, -s recurse, -c CSV, -h hashes
        & $exe -accepteula -nobanner -u -e -s -h -c "$r" 2>$null | ConvertFrom-Csv -ErrorAction SilentlyContinue
    }
    $all | Export-Csv $csv -NoTypeInformation
    $all | Select-Object -First 40 Path, Publisher, 'File version', Date | Format-Table -AutoSize -Wrap
    Write-Host "  $(@($all).Count) unsigned executables. Full list with SHA256 hashes: $csv (check hashes in VirusTotal / your EDR)." -ForegroundColor $(if ($all) { 'Yellow' } else { 'Green' })
}

function Invoke-HandleSearch {
    Write-Title 'Sysinternals Handle - what is locking this file/folder?'
    if (-not (Confirm-Sysinternals)) { return }
    $exe = Get-SysinternalsTool $(if ([Environment]::Is64BitOperatingSystem) { 'handle64.exe' } else { 'handle.exe' })
    if (-not $exe) { return }
    $name = Read-Default 'File name, folder or part of a path' ''
    if (-not $name) { return }
    & $exe -accepteula -nobanner "$name" 2>&1 | Write-Host
    Write-Host '  To release a lock: close that program, or end the process listed (pid:) in Task Manager.' -ForegroundColor DarkGray
}

function Invoke-ProcDump {
    Write-Title 'Sysinternals ProcDump - capture a dump of a hung or crashing program'
    if (-not (Confirm-Sysinternals)) { return }
    $exe = Get-SysinternalsTool $(if ([Environment]::Is64BitOperatingSystem) { 'procdump64.exe' } else { 'procdump.exe' })
    if (-not $exe) { return }
    Get-Process | Sort-Object CPU -Descending | Select-Object -First 15 Name, Id, @{n='CPU_s';e={[math]::Round($_.CPU)}}, @{n='WS_MB';e={[math]::Round($_.WS/1MB)}}, Responding | Format-Table -AutoSize
    $target = Read-Default 'Process name or PID' ''
    if (-not $target) { return }
    $mode = "$(Read-Default 'N = dump NOW (hung app)   C = wait and dump when it CRASHES' 'N')".ToUpper()
    $dir = Get-OutDir 'Dumps'
    if ($mode -eq 'C') { & $exe -accepteula -nobanner -ma -e -w "$target" "$dir" 2>&1 | Write-Host }
    else { & $exe -accepteula -nobanner -ma "$target" "$dir" 2>&1 | Write-Host }
    Write-Host "  Dumps: $dir  (send to the vendor, or open in WinDbg: !analyze -v)" -ForegroundColor Green
}

function Invoke-TcpConnections {
    Write-Title 'Network connections by process (Sysinternals TCPView CLI / built-in)'
    $rows = Get-NetTCPConnection -ErrorAction SilentlyContinue | Where-Object { $_.State -in 'Established','Listen' } | ForEach-Object {
        $p = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue
        [pscustomobject]@{ Process = $p.ProcessName; PID = $_.OwningProcess; State = $_.State; Local = "$($_.LocalAddress):$($_.LocalPort)"; Remote = "$($_.RemoteAddress):$($_.RemotePort)"; Path = $p.Path }
    }
    $rows | Where-Object State -eq 'Established' | Sort-Object Process | Format-Table Process, PID, Local, Remote -AutoSize
    Write-Sub 'Listening ports'
    $rows | Where-Object State -eq 'Listen' | Sort-Object { [int]($_.Local -replace '.*:','') } | Format-Table Process, PID, Local -AutoSize
    $out = Join-Path (Get-OutDir 'Network') "Connections_$(Get-Stamp).csv"
    $rows | Export-Csv $out -NoTypeInformation
    Write-Host "  Saved to $out. For a live GUI view use 'Download & launch a tool' > TCPView." -ForegroundColor DarkGray
}

function Invoke-NirSoftReports {
    Write-Title 'NirSoft crash / activity reports (HTML)'
    Write-Host '  BlueScreenView   - every BSOD minidump: stop code + the driver that caused it'
    Write-Host '  AppCrashView     - application crashes (WER) with faulting module'
    Write-Host '  TurnedOnTimesView- every power-on / shutdown / crash with the reason'
    Write-Host '  LastActivityView - what ran / was opened recently (IR timeline)'
    Write-Host '  USBDeview        - every USB device ever connected'
    Write-Host '  DriverView       - loaded drivers with versions / companies'
    Write-Host '  NirSoft tools are freeware by Nir Sofer (https://www.nirsoft.net) - downloaded now from nirsoft.net.' -ForegroundColor DarkGray
    $pick = Read-List 'Which reports? (B,A,T,L,U,D or ALL)' 'B,A,T'
    if ($pick -contains 'ALL') { $pick = 'B','A','T','L','U','D' }
    $dir = Get-OutDir ("NirSoft\{0}_{1}" -f $env:COMPUTERNAME, (Get-Stamp))
    $map = @{
        'B' = @{ N = 'bluescreenview';    E = 'BlueScreenView.exe';    F = 'BlueScreens.html' }
        'A' = @{ N = 'appcrashview';      E = 'AppCrashView.exe';      F = 'AppCrashes.html' }
        'T' = @{ N = 'turnedontimesview'; E = 'TurnedOnTimesView.exe'; F = 'PowerOnOffTimes.html' }
        'L' = @{ N = 'lastactivityview';  E = 'LastActivityView.exe';  F = 'LastActivity.html' }
        'U' = @{ N = 'usbdeview';         E = 'USBDeview.exe';         F = 'USBDevices.html' }
        'D' = @{ N = 'driverview';        E = 'DriverView.exe';        F = 'Drivers.html' }
    }
    foreach ($k in $pick) {
        $m = $map["$k".ToUpper()]; if (-not $m) { continue }
        $exe = Get-NirSoftTool $m.N $m.E
        if (-not $exe) { continue }
        $out = Join-Path $dir $m.F
        Start-Process -FilePath $exe -ArgumentList "/shtml `"$out`"" -Wait -WindowStyle Hidden
        if (Test-Path $out) { Write-Host "  $($m.F) created" -ForegroundColor Green } else { Write-Host "  $($m.E) produced no report (nothing found, or blocked by AV)" -ForegroundColor Yellow }
    }
    Write-Host "  Reports: $dir" -ForegroundColor Green
    if ((Get-ChildItem $dir -Filter *.html -ErrorAction SilentlyContinue) -and (Read-YesNo 'Open the folder?' $false)) { Start-Process explorer.exe $dir }
}

