        @{ K='14'; N='NirSoft ShellExView (disable bad Explorer context-menu extensions)'; Nir='shexview'; E='shexview.exe' }
        @{ K='15'; N='NirSoft CurrPorts (open ports by process)';               Nir='cports'; E='cports.exe' }
        @{ K='16'; N='NirSoft FullEventLogView (all event logs in one grid)';   Nir='fulleventlogview'; E='FullEventLogView.exe' }
        @{ K='17'; N='NirSoft WinUpdatesView (update history incl. failures)';  Nir='winupdatesview'; E='WinUpdatesView.exe' }
        @{ K='18'; N='NirSoft OpenedFilesView (open files + locking process)';  Nir='ofview'; E='OpenedFilesView.exe' }
        @{ K='19'; N='NirSoft SearchMyFiles (find files by size/date/content)'; Nir='searchmyfiles'; E='SearchMyFiles.exe' }
        @{ K='20'; N='NirSoft WifiInfoView (nearby Wi-Fi channels/signal)';     Nir='wifiinfoview'; E='WifiInfoView.exe' }
        @{ K='S';  N='Download the FULL Sysinternals Suite to C:\temp\Tools';   Suite=$true }
        @{ K='L';  N='Show download links';                                     Links=$true }
    )
    foreach ($t in $tools) { Write-Host ("  {0,3}. {1}" -f $t.K, $t.N) }
    $k = "$(Read-Default 'Pick a tool (blank = back)' '')".ToUpper()
    $t = $tools | Where-Object { $_.K -eq $k } | Select-Object -First 1
    if (-not $t) { return }
    if ($t.Links) { $Script:ToolLinks.GetEnumerator() | ForEach-Object { Write-Host ("  {0,-42} {1}" -f $_.Key, $_.Value) }; return }
    if ($t.Suite) {
        if (-not (Confirm-Sysinternals)) { return }
        $dir = Get-ToolsDir 'Sysinternals'; $zip = Join-Path $dir 'SysinternalsSuite.zip'
        if (Get-WebFile $Script:ToolLinks['Sysinternals Suite (all tools)'] $zip) { Expand-Archive $zip -DestinationPath $dir -Force; Remove-Item $zip; Write-Host "  Extracted to $dir" -ForegroundColor Green }
        return
    }
    if ($t.S) { if (-not (Confirm-Sysinternals)) { return }; $exe = Get-SysinternalsTool $t.S }
    else      { $exe = Get-NirSoftTool $t.Nir $t.E }
    if ($exe) { Start-Process -FilePath $exe; Write-Host "  Launched $exe" -ForegroundColor Green }
}

function Invoke-SetupDiag {
    Write-Title 'Microsoft SetupDiag - why did a Windows upgrade / feature update fail?'
    $dir = Get-ToolsDir 'SetupDiag'
    $exe = Join-Path $dir 'SetupDiag.exe'
    if (-not (Test-Path $exe)) {
        Write-Host '  Downloading SetupDiag from Microsoft...' -ForegroundColor DarkGray
        if (-not (Get-WebFile $Script:ToolLinks['Microsoft SetupDiag'] $exe)) { return }
    }
    $out = Join-Path (Get-OutDir 'Win11Upgrade') "SetupDiagResults_$(Get-Stamp).log"
    Write-Host '  Analyzing upgrade logs (1-3 minutes)...' -ForegroundColor DarkGray
    Start-Process -FilePath $exe -ArgumentList "/Output:`"$out`" /ZipLogs:False" -Wait -NoNewWindow
    if (Test-Path $out) { Get-Content $out | Select-Object -First 60 | Write-Host; Write-Host "  Full result: $out" -ForegroundColor Green }
    else { Write-Host '  No result file - there may be no failed upgrade logs on this machine.' -ForegroundColor Yellow }
}

function Invoke-MicrosoftTSS {
    Write-Title 'Microsoft TSS - official support log collection'
    Write-Host '  Microsoft''s own TroubleShootingScript toolset (what MS support asks you to run).'
    Write-Host '  Downloaded from https://aka.ms/getTSS. You will be asked to accept Microsoft''s EULA on first run.' -ForegroundColor DarkGray
    $dir = Get-ToolsDir 'TSS'
    $ps1 = Get-ChildItem $dir -Filter 'TSS.ps1' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $ps1) {
        $zip = Join-Path $dir 'TSS.zip'
        if (-not (Get-WebFile $Script:ToolLinks['Microsoft TSS (support logs)'] $zip)) { return }
        Expand-Archive $zip -DestinationPath $dir -Force; Remove-Item $zip -Force
        $ps1 = Get-ChildItem $dir -Filter 'TSS.ps1' -Recurse | Select-Object -First 1
    }
    if (-not $ps1) { Write-Host '  TSS.ps1 not found after download.' -ForegroundColor Red; return }
    Write-Host '  Support Diagnostic Packages (SDP): Net, Perf, Print, RDS, Setup, Dom, HyperV, Cluster, SQLbase, Mini (small, general)'
    $sdp = Read-Default 'SDP to collect' 'Mini'
    $logs = Get-OutDir 'TSS_Data'
    Write-Host "  Running TSS -SDP $sdp (this can take 10-30 minutes)..." -ForegroundColor Cyan
    $p = Start-Process -FilePath $Script:PSExe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$($ps1.FullName)`" -SDP $sdp -LogFolderPath `"$logs`"" -NoNewWindow -Wait -PassThru
    Write-Host "  TSS finished (exit $($p.ExitCode)). Zipped output in $logs" -ForegroundColor Green
}


# ---------- DOWNLOAD SAFETY ------------------------------------------------------------
# Every downloaded .exe/.msi is checked: must be a real Windows binary/installer (not an
# error page) and, where the vendor signs it, must carry a VALID Authenticode signature from
# the expected publisher. Anything that fails is deleted and skipped.
function Test-DownloadedBinary([string]$Path, [string]$ExpectSigner, [switch]$AllowUnsigned) {
    if (-not (Test-Path $Path)) { return $false }
    $bytes = [byte[]](Get-Content -LiteralPath $Path -Encoding Byte -TotalCount 8 -ErrorAction SilentlyContinue)
    $isPE  = $bytes.Count -ge 2 -and $bytes[0] -eq 0x4D -and $bytes[1] -eq 0x5A              # MZ
    $isMSI = $bytes.Count -ge 4 -and $bytes[0] -eq 0xD0 -and $bytes[1] -eq 0xCF -and $bytes[2] -eq 0x11 -and $bytes[3] -eq 0xE0
    if (-not ($isPE -or $isMSI)) { Write-Host "  $([IO.Path]::GetFileName($Path)) is not a valid installer (probably an error page) - skipped." -ForegroundColor Red; Remove-Item $Path -Force -ErrorAction SilentlyContinue; return $false }
    if ($ExpectSigner) {
        $sig = Get-AuthenticodeSignature -FilePath $Path
        $who = $sig.SignerCertificate.Subject
        if ($AllowUnsigned -and $sig.Status -eq 'NotSigned') {
            Write-Host "  NOTE: $([IO.Path]::GetFileName($Path)) is not code-signed by its vendor (downloaded from the official site) - allowed." -ForegroundColor DarkYellow
            return $true
        }
        if ($sig.Status -ne 'Valid' -or $who -notmatch $ExpectSigner) {
            Write-Host "  Signature check FAILED for $([IO.Path]::GetFileName($Path)) (status $($sig.Status), signer '$who') - deleted, skipped." -ForegroundColor Red
            Remove-Item $Path -Force -ErrorAction SilentlyContinue
            return $false
        }
        Write-Host "  Signature OK: $(($who -split ',')[0])" -ForegroundColor DarkGray
    }
    return $true
}

