function Invoke-NiniteInstall {
    Write-Title '[!] Install common apps with Ninite'
    Write-Host '  Ninite installs the latest version of each app, says no to toolbars/bundles, and skips apps already up to date.'
    Write-Host '  The installer is downloaded from ninite.com into C:\temp\Tools\Ninite and its signature checked.' -ForegroundColor DarkGray
    $keys = @($Script:NiniteApps.Keys)
    for ($i = 0; $i -lt $keys.Count; $i++) { Write-Host ("  {0,3}. {1,-22}" -f ($i + 1), $Script:NiniteApps[$keys[$i]]) -NoNewline; if (($i + 1) % 3 -eq 0) { Write-Host '' } }
    Write-Host ''
    $pick = Read-List 'Numbers to install, comma separated (e.g. 1,2,4)' '1,2,4'
    $slugs = foreach ($p in $pick) { $n = 0; if ([int]::TryParse($p, [ref]$n) -and $n -ge 1 -and $n -le $keys.Count) { $keys[$n - 1] } }
    $extra = Read-Default 'Extra Ninite app ids (as in ninite.com/<ids>/ninite.exe, blank = none)' ''
    if ($extra) { $slugs += ($extra -split '[,\s-]+' | Where-Object { $_ }) }
    $slugs = @($slugs | Select-Object -Unique)
    if (-not $slugs) { return }
    $names = ($slugs | ForEach-Object { if ($Script:NiniteApps[$_]) { $Script:NiniteApps[$_] } else { $_ } }) -join ', '
    if (-not (Confirm-Change "Download and install: $names")) { return }
    $dir = Get-ToolsDir 'Ninite'
    $exe = Join-Path $dir ("Ninite_" + ($slugs -join '-') + '.exe')
    if (-not (Get-WebFile ("https://ninite.com/" + ($slugs -join '-') + "/ninite.exe") $exe)) { return }
    if (-not (Test-DownloadedBinary $exe 'Secure By Design|Ninite')) { return }
    Write-Host '  Running Ninite - its window shows progress; close it when it says Finished.' -ForegroundColor Cyan
    Start-Process -FilePath $exe -Wait
    Write-Host '  Ninite finished.' -ForegroundColor Green
}

