    '4' = @{ N = 'Microsoft Teams (new, machine-wide)';     U = 'https://go.microsoft.com/fwlink/?linkid=2243204&clcid=0x409'; F = 'teamsbootstrapper.exe'; S = 'Microsoft'; A = '-p' }
    '5' = @{ N = 'Microsoft OneDrive (per-machine)';        U = 'https://go.microsoft.com/fwlink/?linkid=844652'; F = 'OneDriveSetup.exe'; S = 'Microsoft'; A = '/allusers /silent' }
