function Invoke-DirectInstall {
    Write-Title '[!] Install apps silently from the vendor (no Ninite)'
    foreach ($k in $Script:DirectApps.Keys) { Write-Host ("  {0}. {1}" -f $k, $Script:DirectApps[$k].N) }
    $pick = Read-List 'Numbers to install, comma separated' ''
    $apps = @($pick | ForEach-Object { $Script:DirectApps["$_"] } | Where-Object { $_ })
    if (-not $apps) { return }
    if (-not (Confirm-Change ("Silently install: " + (($apps | ForEach-Object { $_.N }) -join ', ')))) { return }
    $dir = Get-ToolsDir 'Installers'
    foreach ($a in $apps) {
        $file = Join-Path $dir $a.F
        Write-Host "  $($a.N): downloading..." -ForegroundColor Cyan
        if (-not (Get-WebFile $a.U $file)) { Write-Host '  Skipped.' -ForegroundColor Yellow; continue }
        if (-not (Test-DownloadedBinary $file $a.S)) { continue }
        Write-Host "  Installing..." -ForegroundColor Cyan
        if ($file -like '*.msi') { $p = Start-Process msiexec.exe -ArgumentList "/i `"$file`" $($a.A) /l*v `"$file.log`"" -Wait -PassThru }
        else { $p = Start-Process $file -ArgumentList $a.A -Wait -PassThru }
        $ok = $p.ExitCode -in 0, 3010, 1641
        Write-Host ("  {0}: exit {1} {2}" -f $a.N, $p.ExitCode, $(if ($p.ExitCode -eq 3010) { '(reboot needed)' } elseif ($ok) { '(OK)' } else { '(check log)' })) -ForegroundColor $(if ($ok) { 'Green' } else { 'Red' })
    }
}

function Get-OfficeDeploymentTool {
    $dir = Get-ToolsDir 'Office'
    $setup = Join-Path $dir 'setup.exe'
    if ((Test-Path $setup) -and (Test-DownloadedBinary $setup 'Microsoft')) { return $setup }
    Write-Host '  Downloading the Office Deployment Tool (setup.exe) from Microsoft''s Office CDN...' -ForegroundColor DarkGray
    if ((Get-WebFile 'https://officecdn.microsoft.com/pr/wsus/setup.exe' $setup) -and (Test-DownloadedBinary $setup 'Microsoft')) { return $setup }
    Write-Host '  Could not get ODT - download it from https://go.microsoft.com/fwlink/p/?LinkID=626065 and extract setup.exe into' -ForegroundColor Yellow
    Write-Host "  $dir, then run this option again." -ForegroundColor Yellow
    return $null
}

function Show-InstalledOffice {
    $rows = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -match 'Microsoft (365|Office)|OneNote|Project|Visio' -and $_.DisplayName -notmatch 'Update|Language Pack Proof|Click-to-Run (Extensibility|Licensing|Localization)' } |
        Select-Object DisplayName, DisplayVersion | Sort-Object DisplayName -Unique
    if ($rows) { $rows | Format-Table -AutoSize } else { Write-Host '  No Office products installed.' }
    $c2r = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration' -ErrorAction SilentlyContinue
    if ($c2r) { Write-Host ("  Click-to-Run products: {0}   Platform: {1}   Version: {2}" -f $c2r.ProductReleaseIds, $c2r.Platform, $c2r.VersionToReport) }
    # Get-AppxPackage -Name only takes ONE name in Windows PowerShell 5.1 - loop instead of passing an array
    foreach ($pkg in 'Microsoft.MicrosoftOfficeHub', 'Microsoft.Office.OneNote') {
        Get-AppxPackage -AllUsers -Name $pkg -ErrorAction SilentlyContinue | Select-Object Name, Version | Format-Table -AutoSize
    }
}

function Invoke-OfficeRemoveAll {
    Write-Title '[!] Remove ALL existing Office (OEM preinstalls, other languages, old MSI Office)'
    Show-InstalledOffice
    Write-Host '  Uses Microsoft''s Office Deployment Tool with <Remove All="TRUE"/> - removes every Click-to-Run Office product'
    Write-Host '  and language (e.g. the 3-language "Microsoft 365 - fr-fr/es-es/en-us" OEM installs), plus the Office hub Store app.'
    if (-not (Confirm-Change 'Uninstall ALL Office products on this machine. Users must save and close Office first.')) { return }
    $setup = Get-OfficeDeploymentTool; if (-not $setup) { return }
    $xml = Join-Path (Split-Path $setup) 'RemoveAll.xml'
    @'
<Configuration>
  <Remove All="TRUE" />
  <Display Level="None" AcceptEULA="TRUE" />
  <Property Name="FORCEAPPSHUTDOWN" Value="TRUE" />
</Configuration>
'@ | Set-Content -Path $xml -Encoding UTF8
    Write-Host '  Removing Office (5-15 minutes, no window)...' -ForegroundColor Cyan
    $p = Start-Process -FilePath $setup -ArgumentList "/configure `"$xml`"" -Wait -PassThru
    Write-Host "  ODT exit code: $($p.ExitCode)" -ForegroundColor $(if ($p.ExitCode -eq 0) { 'Green' } else { 'Yellow' })
    Get-AppxPackage -AllUsers -Name 'Microsoft.MicrosoftOfficeHub' -ErrorAction SilentlyContinue | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
    Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object DisplayName -eq 'Microsoft.MicrosoftOfficeHub' | Remove-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Out-Null
    Write-Host '  Remaining Office products:'; Show-InstalledOffice
    Write-Host '  If anything is left (very old MSI Office), use Microsoft''s "Uninstall Office" support tool: https://aka.ms/SaRA-OfficeUninstallFromPC' -ForegroundColor DarkGray
}

function Invoke-OfficeInstall {
    Write-Title '[!] Install Microsoft 365 Apps (Office) with the Office Deployment Tool'
    Show-InstalledOffice
    Write-Host '  1. Microsoft 365 Apps for business   (Business Standard / Premium)   O365BusinessRetail'
    Write-Host '  2. Microsoft 365 Apps for enterprise (E3 / E5)                        O365ProPlusRetail'
    $prod = if ("$(Read-Default 'Product' '1')" -eq '2') { 'O365ProPlusRetail' } else { 'O365BusinessRetail' }
    $bits = if ("$(Read-Default 'Architecture 64 or 32' '64')" -eq '32') { '32' } else { '64' }
    $chIn = "$(Read-Default 'Update channel: C = Current, M = Monthly Enterprise, S = Semi-Annual' 'C')".ToUpper()
    $chan = switch ($chIn) { 'M' { 'MonthlyEnterprise' } 'S' { 'SemiAnnual' } default { 'Current' } }
    $exclude = Read-List 'Apps to EXCLUDE (Groove,Lync,Bing,Publisher,Access,OneNote,Teams,OneDrive)' 'Groove,Lync,Bing'
    $isRds = (Get-WindowsFeature -Name RDS-RD-Server -ErrorAction SilentlyContinue).Installed
    $shared = Read-YesNo 'Shared Computer Activation (REQUIRED on RDS/terminal servers)?' ([bool]$isRds)
    $removeOld = Read-YesNo 'Remove existing Office first (OEM preinstalls, other languages, MSI Office)?' $true
    if (-not (Confirm-Change "Install $prod ($bits-bit, $chan channel) - downloads ~3 GB from Microsoft.")) { return }
    $setup = Get-OfficeDeploymentTool; if (-not $setup) { return }
    $ex = ($exclude | ForEach-Object { "      <ExcludeApp ID=`"$_`" />" }) -join "`r`n"
    $xmlText = @"
<Configuration>
  <Add OfficeClientEdition="$bits" Channel="$chan" MigrateArch="TRUE">
    <Product ID="$prod">
      <Language ID="MatchOS" />
$ex
    </Product>
  </Add>
$(if ($removeOld) { '  <Remove All="TRUE" />' + "`r`n" + '  <RemoveMSI />' })
  <Property Name="SharedComputerLicensing" Value="$(if ($shared) { 1 } else { 0 })" />
  <Property Name="FORCEAPPSHUTDOWN" Value="TRUE" />
  <Property Name="AUTOACTIVATE" Value="1" />
  <Updates Enabled="TRUE" />
  <Display Level="Full" AcceptEULA="TRUE" />
</Configuration>
"@
    # ODT doesn't allow <Remove All> alongside <Add> in one file, so do removal as its own pass.
    $xml = Join-Path (Split-Path $setup) "Install_$prod.xml"
    ($xmlText -replace '(?m)^\s*<Remove All="TRUE" />\r?\n', '') | Set-Content -Path $xml -Encoding UTF8
    if ($removeOld) {
        $rx = Join-Path (Split-Path $setup) 'RemoveAll.xml'
        '<Configuration><Remove All="TRUE" /><Display Level="None" AcceptEULA="TRUE" /><Property Name="FORCEAPPSHUTDOWN" Value="TRUE" /></Configuration>' | Set-Content $rx -Encoding UTF8
        Write-Host '  Removing existing Office first...' -ForegroundColor Cyan
        Start-Process -FilePath $setup -ArgumentList "/configure `"$rx`"" -Wait | Out-Null
    }
    Write-Host "  Installing - the Office installer window shows progress. Config: $xml" -ForegroundColor Cyan
    $p = Start-Process -FilePath $setup -ArgumentList "/configure `"$xml`"" -Wait -PassThru
    Write-Host "  ODT exit code: $($p.ExitCode)" -ForegroundColor $(if ($p.ExitCode -eq 0) { 'Green' } else { 'Yellow' })
    Show-InstalledOffice
}

# ---------- EXTRA DIAGNOSTICS ------------------------------------------------------------

function Invoke-ReliabilityHistory {
    Write-Title 'Reliability history (the "Reliability Monitor" data) - last 30 days'
    $rel = Get-CimInstance Win32_ReliabilityRecords -ErrorAction SilentlyContinue | Where-Object { $_.TimeGenerated -gt (Get-Date).AddDays(-30) }
    if (-not $rel) { Write-Host '  No records (the RacTask scheduled task may be disabled - common on servers).' -ForegroundColor Yellow; return }
    $rel | Group-Object SourceName | Sort-Object Count -Descending | Select-Object -First 10 Count, Name | Format-Table -AutoSize
    $rel | Where-Object { $_.EventIdentifier -in 1000,1001,1002,41,6008 -or $_.SourceName -match 'Application Error|Application Hang|Windows Error Reporting|Kernel' } |
        Sort-Object TimeGenerated -Descending | Select-Object -First 25 TimeGenerated, SourceName, ProductName, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
    $stab = Get-CimInstance Win32_ReliabilityStabilityMetrics -ErrorAction SilentlyContinue | Sort-Object TimeGenerated | Select-Object -Last 1
    if ($stab) { Write-Host ("  Stability index: {0:N1} / 10" -f $stab.SystemStabilityIndex) -ForegroundColor $(if ($stab.SystemStabilityIndex -lt 5) { 'Yellow' } else { 'Green' }) }
}

function Invoke-PerfSnapshot {
    Write-Title 'Performance snapshot (CPU / memory / disk / network over 30 seconds)'
    $counters = '\Processor(_Total)\% Processor Time','\Memory\Available MBytes','\Memory\Pages/sec','\Memory\% Committed Bytes In Use',
                '\PhysicalDisk(_Total)\% Disk Time','\PhysicalDisk(_Total)\Avg. Disk Queue Length','\PhysicalDisk(_Total)\Avg. Disk sec/Read','\PhysicalDisk(_Total)\Avg. Disk sec/Write',
                '\Network Interface(*)\Bytes Total/sec','\System\Processor Queue Length'
    Write-Host '  Sampling 15 x 2 seconds...' -ForegroundColor DarkGray
    $s = Get-Counter -Counter $counters -SampleInterval 2 -MaxSamples 15 -ErrorAction SilentlyContinue
    $s.CounterSamples | Group-Object Path | ForEach-Object {
        $v = $_.Group.CookedValue
        [pscustomobject]@{ Counter = ($_.Name -replace '^\\\\[^\\]+', ''); Avg = [math]::Round(($v | Measure-Object -Average).Average, 3); Max = [math]::Round(($v | Measure-Object -Maximum).Maximum, 3) }
    } | Format-Table -AutoSize
    Write-Host '  Rules of thumb: CPU avg > 80%, Available MB < 500, Disk sec/Read or Write > 0.025 (25 ms), Disk queue > 2 per disk = bottleneck.' -ForegroundColor DarkGray
    Write-Sub 'Top processes right now'
    $cores = (Get-CimInstance Win32_ComputerSystem).NumberOfLogicalProcessors
    Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin '_Total','Idle' } |
        Sort-Object PercentProcessorTime -Descending | Select-Object -First 10 Name, IDProcess, @{n='CPU%';e={[math]::Round($_.PercentProcessorTime / $cores, 1)}}, @{n='WS_MB';e={[math]::Round($_.WorkingSet/1MB)}}, @{n='IO_KBps';e={[math]::Round($_.IODataBytesPersec/1KB)}} | Format-Table -AutoSize
}

function Invoke-BootPerformance {
    Write-Title 'Boot / logon performance (slow startup)'
    $ev = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 10 -ErrorAction SilentlyContinue
    if ($ev) {
        $ev | ForEach-Object { $x = [xml]$_.ToXml(); $d = @{}; $x.Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
            [pscustomobject]@{ Time = $_.TimeCreated; BootSec = [math]::Round([int]$d.BootTime/1000,1); MainPathSec = [math]::Round([int]$d.MainPathBootTime/1000,1); PostBootSec = [math]::Round([int]$d.BootPostBootTime/1000,1) } } | Format-Table -AutoSize
    } else { Write-Host '  No boot performance events (log disabled or not available on this edition).' }
    Write-Sub 'What slowed boot down (events 101-110: apps, drivers, services)'
    Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 101..110 } -MaxEvents 200 -ErrorAction SilentlyContinue |
        ForEach-Object { $x = [xml]$_.ToXml(); $d = @{}; $x.Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
            [pscustomobject]@{ Item = $(if ($d.FriendlyName) { $d.FriendlyName } elseif ($d.Name) { $d.Name } else { $d.FileName }); DelayMs = [int]$d.TotalTime - [int]$d.DegradationTime + [int]$d.DegradationTime; Degradation = [int]$d.DegradationTime } } |
        Group-Object Item | ForEach-Object { [pscustomobject]@{ Item = $_.Name; Times = $_.Count; AvgDelayMs = [math]::Round(($_.Group.Degradation | Measure-Object -Average).Average) } } |
        Sort-Object AvgDelayMs -Descending | Select-Object -First 15 | Format-Table -AutoSize
    Write-Sub 'Last 5 Group Policy / logon durations'
    Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-GroupPolicy/Operational'; Id = 8001, 8000 } -MaxEvents 10 -ErrorAction SilentlyContinue |
        Select-Object TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
}

function Invoke-SlowLogoffDiag {
    Write-Title 'Slow sign-out / logoff / shutdown + general lag diagnostics'
    $days  = Read-Int '  How many days back to look' 7
    $since = (Get-Date).AddDays(-$days)
    $dir = Get-OutDir 'SlowLogoff'; $stamp = Get-Stamp
    $report = Join-Path $dir "SlowLogoff_$($env:COMPUTERNAME)_$stamp.txt"
    $findings = New-Object System.Collections.ArrayList
    function Add-Hit([string]$Sev, [string]$Text) { [void]$findings.Add([pscustomobject]@{ Severity = $Sev; Finding = $Text }) }
    function Get-EvData($e) { $d = @{}; try { ([xml]$e.ToXml()).Event.EventData.Data | ForEach-Object { if ($_.Name) { $d[$_.Name] = $_.'#text' } } } catch {}; $d }
    $log = New-Object System.Collections.ArrayList
    function Out-Section([string]$Title, $Data) {
        Write-Sub $Title
        $txt = if ($null -eq $Data -or @($Data).Count -eq 0) { '  (nothing found)' } else { ($Data | Format-Table -AutoSize -Wrap | Out-String -Width 220).TrimEnd() }
        Write-Host $txt
        [void]$log.Add("`r`n--- $Title ---`r`n$txt")
    }

    # 1. Uptime, memory, CPU
    $os = Get-CimInstance Win32_OperatingSystem
    $upDays = [math]::Round(((Get-Date) - $os.LastBootUpTime).TotalDays, 1)
    $memPct = [math]::Round((($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / $os.TotalVisibleMemorySize) * 100)
    $cpu = (Get-CimInstance Win32_Processor | Measure-Object LoadPercentage -Average).Average
    $sys = [pscustomobject]@{ UptimeDays = $upDays; RAMUsedPct = $memPct; RAMTotalGB = [math]::Round($os.TotalVisibleMemorySize/1MB,1); CPUPct = $cpu; LastBoot = $os.LastBootUpTime }
    Out-Section 'Uptime / memory / CPU' $sys
    if ($upDays -ge 14) { Add-Hit 'MEDIUM' "Up $upDays days without a reboot - a full restart often clears logoff hangs and lag." }
    if ($memPct -ge 90) { Add-Hit 'HIGH' "RAM is $memPct% used - machine is paging; see top memory processes." }
    if ($cpu -ge 85)    { Add-Hit 'HIGH' "CPU is at $cpu% right now - see top CPU processes." }

    # 2. Top processes
    $procs = Get-Process -IncludeUserName -ErrorAction SilentlyContinue
    if (-not $procs) { $procs = Get-Process }
    Out-Section 'Top 15 processes by memory' ($procs | Sort-Object WorkingSet64 -Descending | Select-Object -First 15 Name, Id, SessionId, UserName, @{n='MemMB';e={[math]::Round($_.WorkingSet64/1MB)}}, @{n='CPUsec';e={[math]::Round($_.CPU)}}, Handles)
    Out-Section 'Top 10 processes by total CPU time' ($procs | Sort-Object CPU -Descending | Select-Object -First 10 Name, Id, SessionId, @{n='CPUsec';e={[math]::Round($_.CPU)}}, @{n='MemMB';e={[math]::Round($_.WorkingSet64/1MB)}})
    $leaky = $procs | Where-Object { $_.Handles -gt 20000 }
    foreach ($p in $leaky) { Add-Hit 'MEDIUM' "$($p.Name) (PID $($p.Id)) has $($p.Handles) handles - possible handle leak; restart that app." }
    $notResp = $procs | Where-Object { $_.MainWindowHandle -ne 0 -and -not $_.Responding }
    if ($notResp) { Out-Section 'Programs NOT RESPONDING right now' ($notResp | Select-Object Name, Id, SessionId) ; foreach ($p in $notResp) { Add-Hit 'HIGH' "$($p.Name) (PID $($p.Id)) is Not Responding now - it will block sign-out." } }

    # 3. Shutdown / logoff performance (Diagnostics-Performance 200-203)
    $dp = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 200; StartTime = $since } -ErrorAction SilentlyContinue
    Out-Section 'Shutdown durations (Diagnostics-Performance 200)' ($dp | Select-Object -First 10 | ForEach-Object { $d = Get-EvData $_; [pscustomobject]@{ Time = $_.TimeCreated; ShutdownSec = [math]::Round([int]$d.ShutdownTime/1000,1); UserSessionSec = [math]::Round([int]$d.ShutdownUserSessionTime/1000,1); ServicesSec = [math]::Round([int]$d.ShutdownServiceTime/1000,1) } })
    $slowItems = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 201,202,203; StartTime = $since } -ErrorAction SilentlyContinue |
        ForEach-Object { $d = Get-EvData $_; [pscustomobject]@{ Type = @{201='App';202='Device';203='Service'}[$_.Id]; Item = $(if ($d.FriendlyName) { $d.FriendlyName } elseif ($d.Name) { $d.Name } else { $d.FileName }); DelayMs = [int]$d.TotalTime } } |
        Group-Object Type, Item | ForEach-Object { [pscustomobject]@{ Item = $_.Name; Times = $_.Count; AvgDelaySec = [math]::Round((($_.Group.DelayMs | Measure-Object -Average).Average)/1000,1) } } | Sort-Object AvgDelaySec -Descending
    Out-Section 'Apps / services / devices that slowed shutdown (201-203)' ($slowItems | Select-Object -First 15)
    foreach ($s in ($slowItems | Where-Object { $_.AvgDelaySec -ge 10 } | Select-Object -First 5)) { Add-Hit 'HIGH' "Delays shutdown/sign-out by ~$($s.AvgDelaySec)s ($($s.Times)x): $($s.Item)" }

    # 4. Winlogon subscribers slow on logoff (Application 6005/6006)
    $wl = Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Microsoft-Windows-Winlogon'; Id = 6005,6006; StartTime = $since } -ErrorAction SilentlyContinue
    $wlRows = $wl | ForEach-Object { [pscustomobject]@{ Time = $_.TimeCreated; Id = $_.Id; Message = ($_.Message -split "`n")[0].Trim() } }
    Out-Section 'Winlogon notification subscribers taking long (6005/6006)' ($wlRows | Select-Object -First 20)
    $wl | Where-Object { $_.Id -eq 6006 } | ForEach-Object { if ($_.Message -match "subscriber <(.+?)> took (\d+) second.+\((\w+)\)") { if ([int]$Matches[2] -ge 10) { Add-Hit 'HIGH' "Winlogon subscriber '$($Matches[1])' took $($Matches[2])s handling $($Matches[3])." } } }

    # 5. User Profile Service - logoff timing + errors
    $ups = Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-User Profile Service/Operational'; Id = 3,4; StartTime = $since } -ErrorAction SilentlyContinue | Sort-Object TimeCreated
    $pairs = @(); $open = @{}
    foreach ($e in $ups) {
        $sess = if ($e.Message -match 'session (\d+)') { $Matches[1] } else { '?' }
        if ($e.Id -eq 3) { $open[$sess] = $e.TimeCreated }
        elseif ($open.ContainsKey($sess)) { $pairs += [pscustomobject]@{ LogoffStarted = $open[$sess]; Session = $sess; ProfileUnloadSec = [math]::Round(($e.TimeCreated - $open[$sess]).TotalSeconds,1) }; $open.Remove($sess) }
    }
    Out-Section 'User Profile Service - logoff processing time per sign-out' ($pairs | Sort-Object LogoffStarted -Descending | Select-Object -First 15)
    $slowPairs = @($pairs | Where-Object { $_.ProfileUnloadSec -ge 15 })
    if ($slowPairs) { Add-Hit 'HIGH' "Profile unload took 15s+ on $($slowPairs.Count) sign-out(s) (max $(($pairs | Measure-Object ProfileUnloadSec -Maximum).Maximum)s) - profile/registry hive or sync issue." }
    $upErr = Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Microsoft-Windows-User Profiles Service','Microsoft-Windows-User Profiles General'; StartTime = $since } -ErrorAction SilentlyContinue | Where-Object { $_.Level -le 3 }
    Out-Section 'User Profile errors/warnings (1530 = registry handles held open at logoff)' ($upErr | Group-Object Id | ForEach-Object { [pscustomobject]@{ Id = $_.Name; Count = $_.Count; Last = $_.Group[0].TimeCreated; Sample = ($_.Group[0].Message -split "`n")[0].Trim() } })
    $h1530 = @($upErr | Where-Object { $_.Id -eq 1530 })
    if ($h1530) {
        $holders = $h1530 | ForEach-Object { if ($_.Message -match 'Process \d+ \(([^)]+)\)') { Split-Path $Matches[1] -Leaf } } | Group-Object | Sort-Object Count -Descending | Select-Object -First 3 | ForEach-Object { "$($_.Name) ($($_.Count)x)" }
        Add-Hit 'MEDIUM' "Event 1530 x$($h1530.Count): a program keeps the user's registry open at sign-out$(if ($holders) { ' - ' + ($holders -join ', ') })."
    }
    if (@($upErr | Where-Object { $_.Id -in 1500,1511,1515,1508,1509 })) { Add-Hit 'HIGH' 'Temporary-profile / profile load-copy errors found - check the profile (C:\Users) and ProfileList registry.' }

    # 6. Profiles (size, roaming, hive size)
    $profs = Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue | Where-Object { -not $_.Special -and $_.LocalPath -like '*\Users\*' }
    $profRows = foreach ($p in $profs) {
        $nt = Join-Path $p.LocalPath 'NTUSER.DAT'; $uc = Join-Path $p.LocalPath 'AppData\Local\Microsoft\Windows\UsrClass.dat'
        $ntMB = if (Test-Path -LiteralPath $nt) { [math]::Round((Get-Item -LiteralPath $nt -Force).Length/1MB,1) } else { $null }
        $ucMB = if (Test-Path -LiteralPath $uc) { [math]::Round((Get-Item -LiteralPath $uc -Force).Length/1MB,1) } else { $null }
        $user = try { (New-Object Security.Principal.SecurityIdentifier($p.SID)).Translate([Security.Principal.NTAccount]).Value } catch { $p.SID }
        [pscustomobject]@{ User = $user; Loaded = $p.Loaded; Roaming = $p.RoamingConfigured; LastUse = $p.LastUseTime; NTUSER_MB = $ntMB; UsrClass_MB = $ucMB; Path = $p.LocalPath }
    }
    Out-Section 'User profiles (registry hive sizes; big hives unload slowly)' ($profRows | Sort-Object LastUse -Descending)
    foreach ($r in $profRows) {
        if ($r.NTUSER_MB -ge 50)   { Add-Hit 'MEDIUM' "$($r.User): NTUSER.DAT is $($r.NTUSER_MB) MB (bloated hive slows sign-in/out)." }
        if ($r.UsrClass_MB -ge 100) { Add-Hit 'MEDIUM' "$($r.User): UsrClass.dat is $($r.UsrClass_MB) MB (bloated - common Start menu/Explorer lag cause)." }
        if ($r.Roaming) { Add-Hit 'MEDIUM' "$($r.User) uses a ROAMING profile - sign-out copies the profile to the server; large or slow link = slow sign-out." }
    }

    # 7. Per-user items for every loaded user (works when run as admin or SYSTEM via RMM)
    $loaded = Get-ChildItem Registry::HKEY_USERS -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-[\d-]+$' }
    $drives = @(); $userScripts = @(); $redir = @()
    foreach ($k in $loaded) {
        $sid = $k.PSChildName
        $user = try { (New-Object Security.Principal.SecurityIdentifier($sid)).Translate([Security.Principal.NTAccount]).Value } catch { $sid }
        Get-ChildItem "Registry::HKEY_USERS\$sid\Network" -ErrorAction SilentlyContinue | ForEach-Object { $drives += [pscustomobject]@{ User = $user; Drive = "$($_.PSChildName):"; Path = (Get-ItemProperty $_.PSPath).RemotePath } }
        Get-ChildItem "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Group Policy\Scripts\Logoff" -Recurse -ErrorAction SilentlyContinue | ForEach-Object { $sp = Get-ItemProperty $_.PSPath; if ($sp.Script) { $userScripts += [pscustomobject]@{ User = $user; Script = $sp.Script; Params = $sp.Parameters } } }
        $sf = Get-ItemProperty "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders" -ErrorAction SilentlyContinue
        if ($sf) { foreach ($n in 'Desktop','Personal','{F42EE2D3-909F-4907-8871-4C22FC0BF756}','My Pictures','AppData') { $v = $sf.$n; if ($v -like '\\*') { $redir += [pscustomobject]@{ User = $user; Folder = $n; Target = $v } } } }
    }
    foreach ($d in $drives) {
        $srv = if ($d.Path -match '^\\\\([^\\]+)') { $Matches[1] } else { $null }
        $d | Add-Member NoteProperty ServerReachable $(if ($srv) { [bool](Test-Connection -ComputerName $srv -Count 1 -Quiet -ErrorAction SilentlyContinue) } else { $null })
        if ($srv -and -not $d.ServerReachable) { Add-Hit 'HIGH' "$($d.User): mapped drive $($d.Drive) -> $($d.Path) is UNREACHABLE - Explorer hangs/lag at sign-out." }
    }
    Out-Section 'Mapped network drives (loaded users)' $drives
    Out-Section 'Folder redirection to network (loaded users)' $redir
    if ($redir) {
        Add-Hit 'LOW' 'Folders are redirected to a network share - a slow/offline server makes Explorer and sign-out lag (check Offline Files sync too).'
        foreach ($k in $loaded) {
            $acct = try { (New-Object Security.Principal.SecurityIdentifier($k.PSChildName)).Translate([Security.Principal.NTAccount]).Value } catch { $k.PSChildName }
            if (-not ($redir | Where-Object { $_.User -eq $acct })) { continue }
            $src = @(Show-FolderRedirectionSource -Sid $k.PSChildName -Account $acct)
            foreach ($h in ($src | Where-Object { $_.AppliedToUserLastTime -or $_.AppliesVia -notmatch '^\(' })) { Add-Hit 'MEDIUM' "$acct folders redirected by GPO '$($h.GPO)' via $($h.AppliesVia) - confirm this is still wanted (legacy SBS policies often linger)." }
        }
    }

    # 8. Logoff scripts (GPO + local) and logoff-related policy
    $machScripts = @()
    Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\State' -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.PSPath -match '\\Scripts\\Logoff\\\d+\\\d+$' } | ForEach-Object { $sp = Get-ItemProperty $_.PSPath; if ($sp.Script) { $machScripts += [pscustomobject]@{ Source = 'GPO (cached state)'; Script = $sp.Script; Params = $sp.Parameters } } }
    $machScripts += $userScripts | ForEach-Object { [pscustomobject]@{ Source = "User: $($_.User)"; Script = $_.Script; Params = $_.Params } }
    Out-Section 'Logoff scripts configured (run at every sign-out)' ($machScripts | Sort-Object Script -Unique)
    if ($machScripts) { Add-Hit 'MEDIUM' "$(@($machScripts | Sort-Object Script -Unique).Count) logoff script(s) run at sign-out - test them / check their network paths." }
    $pol = @()
    $sysPol = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue
    $ctl = Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control' -ErrorAction SilentlyContinue
    $pol += [pscustomobject]@{ Setting = 'RunLogoffScriptSync';     Value = $sysPol.RunLogoffScriptSync;   Note = '1 = sign-out waits for logoff scripts' }
    $pol += [pscustomobject]@{ Setting = 'VerboseStatus';           Value = $sysPol.VerboseStatus;         Note = '1 = shows what sign-out is waiting on (handy for testing)' }
    $pol += [pscustomobject]@{ Setting = 'WaitToKillServiceTimeout'; Value = $ctl.WaitToKillServiceTimeout; Note = 'default 5000 ms; large values = slow shutdown' }
    $pol += [pscustomobject]@{ Setting = 'MaxGPOScriptWait (HKLM policy)'; Value = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' -ErrorAction SilentlyContinue).MaxGPOScriptWait; Note = 'seconds a GPO script may run' }
    Out-Section 'Logoff / shutdown related settings' $pol
    if ($ctl.WaitToKillServiceTimeout -and [int]$ctl.WaitToKillServiceTimeout -gt 20000) { Add-Hit 'LOW' "WaitToKillServiceTimeout is $($ctl.WaitToKillServiceTimeout) ms - shutdown waits that long for hung services." }

    # 9. App hangs / crashes
    $hangs = Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Application Hang','Application Error'; StartTime = $since } -ErrorAction SilentlyContinue |
        ForEach-Object { $d = $_.Properties; [pscustomobject]@{ Type = $(if ($_.ProviderName -eq 'Application Hang') { 'Hang' } else { 'Crash' }); App = "$($d[0].Value)"; Time = $_.TimeCreated } } |
        Group-Object Type, App | ForEach-Object { [pscustomobject]@{ Event = $_.Name; Count = $_.Count; Last = ($_.Group | Sort-Object Time -Descending)[0].Time } } | Sort-Object Count -Descending
    Out-Section "Application hangs / crashes (last $days days)" ($hangs | Select-Object -First 15)
    foreach ($h in ($hangs | Where-Object { $_.Count -ge 3 } | Select-Object -First 5)) { Add-Hit 'MEDIUM' "$($h.Event) $($h.Count)x in $days days." }

    # 10. Disk health / free space / storage errors
    $disks = Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | Select-Object DeviceID, @{n='SizeGB';e={[math]::Round($_.Size/1GB)}}, @{n='FreeGB';e={[math]::Round($_.FreeSpace/1GB,1)}}, @{n='FreePct';e={[math]::Round($_.FreeSpace/$_.Size*100)}}
    Out-Section 'Disk free space' $disks
    foreach ($d in $disks) { if ($d.FreePct -lt 10) { Add-Hit 'HIGH' "$($d.DeviceID) only $($d.FreePct)% free ($($d.FreeGB) GB) - low space causes lag and slow profile writes." } }
    $phys = Get-PhysicalDisk -ErrorAction SilentlyContinue | Select-Object FriendlyName, MediaType, HealthStatus, OperationalStatus
    Out-Section 'Physical disks' $phys
    foreach ($p in ($phys | Where-Object { $_.HealthStatus -and $_.HealthStatus -ne 'Healthy' })) { Add-Hit 'HIGH' "Disk '$($p.FriendlyName)' health is $($p.HealthStatus)." }
    foreach ($p in ($phys | Where-Object { $_.MediaType -eq 'HDD' })) { Add-Hit 'LOW' "Disk '$($p.FriendlyName)' is a spinning HDD - an SSD upgrade is the biggest fix for general lag." }
    $stor = Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 7,11,51,129,153,157; StartTime = $since } -ErrorAction SilentlyContinue | Where-Object { $_.ProviderName -match 'disk|stor|nvme|iaStor|Ntfs|volmgr' }
    Out-Section 'Storage errors (disk 7/51/153, controller 129, etc.)' ($stor | Group-Object ProviderName, Id | ForEach-Object { [pscustomobject]@{ Event = $_.Name; Count = $_.Count; Last = $_.Group[0].TimeCreated } })
    if ($stor) { Add-Hit 'HIGH' "$(@($stor).Count) storage/disk error event(s) in $days days - disk or controller trouble causes freezes and slow sign-out." }
    try {
        $lat = (Get-Counter '\PhysicalDisk(_Total)\Avg. Disk sec/Transfer','\PhysicalDisk(_Total)\% Idle Time' -SampleInterval 1 -MaxSamples 5 -ErrorAction Stop).CounterSamples | Group-Object Path | ForEach-Object { [pscustomobject]@{ Counter = ($_.Name -split '\\')[-1]; Avg = [math]::Round(($_.Group.CookedValue | Measure-Object -Average).Average, 4) } }
        Out-Section 'Disk latency (5 sec sample; >0.025 sec/transfer is slow)' $lat
        $sec = ($lat | Where-Object { $_.Counter -like 'avg. disk sec*' }).Avg
        if ($sec -gt 0.025) { Add-Hit 'HIGH' "Average disk latency is $([math]::Round($sec*1000)) ms per transfer right now (should be under 25 ms)." }
    } catch {}

    # 11. Pending reboot + Windows Update
    $pend = @()
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $pend += 'CBS' }
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $pend += 'Windows Update' }
    if ((Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -ErrorAction SilentlyContinue).PendingFileRenameOperations) { $pend += 'File rename' }
    Out-Section 'Pending reboot' ([pscustomobject]@{ Pending = [bool]$pend; Reasons = ($pend -join ', ') })
    if ($pend) { Add-Hit 'MEDIUM' "Reboot pending ($($pend -join ', ')) - updates waiting to install can make sign-out/shutdown slow; reboot the machine." }

    # 12. Known sign-out blockers running now
    $known = 'OneDrive','Teams','ms-teams','Outlook','Dropbox','GoogleDriveFS','Box','iCloudDrive','CcmExec','SearchIndexer','SearchProtocolHost','MsMpEng','TiWorker','TrustedInstaller','wuauclt','MoUsoCoreWorker','ShellExperienceHost','StartMenuExperienceHost','explorer','dwm','csrss'
    Out-Section 'Common sign-out blockers currently running' ($procs | Where-Object { $known -contains $_.Name } | Sort-Object WorkingSet64 -Descending | Select-Object Name, Id, SessionId, @{n='MemMB';e={[math]::Round($_.WorkingSet64/1MB)}}, @{n='CPUsec';e={[math]::Round($_.CPU)}}, Responding)
    if ($procs | Where-Object { $_.Name -in 'TiWorker','TrustedInstaller','MoUsoCoreWorker' -and $_.CPU -gt 60 }) { Add-Hit 'MEDIUM' 'Windows Update servicing (TiWorker/TrustedInstaller) is busy right now - lag and slow sign-out until it finishes.' }

    # 13. Black screen / forced power-offs (WER black-screen diagnostics, live kernel watchdog dumps)
    $wer = Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = 'Windows Error Reporting'; Id = 1001; StartTime = $since } -ErrorAction SilentlyContinue
    $bs = $wer | Where-Object { $_.Message -match 'WindowsBlackScreenDiagnostics|HamLkd|AppHangB1|MoAppHang' } | ForEach-Object {
        $m = $_.Message
        $ev = if ($m -match 'Event Name: (\S+)') { $Matches[1] } else { '?' }
        $p1 = if ($m -match 'P1: (\S*)') { $Matches[1] } else { '' }
        $p4 = if ($m -match 'P4: (\S*)') { $Matches[1] } else { '' }
        [pscustomobject]@{ Time = $_.TimeCreated; Event = $ev; P1 = $p1; P4 = $p4 } } |
        Group-Object { '{0:yyyyMMddHHmm}|{1}|{2}|{3}' -f $_.Time, $_.Event, $_.P1, $_.P4 } | ForEach-Object { $_.Group[0] } | Sort-Object Time
    Out-Section 'Black screen / app-hang reports (WER)' ($bs | Select-Object -Last 25)
    $pwrHold = @($bs | Where-Object { $_.P4 -match 'LongPowerButtonHold' })
    if ($pwrHold) { Add-Hit 'HIGH' "Black screen + power button held $($pwrHold.Count)x (last $($pwrHold[-1].Time)) - user is hard-powering off a hung display/shell. Suspect graphics driver/DWM; check LiveKernelReports dumps." }
    if (@($bs | Where-Object { $_.Event -eq 'HamLkd' })) { Add-Hit 'HIGH' "HamLkd live dump: an app ($(@($bs | Where-Object { $_.Event -eq 'HamLkd' })[0].P1 -replace '_.*','')) could not be terminated - stuck in a kernel/driver call (classic sign-out hang)." }
    $lkr = Join-Path $env:SystemRoot 'LiveKernelReports'
    $dumps = Get-ChildItem $lkr -Recurse -Filter *.dmp -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $since } | Sort-Object LastWriteTime -Descending
    Out-Section "Live kernel dumps in $lkr (last $days days)" ($dumps | Select-Object -First 20 LastWriteTime, @{n='Folder';e={$_.Directory.Name}}, Name, @{n='MB';e={[math]::Round($_.Length/1MB,1)}})
    if ($dumps) { Add-Hit 'HIGH' "$(@($dumps).Count) live kernel dump(s) (WATCHDOG = display/GPU watchdog) - open in WinDbg (!analyze -v) to name the driver; update the graphics driver from the OEM." }
    $gpu = Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Select-Object Name, DriverVersion, @{n='DriverDate';e={$_.DriverDate}}, Status
    Out-Section 'Graphics adapter / driver' $gpu

    # 14. Multi-homed / wrong DNS (domain machine on a second network, e.g. guest Wi-Fi)
    $cs = Get-CimInstance Win32_ComputerSystem
    $ipc = Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.IPv4DefaultGateway -and $_.NetAdapter.Status -eq 'Up' }
    $nets = $ipc | Select-Object InterfaceAlias, @{n='IPv4';e={$_.IPv4Address.IPAddress -join ','}}, @{n='Gateway';e={$_.IPv4DefaultGateway.NextHop -join ','}}, @{n='DNS';e={$_.DNSServer.ServerAddresses -join ','}}, @{n='Profile';e={$_.NetProfile.NetworkCategory}}
    Out-Section 'Active network connections with a gateway' $nets
    if (@($ipc).Count -gt 1) { Add-Hit 'MEDIUM' "$(@($ipc).Count) networks connected at once ($((@($ipc).InterfaceAlias) -join ', ')) - DNS/DC lookups can go out the wrong one; disconnect the extra (e.g. guest Wi-Fi)." }
    if ($cs.PartOfDomain) {
        $nl = Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'NETLOGON'; Id = 5719; StartTime = $since } -ErrorAction SilentlyContinue
        $gp = Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-GroupPolicy'; Id = 1058,1129,1054,1055; StartTime = $since } -ErrorAction SilentlyContinue
        if ($nl -or $gp) { Add-Hit 'MEDIUM' "Domain controller trouble: NETLOGON 5719 x$(@($nl).Count), Group Policy failures x$(@($gp).Count) - slow sign-in/out waiting on the DC. Check DNS points only at the DCs." }
        $dcIps = @(); try { $dcIps = @(Resolve-DnsName -Name $cs.Domain -Type A -ErrorAction Stop | Where-Object IPAddress | Select-Object -ExpandProperty IPAddress) } catch {}
        foreach ($c in $ipc) { foreach ($dns in $c.DNSServer.ServerAddresses) { if ($dns -notmatch ':' -and $dcIps -and $dcIps -notcontains $dns) { Add-Hit 'MEDIUM' "$($c.InterfaceAlias) uses DNS $dns which is not a domain controller ($($dcIps -join ', ')) - domain lookups may fail." } } }
    }

    # Summary
    $order = @{ HIGH = 0; MEDIUM = 1; LOW = 2 }
    $sorted = $findings | Sort-Object { $order[$_.Severity] }
    Write-Sub 'LIKELY CAUSES (most serious first)'
    if (-not $sorted) { Write-Host '  Nothing obvious found. Next: set VerboseStatus=1 to see what sign-out waits on, run Performance snapshot during the lag, or Sysinternals ProcMon boot/logoff trace.' -ForegroundColor Green }
    foreach ($f in $sorted) { $c = @{ HIGH = 'Red'; MEDIUM = 'Yellow'; LOW = 'Gray' }[$f.Severity]; Write-Host ("  [{0,-6}] {1}" -f $f.Severity, $f.Finding) -ForegroundColor $c }
    Write-Host "`n  Quick wins: reboot (clears pending updates/handle leaks), disconnect dead mapped drives, quit sync apps (OneDrive/Teams) before sign-out to test," -ForegroundColor DarkCyan
    Write-Host '  and if sign-out sits on a blank/"Signing out" screen, enable VerboseStatus to see what it is waiting on.' -ForegroundColor DarkCyan
    $head = "Slow sign-out / lag diagnostics - $env:COMPUTERNAME - $(Get-Date) - last $days days`r`nPrepared by Sigma Data Systems Inc. - Sigma Data Systems INC ToolKit`r`n`r`nLIKELY CAUSES:`r`n" + (($sorted | ForEach-Object { "  [$($_.Severity)] $($_.Finding)" }) -join "`r`n")
    ($head + "`r`n" + ($log -join "`r`n")) | Out-File -FilePath $report -Encoding UTF8
    $sorted | Export-Csv (Join-Path $dir "SlowLogoff_Findings_$($env:COMPUTERNAME)_$stamp.csv") -NoTypeInformation -Encoding UTF8
    Write-Host "`n  Report saved: $report" -ForegroundColor Green
}

function Invoke-ADHealth {
    Write-Title 'Active Directory / DC health (dcdiag, repadmin, SYSVOL, FSMO)'
    if (-not (Get-Command dcdiag.exe -ErrorAction SilentlyContinue)) { Write-Host '  dcdiag not found - run on a domain controller or a machine with RSAT AD DS tools.' -ForegroundColor Red; return }
    $dir = Get-OutDir 'ADHealth'; $stamp = Get-Stamp
    Write-Sub 'dcdiag (errors only)'
    $dc = dcdiag /q 2>&1; $dc | Out-File "$dir\dcdiag_q_$stamp.txt"
    if ($dc) { $dc | Write-Host } else { Write-Host '  dcdiag /q: no errors.' -ForegroundColor Green }
    dcdiag /v /c /e /skip:SystemLog 2>&1 | Out-File "$dir\dcdiag_full_$stamp.txt"
    Write-Sub 'Replication summary'
    repadmin /replsummary 2>&1 | Tee-Object "$dir\repadmin_replsummary_$stamp.txt" | Write-Host
    repadmin /showrepl * /csv 2>&1 | Out-File "$dir\repadmin_showrepl_$stamp.csv"
    Write-Sub 'FSMO role holders'
    netdom query fsmo 2>&1 | Write-Host
    Write-Sub 'SYSVOL / NETLOGON shares and DFSR state'
    Get-SmbShare -Name SYSVOL, NETLOGON -ErrorAction SilentlyContinue | Format-Table Name, Path -AutoSize
    Get-CimInstance -Namespace root\microsoftdfs -ClassName DfsrReplicatedFolderInfo -ErrorAction SilentlyContinue |
        Select-Object ReplicatedFolderName, @{n='State';e={@{0='Uninitialized';1='Initialized';2='Initial Sync';3='Auto Recovery';4='Normal';5='In Error'}[[int]$_.State]}} | Format-Table -AutoSize
    Write-Sub 'DC locator / time source'
    nltest /dsgetdc: 2>&1 | Write-Host
    Write-Host "  Full output saved under $dir" -ForegroundColor Green
}

function Invoke-BackupVssHealth {
    Write-Title 'Backup / VSS health (VSS writers, shadow copies, Windows Server Backup)'
    Write-Sub 'VSS writers (any not "Stable / No error" break backups)'
    $w = vssadmin list writers 2>&1
    $writers = @(); $cur = $null
    foreach ($l in $w) {
        if ($l -match "Writer name: '(.+)'") { $cur = [ordered]@{ Writer = $Matches[1] } }
        elseif ($cur -and $l -match 'State: \[\d+\] (.+)') { $cur.State = $Matches[1] }
        elseif ($cur -and $l -match 'Last error: (.+)') { $cur.LastError = $Matches[1]; $writers += [pscustomobject]$cur; $cur = $null }
    }
    $writers | Format-Table -AutoSize
    $bad = $writers | Where-Object { $_.State -ne 'Stable' -or $_.LastError -ne 'No error' }
    if ($bad) { Write-Host '  Failed writers: restart the owning service (e.g. SQL Writer -> SQLWriter, Exchange -> MSExchangeIS) or reboot.' -ForegroundColor Yellow }
    Write-Sub 'Shadow storage'
    vssadmin list shadowstorage 2>&1 | Write-Host
    Write-Sub 'VSS / volsnap errors (last 7 days)'
    Get-WinEvent -FilterHashtable @{ LogName = 'Application','System'; ProviderName = 'VSS','volsnap'; Level = 1,2; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 20 -ErrorAction SilentlyContinue |
        Select-Object TimeCreated, ProviderName, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
    if (Get-Command wbadmin.exe -ErrorAction SilentlyContinue) {
        Write-Sub 'Windows Server Backup - versions'
        wbadmin get versions 2>&1 | Select-Object -Last 12 | Write-Host
    }
    Write-Sub 'Backup agent services'
    Get-Service | Where-Object { $_.DisplayName -match 'Backup|Veeam|Datto|Acronis|Cove|N-able|SolarWinds MSP|Carbonite|StorageCraft|ShadowProtect|Axcient|Macrium|Synology' } |
        Select-Object Name, DisplayName, Status, StartType | Format-Table -AutoSize
}

function Invoke-SharesOpenFiles {
    Write-Title 'File shares, sessions and open files'
    Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '^\w\$$|^ADMIN\$$|^IPC\$$' } | Select-Object Name, Path, Description, CurrentUsers | Format-Table -AutoSize
    Write-Sub 'Connected sessions'
    Get-SmbSession -ErrorAction SilentlyContinue | Select-Object ClientComputerName, ClientUserName, NumOpens, SecondsIdle | Format-Table -AutoSize
    $f = Read-Default 'Show open files matching (blank = top 30 by user)' ''
    Write-Sub 'Open files'
    $open = Get-SmbOpenFile -ErrorAction SilentlyContinue
    if ($f) { $open = $open | Where-Object { $_.Path -like "*$f*" } }
    $open | Select-Object -First 30 ClientUserName, ClientComputerName, Path, FileId | Format-Table -AutoSize -Wrap
    if ($f -and $open -and (Read-YesNo 'Close these open file handles (user may lose unsaved changes)?' $false)) {
        if (Confirm-Change "Force-close $(@($open).Count) open file handle(s) matching '$f'.") { $open | Close-SmbOpenFile -Force; Write-Host '  Closed.' -ForegroundColor Green }
    }
}

function Invoke-NetworkDeepDive {
    Write-Title 'Advanced network diagnostics (DNS, route, MTU, proxy, Wi-Fi)'
    $target = Read-Default 'Target host to test (website, server, VPN peer)' 'www.microsoft.com'
    Write-Sub 'Adapters'
    Get-NetAdapter -ErrorAction SilentlyContinue | Select-Object Name, InterfaceDescription, Status, LinkSpeed, MacAddress | Format-Table -AutoSize
    Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.NetAdapter.Status -eq 'Up' } |
        Select-Object InterfaceAlias, @{n='IPv4';e={$_.IPv4Address.IPAddress -join ','}}, @{n='Gateway';e={$_.IPv4DefaultGateway.NextHop -join ','}}, @{n='DNS';e={$_.DNSServer.ServerAddresses -join ','}} | Format-Table -AutoSize
    Write-Sub "DNS resolution of $target against each configured DNS server + public"
    $dnsServers = @((Get-DnsClientServerAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue).ServerAddresses | Select-Object -Unique) + '1.1.1.1','8.8.8.8'
    foreach ($s in $dnsServers) {
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $r = Resolve-DnsName -Name $target -Server $s -DnsOnly -QuickTimeout -ErrorAction SilentlyContinue | Where-Object IPAddress
        Write-Host ("  {0,-16} {1,-40} {2} ms" -f $s, $(if ($r) { ($r.IPAddress | Select-Object -First 2) -join ', ' } else { 'FAILED' }), $sw.ElapsedMilliseconds) -ForegroundColor $(if ($r) { 'White' } else { 'Red' })
    }
    Write-Sub 'Gateway + target latency / loss (20 pings)'
    $gw = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Sort-Object RouteMetric | Select-Object -First 1).NextHop
    foreach ($h in @($gw, $target) | Where-Object { $_ }) {
        $p = Test-Connection -ComputerName $h -Count 20 -ErrorAction SilentlyContinue
        $loss = 100 - [math]::Round((@($p).Count / 20) * 100)
        Write-Host ("  {0,-30} loss {1,3}%  avg {2} ms  max {3} ms" -f $h, $loss, [math]::Round(($p | Measure-Object ResponseTime -Average).Average), ($p | Measure-Object ResponseTime -Maximum).Maximum) -ForegroundColor $(if ($loss -gt 0) { 'Yellow' } else { 'Green' })
    }
    Write-Sub 'Path MTU to target (largest packet that passes without fragmenting)'
    $lo = 1200; $hi = 1472
    while ($lo -lt $hi) { $mid = [math]::Ceiling(($lo + $hi) / 2); $ok = (ping -n 1 -f -l $mid -w 1000 $target) -match 'TTL='; if ($ok) { $lo = $mid } else { $hi = $mid - 1 } }
    Write-Host ("  Largest payload: {0} bytes  =>  path MTU ~{1}  {2}" -f $lo, ($lo + 28), $(if ($lo + 28 -lt 1500) { '(below 1500 - VPN/PPPoE overhead; may need MSS clamp)' } else { '' }))
    Write-Sub "Route to $target"
    tracert -d -h 20 -w 800 $target 2>&1 | Write-Host
    Write-Sub 'Proxy settings'
    netsh winhttp show proxy 2>&1 | Write-Host
    $ie = Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -ErrorAction SilentlyContinue
    Write-Host ("  User proxy enabled: {0}  Server: {1}  PAC: {2}" -f [bool]$ie.ProxyEnable, $ie.ProxyServer, $ie.AutoConfigURL)
    if (Get-Command netsh -ErrorAction SilentlyContinue) {
        $wl = netsh wlan show interfaces 2>&1
        if ($wl -match 'SSID') {
            Write-Sub 'Wi-Fi'
            $wl | Select-String 'SSID|Signal|Radio type|Channel|Receive rate|Transmit rate|State' | ForEach-Object { Write-Host "  $($_.Line.Trim())" }
            if (Read-YesNo 'Generate the Windows Wi-Fi report (drops, errors, last 3 days, HTML)?' $false) {
                netsh wlan show wlanreport 2>&1 | Out-Null
                $rep = "$env:ProgramData\Microsoft\Windows\WlanReport\wlan-report-latest.html"
                if (Test-Path $rep) { $dst = Join-Path (Get-OutDir 'Network') "WlanReport_$(Get-Stamp).html"; Copy-Item $rep $dst; Write-Host "  Saved $dst" -ForegroundColor Green }
            }
        }
    }
}

function Invoke-ServerRolesStatus {
    Write-Title 'Server roles & key services status'
    if (Get-Command Get-WindowsFeature -ErrorAction SilentlyContinue) {
        Get-WindowsFeature | Where-Object { $_.Installed -and $_.FeatureType -eq 'Role' } | Select-Object Name, DisplayName | Format-Table -AutoSize
    }
    $patterns = 'MSSQL|SQLAgent|SQLWriter|W3SVC|WAS$|MSExchange|DNS$|DHCPServer|NTDS|Netlogon|DFSR|Spooler|TermService|TermServLicensing|Tssdis|RDMS|vmms|ADSync|CertSvc|WsusService|IISADMIN|SMTPSVC|QuickBooksDB|QBCFMonitorService|Sage|Timberline|Pervasive|psqlWGE|Backup|Veeam'
    Get-CimInstance Win32_Service | Where-Object { $_.Name -match $patterns -or $_.DisplayName -match $patterns } |
        Select-Object Name, DisplayName, State, StartMode, @{n='Alert';e={ if ($_.StartMode -eq 'Auto' -and $_.State -ne 'Running') { 'NOT RUNNING' } }} | Sort-Object Alert -Descending | Format-Table -AutoSize
    if (Get-Module -ListAvailable WebAdministration) {
        Import-Module WebAdministration -ErrorAction SilentlyContinue
        Write-Sub 'IIS sites / app pools'
        Get-ChildItem IIS:\Sites -ErrorAction SilentlyContinue | Select-Object Name, State, @{n='Bindings';e={($_.Bindings.Collection | ForEach-Object { $_.bindingInformation }) -join '; '}} | Format-Table -AutoSize
        Get-ChildItem IIS:\AppPools -ErrorAction SilentlyContinue | Select-Object Name, State | Format-Table -AutoSize
    }
    $qb = Get-Service -Name 'QuickBooksDB*' -ErrorAction SilentlyContinue
    if ($qb) { Write-Sub 'QuickBooks Database Server Manager'; $qb | Format-Table Name, Status, StartType -AutoSize }
}


function Invoke-SelfTest {
    $dir = Get-OutDir 'SelfTest'
    $stamp = Get-Stamp
    $log = Join-Path $dir "SelfTest_${env:COMPUTERNAME}_$stamp.log"
    $csv = Join-Path $dir "SelfTest_${env:COMPUTERNAME}_$stamp.csv"
    try { Start-Transcript -Path $log -Force | Out-Null } catch { }
    $levels = @('safe') + $(if ($IncludeSlow) { 'slow' }) + $(if ($IncludeDownloads) { 'net' })
    Write-Title "SELF-TEST  v$Script:ToolkitVersion  on $env:COMPUTERNAME  ($($levels -join ', '))"
    $results = New-Object System.Collections.Generic.List[object]

    # 1. Static checks: every embedded tool extracts and parses; every menu action exists
    foreach ($k in ($Script:Payloads.Keys | Sort-Object)) {
        if ($k -like '*.json') {
            $ok = $true; try { $null = (Expand-Payload $k) | ConvertFrom-Json -ErrorAction Stop } catch { $ok = $false }
            $results.Add([pscustomobject]@{ Kind = 'Data'; Item = $k; Status = $(if ($ok) { 'PASS' } else { 'FAIL' }); Seconds = 0; ExitCode = ''; Errors = [int](-not $ok); Detail = '' })
            continue
        }
        $tok = $null; $err = $null
        [void][System.Management.Automation.Language.Parser]::ParseInput((Expand-Payload $k), [ref]$tok, [ref]$err)
        $results.Add([pscustomobject]@{ Kind = 'Parse'; Item = "$k.ps1"; Status = $(if ($err) { 'FAIL' } else { 'PASS' }); Seconds = 0; ExitCode = ''; Errors = @($err).Count; Detail = (@($err) | Select-Object -First 1 | ForEach-Object { "L$($_.Extent.StartLineNumber): $($_.Message)" }) })
    }
    foreach ($m in $Script:Menu | Where-Object { $_.Action }) {
        $fn = ([regex]::Match($m.Action.ToString(), '\b[A-Z][a-zA-Z]+-[A-Za-z0-9]+')).Value
        if (-not $fn -or -not (Get-Command $fn -ErrorAction SilentlyContinue)) { $results.Add([pscustomobject]@{ Kind = 'Menu'; Item = $m.Text; Status = 'FAIL'; Seconds = 0; ExitCode = ''; Errors = 1; Detail = "$fn not defined" }) }
    }

    # 2. Run every option at the selected test levels with default answers (changes are always declined)
    $items = @($Script:Menu | Where-Object { $_.Action -and $_.Test -in $levels })
    $n = 0
    foreach ($m in $items) {
        $n++
        Write-Host ("`n##### [{0}/{1}] {2}. {3}" -f $n, $items.Count, $m.Key, $m.Text) -ForegroundColor Magenta
        $Error.Clear(); $Script:LastToolExit = $null
        $sw = [Diagnostics.Stopwatch]::StartNew()
        $status = 'PASS'; $detail = ''
        try { & $m.Action *>&1 | Out-Host }
        catch { $status = 'FAIL'; $detail = $_.Exception.Message }
        $sw.Stop()
        if ($status -eq 'PASS' -and $null -ne $Script:LastToolExit -and $Script:LastToolExit -ne 0) { $status = 'WARN'; $detail = "embedded tool exit code $Script:LastToolExit" }
        $errs = @($Error | Where-Object { $_ -is [System.Management.Automation.ErrorRecord] })
        if (-not $detail -and $errs) { $detail = ($errs | Select-Object -Last 1).Exception.Message }
        $results.Add([pscustomobject]@{ Kind = 'Run'; Item = "$($m.Key). $($m.Text)"; Status = $status; Seconds = [math]::Round($sw.Elapsed.TotalSeconds, 1); ExitCode = $Script:LastToolExit; Errors = $errs.Count; Detail = "$detail".Substring(0, [math]::Min(200, "$detail".Length)) })
    }
    try { Stop-Transcript | Out-Null } catch { }
    $results | Export-Csv $csv -NoTypeInformation
    Write-Title 'SELF-TEST SUMMARY'
    $results | Where-Object { $_.Kind -eq 'Run' } | Format-Table Status, Seconds, ExitCode, Errors, Item -AutoSize
    $bad = @($results | Where-Object Status -ne 'PASS')
    if ($bad) { Write-Host "  Not clean ($($bad.Count)):" -ForegroundColor Yellow; $bad | Format-Table Kind, Status, Item, Detail -AutoSize -Wrap }
    $p = @($results | Where-Object Status -eq 'PASS').Count
    Write-Host ("  {0} PASS / {1} WARN / {2} FAIL.  'Errors' = non-fatal errors swallowed inside the check (missing roles/modules are normal)." -f $p, @($results | Where-Object Status -eq 'WARN').Count, @($results | Where-Object Status -eq 'FAIL').Count)
    Write-Host "  Report: $csv`n  Full transcript: $log" -ForegroundColor Green
}


# ---------- PUBLIC IP / SPEED TEST -------------------------------------------------------

function Get-PublicIPInfo([int]$TimeoutSec = 8) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    $r = [ordered]@{ IPv4 = $null; IPv6 = $null; DnsMethod = $null; ISP = $null; Location = $null; ReverseDNS = $null; CloudflareColo = $null }
    try { $r.IPv4 = (Invoke-RestMethod -Uri 'https://api.ipify.org' -TimeoutSec $TimeoutSec -UseBasicParsing).ToString().Trim() } catch { }
    try { $v6 = (Invoke-RestMethod -Uri 'https://api64.ipify.org' -TimeoutSec $TimeoutSec -UseBasicParsing).ToString().Trim(); if ($v6 -match ':') { $r.IPv6 = $v6 } } catch { }
    # DNS-based lookup (works even when HTTP goes through a proxy - shows the real firewall WAN IP)
    try { $r.DnsMethod = (Resolve-DnsName -Name 'myip.opendns.com' -Server 'resolver1.opendns.com' -Type A -DnsOnly -ErrorAction Stop | Where-Object IPAddress | Select-Object -First 1).IPAddress } catch { }
    if (-not $r.IPv4) { $r.IPv4 = $r.DnsMethod }
    try {
        $trace = (Invoke-WebRequest -Uri 'https://speed.cloudflare.com/cdn-cgi/trace' -TimeoutSec $TimeoutSec -UseBasicParsing).Content
        $kv = @{}; $trace -split "`n" | ForEach-Object { if ($_ -match '^(\w+)=(.*)$') { $kv[$Matches[1]] = $Matches[2] } }
        $r.CloudflareColo = "$($kv.colo) ($($kv.loc))"
        if (-not $r.IPv4 -and $kv.ip -notmatch ':') { $r.IPv4 = $kv.ip }
    } catch { }
    if ($r.IPv4) {
        try {
            $geo = Invoke-RestMethod -Uri "https://ipinfo.io/$($r.IPv4)/json" -TimeoutSec $TimeoutSec -UseBasicParsing
            $r.ISP = $geo.org
            $r.Location = (@($geo.city, $geo.region, $geo.country) | Where-Object { $_ }) -join ', '
        } catch { }
        try { $r.ReverseDNS = (Resolve-DnsName -Name $r.IPv4 -Type PTR -DnsOnly -ErrorAction Stop | Select-Object -First 1).NameHost } catch { }
    }
    [pscustomobject]$r
}

function Invoke-PublicIP {
    Write-Title 'What is my public IP?'
    $i = Get-PublicIPInfo
    if (-not $i.IPv4 -and -not $i.IPv6) { Write-Host '  Could not reach any IP lookup service - no internet, or outbound HTTPS/DNS is blocked.' -ForegroundColor Red; return }
    $i | Format-List
    if ($i.DnsMethod -and $i.IPv4 -and $i.DnsMethod -ne $i.IPv4) {
        Write-Host "  HTTP and DNS lookups disagree ($($i.IPv4) vs $($i.DnsMethod)) - web traffic is going through a proxy / web filter / VPN, or the site has multiple WAN links." -ForegroundColor Yellow
    }
    Write-Host '  Use this IP for: SPF records, M365 connectors, firewall allow-lists, VPN peers, vendor whitelists.' -ForegroundColor DarkGray
    $local = Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.IPv4DefaultGateway } | Select-Object -First 1
    if ($local) { Write-Host ("  Local IP: {0}   Gateway: {1}" -f ($local.IPv4Address.IPAddress -join ','), ($local.IPv4DefaultGateway.NextHop -join ',')) }
}

function Measure-CfDownload([int64]$Bytes) {
    $req = [Net.HttpWebRequest]::Create("https://speed.cloudflare.com/__down?bytes=$Bytes")
    $req.Timeout = 90000; $req.ReadWriteTimeout = 90000
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $resp = $req.GetResponse(); $s = $resp.GetResponseStream()
    $buf = New-Object byte[] 262144; $total = 0
    while (($n = $s.Read($buf, 0, $buf.Length)) -gt 0) { $total += $n }
    $sw.Stop(); $s.Close(); $resp.Close()
    return [math]::Round(($total * 8 / 1e6) / $sw.Elapsed.TotalSeconds, 1)
}

function Measure-CfUpload([int64]$Bytes) {
    $data = New-Object byte[] $Bytes
    (New-Object Random).NextBytes($data)
    $req = [Net.HttpWebRequest]::Create('https://speed.cloudflare.com/__up')
    $req.Method = 'POST'; $req.ContentType = 'application/octet-stream'; $req.ContentLength = $data.Length
    $req.AllowWriteStreamBuffering = $false; $req.SendChunked = $false; $req.Timeout = 90000; $req.ReadWriteTimeout = 90000
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $rs = $req.GetRequestStream()
    for ($o = 0; $o -lt $data.Length; $o += 262144) { $rs.Write($data, $o, [math]::Min(262144, $data.Length - $o)) }
    $rs.Close()
    $resp = $req.GetResponse(); $resp.Close()
    $sw.Stop()
    return [math]::Round(($Bytes * 8 / 1e6) / $sw.Elapsed.TotalSeconds, 1)
}

function Invoke-SpeedTest {
    Write-Title 'Internet speed test'
    Write-Host '  1. Built-in (Cloudflare speed test servers - nothing to download)'
    Write-Host '  2. Ookla Speedtest CLI (same engine as speedtest.net - downloads speedtest.exe to C:\temp\Tools)'
    $m = "$(Read-Default 'Method' '1')"
    $hist = Join-Path (Get-OutDir 'Network') 'SpeedTest_History.csv'
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    $ip = Get-PublicIPInfo -TimeoutSec 5
    Write-Host ("  Public IP: {0}   ISP: {1}   Server: Cloudflare {2}" -f $ip.IPv4, $ip.ISP, $ip.CloudflareColo) -ForegroundColor DarkGray

    if ($m -eq '2') {
        $dir = Get-ToolsDir 'Speedtest'
        $exe = Join-Path $dir 'speedtest.exe'
        if (-not (Test-Path $exe)) {
            $zip = Join-Path $dir 'speedtest.zip'
            Write-Host '  Downloading Ookla Speedtest CLI from install.speedtest.net...' -ForegroundColor DarkGray
            if (Get-WebFile 'https://install.speedtest.net/app/cli/ookla-speedtest-1.2.0-win64.zip' $zip) {
                try { Expand-Archive $zip -DestinationPath $dir -Force; Remove-Item $zip -Force } catch { Write-Host "  Unzip failed: $($_.Exception.Message)" -ForegroundColor Red }
            }
            if (-not (Test-Path $exe) -or -not (Test-DownloadedBinary $exe 'Ookla' -AllowUnsigned)) {
                Write-Host '  Ookla CLI not available - falling back to the built-in test. (Manual download: https://www.speedtest.net/apps/cli)' -ForegroundColor Yellow
                $m = '1'
            }
        }
        if ($m -eq '2') {
            Write-Host '  Running Ookla Speedtest (you are accepting the Ookla license / privacy terms by running it)...' -ForegroundColor Cyan
            $json = & $exe --accept-license --accept-gdpr --format=json 2>$null
            try {
                $o = $json | ConvertFrom-Json
                $row = [pscustomobject]@{
                    Time = Get-Date -Format 'yyyy-MM-dd HH:mm'; Host = $env:COMPUTERNAME; Method = 'Ookla'
                    DownloadMbps = [math]::Round($o.download.bandwidth * 8 / 1e6, 1); UploadMbps = [math]::Round($o.upload.bandwidth * 8 / 1e6, 1)
                    PingMs = [math]::Round($o.ping.latency, 1); JitterMs = [math]::Round($o.ping.jitter, 1); LossPct = $o.packetLoss
                    PublicIP = $o.interface.externalIp; ISP = $o.isp; Server = "$($o.server.name) - $($o.server.location)"; ResultUrl = $o.result.url
                }
            } catch { Write-Host "  Could not read Ookla output: $json" -ForegroundColor Red; return }
        }
    }
    if ($m -ne '2') {
        Write-Host '  Measuring latency (10 requests)...' -ForegroundColor DarkGray
        $lat = foreach ($x in 1..10) {
            $sw = [Diagnostics.Stopwatch]::StartNew()
            try { $r = [Net.HttpWebRequest]::Create('https://speed.cloudflare.com/__down?bytes=0'); $r.Timeout = 5000; $resp = $r.GetResponse(); $resp.Close(); $sw.Stop(); $sw.Elapsed.TotalMilliseconds } catch { }
        }
        $lat = @($lat | Sort-Object)
        if (-not $lat) { Write-Host '  Cannot reach speed.cloudflare.com - no internet or HTTPS is blocked.' -ForegroundColor Red; return }
        $ping = [math]::Round($lat[[int][math]::Floor($lat.Count / 2)], 1)
        $jit = if ($lat.Count -gt 1) { [math]::Round((1..($lat.Count - 1) | ForEach-Object { [math]::Abs($lat[$_] - $lat[$_ - 1]) } | Measure-Object -Average).Average, 1) } else { 0 }
        Write-Host "  Latency ~$ping ms (jitter $jit ms)  [includes HTTPS overhead, so a bit higher than ICMP ping]"

        Write-Host '  Download test...' -ForegroundColor DarkGray
        $dl = @()
        try {
            $warm = Measure-CfDownload 10MB
            $size = if ($warm -gt 300) { 100MB } elseif ($warm -gt 50) { 50MB } else { 15MB }
            $dl = @($warm) + @(1..3 | ForEach-Object { Measure-CfDownload $size })
        } catch { Write-Host "  Download test failed: $($_.Exception.Message)" -ForegroundColor Red }
        Write-Host '  Upload test...' -ForegroundColor DarkGray
        $ul = @()
        try {
            $warmU = Measure-CfUpload 5MB
            $sizeU = if ($warmU -gt 200) { 50MB } elseif ($warmU -gt 30) { 25MB } else { 10MB }
            $ul = @($warmU) + @(1..2 | ForEach-Object { Measure-CfUpload $sizeU })
        } catch { Write-Host "  Upload test failed: $($_.Exception.Message)" -ForegroundColor Red }
        $row = [pscustomobject]@{
            Time = Get-Date -Format 'yyyy-MM-dd HH:mm'; Host = $env:COMPUTERNAME; Method = 'Cloudflare'
            DownloadMbps = if ($dl) { ($dl | Measure-Object -Maximum).Maximum } else { $null }
            UploadMbps   = if ($ul) { ($ul | Measure-Object -Maximum).Maximum } else { $null }
            PingMs = $ping; JitterMs = $jit; LossPct = $null; PublicIP = $ip.IPv4; ISP = $ip.ISP; Server = "Cloudflare $($ip.CloudflareColo)"; ResultUrl = $null
        }
    }
    Write-Host ''
    Write-Host ("  DOWNLOAD  {0,8} Mbps" -f $row.DownloadMbps) -ForegroundColor Green
    Write-Host ("  UPLOAD    {0,8} Mbps" -f $row.UploadMbps) -ForegroundColor Green
    Write-Host ("  PING      {0,8} ms   (jitter {1} ms{2})" -f $row.PingMs, $row.JitterMs, $(if ($null -ne $row.LossPct) { ", loss $($row.LossPct)%" })) -ForegroundColor Green
    if ($row.ResultUrl) { Write-Host "  Result: $($row.ResultUrl)" }
    $wifi = (netsh wlan show interfaces 2>$null) -match '^\s+State\s+:\s+connected'
    if ($wifi) { Write-Host '  NOTE: this PC is on Wi-Fi - for a true line-speed test, plug into Ethernet.' -ForegroundColor Yellow }
    Write-Host '  Tip: speeds well below the ISP plan on a wired PC -> test from the firewall itself, then call the ISP.' -ForegroundColor DarkGray
    $row | Export-Csv -Path $hist -NoTypeInformation -Append
    $prev = @(Import-Csv $hist -ErrorAction SilentlyContinue)
    if ($prev.Count -gt 1) { Write-Sub 'Previous results on this machine'; $prev | Select-Object -Last 6 Time, Method, DownloadMbps, UploadMbps, PingMs, PublicIP | Format-Table -AutoSize }
    Write-Host "  History: $hist" -ForegroundColor DarkGray
}


# ---------- MICROSOFT 365 ---------------------------------------------------------------
# Every M365 option runs in its own PowerShell process (Exchange Online and Microsoft Graph
# can't share one Windows PowerShell 5.1 session reliably). Set the admin account / client
# tenant once with "M365: set admin account & client tenant" and every option reuses it.

$Script:M365 = @{ AdminUPN = ''; DelegatedOrganization = ''; TenantId = '' }

function Get-M365Label {
    $parts = @()
    if ($Script:M365.AdminUPN) { $parts += "admin $($Script:M365.AdminUPN)" }
    if ($Script:M365.DelegatedOrganization) { $parts += "client $($Script:M365.DelegatedOrganization)" }
    elseif ($Script:M365.TenantId) { $parts += "tenant $($Script:M365.TenantId)" }
    if ($parts) { $parts -join ', ' } else { 'not set (you will be asked to sign in)' }
}

function Set-M365Target {
    Write-Title 'Microsoft 365: admin account & client tenant'
    Write-Host '  Leave blank to sign in interactively to your own tenant.'
    Write-Host '  For a CLIENT tenant via partner/GDAP access, enter the client''s domain (e.g. client.onmicrosoft.com) for both tenant prompts.' -ForegroundColor DarkGray
    $Script:M365.AdminUPN = "$(Read-Default 'Admin account UPN (e.g. you@yourdomain.com)' $Script:M365.AdminUPN)"
    $Script:M365.DelegatedOrganization = "$(Read-Default 'Client tenant for Exchange Online (DelegatedOrganization, blank = own tenant)' $Script:M365.DelegatedOrganization)"
    $defTid = if ($Script:M365.TenantId) { $Script:M365.TenantId } else { $Script:M365.DelegatedOrganization }
    $Script:M365.TenantId = "$(Read-Default 'Client tenant for Microsoft Graph (domain or tenant ID, blank = own tenant)' $defTid)"
    Write-Host "  M365 target: $(Get-M365Label)" -ForegroundColor Green
}

function Get-M365Params {
    $p = [ordered]@{ AdminUPN = $Script:M365.AdminUPN; DelegatedOrganization = $Script:M365.DelegatedOrganization; TenantId = $Script:M365.TenantId }
    return $p
}

function Invoke-M365 {
    param([string]$Action, [System.Collections.IDictionary]$Extra = @{})
    Write-Host "  M365 target: $(Get-M365Label)" -ForegroundColor DarkGray
    $p = [ordered]@{ Action = $Action }
    foreach ($k in (Get-M365Params).Keys) { $p[$k] = (Get-M365Params)[$k] }
    $p.OutputPath = (Get-OutDir 'M365')
    foreach ($k in $Extra.Keys) { $p[$k] = $Extra[$k] }
    Invoke-Tool 'M365-Toolbox' $p | Out-Null
}

function Invoke-M365CompromiseAudit {
    Write-Title 'M365: compromised account audit (read-only, HTML report)'
    Write-Host '  Inbox rules, forwarding, sign-ins & risk, MFA methods, delegates, OAuth apps, recent sends, admin roles.'
    $u = Read-Default 'User / mailbox to audit (UPN)' ''
    if (-not $u) { return }
    $d = Read-Int 'Days of history' 30
    $rm = Read-YesNo 'Open the interactive rule manager to remove malicious inbox rules afterwards?' $false
    $p = [ordered]@{ UserPrincipalName = $u; DaysBack = $d; ReportPath = (Get-OutDir 'M365'); RemoveMaliciousRules = $rm }
    foreach ($k in (Get-M365Params).Keys) { $p[$k] = (Get-M365Params)[$k] }
    Invoke-Tool 'Invoke-CompromisedAccountAudit' $p | Out-Null
}

function Invoke-M365Contain {
    Write-Title '[!] M365: contain a compromised account'
    Write-Host '  Step 1 (Entra / Graph): block sign-in, revoke sessions, reset password, review MFA methods + app consents, last sign-ins.'
    Write-Host '  Step 2 (Exchange): remove forwarding, disable malicious rules, lift the outbound-spam send restriction, check delegates.'
    Write-Host '  Every action asks first (type YES).' -ForegroundColor DarkGray
    $u = Read-Default 'Compromised user (UPN)' ''
    if (-not $u) { return }
    if (Read-YesNo 'Run step 1 - Entra ID / Graph?' $true) { Invoke-M365 'ContainGraph' ([ordered]@{ UserPrincipalName = $u }) }
    if (Read-YesNo 'Run step 2 - Exchange Online?' $true) { Invoke-M365 'ContainExchange' ([ordered]@{ UserPrincipalName = $u }) }
    Write-Host '  Then: run the compromised account audit to confirm, tell the user, and watch sign-ins for a few days.' -ForegroundColor Cyan
}

function Invoke-M365TopDomains {
    Write-Title 'M365: top sender / recipient domains (message trace, up to 90 days)'
    $dir = if ("$(Read-Default 'I = inbound (who sends to us)  O = outbound (who we send to)' 'I')".ToUpper() -eq 'O') { 'Get-TopOutboundDomains' } else { 'Get-TopInboundDomains' }
    $d = Read-Int 'Days (1-90)' 90
    $top = Read-Int 'Domains to show on screen' 50
    $del = Read-YesNo 'Count delivered mail only?' $false
    $p = [ordered]@{ UserPrincipalName = $Script:M365.AdminUPN; DelegatedOrganization = $Script:M365.DelegatedOrganization; Days = $d; Top = $top; OutputFolder = (Get-OutDir 'M365'); DeliveredOnly = $del }
    Invoke-Tool $dir $p | Out-Null
    Write-Host '  Use the inbound list to pre-whitelist top partners before switching mail filtering (e.g. Barracuda) on.' -ForegroundColor DarkGray
}

function Invoke-M365TenantHardening {
    Write-Title 'M365: tenant hardening audit (legacy auth, forwarding, audit log, Defender policies, alerts, admins)'
    $p = [ordered]@{ OutputPath = (Get-OutDir 'M365') }
    foreach ($k in (Get-M365Params).Keys) { $p[$k] = (Get-M365Params)[$k] }
    Invoke-Tool 'Invoke-TenantHardeningAudit' $p | Out-Null
}

function Invoke-M365PostureAudit {
    Write-Title 'M365: security posture audit (134 checks, license-aware, client-ready HTML + JSON)'
    Save-Payload 'data/all-checks.json' $Script:WorkDir | Out-Null
    Save-Payload 'data/license-sku-map.json' $Script:WorkDir | Out-Null
    $name = Read-Default 'Client / tenant name for the report title (blank = tenant domain)' ''
    $spo = Read-YesNo 'Include SharePoint Online checks (needs the SPO module + SharePoint admin URL)?' $true
    $p = [ordered]@{ TenantName = $name; OutputPath = (Get-OutDir 'M365'); SkipSharePoint = (-not $spo) }
    foreach ($k in (Get-M365Params).Keys) { $p[$k] = (Get-M365Params)[$k] }
    Invoke-Tool 'Invoke-M365PostureAudit' $p | Out-Null
    if (Read-YesNo 'Generate the remediation plan (technical + client summary) from this audit now?' $true) { Invoke-M365RemediationPlan }
}

function Invoke-M365RemediationPlan {
    Write-Title 'M365: remediation plan from a posture audit'
    Save-Payload 'data/all-checks.json' $Script:WorkDir | Out-Null
    $latest = Get-ChildItem (Get-OutDir 'M365') -Filter 'M365_Posture_Audit_*.json' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    $json = Read-Default 'Posture audit JSON file' $(if ($latest) { $latest.FullName } else { '' })
    if (-not $json -or -not (Test-Path $json)) { Write-Host '  No audit JSON found - run the posture audit first.' -ForegroundColor Yellow; return }
    Invoke-Tool 'New-RemediationPlan' ([ordered]@{ AuditJsonPath = $json; OutputPath = (Get-OutDir 'M365') }) | Out-Null
}

function Invoke-M365AppRegistration {
    Write-Title '[!] M365: create an app registration for unattended automation (certificate auth)'
    Write-Host '  Creates an Entra app + self-signed certificate (in your CurrentUser store) and grants it'
    Write-Host '  User.ReadWrite.All, Group.ReadWrite.All, Organization.Read.All application permissions.'
    if (-not (Confirm-Change 'Create an app registration with application permissions in the tenant you sign in to.')) { return }
    $name = Read-Default 'App display name' 'SDSI-M365-Automation'
    $yrs = Read-Int 'Certificate validity (years)' 2
    Invoke-Tool 'Setup-GraphAppRegistration' ([ordered]@{ AppDisplayName = $name; CertValidityYears = $yrs }) | Out-Null
    Write-Host '  Save the TenantId / AppId / Thumbprint it printed (password manager). Rotate the certificate before it expires.' -ForegroundColor Yellow
}

function Invoke-M365Simple([string]$Title, [string]$Action, [switch]$AskUser, [switch]$OfferAll) {
    Write-Title "M365: $Title"
    $x = [ordered]@{}
    if ($OfferAll -and (Read-YesNo 'Run against ALL mailboxes (slow on big tenants)?' $false)) { $x.AllMailboxes = $true }
    elseif ($AskUser -or $OfferAll) { $u = Read-Default 'User / mailbox (UPN)' ''; if (-not $u) { return }; $x.UserPrincipalName = $u }
    Invoke-M365 $Action $x
}

# ---------- Entra / Intune on THIS device ------------------------------------------------

function Invoke-ForceHybridJoin {
    Write-Title '[!] Force a Hybrid Entra ID join attempt (domain-joined PC)'
    $st = dsregcmd /status
    $get = { param($k) (($st | Select-String "^\s*$k\s*:" | Select-Object -First 1).ToString() -split ':', 2)[1].Trim() }
    Write-Host ("  DomainJoined: {0}   AzureAdJoined: {1}" -f (& $get 'DomainJoined'), (& $get 'AzureAdJoined'))
    if ((& $get 'DomainJoined') -ne 'YES') { Write-Host '  Not domain joined - hybrid join does not apply.' -ForegroundColor Yellow; return }
    if (-not (Confirm-Change 'Run gpupdate /force and trigger the "Automatic-Device-Join" scheduled task.')) { return }
    gpupdate /force | Out-Null
    Get-ScheduledTask -TaskName 'Automatic-Device-Join' -TaskPath '\Microsoft\Windows\Workplace Join\' -ErrorAction SilentlyContinue | Start-ScheduledTask
    Write-Host '  Waiting 20 seconds...' -ForegroundColor DarkGray; Start-Sleep -Seconds 20
    $st = dsregcmd /status
    $aad = & $get 'AzureAdJoined'
    $info = Get-ScheduledTaskInfo -TaskName 'Automatic-Device-Join' -TaskPath '\Microsoft\Windows\Workplace Join\' -ErrorAction SilentlyContinue
    Write-Host ("  AzureAdJoined now: {0}   Join task last result: 0x{1:X}" -f $aad, $info.LastTaskResult) -ForegroundColor $(if ($aad -eq 'YES') { 'Green' } else { 'Yellow' })
    if ($aad -ne 'YES') {
        Write-Host '  Not joined yet. Usual causes: Entra Connect has not synced the computer object yet (wait one sync cycle), the computer''s OU' -ForegroundColor DarkGray
        Write-Host '  is not in sync scope, the SCP is missing, or the PC cannot reach enterpriseregistration.windows.net. See event log:' -ForegroundColor DarkGray
        Write-Host '  Applications and Services > Microsoft > Windows > User Device Registration > Admin.' -ForegroundColor DarkGray
        Get-WinEvent -LogName 'Microsoft-Windows-User Device Registration/Admin' -MaxEvents 5 -ErrorAction SilentlyContinue | Select-Object TimeCreated, Id, @{n='Message';e={($_.Message -split "`n")[0]}} | Format-Table -AutoSize -Wrap
    }
}

function Invoke-BitLockerToEntra {
    Write-Title '[!] Back up this PC''s BitLocker recovery key to Entra ID'
    $vol = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction SilentlyContinue
    if (-not $vol) { Write-Host '  BitLocker not available on this machine.' -ForegroundColor Red; return }
    Write-Host ("  {0}: protection {1}, {2}% encrypted" -f $vol.MountPoint, $vol.ProtectionStatus, $vol.EncryptionPercentage)
    $rp = @($vol.KeyProtector | Where-Object KeyProtectorType -eq 'RecoveryPassword')
    if (-not $rp) { Write-Host '  No recovery password protector exists - add one first: manage-bde -protectors -add C: -RecoveryPassword' -ForegroundColor Yellow; return }
    $dj = dsregcmd /status | Select-String 'AzureAdJoined\s*:\s*YES'
    if (-not $dj) { Write-Host '  This PC is not Entra (Azure AD) joined - the key cannot be escrowed to Entra. (Hybrid: join first.)' -ForegroundColor Yellow; return }
    if (Confirm-Change "Escrow $($rp.Count) recovery key(s) for $($vol.MountPoint) to Entra ID.") {
        foreach ($k in $rp) {
            try { BackupToAAD-BitLockerKeyProtector -MountPoint $env:SystemDrive -KeyProtectorId $k.KeyProtectorId -ErrorAction Stop | Out-Null; Write-Host "  Backed up key $($k.KeyProtectorId)" -ForegroundColor Green }
            catch { Write-Host "  Failed: $($_.Exception.Message)" -ForegroundColor Red }
        }
        Write-Host '  Check: Entra admin center > Devices > this device > BitLocker keys.' -ForegroundColor DarkGray
    }
}

# ---------- TOOLKIT ------------------------------------------------------------------

function Set-OutputRoot {
    $new = Read-Default 'New output folder' $Script:OutRoot
    try { Ensure-Dir $new | Out-Null; $Script:OutRoot = (Resolve-Path $new).ProviderPath; Write-Host "  Output folder: $Script:OutRoot" -ForegroundColor Green }
    catch { Write-Host "  Can't use that folder: $($_.Exception.Message)" -ForegroundColor Red }
}

function Export-AllTools {
    $dest = Get-OutDir 'EmbeddedScripts'
    foreach ($k in ($Script:Payloads.Keys | Sort-Object)) { Write-Host "  $(Save-Payload $k $dest)" }
    Write-Host "  Extracted $($Script:Payloads.Count) scripts to $dest" -ForegroundColor Green
}

