#region ------------------------------------------------------------- Menu

$Script:Menu = @(
    @{ Section = 'SYSTEM HEALTH' }
    @{ Test='safe'; Text = 'Quick system snapshot (OS, uptime, RAM, disks, pending reboot, errors)';       Action = { Invoke-QuickSnapshot } }
    @{ Test='slow'; Text = 'Export event logs (Application, System, Security, Setup...) + error summary';  Action = { Invoke-EventLogExport } }
    @{ Test='safe'; Text = 'Crash / BSOD / unexpected reboot report (HTML)';                                Action = { Invoke-CrashReport } }
    @{ Test='safe'; Text = 'Display / GPU crash diagnostics (TDR, nvlddmkm, WHEA)';                         Action = { Invoke-DisplayCrash } }
    @{ Test='safe'; Text = 'Memory usage diagnostics';                                                      Action = { Invoke-MemoryDiag } }
    @{ Test='safe'; Text = 'Reliability history (Reliability Monitor data, stability index)';               Action = { Invoke-ReliabilityHistory } }
    @{ Test='safe'; Text = 'Performance snapshot (CPU / RAM / disk latency / network, 30 sec)';             Action = { Invoke-PerfSnapshot } }
    @{ Test='safe'; Text = 'Boot / logon performance (what slows startup)';                                 Action = { Invoke-BootPerformance } }
    @{ Test='safe'; Text = 'Slow sign-out / logoff / shutdown / black screen / lag diagnostics';           Action = { Invoke-SlowLogoffDiag } }
    @{ Test='safe'; Text = 'Hardware health (SMART, disk errors, driver problems, battery, temps)';         Action = { Invoke-HardwareHealth } }
    @{ Test='safe'; Text = 'Pending reboot - detailed (CBS, WU, file renames, rename/join, ConfigMgr)';     Action = { Invoke-PendingReboot } }
    @{ Test='safe'; Text = 'Device join / Entra ID / Workplace join / PIN status (dsregcmd)';               Action = { Invoke-DeviceJoinStatus } }
    @{ Test='safe'; Text = 'Patch & reboot history report (HTML)';                                          Action = { Invoke-PatchReport } }
    @{               Text = '[!] Enable crash dumps (Automatic memory dump)';                                Action = { Invoke-EnableCrashDump } }
    @{ Section = 'WINDOWS UPDATE / UPGRADE / REPAIR' }
    @{ Test='slow'; Text = 'Windows Update - list available updates + history (optional install)';        Action = { Invoke-WindowsUpdateList } }
    @{               Text = '[!] Reset Windows Update components (Windows 10/11)';                           Action = { Invoke-WUReset } }
    @{               Text = '[!] Repair Windows Update (Windows Server 2016+)';                              Action = { Invoke-WURepairServer } }
    @{               Text = '[!] System file repair (DISM RestoreHealth + SFC)';                             Action = { Invoke-SfcDism } }
    @{ Test='safe'; Text = 'Windows 11 upgrade troubleshooter (status, SetupDiag, logs...)';                Action = { Invoke-Win11Troubleshooter } }
    @{ Test='net';  Text = 'Microsoft SetupDiag - why did an upgrade fail? (downloads from Microsoft)';     Action = { Invoke-SetupDiag } }
