# Number the menu items in order (adding/removing an item never needs renumbering)
# Section letters skip B/O/Q/R/T/X (those are menu commands)
$n = 0; $letters = 'ACDEFGHIJKLMNPSUVWYZ'; $si = -1; $curSec = $null
foreach ($m in $Script:Menu) {
    if ($m.Section) { $si++; $m.Letter = "$($letters[$si])"; $curSec = $m; continue }
    $n++; $m.Key = "$n"
    if (-not $curSec.First) { $curSec.First = $n }
    $curSec.Last = $n
}
