function Show-Menu {
    Clear-Host
    $host.UI.RawUI.WindowTitle = 'Sigma Data Systems INC ToolKit'
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    Write-Host $Script:Banner -ForegroundColor Cyan
    Write-Host ('=' * 78) -ForegroundColor Cyan
    Write-Host "  Sigma Data Systems INC ToolKit  v$Script:ToolkitVersion  -  workstation & server diagnostics" -ForegroundColor Cyan
    Write-Host "  https://sigmadatainc.com/" -ForegroundColor DarkCyan
    Write-Host ('=' * 78) -ForegroundColor Cyan
    Write-Host ("  Host: {0}   Domain: {1}" -f $env:COMPUTERNAME, $(if ($cs.PartOfDomain) { $cs.Domain } else { 'WORKGROUP' }))
    Write-Host ("  OS:   {0}" -f $os.Caption)
    Write-Host ("  M365:  {0}" -f (Get-M365Label)) -ForegroundColor DarkGray
    Write-Host ("  Admin: {0}   Output: {1}" -f $(if (Test-IsAdmin) { 'Yes' } else { 'NO - many options need elevation' }), $Script:OutRoot)
    $sections = @($Script:Menu | Where-Object { $_.Section })
    if ($Script:View -eq 'HOME') {
        Write-Host ''
        for ($s = 0; $s -lt $sections.Count; $s++) {
            $first = $sections[$s].First; $last = $sections[$s].Last
            Write-Host ("  {0}. {1,-62} ({2}-{3})" -f $sections[$s].Letter, $sections[$s].Section, $first, $last) -ForegroundColor Yellow
        }
        Write-Host "`n  Pick a letter to open a section, or type any option number directly. ALL = show every option." -ForegroundColor Gray
    } else {
        $show = $false
        foreach ($m in $Script:Menu) {
            if ($m.Section) {
                $show = ($Script:View -eq 'ALL' -or $m.Letter -eq $Script:View)
                if ($show) { Write-Host "`n $($m.Letter). $($m.Section)" -ForegroundColor Yellow }
                continue
            }
            if (-not $show) { continue }
            $color = if ($m.Text.StartsWith('[!]')) { 'DarkYellow' } else { 'White' }
            Write-Host ("  {0,3}. {1}" -f $m.Key, $m.Text) -ForegroundColor $color
        }
        Write-Host "`n  B. Back to sections" -ForegroundColor Gray
    }
    Write-Host "  O. Output folder   R. Open output folder   T. Self-test   X. Extract embedded scripts   L2. Tool download links   Q. Quit" -ForegroundColor Gray
    Write-Host '  [!] = changes the machine (always asks first)' -ForegroundColor DarkYellow
}

