# --- Connected Apps & User Consent ---
Invoke-SafeCheck -CheckId 'connected-apps-user-consent' -ScriptBlock {
    try {
        $spResp = Invoke-MgGraphRequest -Method GET -Uri ("https://graph.microsoft.com/v1.0/servicePrincipals?" + '$filter=tags/any(t:t eq ' + "'WindowsAzureActiveDirectoryIntegratedApp')" + "&" + '$count=true') -Headers @{ 'ConsistencyLevel' = 'eventual' }
        $appCount = $spResp.value.Count
    } catch {
        $appCount = 0
    }
    $authPolicy = Get-CachedAuthorizationPolicy
    $consentPolicyIds = $authPolicy.permissionGrantPolicyIdsAssignedToDefaultUserRole
    $usersCanConsent = ($consentPolicyIds -contains 'ManagePermissionGrantsForSelf.microsoft-user-default-legacy')
    $status = if (-not $usersCanConsent) { 'Compliant' } else { 'Not Compliant' }
    $detail = "You have $appCount connected apps. Users may $(if ($usersCanConsent) {''} else {'not '})consent for applications."
    Add-CheckResult (New-CheckResult -CheckId 'connected-apps-user-consent' -Status $status -Detail $detail -Confidence 'Medium')
}

