# --- Guest User Access ---
Invoke-SafeCheck -CheckId 'guest-user-access' -ScriptBlock {
    $authPolicy = Get-CachedAuthorizationPolicy
    $guestRole = $authPolicy.guestUserRoleId
    # '2af84b1e-32c8-42b7-82bc-daa82404023b' = Restricted Guest User (most restrictive)
    $status = if ($guestRole -eq '2af84b1e-32c8-42b7-82bc-daa82404023b') { 'Compliant' } else { 'Not Compliant' }
    $detail = "Guest user role ID: $guestRole"
    Add-CheckResult (New-CheckResult -CheckId 'guest-user-access' -Status $status -Detail $detail -Confidence 'High')
}

# --- Guest Access Restrictions (same setting) ---
Invoke-SafeCheck -CheckId 'guest-access-restrictions' -ScriptBlock {
    $authPolicy = Get-CachedAuthorizationPolicy
    $guestRole = $authPolicy.guestUserRoleId
    # Two GUIDs pass per Microsoft/CIS guidance: '10dae51f-...' (limited access, the
    # secure default) and '2af84b1e-...' (most restrictive). Only the legacy
    # 'a0b1b346-...' (same access as tenant members) value should fail this check.
    $compliantRoleIds = @('10dae51f-b6af-4016-8d66-8c2a99b929b3', '2af84b1e-32c8-42b7-82bc-daa82404023b')
    $status = if ($compliantRoleIds -contains $guestRole) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Guest user role ID: $guestRole"
    Add-CheckResult (New-CheckResult -CheckId 'guest-access-restrictions' -Status $status -Detail $detail -Confidence 'High')
}

