    $compliantRoleIds = @('10dae51f-b6af-4016-8d66-8c2a99b929b3', '2af84b1e-32c8-42b7-82bc-daa82404023b')
    $status = if ($compliantRoleIds -contains $guestRole) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Guest user role ID: $guestRole"
    Add-CheckResult (New-CheckResult -CheckId 'entra-guest-user-access-permissions' -Status $status -Detail $detail -Confidence 'High')
}

# --- Powershell Access For Non-admins (requires Exchange Online) ---
Invoke-SafeCheck -CheckId 'powershell-access-non-admins' -ScriptBlock {
    if ($script:SkipExchange) {
        Add-CheckResult (New-CheckResult -CheckId 'powershell-access-non-admins' -Status 'Not Run' -Detail "Exchange Online connection not available." -Confidence 'High')
        return
    }
    $allUsers = Get-User -ResultSize Unlimited | Where-Object { $_.RecipientTypeDetails -eq 'UserMailbox' }

    $privMembers = Get-AllPrivilegedRoleMembers
    $adminUpnList = @()
    foreach ($m in $privMembers) {
        $upn = if ($m -is [System.Collections.IDictionary]) { $m['userPrincipalName'] } else { $m.userPrincipalName }
        if ($upn) { $adminUpnList += $upn }
    }

    $nonAdmins = $allUsers | Where-Object { $_.UserPrincipalName -notin $adminUpnList }
    $enabledCount = ($nonAdmins | Where-Object { $_.RemotePowerShellEnabled -eq $true }).Count
    $disabledCount = $nonAdmins.Count - $enabledCount
    $status = if ($enabledCount -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = "You have $disabledCount of $($nonAdmins.Count) non-admin accounts that have Powershell disabled."
    Add-CheckResult (New-CheckResult -CheckId 'powershell-access-non-admins' -Status $status -Detail $detail -Confidence 'High')
}

