# --- Disable weakest 2FA authenticators ---
Invoke-SafeCheck -CheckId 'disable-weakest-2fa' -ScriptBlock {
    $authMethodsPolicy = Get-CachedAuthenticationMethodsPolicy
    $weakMethods = @('Sms','Voice','Email')
    $enabledWeak = @()
    foreach ($m in $weakMethods) {
        $cfg = $authMethodsPolicy.authenticationMethodConfigurations | Where-Object { $_.id -eq $m }
        if ($cfg -and $cfg.state -eq 'enabled') { $enabledWeak += $m }
    }
    $status = if ($enabledWeak.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($enabledWeak.Count -gt 0) { "Weak authenticator methods enabled: $($enabledWeak -join ', ')" } else { "No weak authenticator methods are enabled." }
    Add-CheckResult (New-CheckResult -CheckId 'disable-weakest-2fa' -Status $status -Detail $detail -Confidence 'High')
}

