# --- Login Portal Branding ---
Invoke-SafeCheck -CheckId 'login-portal-branding' -ScriptBlock {
    try {
        $branding = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/organization/$($mgContext.TenantId)/branding/localizations/0"
        $hasBranding = $branding.backgroundColor -or $branding.bannerLogoRelativeUrl
