    $enabledPolicies = $policies | Where-Object { $_.state -eq 'enabled' }
    $withoutExclusion = $enabledPolicies | Where-Object {
        $_.conditions.users.excludeUsers.Count -eq 0 -and $_.conditions.users.excludeGroups.Count -eq 0
    }
    $status = if ($withoutExclusion.Count -eq 0 -and $enabledPolicies.Count -gt 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = "$($withoutExclusion.Count) of $($enabledPolicies.Count) enabled policies have no user/group exclusions configured. Manually confirm a break-glass account exists and is excluded from all of them."
    Add-CheckResult (New-CheckResult -CheckId 'exclude-breakglass-account' -Status $status -Detail $detail -Confidence 'Medium')
}

