# --- Global Admin Role Activation (PIM, requires Entra ID P2 to even query) ---
Invoke-SafeCheck -CheckId 'global-admin-role-activation' -ScriptBlock {
    try {
        $gaRole = (Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/directoryRoles?`$filter=displayName eq 'Global Administrator'").value
        $roleDefId = $gaRole.roleTemplateId
        $policyAssignment = Invoke-MgGraphRequest -Method GET -Uri ("https://graph.microsoft.com/v1.0/policies/roleManagementPolicyAssignments?" + '$filter=scopeId eq ' + "'/' and scopeType eq 'DirectoryRole' and roleDefinitionId eq '$roleDefId'" + "&" + '$expand=policy($expand=rules)')
        $approvalRule = $policyAssignment.value.policy.rules | Where-Object { $_.id -eq 'Approval_EndUser_Assignment' }
        $requiresApproval = $approvalRule.setting.isApprovalRequired
        $status = if ($requiresApproval -eq $true) { 'Compliant' } else { 'Not Compliant' }
        $detail = "Global Administrator activation requires approval: $requiresApproval"
        Add-CheckResult (New-CheckResult -CheckId 'global-admin-role-activation' -Status $status -Detail $detail -Confidence 'Medium')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'global-admin-role-activation' -Status 'Not Run' -Detail "Requires Entra ID P2/PIM policy read access; could not retrieve. Verify manually in PIM role settings for Global Administrator." -Confidence 'Low')
    }
}

# --- Highly Privileged Roles Outside of PAM ---
Invoke-SafeCheck -CheckId 'highly-privileged-roles-outside-pam' -ScriptBlock {
    try {
        $eligibleAssignments = (Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/roleManagement/directory/roleEligibilitySchedules").value
        $activeAssignments = (Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignmentSchedules").value
        $directAssignments = (Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignments").value
        $eligiblePrincipalIds = $eligibleAssignments | Select-Object -ExpandProperty principalId -Unique
        $outsidePam = $directAssignments | Where-Object { $_.principalId -notin $eligiblePrincipalIds }
        $status = if ($outsidePam.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
        $detail = "$($outsidePam.Count) role assignment(s) found outside PIM management (excludes break-glass exclusion logic, review manually)."
        Add-CheckResult (New-CheckResult -CheckId 'highly-privileged-roles-outside-pam' -Status $status -Detail $detail -Confidence 'Low')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'highly-privileged-roles-outside-pam' -Status 'Not Run' -Detail "Requires Entra ID P2/PIM read access. Verify manually." -Confidence 'Low')
    }
}

# --- Permanent Highly Privileged Role Assignments ---
Invoke-SafeCheck -CheckId 'permanent-highly-privileged-roles' -ScriptBlock {
    try {
        $assignmentSchedules = (Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/roleManagement/directory/roleAssignmentSchedules?`$filter=assignmentType eq 'Assigned'").value
        $permanent = $assignmentSchedules | Where-Object { -not $_.scheduleInfo.expiration -or $_.scheduleInfo.expiration.type -eq 'noExpiration' }
        $status = if ($permanent.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
        $detail = "$($permanent.Count) permanent (non-expiring) privileged role assignment(s) found."
        Add-CheckResult (New-CheckResult -CheckId 'permanent-highly-privileged-roles' -Status $status -Detail $detail -Confidence 'Low')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'permanent-highly-privileged-roles' -Status 'Not Run' -Detail "Requires Entra ID P2/PIM read access. Verify manually." -Confidence 'Low')
    }
}

# --- Privileged role on Control Plane are managed by PIM only ---
Invoke-SafeCheck -CheckId 'privileged-role-pim-only' -ScriptBlock {
    Add-CheckResult (New-CheckResult -CheckId 'privileged-role-pim-only' -Status 'Not Run' -Detail "Overlaps with 'Highly Privileged Roles Outside of PAM' check; review that result and verify manually, excluding break-glass accounts." -Confidence 'Low')
}

# --- Unused privileged role assignments ---
Invoke-SafeCheck -CheckId 'unused-privileged-role-assignments' -ScriptBlock {
