}

# --- Enforce credential configurations on apps and service principals ---
Invoke-SafeCheck -CheckId 'entra-workload-id-credential-config' -ScriptBlock {
    try {
        $appMgmtPolicy = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/policies/defaultAppManagementPolicy"
        $status = if ($appMgmtPolicy.isEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
