    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'entra-workload-id-credential-config' -Status 'Not Run' -Detail "Could not retrieve default app management policy. Verify manually; requires Entra Workload ID Premium." -Confidence 'Low')
    }
}

# ============================================================================
# CHECKS: Exchange Online & Defender for Office 365
# ============================================================================

if ($script:SkipExchange) {
    Write-Host "Skipping all Exchange/Defender checks - Exchange Online connection not available." -ForegroundColor Yellow
} else {

# --- Calendar sharing ---
Invoke-SafeCheck -CheckId 'calendar-sharing' -ScriptBlock {
    $policy = Get-SharingPolicy | Where-Object { $_.Default -eq $true }
    $allDomainsCalendar = $policy.Domains | Where-Object { $_ -like 'Anonymous*CalendarSharing*' -or $_ -like '*:CalendarSharing*' }
    $sharesWithAll = ($policy.Domains -join ';') -match 'Anonymous.*Calendar'
    $status = if (-not $sharesWithAll) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($sharesWithAll) { "Calendar details are shared with all domains." } else { "Calendar details are not shared with all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'calendar-sharing' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Contact folders sharing ---
Invoke-SafeCheck -CheckId 'contact-folder-sharing' -ScriptBlock {
    $policy = Get-SharingPolicy | Where-Object { $_.Default -eq $true }
    $sharesWithAll = ($policy.Domains -join ';') -match 'Anonymous.*Contacts'
    $status = if (-not $sharesWithAll) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($sharesWithAll) { "Contact folders are shared with all domains." } else { "Contact folders are not shared with all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'contact-folder-sharing' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Create Safe Links policies for email messages ---
Invoke-SafeCheck -CheckId 'create-safe-links-policy' -ScriptBlock {
    $policies = @(Get-SafeLinksPolicy)
    $rules = @(Get-SafeLinksRule)
    $hasPolicy = $policies.Count -gt 0
    $hasFullCoverageRule = $rules | Where-Object { $_.State -eq 'Enabled' -and (-not $_.SentToMemberOf -and -not $_.RecipientDomainIs -and -not $_.SentTo) }
    $status = if ($hasPolicy -and ($hasFullCoverageRule -or $rules.Count -gt 0)) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Safe Links policies found: $($policies.Count). Rules found: $($rules.Count)."
    Add-CheckResult (New-CheckResult -CheckId 'create-safe-links-policy' -Status $status -Detail $detail -Confidence 'Medium')
}

