# --- Ensure all forms of mail forwarding are blocked and/or disabled ---
Invoke-SafeCheck -CheckId 'block-mail-forwarding' -ScriptBlock {
    $remoteDomain = Get-RemoteDomain -Identity Default
    $autoForwardBlocked = ($remoteDomain.AutoForwardEnabled -eq $false)
    $inboxRulesWithForward = @()
    try {
        $mailboxes = Get-Mailbox -ResultSize Unlimited -RecipientTypeDetails UserMailbox
        foreach ($mb in $mailboxes) {
            $rules = Get-InboxRule -Mailbox $mb.PrimarySmtpAddress -ErrorAction SilentlyContinue | Where-Object { $_.ForwardTo -or $_.ForwardAsAttachmentTo -or $_.RedirectTo }
            if ($rules) { $inboxRulesWithForward += $rules }
        }
    } catch { }
    $status = if ($autoForwardBlocked -and $inboxRulesWithForward.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Tenant-wide AutoForwardEnabled: $($remoteDomain.AutoForwardEnabled). Individual mailbox forwarding rules found: $($inboxRulesWithForward.Count)."
    Add-CheckResult (New-CheckResult -CheckId 'block-mail-forwarding' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Ensure Exchange Online Spam Policies are set to notify administrators ---
Invoke-SafeCheck -CheckId 'exo-spam-policies-notify-admin' -ScriptBlock {
    $policy = Get-HostedOutboundSpamFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-HostedOutboundSpamFilterPolicy | Select-Object -First 1 }
    $status = if ($policy.NotifyOutboundSpam -eq $true -and $policy.NotifyOutboundSpamRecipients) { 'Compliant' } else { 'Not Compliant' }
    $detail = "NotifyOutboundSpam: $($policy.NotifyOutboundSpam), Recipients: $($policy.NotifyOutboundSpamRecipients -join ', ')"
    Add-CheckResult (New-CheckResult -CheckId 'exo-spam-policies-notify-admin' -Status $status -Detail $detail -Confidence 'High')
}

