    $enabledRules = @($rules | Where-Object { $_.State -eq 'Enabled' })
    $status = if ($policies.Count -gt 0 -and $enabledRules.Count -gt 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Safe Attachments policies: $($policies.Count). Enabled rules: $($enabledRules.Count)."
    Add-CheckResult (New-CheckResult -CheckId 'safe-attachments-enabled' -Status $status -Detail $detail -Confidence 'High')
}

