Invoke-SafeCheck -CheckId 'safe-links-office-apps' -ScriptBlock {
    $policy = Get-SafeLinksPolicy | Select-Object -First 1
    $status = if ($policy.EnableSafeLinksForEmail -eq $true -or $policy.ScanUrls -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Safe Links policy found with scanning settings: ScanUrls=$($policy.ScanUrls)"
    Add-CheckResult (New-CheckResult -CheckId 'safe-links-office-apps' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Ensure that an anti-phishing policy has been created ---
Invoke-SafeCheck -CheckId 'anti-phishing-policy-created' -ScriptBlock {
    $customPolicies = Get-AntiPhishPolicy | Where-Object { $_.Identity -ne 'Office365 AntiPhish Default' }
    $status = if ($customPolicies.Count -gt 0) { 'Compliant' } else { 'Not Compliant' }
