# --- Set a daily message limit ---
Invoke-SafeCheck -CheckId 'daily-message-limit' -ScriptBlock {
    $policy = Get-HostedOutboundSpamFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-HostedOutboundSpamFilterPolicy | Select-Object -First 1 }
    # Unlike the per-hour recipient limits, a RecipientLimitPerDay value AT the maximum
    # allowed ceiling (10000) is effectively meaningless as a security control -- it
    # won't trigger before a compromised account does serious damage. 0 still means
    # "service defaults are used" per Microsoft's docs (a real, modest limit), but a
    # value at or near the 10000 ceiling reflects an admin-set limit so loose it provides
    # little protection. Treat 0 (defaults) and any low/moderate custom value as
    # Compliant, but flag values at the practical ceiling as Not Compliant.
    $limit = $policy.RecipientLimitPerDay
    $status = if ($limit -eq 0 -or ($limit -gt 0 -and $limit -lt 10000)) { 'Compliant' } else { 'Not Compliant' }
    $detail = "RecipientLimitPerDay: $limit"
    Add-CheckResult (New-CheckResult -CheckId 'daily-message-limit' -Status $status -Detail $detail -Confidence 'Medium')
}

