    $remoteDomain = Get-RemoteDomain -Identity Default
    $status = if ($remoteDomain.AutoForwardEnabled -eq $false) { 'Compliant' } else { 'Not Compliant' }
    # Note: AutoForwardEnabled=$true is Exchange Online's documented default (per Microsoft
    # Learn). This check intentionally flags the default as Not Compliant -- some other
    # audit tools may treat this setting as Compliant if they're actually checking a
    # different/narrower signal (e.g. transport-rule-based forwarding restrictions rather
    # than the remote-domain AutoForwardEnabled flag itself). If this result looks wrong
    # for a specific tenant, cross-check the 'block-mail-forwarding' result too, which
    # also factors in per-mailbox inbox rules.
    $detail = "AutoForwardEnabled: $($remoteDomain.AutoForwardEnabled)"
    Add-CheckResult (New-CheckResult -CheckId 'system-controlled-auto-forward' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Set maximum number of external recipients that a user can email per hour ---
Invoke-SafeCheck -CheckId 'external-recipient-rate-limit' -ScriptBlock {
    $policy = Get-HostedOutboundSpamFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-HostedOutboundSpamFilterPolicy | Select-Object -First 1 }
    # Per Microsoft's own documentation for RecipientLimitExternalPerHour: valid range is
    # 0-10000, and 0 specifically means "the service defaults are used" -- NOT unlimited.
    # There is no way to configure a genuinely uncapped value via this property, so any
    # value Microsoft will ever actually return (0-10000) reflects a real, enforced limit
    # (either Microsoft-managed or admin-customized). This means the check will almost
    # always read Compliant -- that's expected and correct given the property's real
    # semantics, not a sign the check lost its teeth. If you want to verify a *custom*
    # (non-default) limit is in place specifically, check for a value other than 0.
    $status = if ($policy.RecipientLimitExternalPerHour -ge 0 -and $policy.RecipientLimitExternalPerHour -le 10000) { 'Compliant' } else { 'Not Compliant' }
    $detail = "RecipientLimitExternalPerHour: $($policy.RecipientLimitExternalPerHour)"
    Add-CheckResult (New-CheckResult -CheckId 'external-recipient-rate-limit' -Status $status -Detail $detail -Confidence 'High')
}

