    if (-not $policy) { $policy = Get-HostedOutboundSpamFilterPolicy | Select-Object -First 1 }
    # Same rationale as external-recipient-rate-limit above: 0 means "service defaults are
    # used" per Microsoft's documentation, not "unlimited." Valid range is 0-10000, so this
    # will almost always read Compliant -- that reflects the property's real semantics.
    $status = if ($policy.RecipientLimitInternalPerHour -ge 0 -and $policy.RecipientLimitInternalPerHour -le 10000) { 'Compliant' } else { 'Not Compliant' }
    $detail = "RecipientLimitInternalPerHour: $($policy.RecipientLimitInternalPerHour)"
