# --- List of approved sender IP addresses (DNS-based, SPF parsing) ---
Invoke-SafeCheck -CheckId 'list-approved-sender-ips' -ScriptBlock {
    $domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' -and -not (Test-IsThirdPartyTechnicalDomain $_.DomainName) }
    $missingOrEmpty = @()
    foreach ($d in $domains) {
        try {
            $txt = Resolve-DnsName -Name $d.DomainName -Type TXT -ErrorAction Stop
            $spf = $txt | Where-Object { $_.Strings -match 'v=spf1' }
            if (-not $spf -or ($spf.Strings -join ' ') -notmatch 'ip4:|ip6:|include:') {
                $missingOrEmpty += $d.DomainName
            }
        } catch {
            $missingOrEmpty += $d.DomainName
        }
    }
    $status = if ($missingOrEmpty.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($missingOrEmpty.Count -gt 0) { "A list of approved sender IP addresses is not configured for: $($missingOrEmpty -join ', ')" } else { "Approved sender IP addresses are configured via SPF for all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'list-approved-sender-ips' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- SPF policies ---
Invoke-SafeCheck -CheckId 'spf-policies' -ScriptBlock {
    $domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' -and -not (Test-IsThirdPartyTechnicalDomain $_.DomainName) }
    $missingSpf = @()
    foreach ($d in $domains) {
        try {
            $txt = Resolve-DnsName -Name $d.DomainName -Type TXT -ErrorAction Stop
            $spf = $txt | Where-Object { $_.Strings -match 'v=spf1' }
            if (-not $spf) { $missingSpf += $d.DomainName }
        } catch {
            $missingSpf += $d.DomainName
        }
    }
    $status = if ($missingSpf.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($missingSpf.Count -gt 0) { "SPF policies are not published for: $($missingSpf -join ', ')" } else { "SPF policies are published for all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'spf-policies' -Status $status -Detail $detail -Confidence 'Medium')
}

