# --- DMARC policies for second-level domains ---
Invoke-SafeCheck -CheckId 'dmarc-second-level-domains' -ScriptBlock {
    # NOTE: this intentionally includes the tenant's *.onmicrosoft.com domain(s) -- even
    # though mail isn't normally sent FROM that domain, Microsoft's own guidance confirms
    # an unprotected onmicrosoft.com subdomain is a real spoofing vector and recommends
    # publishing a DMARC record for it regardless of whether it's actively used for mail.
    # If this check disagrees with another audit tool's result for the same tenant, that
    # tool may be excluding onmicrosoft.com domains from its scope rather than this check
    # being wrong. It DOES exclude known third-party technical/relay domains (see
    # Test-IsThirdPartyTechnicalDomain) since those are never real organizational mail
    # domains and aren't expected to have DMARC configured.
    $domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' -and -not (Test-IsThirdPartyTechnicalDomain $_.DomainName) }
    $missingDmarc = @()
    foreach ($d in $domains) {
        try {
            $txt = Resolve-DnsName -Name "_dmarc.$($d.DomainName)" -Type TXT -ErrorAction Stop
            $dmarc = $txt | Where-Object { $_.Strings -match 'v=DMARC1' }
            if (-not $dmarc) { $missingDmarc += $d.DomainName }
        } catch {
            $missingDmarc += $d.DomainName
        }
    }
    $status = if ($missingDmarc.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($missingDmarc.Count -gt 0) { "DMARC policies are not published for: $($missingDmarc -join ', ')" } else { "DMARC policies are published for all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'dmarc-second-level-domains' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- DMARC message rejection ---
Invoke-SafeCheck -CheckId 'dmarc-message-rejection' -ScriptBlock {
    $domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' -and -not (Test-IsThirdPartyTechnicalDomain $_.DomainName) }
    $notReject = @()
    foreach ($d in $domains) {
        try {
            $txt = Resolve-DnsName -Name "_dmarc.$($d.DomainName)" -Type TXT -ErrorAction Stop
            $dmarcRecord = ($txt | Where-Object { $_.Strings -match 'v=DMARC1' } | Select-Object -First 1).Strings -join ''
            if ($dmarcRecord -notmatch 'p=reject') { $notReject += $d.DomainName }
        } catch {
            $notReject += $d.DomainName
        }
    }
    $status = if ($notReject.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($notReject.Count -gt 0) { "The DMARC message rejection options is not set to p=reject for: $($notReject -join ', ')" } else { "DMARC is set to p=reject for all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'dmarc-message-rejection' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- DMARC point of contact ---
Invoke-SafeCheck -CheckId 'dmarc-point-of-contact' -ScriptBlock {
    $domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' -and -not (Test-IsThirdPartyTechnicalDomain $_.DomainName) }
    $missingRua = @()
    foreach ($d in $domains) {
        try {
            $txt = Resolve-DnsName -Name "_dmarc.$($d.DomainName)" -Type TXT -ErrorAction Stop
            $dmarcRecord = ($txt | Where-Object { $_.Strings -match 'v=DMARC1' } | Select-Object -First 1).Strings -join ''
            if ($dmarcRecord -notmatch 'rua=') { $missingRua += $d.DomainName }
        } catch {
            $missingRua += $d.DomainName
        }
    }
    $status = if ($missingRua.Count -eq 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($missingRua.Count -gt 0) { "The DMARC point of contact (rua=) is missing for: $($missingRua -join ', ')" } else { "DMARC reporting address configured for all domains." }
    Add-CheckResult (New-CheckResult -CheckId 'dmarc-point-of-contact' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Disable SMTP Auth ---
Invoke-SafeCheck -CheckId 'disable-smtp-auth' -ScriptBlock {
    $transportConfig = Get-TransportConfig
    $status = if ($transportConfig.SmtpClientAuthenticationDisabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($transportConfig.SmtpClientAuthenticationDisabled) { "SMTP Auth is disabled." } else { "SMTP Auth is not disabled tenant-wide." }
    Add-CheckResult (New-CheckResult -CheckId 'disable-smtp-auth' -Status $status -Detail $detail -Confidence 'High')
}

# --- Create zero-hour auto purge policies for malware ---
Invoke-SafeCheck -CheckId 'zap-malware' -ScriptBlock {
    $policy = Get-MalwareFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-MalwareFilterPolicy | Select-Object -First 1 }
    $status = if ($policy.ZapEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = "ZapEnabled (malware): $($policy.ZapEnabled)"
    Add-CheckResult (New-CheckResult -CheckId 'zap-malware' -Status $status -Detail $detail -Confidence 'High')
}

# --- Create zero-hour auto purge policies for phishing messages ---
Invoke-SafeCheck -CheckId 'zap-phishing' -ScriptBlock {
    $policy = Get-HostedContentFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-HostedContentFilterPolicy | Select-Object -First 1 }
    $status = if ($policy.PhishZapEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = "PhishZapEnabled: $($policy.PhishZapEnabled)"
    Add-CheckResult (New-CheckResult -CheckId 'zap-phishing' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Create zero-hour auto purge policies for spam messages ---
Invoke-SafeCheck -CheckId 'zap-spam' -ScriptBlock {
    $policy = Get-HostedContentFilterPolicy -Identity Default -ErrorAction SilentlyContinue
    if (-not $policy) { $policy = Get-HostedContentFilterPolicy | Select-Object -First 1 }
    $status = if ($policy.SpamZapEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = "SpamZapEnabled: $($policy.SpamZapEnabled)"
    Add-CheckResult (New-CheckResult -CheckId 'zap-spam' -Status $status -Detail $detail -Confidence 'High')
}

# --- Modern Authentication for Exchange/Outlook ---
Invoke-SafeCheck -CheckId 'modern-auth-exchange-outlook' -ScriptBlock {
    $orgConfig = Get-OrganizationConfig
    $status = if ($orgConfig.OAuth2ClientProfileEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($orgConfig.OAuth2ClientProfileEnabled) { "This setting is in place" } else { "This setting is not in place" }
    Add-CheckResult (New-CheckResult -CheckId 'modern-auth-exchange-outlook' -Status $status -Detail $detail -Confidence 'High')
}

# --- Unified Audit Log ---
Invoke-SafeCheck -CheckId 'unified-audit-log' -ScriptBlock {
    try {
        $auditConfig = Get-AdminAuditLogConfig
        $status = if ($auditConfig.UnifiedAuditLogIngestionEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
        $detail = "Feature in place: $($auditConfig.UnifiedAuditLogIngestionEnabled)."
        Add-CheckResult (New-CheckResult -CheckId 'unified-audit-log' -Status $status -Detail $detail -Confidence 'High')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'unified-audit-log' -Status 'Not Run' -Detail "Get-AdminAuditLogConfig requires Purview/compliance permissions. Verify manually." -Confidence 'Low')
    }
}

# --- Mailbox Auditing Default (org level) ---
Invoke-SafeCheck -CheckId 'mailbox-auditing-default-org' -ScriptBlock {
    $orgConfig = Get-OrganizationConfig
    $status = if ($orgConfig.AuditDisabled -eq $false) { 'Compliant' } else { 'Not Compliant' }
    $detail = "Feature in place:$(-not $orgConfig.AuditDisabled)"
    Add-CheckResult (New-CheckResult -CheckId 'mailbox-auditing-default-org' -Status $status -Detail $detail -Confidence 'High')
}

# --- Block Sign-in on Shared Mailboxes ---
Invoke-SafeCheck -CheckId 'block-signin-shared-mailboxes' -ScriptBlock {
    $sharedMailboxes = Get-Mailbox -ResultSize Unlimited -RecipientTypeDetails SharedMailbox
    $blockedCount = 0
    foreach ($mb in $sharedMailboxes) {
        try {
            $userResp = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/users/$($mb.ExternalDirectoryObjectId)?`$select=accountEnabled"
            if ($userResp.accountEnabled -eq $false) { $blockedCount++ }
        } catch { }
    }
    $status = if ($blockedCount -eq $sharedMailboxes.Count -and $sharedMailboxes.Count -gt 0) { 'Compliant' } else { 'Not Compliant' }
    $detail = "You have $blockedCount of $($sharedMailboxes.Count) shared mailboxes that have sign-ins blocked"
    Add-CheckResult (New-CheckResult -CheckId 'block-signin-shared-mailboxes' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Resharing By External Users (SharePoint, but listed under Exchange/Defender category) ---
Invoke-SafeCheck -CheckId 'resharing-external-users' -ScriptBlock {
    $spSettings = Get-CachedSharePointSettings
    if ($null -ne $spSettings -and $null -ne (Get-SafeProperty $spSettings 'isResharingByExternalUsersEnabled')) {
        # Graph's isResharingByExternalUsersEnabled: $false means external users CANNOT
        # reshare, which is the secure/Compliant state.
        $resharingEnabled = Get-SafeProperty $spSettings 'isResharingByExternalUsersEnabled'
        $status = if ($resharingEnabled -eq $false) { 'Compliant' } else { 'Not Compliant' }
        $detail = if ($resharingEnabled -eq $false) { "This setting is in place (isResharingByExternalUsersEnabled: false)." } else { "This setting is not in place (isResharingByExternalUsersEnabled: true)." }
        Add-CheckResult (New-CheckResult -CheckId 'resharing-external-users' -Status $status -Detail $detail -Confidence 'High')
        return
    }
    if ($script:SkipSharePointRuntime) {
        Add-CheckResult (New-CheckResult -CheckId 'resharing-external-users' -Status 'Not Run' -Detail "SharePoint Online connection not available, and the Graph admin/sharepoint/settings endpoint did not return usable data (check SharePointTenantSettings.Read.All scope)." -Confidence 'Low')
        return
    }
    $tenant = Get-SPOTenant
    $status = if ($tenant.PreventExternalUsersFromResharing -eq $true) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($tenant.PreventExternalUsersFromResharing) { "This setting is in place" } else { "This setting is not in place" }
    Add-CheckResult (New-CheckResult -CheckId 'resharing-external-users' -Status $status -Detail $detail -Confidence 'High')
}

} # end if (-not $script:SkipExchange)

# ============================================================================
# CHECKS: SharePoint / Teams / App Governance / Licensing
# ============================================================================

# --- Sharepoint site creation by standard users ---
Invoke-SafeCheck -CheckId 'sharepoint-site-creation-standard-users' -ScriptBlock {
    $spSettings = Get-CachedSharePointSettings
    if ($null -ne $spSettings -and $null -ne (Get-SafeProperty $spSettings 'isSiteCreationEnabled')) {
        # Graph's isSiteCreationEnabled reflects whether standard (non-admin) users can
        # create SharePoint sites. $false = restricted = Compliant.
        $siteCreationEnabled = Get-SafeProperty $spSettings 'isSiteCreationEnabled'
        $restricted = ($siteCreationEnabled -eq $false)
        $status = if ($restricted) { 'Compliant' } else { 'Not Compliant' }
        $detail = if ($restricted) { "Site creation by standard users is restricted (isSiteCreationEnabled: false)." } else { "Site creation by standard users is allowed (isSiteCreationEnabled: true)." }
        Add-CheckResult (New-CheckResult -CheckId 'sharepoint-site-creation-standard-users' -Status $status -Detail $detail -Confidence 'High')
        return
    }
    if ($script:SkipSharePointRuntime) {
        Add-CheckResult (New-CheckResult -CheckId 'sharepoint-site-creation-standard-users' -Status 'Not Run' -Detail "SharePoint Online connection not available, and the Graph admin/sharepoint/settings endpoint did not return usable data (check SharePointTenantSettings.Read.All scope)." -Confidence 'Low')
        return
    }
    $tenant = Get-SPOTenant
    # Restricted site creation is reflected differently across tenant versions;
    # DenyAddAndCustomizePages and site creation settings are the closest GA proxies.
    $restricted = ($tenant.SiteCreationMode -eq 'Restricted') -or ($tenant.DenyAddAndCustomizePages -eq 'Enabled')
    $status = if ($restricted) { 'Compliant' } else { 'Not Compliant' }
    $detail = if ($restricted) { "This setting is in place" } else { "This setting is not in place" }
    Add-CheckResult (New-CheckResult -CheckId 'sharepoint-site-creation-standard-users' -Status $status -Detail $detail -Confidence 'Low')
}

# --- Deleted User OneDrive Retention ---
Invoke-SafeCheck -CheckId 'deleted-user-onedrive-retention' -ScriptBlock {
    $spSettings = Get-CachedSharePointSettings
    $retentionDays = if ($null -ne $spSettings) { Get-SafeProperty $spSettings 'deletedUserPersonalSiteRetentionPeriodInDays' } else { $null }
    if ($null -eq $retentionDays) {
        Add-CheckResult (New-CheckResult -CheckId 'deleted-user-onedrive-retention' -Status 'Not Run' -Detail "Could not retrieve deletedUserPersonalSiteRetentionPeriodInDays from the Graph admin/sharepoint/settings endpoint (check SharePointTenantSettings.Read.All scope)." -Confidence 'Low')
        return
    }
    # Valid range per Microsoft docs is 30-3650 days. Any explicitly configured value in
    # that range (including the 30-day default) reflects a real, deliberate retention
    # policy, so it's treated as Compliant -- the specific number of days is an
    # organizational policy decision, not something this check should second-guess.
    $status = if ($retentionDays -ge 30 -and $retentionDays -le 3650) { 'Compliant' } else { 'Not Compliant' }
    $detail = "This setting is in place (deletedUserPersonalSiteRetentionPeriodInDays: $retentionDays)."
    Add-CheckResult (New-CheckResult -CheckId 'deleted-user-onedrive-retention' -Status $status -Detail $detail -Confidence 'High')
}

# --- SharePoint External/Guest Sharing ---
Invoke-SafeCheck -CheckId 'sharepoint-external-guest-sharing' -ScriptBlock {
    if ($script:SkipSharePointRuntime) {
        Add-CheckResult (New-CheckResult -CheckId 'sharepoint-external-guest-sharing' -Status 'Not Run' -Detail "SharePoint Online connection not available." -Confidence 'High')
        return
    }
    $tenant = Get-SPOTenant
    $secureSettings = 0
    if ($tenant.SharingCapability -in @('ExistingExternalUserSharingOnly','Disabled')) { $secureSettings++ }
    if ($tenant.PreventExternalUsersFromResharing -eq $true) { $secureSettings++ }
    $status = if ($secureSettings -eq 2) { 'Compliant' } else { 'Not Compliant' }
    $detail = "You have $secureSettings out of 2 secure sharing settings applied."
    Add-CheckResult (New-CheckResult -CheckId 'sharepoint-external-guest-sharing' -Status $status -Detail $detail -Confidence 'Medium')
}

# --- Teams Default External/Guest Options ---
Invoke-SafeCheck -CheckId 'teams-default-external-guest-options' -ScriptBlock {
    Add-CheckResult (New-CheckResult -CheckId 'teams-default-external-guest-options' -Status 'Not Run' -Detail "Requires the MicrosoftTeams PowerShell module (Get-CsTeamsClientConfiguration / Get-CsTenantFederationConfiguration), which is not connected in this script run. Verify manually in the Teams admin center, or extend this script with Connect-MicrosoftTeams." -Confidence 'Low')
}

# --- All users utilizing an Entra ID P1 license should be licensed ---
Invoke-SafeCheck -CheckId 'all-users-p1-licensed' -ScriptBlock {
    $policies = Get-CachedConditionalAccessPolicies
    $p1DependentPolicyExists = $policies.Count -gt 0  # any CA policy implies P1 usage
    if (-not $p1DependentPolicyExists) {
        Add-CheckResult (New-CheckResult -CheckId 'all-users-p1-licensed' -Status 'Compliant' -Detail "No Conditional Access policies in use; P1 licensing compliance not applicable." -Confidence 'Medium')
        return
    }
    $p1Satisfied = Test-LicenseSatisfied -RequiredLicense 'Entra ID P1'
    $usersResp = Invoke-MgGraphRequest -Method GET -Uri ("https://graph.microsoft.com/v1.0/users?" + '$select=id,assignedLicenses' + "&" + '$top=999')
    $allUsersCount = $usersResp.value.Count
    if ($null -eq $p1Satisfied) {
        Add-CheckResult (New-CheckResult -CheckId 'all-users-p1-licensed' -Status 'Not Run' -Detail "License requirement 'Entra ID P1' not found in license map." -Confidence 'Low')
        return
    }
    if (-not $p1Satisfied) {
        Add-CheckResult (New-CheckResult -CheckId 'all-users-p1-licensed' -Status 'Not Compliant' -Detail "Not enough P1 licenses entitled users (no qualifying P1 SKU found on tenant)." -Confidence 'Medium')
        return
    }
    Add-CheckResult (New-CheckResult -CheckId 'all-users-p1-licensed' -Status 'Not Run' -Detail "Tenant holds a qualifying P1 SKU, but confirming per-seat coverage for all $allUsersCount users requires comparing assigned licenses per user against CA-policy scope. Verify manually in the Entra ID Licenses blade." -Confidence 'Low')
}

# --- All users utilizing an Entra ID P2 license should be licensed ---
Invoke-SafeCheck -CheckId 'all-users-p2-licensed' -ScriptBlock {
    $policies = Get-CachedConditionalAccessPolicies
    $p2DependentPolicyExists = $policies | Where-Object { $_.conditions.userRiskLevels.Count -gt 0 -or $_.conditions.signInRiskLevels.Count -gt 0 }
    if (-not $p2DependentPolicyExists) {
        Add-CheckResult (New-CheckResult -CheckId 'all-users-p2-licensed' -Status 'Compliant' -Detail "No risk-based Conditional Access policies in use; P2 licensing compliance not applicable." -Confidence 'Medium')
        return
    }
    Add-CheckResult (New-CheckResult -CheckId 'all-users-p2-licensed' -Status 'Not Run' -Detail "Risk-based policies are in use; precisely calculating which users require P2 licensing needs deeper policy-scope analysis. Verify manually." -Confidence 'Low')
}

# --- App Request Expiry ---
Invoke-SafeCheck -CheckId 'app-request-expiry' -ScriptBlock {
    try {
        $consentPolicy = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/policies/adminConsentRequestPolicy"
        $status = if ($consentPolicy.requestDurationInDays -gt 0) { 'Compliant' } else { 'Not Compliant' }
        $detail = if ($status -eq 'Compliant') { "App request automatic expiry enabled." } else { "App request automatic expiry is not configured." }
        Add-CheckResult (New-CheckResult -CheckId 'app-request-expiry' -Status $status -Detail $detail -Confidence 'High')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'app-request-expiry' -Status 'Error' -ErrorMessage $_.Exception.Message -Confidence 'High')
    }
}

# --- Reviewer App Request Notifications ---
Invoke-SafeCheck -CheckId 'reviewer-app-request-notifications' -ScriptBlock {
    try {
        $consentPolicy = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/policies/adminConsentRequestPolicy"
        $status = if ($consentPolicy.notifyReviewers -eq $true) { 'Compliant' } else { 'Not Compliant' }
        $detail = if ($status -eq 'Compliant') { "App request notifications enabled." } else { "App request notifications are not enabled." }
        Add-CheckResult (New-CheckResult -CheckId 'reviewer-app-request-notifications' -Status $status -Detail $detail -Confidence 'High')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'reviewer-app-request-notifications' -Status 'Error' -ErrorMessage $_.Exception.Message -Confidence 'High')
    }
}

# --- Reviewer App Request Reminders ---
Invoke-SafeCheck -CheckId 'reviewer-app-request-reminders' -ScriptBlock {
    try {
        $consentPolicy = Invoke-MgGraphRequest -Method GET -Uri "https://graph.microsoft.com/v1.0/policies/adminConsentRequestPolicy"
        $status = if ($consentPolicy.remindersEnabled -eq $true) { 'Compliant' } else { 'Not Compliant' }
        $detail = if ($status -eq 'Compliant') { "App request reminders enabled." } else { "App request reminders are not enabled." }
        Add-CheckResult (New-CheckResult -CheckId 'reviewer-app-request-reminders' -Status $status -Detail $detail -Confidence 'High')
    } catch {
        Add-CheckResult (New-CheckResult -CheckId 'reviewer-app-request-reminders' -Status 'Error' -ErrorMessage $_.Exception.Message -Confidence 'High')
    }
}

Write-Host "`n--- Checks complete ---" -ForegroundColor Cyan
Write-Host "Total results: $($Results.Count)" -ForegroundColor Gray

# ----------------------------------------------------------------------------
# 6. Summary statistics
# ----------------------------------------------------------------------------
$compliantCount    = ($Results | Where-Object { $_.Status -eq 'Compliant' }).Count
$notCompliantCount = ($Results | Where-Object { $_.Status -eq 'Not Compliant' }).Count
$notRunCount       = ($Results | Where-Object { $_.Status -eq 'Not Run' }).Count
$errorCount        = ($Results | Where-Object { $_.Status -eq 'Error' }).Count
$totalEvaluable    = $compliantCount + $notCompliantCount
$postureScore      = if ($totalEvaluable -gt 0) { [math]::Round(($compliantCount / $totalEvaluable) * 100) } else { 0 }

$canRemediateCount    = ($Results | Where-Object { $_.Status -eq 'Not Compliant' -and $_.CanRemediate }).Count
$cannotRemediateCount = ($Results | Where-Object { $_.Status -eq 'Not Compliant' -and -not $_.CanRemediate -and $_.LicenseStatus -eq 'Not Licensed' }).Count
$unknownLicenseCount  = ($Results | Where-Object { $_.Status -eq 'Not Compliant' -and $_.LicenseStatus -eq 'Unknown' }).Count

Write-Host "`nPosture Score: $postureScore%" -ForegroundColor $(if ($postureScore -ge 80) { 'Green' } elseif ($postureScore -ge 50) { 'Yellow' } else { 'Red' })
Write-Host "  Compliant: $compliantCount" -ForegroundColor Green
Write-Host "  Not Compliant: $notCompliantCount" -ForegroundColor Red
Write-Host "    -> Can remediate now (licensed): $canRemediateCount" -ForegroundColor Gray
Write-Host "    -> Blocked by licensing: $cannotRemediateCount" -ForegroundColor Yellow
Write-Host "    -> License requirement unclear: $unknownLicenseCount" -ForegroundColor Gray
Write-Host "  Not Run (manual verification needed): $notRunCount" -ForegroundColor Gray
Write-Host "  Errors: $errorCount" -ForegroundColor Red

# ----------------------------------------------------------------------------
# 7. HTML report generation
# ----------------------------------------------------------------------------
function ConvertTo-HtmlSafe {
    param([string]$Text)
    if (-not $Text) { return "" }
    return [System.Web.HttpUtility]::HtmlEncode($Text)
}

Add-Type -AssemblyName System.Web

function Get-StatusBadgeClass {
    param([string]$Status)
    switch ($Status) {
        'Compliant'     { return 'badge-compliant' }
        'Not Compliant' { return 'badge-not-compliant' }
        'Not Run'       { return 'badge-not-run' }
        'Error'         { return 'badge-error' }
        default         { return 'badge-not-run' }
    }
}

function Get-ImpactBadgeClass {
    param([string]$Impact)
    switch ($Impact) {
        'None'   { return 'impact-none' }
        'Low'    { return 'impact-low' }
        'Medium' { return 'impact-medium' }
        'High'   { return 'impact-high' }
        default  { return 'impact-low' }
    }
}

function New-HtmlReport {
    param(
        [Parameter(Mandatory)] $AllResults,
        [Parameter(Mandatory)] [string]$TenantDisplayName,
        [Parameter(Mandatory)] [int]$Score
    )

    $reportDate = Get-Date -Format "MMMM dd, yyyy"
    $categories = $AllResults | Select-Object -ExpandProperty Category -Unique | Sort-Object

    $rowsHtml = New-Object System.Text.StringBuilder

    foreach ($cat in $categories) {
        $catResults = $AllResults | Where-Object { $_.Category -eq $cat } | Sort-Object Name
        [void]$rowsHtml.Append("<tr class='category-row'><td colspan='6'>$(ConvertTo-HtmlSafe $cat)</td></tr>`n")

        foreach ($r in $catResults) {
            $statusClass = Get-StatusBadgeClass -Status $r.Status
            $impactClass = Get-ImpactBadgeClass -Impact $r.UserImpact

            $licenseNote = switch ($r.LicenseStatus) {
                'Licensed'     { "<span class='lic-ok'>&#10003; Licensed</span>" }
                'Not Licensed' { "<span class='lic-missing'>&#10007; Not Licensed</span>" }
                default        { "<span class='lic-unknown'>? Unknown</span>" }
            }

            $confidenceNote = if ($r.Confidence -ne 'High') {
                "<div class='confidence-note confidence-$($r.Confidence.ToLower())'>$($r.Confidence) confidence &mdash; verify manually</div>"
            } else { "" }

            $errorNote = if ($r.ErrorMessage) {
                "<div class='error-note'>Error: $(ConvertTo-HtmlSafe $r.ErrorMessage)</div>"
            } else { "" }

            [void]$rowsHtml.Append(@"
            <tr class="check-row">
                <td class="check-name">
                    $(ConvertTo-HtmlSafe $r.Name)
                    $confidenceNote
                    $errorNote
                </td>
                <td><span class="badge $statusClass">$(ConvertTo-HtmlSafe $r.Status)</span></td>
                <td class="detail-cell">$(ConvertTo-HtmlSafe $r.Detail)</td>
                <td class="license-cell">
                    <div>$(ConvertTo-HtmlSafe $r.MinLicense)</div>
                    <div>$licenseNote</div>
                </td>
                <td><span class="badge $impactClass">$(ConvertTo-HtmlSafe $r.UserImpact)</span></td>
                <td class="impact-cell">$(ConvertTo-HtmlSafe $r.UserImpactSummary)</td>
            </tr>
"@)
        }
    }

    $html = @"
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>M365 Security Posture Audit - $(ConvertTo-HtmlSafe $TenantDisplayName)</title>
<style>
    :root {
        --ink: #1c2330;
        --ink-soft: #4b5468;
        --line: #e2e5eb;
        --bg: #f7f8fa;
        --card: #ffffff;
        --green: #1e8e5a;
        --green-bg: #e7f6ee;
        --red: #c0392b;
        --red-bg: #fbeae8;
        --amber: #b8860b;
        --amber-bg: #fbf3e0;
        --gray: #6b7280;
        --gray-bg: #eef0f3;
        --accent: #2452a3;
    }
    * { box-sizing: border-box; }
    body {
        margin: 0;
        font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
        background: var(--bg);
        color: var(--ink);
        line-height: 1.5;
    }
    .wrap { max-width: 1280px; margin: 0 auto; padding: 32px 24px 80px; }
    header.report-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        flex-wrap: wrap;
        gap: 24px;
        margin-bottom: 32px;
    }
    .title-block h1 { font-size: 26px; margin: 0 0 4px; letter-spacing: -0.01em; }
    .title-block .subtitle { color: var(--ink-soft); font-size: 14px; }
    .audit-note {
        background: var(--card);
        border: 1px solid var(--line);
        border-left: 4px solid var(--accent);
        border-radius: 6px;
        padding: 12px 16px;
        font-size: 13px;
        color: var(--ink-soft);
        max-width: 420px;
    }

    .summary-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 16px;
        margin-bottom: 32px;
    }
    .summary-card {
        background: var(--card);
        border: 1px solid var(--line);
        border-radius: 10px;
        padding: 18px 20px;
    }
    .summary-card .num { font-size: 30px; font-weight: 600; line-height: 1; }
    .summary-card .label { font-size: 13px; color: var(--ink-soft); margin-top: 6px; }
    .score-card .num { color: $(if ($Score -ge 80) {'var(--green)'} elseif ($Score -ge 50) {'var(--amber)'} else {'var(--red)'}); }

    table.checks-table {
        width: 100%;
        border-collapse: collapse;
        background: var(--card);
        border-radius: 10px;
        overflow: hidden;
        border: 1px solid var(--line);
        font-size: 13.5px;
    }
    table.checks-table thead th {
        text-align: left;
        background: #eef1f6;
        color: var(--ink-soft);
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.04em;
        padding: 10px 14px;
        border-bottom: 1px solid var(--line);
    }
    table.checks-table td {
        padding: 12px 14px;
        border-bottom: 1px solid var(--line);
        vertical-align: top;
    }
    tr.category-row td {
        background: #dde3ee;
        font-weight: 600;
        font-size: 12.5px;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--accent);
        padding: 8px 14px;
    }
    tr.check-row:hover { background: #fafbfc; }
    .check-name { font-weight: 600; min-width: 200px; }
    .detail-cell { color: var(--ink-soft); min-width: 220px; }
    .impact-cell { color: var(--ink-soft); min-width: 260px; font-size: 13px; }
    .license-cell { font-size: 12.5px; min-width: 110px; }

    .badge {
        display: inline-block;
        padding: 3px 10px;
        border-radius: 999px;
        font-size: 11.5px;
        font-weight: 600;
        white-space: nowrap;
    }
    .badge-compliant     { background: var(--green-bg); color: var(--green); }
    .badge-not-compliant { background: var(--red-bg); color: var(--red); }
    .badge-not-run       { background: var(--gray-bg); color: var(--gray); }
    .badge-error         { background: var(--red-bg); color: var(--red); }

    .impact-none   { background: var(--gray-bg); color: var(--gray); }
    .impact-low    { background: var(--green-bg); color: var(--green); }
    .impact-medium { background: var(--amber-bg); color: var(--amber); }
    .impact-high   { background: var(--red-bg); color: var(--red); }

    .lic-ok      { color: var(--green); font-size: 12px; font-weight: 600; }
    .lic-missing { color: var(--red); font-size: 12px; font-weight: 600; }
    .lic-unknown { color: var(--gray); font-size: 12px; font-weight: 600; }

    .confidence-note {
        font-size: 11px;
        margin-top: 4px;
        padding: 2px 6px;
        border-radius: 4px;
        display: inline-block;
    }
    .confidence-medium { background: var(--amber-bg); color: var(--amber); }
    .confidence-low { background: var(--red-bg); color: var(--red); }
    .error-note { font-size: 11px; color: var(--red); margin-top: 4px; }

    .legend {
        display: flex;
        gap: 18px;
        flex-wrap: wrap;
        margin-bottom: 20px;
        font-size: 12.5px;
        color: var(--ink-soft);
    }
    .legend span { display: inline-flex; align-items: center; gap: 6px; }
    .legend .dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }

    footer {
        margin-top: 40px;
        font-size: 12px;
        color: var(--gray);
        text-align: center;
    }
</style>
</head>
<body>
<div class="wrap">

    <header class="report-header">
        <div class="title-block">
            <h1>M365 Security Posture Audit</h1>
            <div class="subtitle">$(ConvertTo-HtmlSafe $TenantDisplayName) &middot; $reportDate</div>
        </div>
        <div class="audit-note">
            This is an <strong>audit-only</strong> report. No configuration changes were made to this tenant.
            Items marked "Not Compliant" require manual remediation; license status indicates whether your
            current Microsoft 365 subscriptions support fixing each item.
        </div>
    </header>

    <div class="summary-grid">
        <div class="summary-card score-card">
            <div class="num">$Score%</div>
            <div class="label">Posture Score</div>
        </div>
        <div class="summary-card">
            <div class="num" style="color:var(--green)">$compliantCount</div>
            <div class="label">Compliant</div>
        </div>
        <div class="summary-card">
            <div class="num" style="color:var(--red)">$notCompliantCount</div>
            <div class="label">Not Compliant</div>
        </div>
        <div class="summary-card">
            <div class="num" style="color:var(--accent)">$canRemediateCount</div>
            <div class="label">Fixable now (licensed)</div>
        </div>
        <div class="summary-card">
            <div class="num" style="color:var(--amber)">$cannotRemediateCount</div>
            <div class="label">Blocked by licensing</div>
        </div>
        <div class="summary-card">
            <div class="num" style="color:var(--gray)">$notRunCount</div>
            <div class="label">Needs manual check</div>
        </div>
    </div>

    <div class="legend">
        <span><span class="dot" style="background:var(--green)"></span> Compliant</span>
        <span><span class="dot" style="background:var(--red)"></span> Not Compliant</span>
        <span><span class="dot" style="background:var(--gray)"></span> Not Run / Manual check needed</span>
        <span>&middot;</span>
        <span>User impact: <span class="badge impact-none">None</span> <span class="badge impact-low">Low</span> <span class="badge impact-medium">Medium</span> <span class="badge impact-high">High</span></span>
    </div>

    <table class="checks-table">
        <thead>
            <tr>
                <th>Security Check</th>
                <th>Status</th>
                <th>Detail</th>
                <th>License Required</th>
                <th>User Impact</th>
                <th>What Staff Will Notice</th>
            </tr>
        </thead>
        <tbody>
$($rowsHtml.ToString())
        </tbody>
    </table>

    <footer>
        Generated by an internal audit script &middot; Read-only audit, no changes were made to this tenant &middot; $reportDate
    </footer>

</div>
</body>
</html>
"@

    return $html
}

$htmlContent = New-HtmlReport -AllResults $Results -TenantDisplayName $TenantName -Score $postureScore

$safeFileName = ($TenantName -replace '[^\w\-]', '_')
$reportFileName = "M365_Posture_Audit_${safeFileName}_$(Get-Date -Format 'yyyy-MM-dd_HHmmss').html"
$reportFullPath = Join-Path $OutputPath $reportFileName

$htmlContent | Out-File -FilePath $reportFullPath -Encoding UTF8

Write-Host "`nReport saved to: $reportFullPath" -ForegroundColor Green

# Also save the raw results as JSON, alongside the HTML report. This is what
# New-RemediationPlan.ps1 reads to generate a fix-it report -- it avoids
# re-running all 131 checks just to produce remediation guidance.
$jsonFileName = "M365_Posture_Audit_${safeFileName}_$(Get-Date -Format 'yyyy-MM-dd_HHmmss').json"
$jsonFullPath = Join-Path $OutputPath $jsonFileName

$exportObject = [PSCustomObject]@{
    tenantName    = $TenantName
    tenantId      = $mgContext.TenantId
    auditDate     = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
    postureScore  = $postureScore
    tenantSkus    = $TenantSkus
    results       = $Results
}

$exportObject | ConvertTo-Json -Depth 10 | Out-File -FilePath $jsonFullPath -Encoding UTF8
Write-Host "Raw results saved to: $jsonFullPath" -ForegroundColor Green
Write-Host "(Use this file with New-RemediationPlan.ps1 to generate a fix-it report.)" -ForegroundColor Gray

# ----------------------------------------------------------------------------
# 8. Disconnect
# ----------------------------------------------------------------------------
try { Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null } catch {}
if (-not $script:SkipExchange) {
    try { Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null } catch {}
}
if (-not $script:SkipSharePointRuntime) {
    try { Disconnect-SPOService -ErrorAction SilentlyContinue | Out-Null } catch {}
}

Write-Host "`nDone. Opening report..." -ForegroundColor Cyan
try { Invoke-Item $reportFullPath } catch { Write-Host "Could not auto-open the report. Find it at: $reportFullPath" -ForegroundColor Yellow }
'@

# ======================= Invoke-TenantHardeningAudit.ps1 =======================
$Script:Payloads['Invoke-TenantHardeningAudit'] = @'
#Requires -Modules ExchangeOnlineManagement

<#
.SYNOPSIS
    Tenant Hardening Audit - checks a Microsoft 365 tenant against a hardening checklist
    Checks current state of each control in the Tenant Hardening Checklist
    against what's actually configured, and reports what's still needed.

.NOTES
    Run this as a Global Admin or Security Administrator.
    Requires modules: ExchangeOnlineManagement, Microsoft.Graph.Authentication,
    Microsoft.Graph.Identity.SignIns, Microsoft.Graph.Applications

    Run each module's Connect-* cmdlet in a FRESH PowerShell window if you hit
    assembly conflicts (Exchange + Graph modules loaded together in one session
    can fail to authenticate correctly).
#>
[CmdletBinding()]
param(
    [string]$OutputPath = 'C:\temp\M365',
    # Added for the SDSI ToolKit: sign in as a specific admin / to a client tenant (GDAP / partner)
    [string]$AdminUPN,
    [string]$DelegatedOrganization,
    [string]$TenantId
)

$script:ExoExtra = @{}
if ($AdminUPN) { $script:ExoExtra.UserPrincipalName = $AdminUPN }
if ($DelegatedOrganization) { $script:ExoExtra.DelegatedOrganization = $DelegatedOrganization }
$script:MgExtra = @{}
if ($TenantId) { $script:MgExtra.TenantId = $TenantId }
if (-not (Test-Path $OutputPath)) { New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null }

$results = @()

function Add-Result {
    param($Item, $Status, $Detail)
    $script:results += [PSCustomObject]@{
        Item   = $Item
        Status = $Status
        Detail = $Detail
    }
}

Write-Host "`n=== Connecting to Exchange Online ===" -ForegroundColor Cyan
try {
    Connect-ExchangeOnline -ShowBanner:$false -ErrorAction Stop @script:ExoExtra
} catch {
    Write-Host "Failed to connect to Exchange Online: $_" -ForegroundColor Red
    return
}

# ------------------------------------------------------------------
# 1. Legacy authentication blocking
# ------------------------------------------------------------------
Write-Host "Checking legacy authentication policy..." -ForegroundColor Cyan
try {
    $orgConfig = Get-OrganizationConfig
    $defaultAuthPolicy = $orgConfig.DefaultAuthenticationPolicy
    if ([string]::IsNullOrEmpty($defaultAuthPolicy)) {
        Add-Result "Block legacy authentication" "NOT APPLIED" "No DefaultAuthenticationPolicy set on the org."
    } else {
        $policy = Get-AuthenticationPolicy -Identity $defaultAuthPolicy -ErrorAction SilentlyContinue
        if ($policy) {
            $blocked = $policy | Select-Object -ExpandProperty AllowBasicAuth* -ErrorAction SilentlyContinue
            Add-Result "Block legacy authentication" "APPLIED" "Default policy: $defaultAuthPolicy"
        } else {
            Add-Result "Block legacy authentication" "NEEDS REVIEW" "Policy '$defaultAuthPolicy' referenced but not found."
        }
    }
} catch {
    Add-Result "Block legacy authentication" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 2. External auto-forwarding
# ------------------------------------------------------------------
Write-Host "Checking auto-forward settings..." -ForegroundColor Cyan
try {
    $remoteDomain = Get-RemoteDomain Default
    if ($remoteDomain.AutoForwardEnabled) {
        Add-Result "Block external auto-forwarding" "NOT APPLIED" "AutoForwardEnabled is currently TRUE on Default remote domain."
    } else {
        Add-Result "Block external auto-forwarding" "APPLIED" "AutoForwardEnabled is FALSE."
    }
} catch {
    Add-Result "Block external auto-forwarding" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 3. Mail flow rule for external sender impersonation warning
# ------------------------------------------------------------------
Write-Host "Checking transport rules for impersonation warning..." -ForegroundColor Cyan
try {
    $rules = Get-TransportRule
    $impersonationRule = $rules | Where-Object {
        $_.Name -match "external" -or $_.Name -match "impersonat" -or $_.Name -match "spoof"
    }
    if ($impersonationRule) {
        Add-Result "External sender impersonation mail flow rule" "APPLIED" "Found rule(s): $($impersonationRule.Name -join ', ')"
    } else {
        Add-Result "External sender impersonation mail flow rule" "NOT APPLIED" "No transport rule found matching external/impersonation/spoof naming."
    }
} catch {
    Add-Result "External sender impersonation mail flow rule" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 4. EOP anti-spam policy review
# ------------------------------------------------------------------
Write-Host "Checking anti-spam policy..." -ForegroundColor Cyan
try {
    $spamPolicy = Get-HostedContentFilterPolicy -Identity Default -ErrorAction Stop
    Add-Result "Anti-spam policy (default)" "REVIEW" "BulkComplaintLevel threshold: $($spamPolicy.BulkThreshold); SpamAction: $($spamPolicy.SpamAction)"
} catch {
    Add-Result "Anti-spam policy (default)" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 5. Anti-malware policy
# ------------------------------------------------------------------
Write-Host "Checking anti-malware policy..." -ForegroundColor Cyan
try {
    $malwarePolicy = Get-MalwareFilterPolicy -Identity Default -ErrorAction Stop
    Add-Result "Anti-malware policy (default)" "APPLIED" "EnableFileFilter: $($malwarePolicy.EnableFileFilter)"
} catch {
    Add-Result "Anti-malware policy (default)" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 6. Anti-phishing policy - spoof intelligence + impersonation protection
# ------------------------------------------------------------------
Write-Host "Checking anti-phishing / impersonation protection..." -ForegroundColor Cyan
try {
    $phishPolicies = Get-AntiPhishPolicy
    $defaultPhish = $phishPolicies | Where-Object { $_.IsDefault -eq $true }
    if ($defaultPhish) {
        $spoofOn = $defaultPhish.EnableSpoofIntelligence
        $protectedUsers = $defaultPhish.TargetedUsersToProtect
        $protectedCount = if ($protectedUsers) { $protectedUsers.Count } else { 0 }
        Add-Result "Spoof intelligence" $(if ($spoofOn) { "APPLIED" } else { "NOT APPLIED" }) "EnableSpoofIntelligence: $spoofOn"
        Add-Result "Impersonation protection - protected users" $(if ($protectedCount -gt 0) { "APPLIED" } else { "NOT APPLIED" }) "$protectedCount user(s) currently configured as protected targets."
        Add-Result "Mailbox intelligence" $(if ($defaultPhish.EnableMailboxIntelligence) { "APPLIED" } else { "NOT APPLIED" }) "EnableMailboxIntelligence: $($defaultPhish.EnableMailboxIntelligence)"
    } else {
        Add-Result "Anti-phishing policy" "NOT FOUND" "No default anti-phishing policy located."
    }
} catch {
    Add-Result "Anti-phishing policy" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# 7. Safe Links policy (Defender for Office 365 - requires Premium license on recipient)
# ------------------------------------------------------------------
Write-Host "Checking Safe Links policy..." -ForegroundColor Cyan
try {
    $safeLinks = Get-SafeLinksPolicy -ErrorAction Stop
    if ($safeLinks) {
        Add-Result "Safe Links policy" "APPLIED" "Found $($safeLinks.Count) policy(ies): $($safeLinks.Name -join ', ')"
    } else {
        Add-Result "Safe Links policy" "NOT APPLIED" "No Safe Links policy configured yet."
    }
} catch {
    Add-Result "Safe Links policy" "NOT APPLIED / NO LICENSE" "Requires Defender for Office 365 (Business Premium). Error: $($_.Exception.Message)"
}

# ------------------------------------------------------------------
# 8. Safe Attachments policy
# ------------------------------------------------------------------
Write-Host "Checking Safe Attachments policy..." -ForegroundColor Cyan
try {
    $safeAttach = Get-SafeAttachmentPolicy -ErrorAction Stop
    if ($safeAttach) {
        Add-Result "Safe Attachments policy" "APPLIED" "Found $($safeAttach.Count) policy(ies): $($safeAttach.Name -join ', ')"
    } else {
        Add-Result "Safe Attachments policy" "NOT APPLIED" "No Safe Attachments policy configured yet."
    }
} catch {
    Add-Result "Safe Attachments policy" "NOT APPLIED / NO LICENSE" "Requires Defender for Office 365 (Business Premium). Error: $($_.Exception.Message)"
}

# ------------------------------------------------------------------
# 9. Alert policies (Security & Compliance / Purview)
# ------------------------------------------------------------------
Write-Host "`n=== Connecting to Security & Compliance (IPPS) for alert policies ===" -ForegroundColor Cyan
try {
    Connect-IPPSSession -ErrorAction Stop @script:ExoExtra
    $alertPolicies = Get-ProtectionAlert
    $inboxRuleAlert = $alertPolicies | Where-Object { $_.Name -match "inbox rule" -or $_.Name -match "forward" }
    if ($inboxRuleAlert) {
        Add-Result "Alert policy: inbox rule / forwarding" "APPLIED" "Found: $($inboxRuleAlert.Name -join ', ')"
    } else {
        Add-Result "Alert policy: inbox rule / forwarding" "NOT APPLIED" "No matching alert policy found - recommend creating one."
    }
} catch {
    Add-Result "Alert policies (IPPS)" "SKIPPED / ERROR" "Could not connect to Security & Compliance PowerShell: $($_.Exception.Message)"
}

# ------------------------------------------------------------------
# 10. Admin role assignments (requires Microsoft Graph)
# ------------------------------------------------------------------
Write-Host "`n=== Checking admin role assignments (requires Microsoft Graph) ===" -ForegroundColor Cyan
Write-Host "NOTE: Run this section in a SEPARATE PowerShell window to avoid module conflicts with Exchange Online." -ForegroundColor Yellow
try {
    # Connect-MgGraph -Scopes "RoleManagement.Read.Directory","User.Read.All"
    # Uncomment above and run separately if Graph isn't already connected in this session
    if (Get-MgContext -ErrorAction SilentlyContinue) {
        $privilegedRoles = @("Global Administrator", "Authentication Administrator", "Exchange Administrator", "Security Administrator")
        $roleFindings = @()
        foreach ($roleName in $privilegedRoles) {
            $role = Get-MgDirectoryRole -Filter "displayName eq '$roleName'" -ErrorAction SilentlyContinue
            if ($role) {
                $members = Get-MgDirectoryRoleMember -DirectoryRoleId $role.Id -ErrorAction SilentlyContinue
                $roleFindings += "$roleName`: $($members.Count) member(s)"
            }
        }
        Add-Result "Admin role review" "REVIEW" ($roleFindings -join " | ")
    } else {
        Add-Result "Admin role review" "SKIPPED" "Not connected to Microsoft Graph. Run Connect-MgGraph in a separate window and re-run this section."
    }
} catch {
    Add-Result "Admin role review" "ERROR" $_.Exception.Message
}

# ------------------------------------------------------------------
# Output summary
# ------------------------------------------------------------------
Write-Host "`n`n=== TENANT HARDENING AUDIT RESULTS ===" -ForegroundColor Green
$results | Format-Table -AutoSize -Wrap

$notApplied = $results | Where-Object { $_.Status -match "NOT APPLIED" }
Write-Host "`n=== ITEMS STILL NEEDING ACTION: $($notApplied.Count) ===" -ForegroundColor Yellow
$notApplied | Format-Table -AutoSize -Wrap

# Export to CSV for record-keeping
$exportPath = Join-Path $OutputPath "TenantHardeningAudit_$(Get-Date -Format 'yyyy-MM-dd_HHmm').csv"
$results | Export-Csv -Path $exportPath -NoTypeInformation
Write-Host "`nFull results exported to: $exportPath" -ForegroundColor Cyan
'@

# ======================= Invoke-VMHangCapture.ps1 =======================
$Script:Payloads['Invoke-VMHangCapture'] = @'
<#
.SYNOPSIS
    Captures evidence from a hung Hyper-V guest BEFORE you hard Turn Off it.
    Run on the Hyper-V HOST (elevated) while the guest VM is unresponsive.

.DESCRIPTION
    Prepared by Sigma Data Systems Inc.

    1. VM state, heartbeat, CPU/memory, integration services
    2. Network reachability: ping, RDP 3389, WinRM 5985
    3. If WinRM still answers: RDP-related services, sessions, top processes (the OS is alive; only RDP is broken)
    4. Screenshot of the VM console (shows what the guest is stuck on, for example
       "Please wait for the User Profile Service" or a frozen login screen)
    5. Hyper-V host events for the last 24 hours
    6. Optional -InjectNMI: forces a guest bugcheck so Windows writes MEMORY.DMP,
       which gives the actual root cause. Use it INSTEAD of Turn Off.

.EXAMPLE
    .\Invoke-VMHangCapture.ps1 -VMName <VM>
    .\Invoke-VMHangCapture.ps1 -VMName <VM> -GuestName <hostname> -RdpPort 3389 -InjectNMI
#>
[CmdletBinding()]
param(
    [string]$VMName,
    [string]$GuestName,
    [string]$OutputRoot = "C:\temp\VMHangCapture",
    [int]$RdpPort       = 3389,
    [switch]$InjectNMI
)

$ErrorActionPreference = 'Continue'
if (-not (Get-Command Get-VM -ErrorAction SilentlyContinue)) {
    Write-Error "Get-VM is not available on $env:COMPUTERNAME. Run this on the Hyper-V HOST, not inside the guest."
    return
}
if ([string]::IsNullOrWhiteSpace($VMName)) { Write-Host 'ERROR: -VMName is required.' -ForegroundColor Red; return }
if ([string]::IsNullOrWhiteSpace($GuestName)) { $GuestName = $VMName }
$stamp  = Get-Date -Format 'yyyyMMdd-HHmmss'
$outDir = Join-Path $OutputRoot "$VMName-$stamp"
New-Item -ItemType Directory -Path $outDir -Force | Out-Null
$report = Join-Path $outDir 'Capture.txt'

function Write-Section([string]$Title) {
    $line = "`r`n==== $Title ====  ($(Get-Date -Format 'HH:mm:ss'))"
    Write-Host $line -ForegroundColor Cyan
    Add-Content -Path $report -Value $line
}
function Write-Out($Object) {
    $text = $Object | Out-String -Width 250
    Write-Host $text
    Add-Content -Path $report -Value $text
}

Write-Section "Capture started for VM '$VMName' on $env:COMPUTERNAME"

# ---- 1. VM state ---------------------------------------------------------
Write-Section 'VM state and heartbeat'
try {
    $vm = Get-VM -Name $VMName -ErrorAction Stop
    Write-Out ($vm | Select-Object Name, State, Status, Heartbeat, Uptime, CPUUsage,
        @{n='MemAssignedGB';e={[math]::Round($_.MemoryAssigned/1GB,2)}},
        @{n='MemDemandGB';e={[math]::Round($_.MemoryDemand/1GB,2)}},
        DynamicMemoryEnabled, Generation, Version)
    Write-Out 'Heartbeat meaning:'
    Write-Out '  OkApplicationsHealthy / OkApplicationsUnknown = guest kernel is alive; problem is in user mode (RDP, profiles, a service)'
    Write-Out '  LostCommunication / NoContact                 = guest OS is hung at kernel level (driver, storage, pool exhaustion)'
    Write-Out (Get-VMIntegrationService -VMName $VMName |
        Select-Object Name, Enabled, PrimaryStatusDescription, SecondaryStatusDescription)
    Write-Out (Get-VMHardDiskDrive -VMName $VMName | Select-Object ControllerType, ControllerNumber, Path)
} catch { Write-Out "Get-VM failed: $_" }

# ---- 2. Reachability ----------------------------------------------------
Write-Section 'Network reachability'
$ping  = Test-Connection -ComputerName $GuestName -Count 2 -Quiet
$rdp   = Test-NetConnection -ComputerName $GuestName -Port $RdpPort -WarningAction SilentlyContinue
$winrm = Test-NetConnection -ComputerName $GuestName -Port 5985 -WarningAction SilentlyContinue
Write-Out ([pscustomobject]@{
    Ping           = $ping
    "RDP_${RdpPort}_Open" = $rdp.TcpTestSucceeded
    WinRM_5985_Open= $winrm.TcpTestSucceeded
    ResolvedIP     = $rdp.RemoteAddress
})

# ---- 3. Remote guest data if WinRM still answers ------------------------
if ($winrm.TcpTestSucceeded) {
    Write-Section 'Guest data over WinRM (60s timeout)'
    $job = Invoke-Command -ComputerName $GuestName -AsJob -ScriptBlock {
        $o = [ordered]@{}
        $o.Services = Get-Service TermService, UmRdpService, SessionEnv, ProfSvc, Spooler, Winmgmt, EventLog -ErrorAction SilentlyContinue |
            Select-Object Name, Status, StartType
        $o.Sessions = (quser 2>&1) -join "`n"
        $os = Get-CimInstance Win32_OperatingSystem
        $o.Memory = [pscustomobject]@{
            FreePhysGB   = [math]::Round($os.FreePhysicalMemory/1MB,2)
            TotalPhysGB  = [math]::Round($os.TotalVisibleMemorySize/1MB,2)
            CommitUsedGB = [math]::Round((Get-Counter '\Memory\Committed Bytes').CounterSamples[0].CookedValue/1GB,2)
            CommitLimitGB= [math]::Round((Get-Counter '\Memory\Commit Limit').CounterSamples[0].CookedValue/1GB,2)
            NonPagedPoolMB = [math]::Round((Get-Counter '\Memory\Pool Nonpaged Bytes').CounterSamples[0].CookedValue/1MB,0)
            PagedPoolMB    = [math]::Round((Get-Counter '\Memory\Pool Paged Bytes').CounterSamples[0].CookedValue/1MB,0)
        }
        $o.TopCPU     = Get-Process | Sort-Object CPU -Descending | Select-Object -First 15 Name, Id, SessionId, CPU, @{n='WS_MB';e={[math]::Round($_.WS/1MB)}}, HandleCount
        $o.TopHandles = Get-Process | Sort-Object HandleCount -Descending | Select-Object -First 10 Name, Id, SessionId, HandleCount
        $o.Disk = Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' |
            Select-Object DeviceID, @{n='FreeGB';e={[math]::Round($_.FreeSpace/1GB,1)}}, @{n='SizeGB';e={[math]::Round($_.Size/1GB,1)}}
        $o.RecentSystem = Get-WinEvent -LogName System -MaxEvents 40 -ErrorAction SilentlyContinue |
            Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, @{n='Msg';e={($_.Message -split "`n")[0]}}
        [pscustomobject]$o
    }
    if (Wait-Job $job -Timeout 60) {
        $g = Receive-Job $job
        foreach ($p in $g.PSObject.Properties | Where-Object Name -notin 'PSComputerName','RunspaceId','PSShowComputerName') {
            Write-Out "--- $($p.Name) ---"
            Write-Out $p.Value
        }
    } else {
        Write-Out 'WinRM port is open but the command did not return within 60s (guest user mode is badly stalled).'
        Stop-Job $job
    }
    Remove-Job $job -Force
} else {
    Write-Out 'WinRM not reachable; skipping in-guest checks.'
}

# ---- 4. Console screenshot ----------------------------------------------
Write-Section 'VM console screenshot'
try {
    Add-Type -AssemblyName System.Drawing
    $ns   = 'root\virtualization\v2'
    $vmms = Get-CimInstance -Namespace $ns -ClassName Msvm_VirtualSystemManagementService
    $cs   = Get-CimInstance -Namespace $ns -ClassName Msvm_ComputerSystem -Filter "ElementName='$VMName'"
    $vssd = Get-CimAssociatedInstance -InputObject $cs -ResultClassName Msvm_VirtualSystemSettingData |
            Where-Object VirtualSystemType -eq 'Microsoft:Hyper-V:System:Realized'
    $w = 1024; $h = 768
    $res = Invoke-CimMethod -InputObject $vmms -MethodName GetVirtualSystemThumbnailImage `
           -Arguments @{ TargetSystem = $vssd; WidthPixels = [uint16]$w; HeightPixels = [uint16]$h }
    if ($res.ImageData) {
        $bmp  = New-Object System.Drawing.Bitmap $w, $h, ([System.Drawing.Imaging.PixelFormat]::Format16bppRgb565)
        $rect = New-Object System.Drawing.Rectangle 0, 0, $w, $h
        $data = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::WriteOnly, $bmp.PixelFormat)
        [System.Runtime.InteropServices.Marshal]::Copy([byte[]]$res.ImageData, 0, $data.Scan0, $res.ImageData.Length)
        $bmp.UnlockBits($data)
        $png = Join-Path $outDir 'Console.png'
        $bmp.Save($png, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmp.Dispose()
        Write-Out "Saved $png"
    } else { Write-Out "Thumbnail call returned no data (ReturnValue $($res.ReturnValue)). Open VMConnect and take a screenshot manually." }
} catch { Write-Out "Screenshot failed: $_  (Open VMConnect and take a screenshot manually.)" }

# ---- 5. Host-side events ------------------------------------------------
Write-Section 'Hyper-V host events, last 24h (warnings and errors)'
$since = (Get-Date).AddHours(-24)
$hvLogs = 'Microsoft-Windows-Hyper-V-Worker-Admin','Microsoft-Windows-Hyper-V-VMMS-Admin',
          'Microsoft-Windows-Hyper-V-StorageVSP-Admin','Microsoft-Windows-Hyper-V-Integration-Admin'
foreach ($log in $hvLogs) {
    $ev = @(Get-WinEvent -FilterHashtable @{ LogName = $log; StartTime = $since; Level = 1,2,3 } -ErrorAction SilentlyContinue | Where-Object { $_ })
    Write-Out "--- $log : $($ev.Count) events ---"
    if ($ev) { Write-Out ($ev | Select-Object -First 30 TimeCreated, Id, LevelDisplayName, @{n='Msg';e={($_.Message -split "`n")[0]}}) }
}
$sysEv = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; StartTime = $since; Level = 1,2 } -ErrorAction SilentlyContinue | Where-Object { $_ })
Write-Out "--- Host System errors: $($sysEv.Count) ---"
if ($sysEv) { Write-Out ($sysEv | Select-Object -First 30 TimeCreated, Id, ProviderName, @{n='Msg';e={($_.Message -split "`n")[0]}}) }

# ---- 6. Optional NMI -----------------------------------------------------
if ($InjectNMI) {
    Write-Section 'Injecting NMI into guest'
    Write-Out 'Guest should bugcheck (0x80 NMI_HARDWARE_FAILURE), write C:\Windows\MEMORY.DMP, then reboot on its own.'
    Write-Out 'Wait 5 to 10 minutes. Only Turn Off if the VM is still frozen on the same screen after that.'
    try { Debug-VM -Name $VMName -InjectNonMaskableInterrupt -Force -ErrorAction Stop; Write-Out 'NMI sent.' }
    catch { Write-Out "Debug-VM failed: $_" }
}

Write-Section 'Done'
Write-Out "Output folder: $outDir"
'@

# ======================= M365-Toolbox.ps1 =======================
$Script:Payloads['M365-Toolbox'] = @'
<#
.SYNOPSIS
    Sigma Data Systems INC ToolKit - Microsoft 365 toolbox (Exchange Online + Microsoft Graph).

.DESCRIPTION
    Prepared by Sigma Data Systems Inc. - https://sigmadatainc.com/

    One action per run (-Action). Each run connects only to the service(s) it needs, so
    Exchange Online and Microsoft Graph never fight over the same MSAL assembly in a
    Windows PowerShell 5.1 session. Graph calls use Invoke-MgGraphRequest, so only the
    Microsoft.Graph.Authentication module is required (fast to load, no SDK sprawl).

    Works for your own tenant or a client tenant:
      -AdminUPN               the admin account to sign in with (optional)
      -DelegatedOrganization  client tenant for partner / GDAP access to Exchange (e.g. client.onmicrosoft.com)
      -TenantId               client tenant (domain or GUID) for Microsoft Graph

    Read-only actions never change anything. Actions that change the tenant ask for
    confirmation (type YES) for every step.

.NOTES
    Modules: ExchangeOnlineManagement 3.7+ (Get-MessageTraceV2), Microsoft.Graph.Authentication.
    Use -Action Modules to install / repair them.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Action,
    [string]$AdminUPN,
    [string]$DelegatedOrganization,
    [string]$TenantId,
    [string]$OutputPath = 'C:\temp\M365',
    [string]$UserPrincipalName,
    [string]$SenderAddress,
    [string]$Recipient,
    [string]$Subject,
    [string]$Domain,
    [string]$Value,
    [int]$Days = 30,
    [switch]$AllMailboxes
)

$ErrorActionPreference = 'Continue'
try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
if (-not (Test-Path $OutputPath)) { New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null }
$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'

#region ------------------------------------------------------------------ helpers
function Write-H([string]$t) { Write-Host "`n=== $t ===" -ForegroundColor Cyan }
function Ask([string]$p, $d = '') { $s = if ("$d" -ne '') { " [$d]" } else { '' }; $a = Read-Host "$p$s"; if ([string]::IsNullOrWhiteSpace($a)) { return $d }; return $a.Trim() }
function AskYes([string]$what) {
    Write-Host "  [!] $what" -ForegroundColor Yellow
    return ((Read-Host '  Type YES to continue') -ceq 'YES')
}
function Save-Csv($rows, [string]$name) {
    $p = Join-Path $OutputPath ("{0}_{1}.csv" -f $name, $Stamp)
    @($rows) | Export-Csv -Path $p -NoTypeInformation -Encoding UTF8
    Write-Host "  Saved: $p" -ForegroundColor Green
    return $p
}
function New-RandomPassword([int]$Len = 16) {
    $sets = 'ABCDEFGHJKLMNPQRSTUVWXYZ', 'abcdefghijkmnopqrstuvwxyz', '23456789', '!@#$%*?-+='
    $chars = foreach ($s in $sets) { $s[(Get-Random -Maximum $s.Length)] }
    $all = -join $sets
    $chars += 1..($Len - 4) | ForEach-Object { $all[(Get-Random -Maximum $all.Length)] }
    -join ($chars | Sort-Object { Get-Random })
}

function Use-Module([string]$Name, [string]$MinVersion) {
    $have = Get-Module -ListAvailable -Name $Name | Sort-Object Version -Descending | Select-Object -First 1
    if (-not $have -or ($MinVersion -and $have.Version -lt [version]$MinVersion)) {
        Write-Host "  Module $Name $(if ($MinVersion) { ">= $MinVersion " })is not installed." -ForegroundColor Yellow
        if ((Ask "  Install $Name from the PowerShell Gallery now (current user)? Y/N" 'Y') -notmatch '^[Yy]') { throw "$Name is required." }
        Install-PSGalleryModule $Name
    }
    Import-Module $Name -ErrorAction Stop -WarningAction SilentlyContinue
}

function Install-PSGalleryModule([string]$Name, [string]$RequiredVersion) {
    if (-not (Get-PackageProvider -ListAvailable -Name NuGet -ErrorAction SilentlyContinue | Where-Object { $_.Version -ge [version]'2.8.5.201' })) {
        Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Scope CurrentUser -Force | Out-Null
    }
    $p = @{ Name = $Name; Scope = 'CurrentUser'; Force = $true; AllowClobber = $true; Repository = 'PSGallery'; ErrorAction = 'Stop' }
    if ($RequiredVersion) { $p.RequiredVersion = $RequiredVersion }
    Install-Module @p
    Write-Host "  Installed $Name $RequiredVersion" -ForegroundColor Green
}

function Connect-EXO {
    Use-Module 'ExchangeOnlineManagement' '3.4.0'
    $c = @{ ShowBanner = $false; ErrorAction = 'Stop' }
    if ($AdminUPN) { $c.UserPrincipalName = $AdminUPN }
    if ($DelegatedOrganization) { $c.DelegatedOrganization = $DelegatedOrganization }
    Write-Host '  Connecting to Exchange Online...' -ForegroundColor DarkGray
    Connect-ExchangeOnline @c
    $org = Get-OrganizationConfig
    Write-Host "  Connected: $($org.DisplayName) ($($org.Name))" -ForegroundColor Green
}

function Connect-IPPS {
    Use-Module 'ExchangeOnlineManagement' '3.4.0'
    $c = @{ ShowBanner = $false; ErrorAction = 'Stop' }
    if ($AdminUPN) { $c.UserPrincipalName = $AdminUPN }
    if ($DelegatedOrganization) { $c.DelegatedOrganization = $DelegatedOrganization }
    Connect-IPPSSession @c
}

function Connect-Graph([string[]]$Scopes) {
    Use-Module 'Microsoft.Graph.Authentication'
    $c = @{ Scopes = $Scopes; NoWelcome = $true; ErrorAction = 'Stop' }
    if ($TenantId) { $c.TenantId = $TenantId }
    Write-Host "  Connecting to Microsoft Graph ($($Scopes -join ', '))..." -ForegroundColor DarkGray
    Connect-MgGraph @c
    $ctx = Get-MgContext
    Write-Host "  Connected: $($ctx.Account) / tenant $($ctx.TenantId)" -ForegroundColor Green
}

# GET with automatic paging. Returns the objects in .value (or the single object).
function Invoke-Graph([string]$Uri, [hashtable]$Headers, [switch]$NoPaging) {
    $out = New-Object System.Collections.Generic.List[object]
    $next = $Uri
    do {
        $p = @{ Method = 'GET'; Uri = $next; OutputType = 'PSObject'; ErrorAction = 'Stop' }
        if ($Headers) { $p.Headers = $Headers }
        $r = Invoke-MgGraphRequest @p
        if ($null -ne $r.value) { foreach ($v in $r.value) { $out.Add($v) } } else { $out.Add($r) }
        $next = if ($NoPaging) { $null } else { $r.'@odata.nextLink' }
    } while ($next)
    return $out
}
function Invoke-GraphWrite([string]$Method, [string]$Uri, $Body) {
    $p = @{ Method = $Method; Uri = $Uri; ErrorAction = 'Stop' }
    if ($null -ne $Body) { $p.Body = ($Body | ConvertTo-Json -Depth 10); $p.ContentType = 'application/json' }
    Invoke-MgGraphRequest @p
}

function Get-LicenseNameMap {
    # Microsoft's official SKU friendly-name list (cached in C:\temp\Tools\M365)
    $dir = 'C:\temp\Tools\M365'; if (-not (Test-Path $dir)) { New-Item -ItemType Directory $dir -Force | Out-Null }
    $csv = Join-Path $dir 'LicenseNames.csv'
    if (-not (Test-Path $csv) -or (Get-Item $csv).LastWriteTime -lt (Get-Date).AddDays(-30)) {
        try { Invoke-WebRequest -UseBasicParsing -Uri 'https://download.microsoft.com/download/e/3/e/e3e9faf2-f28b-490a-9ada-c6089a1fc5b0/Product%20names%20and%20service%20plan%20identifiers%20for%20licensing.csv' -OutFile $csv -ErrorAction Stop } catch { }
    }
    $map = @{}
    if (Test-Path $csv) { Import-Csv $csv | ForEach-Object { if (-not $map.ContainsKey($_.GUID)) { $map[$_.GUID] = $_.Product_Display_Name } } }
    return $map
}

function Get-TargetUpn {
    if (-not $UserPrincipalName) { $script:UserPrincipalName = Ask 'User / mailbox (UPN or email address)' }
    if (-not $UserPrincipalName) { throw 'A user is required.' }
    return $UserPrincipalName
}

$SuspiciousRule = {
    param($r)
    $why = @()
    if ($r.ForwardTo -or $r.ForwardAsAttachmentTo -or $r.RedirectTo) { $why += 'forwards/redirects' }
    if ($r.DeleteMessage) { $why += 'deletes' }
    if ($r.MoveToFolder -match 'RSS|Conversation History|Archive|Junk|Deleted|Notes|Sync Issues') { $why += "moves to '$($r.MoveToFolder)'" }
    if ($r.MarkAsRead -and ($r.MoveToFolder -or $r.DeleteMessage)) { $why += 'marks read + hides' }
    if ($r.Name -match '^[\W_]{1,3}$' -or $r.Name.Length -le 2) { $why += "odd name '$($r.Name)'" }
    if ($r.SubjectOrBodyContainsWords -match 'invoice|payment|wire|bank|ach|password|hacked|phish|security|verify|w-2|w2|payroll') { $why += 'finance/security keywords' }
    $why -join '; '
}
#endregion

#region ------------------------------------------------------------------ actions
switch ($Action) {

# ======================================================================== MODULES
'Modules' {
    Write-H 'Microsoft 365 PowerShell modules'
    $mods = 'ExchangeOnlineManagement', 'Microsoft.Graph.Authentication', 'Microsoft.Graph.Users', 'Microsoft.Graph.Identity.SignIns', 'Microsoft.Graph.Reports', 'Microsoft.Graph.Applications', 'Microsoft.Graph.DirectoryObjects', 'Microsoft.Graph.Identity.DirectoryManagement', 'Microsoft.Online.SharePoint.PowerShell', 'MicrosoftTeams'
    foreach ($m in $mods) {
        $v = Get-Module -ListAvailable -Name $m | Sort-Object Version -Descending
        Write-Host ("  {0,-42} {1}" -f $m, $(if ($v) { ($v.Version | Select-Object -Unique | ForEach-Object { "$_" }) -join ', ' } else { 'NOT INSTALLED' })) -ForegroundColor $(if ($v) { 'White' } else { 'Yellow' })
    }
    Write-Host '  (Only the Graph sub-modules the ToolKit uses are installed - not the full ~40-module Microsoft.Graph SDK.' -ForegroundColor DarkGray
    Write-Host '   Graph sub-modules must all be the SAME version; option 1 keeps them aligned to Microsoft.Graph.Authentication.)' -ForegroundColor DarkGray
    Write-Host "`n  1. Install / update all of the above (current user)"
    Write-Host '  2. Install ExchangeOnlineManagement 3.7.1 side-by-side (fixes EXO + Graph "method not found" / MSAL conflicts in PS 5.1)'
    switch (Ask 'Choose (blank = done)' '') {
        '1' {
            foreach ($m in $mods) {
                try {
                    if ($m -like 'Microsoft.Graph.*' -and $m -ne 'Microsoft.Graph.Authentication') {
                        $authVer = (Get-Module -ListAvailable -Name 'Microsoft.Graph.Authentication' | Sort-Object Version -Descending | Select-Object -First 1).Version
                        Install-PSGalleryModule $m "$authVer"
                    } else { Install-PSGalleryModule $m }
                } catch { Write-Host "  $m failed: $($_.Exception.Message)" -ForegroundColor Red }
            }
        }
        '2' {
            try { Install-PSGalleryModule 'ExchangeOnlineManagement' '3.7.1' } catch {
                # Fallback without PowerShellGet: pull the .nupkg straight from the gallery into the user module path
                $base = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'WindowsPowerShell\Modules\ExchangeOnlineManagement\3.7.1'
                New-Item -ItemType Directory -Path $base -Force | Out-Null
                $zip = Join-Path $env:TEMP 'EXO371.zip'
                Invoke-WebRequest -UseBasicParsing -Uri 'https://www.powershellgallery.com/api/v2/package/ExchangeOnlineManagement/3.7.1' -OutFile $zip
                Expand-Archive -Path $zip -DestinationPath $base -Force
                Write-Host "  Extracted to $base" -ForegroundColor Green
            }
            Write-Host '  To use it in a session: Import-Module ExchangeOnlineManagement -RequiredVersion 3.7.1 (before anything Graph).' -ForegroundColor DarkGray
        }
    }
}

# ======================================================================== EXCHANGE: INBOX RULES
'InboxRules' {
    Connect-EXO
    $targets = if ($AllMailboxes) { Get-EXOMailbox -ResultSize Unlimited -RecipientTypeDetails UserMailbox, SharedMailbox | Select-Object -ExpandProperty PrimarySmtpAddress } else { @(Get-TargetUpn) }
    Write-H "Inbox rules ($(@($targets).Count) mailbox(es))"
    $rows = foreach ($mb in $targets) {
        try {
            Get-InboxRule -Mailbox $mb -IncludeHidden -ErrorAction Stop | ForEach-Object {
                $why = & $SuspiciousRule $_
                [pscustomobject]@{
                    Mailbox = $mb; Name = $_.Name; Enabled = $_.Enabled; Suspicious = $why
                    ForwardTo = ($_.ForwardTo -join '; '); ForwardAsAttachmentTo = ($_.ForwardAsAttachmentTo -join '; '); RedirectTo = ($_.RedirectTo -join '; ')
                    DeleteMessage = $_.DeleteMessage; MoveToFolder = $_.MoveToFolder; MarkAsRead = $_.MarkAsRead; StopProcessing = $_.StopProcessingRules
                    From = ($_.From -join '; '); SubjectOrBodyContains = ($_.SubjectOrBodyContainsWords -join '; '); Description = ($_.Description -replace '\s+', ' ')
                    RuleIdentity = $_.Identity
                }
            }
        } catch { Write-Host "  $mb : $($_.Exception.Message)" -ForegroundColor DarkYellow }
    }
    $rows | Select-Object Mailbox, Name, Enabled, Suspicious, ForwardTo, RedirectTo, DeleteMessage, MoveToFolder | Format-Table -AutoSize -Wrap
    $sus = @($rows | Where-Object Suspicious)
    Write-Host "  $(@($rows).Count) rules, $($sus.Count) flagged suspicious." -ForegroundColor $(if ($sus) { 'Yellow' } else { 'Green' })
    if ($rows) { Save-Csv $rows 'InboxRules' | Out-Null }

    if (-not $AllMailboxes) {
        Write-H "When were rules created / changed? (unified audit log, last $Days days)"
        Write-Host '  Use this to prove whether a "new rule" alert (e.g. from Augmentt) is really new or a pre-existing rule set.' -ForegroundColor DarkGray
        try {
            $audit = Search-UnifiedAuditLog -StartDate (Get-Date).AddDays(-[math]::Min($Days, 180)) -EndDate (Get-Date) -UserIds $targets[0] -Operations New-InboxRule, Set-InboxRule, Remove-InboxRule, UpdateInboxRules, Enable-InboxRule, Disable-InboxRule -ResultSize 5000 -ErrorAction Stop
            $a = $audit | ForEach-Object {
                $d = $_.AuditData | ConvertFrom-Json
                $ruleName = ($d.Parameters | Where-Object Name -eq 'Name').Value
                if (-not $ruleName -and $d.OperationProperties) { $ruleName = ($d.OperationProperties | Where-Object Name -eq 'RuleName').Value }
                [pscustomobject]@{ Time = $_.CreationDate.ToLocalTime(); Operation = $_.Operations; By = $_.UserIds; Rule = $ruleName; ClientIP = $d.ClientIP; App = $d.AppId; Client = $d.ClientInfoString }
            }
            if ($a) { $a | Sort-Object Time | Format-Table -AutoSize -Wrap; Save-Csv $a 'InboxRuleAudit' | Out-Null }
            else { Write-Host "  No rule create/change events in the last $Days days - the existing rules are OLDER than that." -ForegroundColor Green }
        } catch { Write-Host "  Audit search failed: $($_.Exception.Message) (is unified audit logging enabled? needs View-Only Audit Logs role)" -ForegroundColor DarkYellow }

        $flag = @($rows | Where-Object Suspicious)
        if ($flag -and (Ask 'Disable the flagged rules? Y/N' 'N') -match '^[Yy]') {
            foreach ($r in $flag) { if (AskYes "Disable rule '$($r.Name)' on $($r.Mailbox) ($($r.Suspicious))") { Disable-InboxRule -Identity $r.RuleIdentity -Confirm:$false; Write-Host '  Disabled.' -ForegroundColor Green } }
        }
    }
}

# ======================================================================== EXCHANGE: FORWARDING
'Forwarding' {
    Connect-EXO
    Write-H 'Tenant forwarding controls'
    $rd = Get-RemoteDomain Default
    $ob = Get-HostedOutboundSpamFilterPolicy | Select-Object Name, AutoForwardingMode, IsDefault
    Write-Host ("  Remote domain 'Default' AutoForwardEnabled: {0}" -f $rd.AutoForwardEnabled)
    $ob | Format-Table -AutoSize
    Write-Host '  AutoForwardingMode Off = external auto-forward blocked; Automatic = blocked (Microsoft default); On = allowed.' -ForegroundColor DarkGray
    Write-H 'Mailboxes with forwarding set'
    $fw = Get-EXOMailbox -ResultSize Unlimited -Properties ForwardingSmtpAddress, ForwardingAddress, DeliverToMailboxAndForward |
        Where-Object { $_.ForwardingSmtpAddress -or $_.ForwardingAddress } |
        Select-Object DisplayName, PrimarySmtpAddress, ForwardingSmtpAddress, ForwardingAddress, DeliverToMailboxAndForward
    if ($fw) { $fw | Format-Table -AutoSize; Save-Csv $fw 'MailboxForwarding' | Out-Null } else { Write-Host '  None.' -ForegroundColor Green }
    if ((Ask 'Also scan EVERY mailbox''s inbox rules for external forwarding (slow on big tenants)? Y/N' 'N') -match '^[Yy]') {
        $accepted = (Get-AcceptedDomain).DomainName
        $rules = foreach ($mb in (Get-EXOMailbox -ResultSize Unlimited -RecipientTypeDetails UserMailbox, SharedMailbox).PrimarySmtpAddress) {
            Get-InboxRule -Mailbox $mb -ErrorAction SilentlyContinue | Where-Object { $_.ForwardTo -or $_.ForwardAsAttachmentTo -or $_.RedirectTo } | ForEach-Object {
                $dest = @($_.ForwardTo) + @($_.ForwardAsAttachmentTo) + @($_.RedirectTo) | Where-Object { $_ }
                $ext = $dest | Where-Object { $_ -match 'SMTP:([^\]"]+@([^\]"]+))' -and $accepted -notcontains $Matches[2] }
                [pscustomobject]@{ Mailbox = $mb; Rule = $_.Name; Enabled = $_.Enabled; Destinations = ($dest -join '; '); External = [bool]$ext }
            }
        }
        $rules | Sort-Object External -Descending | Format-Table -AutoSize -Wrap
        if ($rules) { Save-Csv $rules 'ForwardingRules' | Out-Null }
    }
    Write-Host '  Remember: some forwarding is legitimate (e.g. an admin mailbox forwarding to your helpdesk) - confirm with the client before removing.' -ForegroundColor DarkGray
}

# ======================================================================== EXCHANGE: MESSAGE TRACE
'MessageTrace' {
    Connect-EXO
    $s = if ($SenderAddress) { $SenderAddress } else { Ask 'Sender address (blank = any; *@domain.com allowed)' '' }
    $r = if ($Recipient) { $Recipient } else { Ask 'Recipient address (blank = any)' '' }
    $subj = if ($Subject) { $Subject } else { Ask 'Subject contains (blank = any)' '' }
    $d = [int](Ask 'Days back (max 90)' ([math]::Min($Days, 10)))
    Write-H 'Message trace'
    $useV2 = [bool](Get-Command Get-MessageTraceV2 -ErrorAction SilentlyContinue)
    $end = Get-Date; $all = New-Object System.Collections.Generic.List[object]
    $start = $end.AddDays(-$d); if ($d -ge 90) { $start = $start.AddHours(1) }
    $cursor = $start
    while ($cursor -lt $end) {
        $chunkEnd = $cursor.AddDays(10); if ($chunkEnd -gt $end) { $chunkEnd = $end }
        $q = @{ StartDate = $cursor; EndDate = $chunkEnd; ErrorAction = 'Stop' }
        if ($s) { $q.SenderAddress = $s }; if ($r) { $q.RecipientAddress = $r }
        try {
            if ($useV2) {
                if ($subj) { $q.Subject = $subj; $q.SubjectFilterType = 'Contains' }
                $q.ResultSize = 5000
                Get-MessageTraceV2 @q | ForEach-Object { $all.Add($_) }
            } else {
                $page = 1
                do { $res = @(Get-MessageTrace @q -PageSize 5000 -Page $page); $res | ForEach-Object { $all.Add($_) }; $page++ } while ($res.Count -eq 5000)
            }
        } catch { Write-Host "  $($cursor.ToShortDateString()): $($_.Exception.Message)" -ForegroundColor DarkYellow }
        $cursor = $chunkEnd
    }
    $rows = $all | Where-Object { -not $subj -or $_.Subject -like "*$subj*" } | Sort-Object Received -Descending
    $rows | Select-Object -First 50 Received, SenderAddress, RecipientAddress, Subject, Status, Size | Format-Table -AutoSize -Wrap
    Write-Host "  $(@($rows).Count) messages." -ForegroundColor Cyan
    if ($rows) {
        Save-Csv ($rows | Select-Object Received, SenderAddress, RecipientAddress, Subject, Status, FromIP, ToIP, Size, MessageId, MessageTraceId) 'MessageTrace' | Out-Null
        $rows | Group-Object Status | Select-Object Count, Name | Format-Table -AutoSize
        $pick = Ask 'Show the delivery detail for message # (1 = newest, blank = skip)' ''
        if ($pick -match '^\d+$') {
            $m = @($rows)[[int]$pick - 1]
            Write-H "Detail: $($m.Subject) -> $($m.RecipientAddress)"
            if ($useV2 -and (Get-Command Get-MessageTraceDetailV2 -ErrorAction SilentlyContinue)) { Get-MessageTraceDetailV2 -MessageTraceId $m.MessageTraceId -RecipientAddress $m.RecipientAddress | Select-Object Date, Event, Action, Detail | Format-Table -AutoSize -Wrap }
            else { Get-MessageTraceDetail -MessageTraceId $m.MessageTraceId -RecipientAddress $m.RecipientAddress | Select-Object Date, Event, Action, Detail | Format-Table -AutoSize -Wrap }
        }
    }
}

# ======================================================================== EXCHANGE: QUARANTINE
'Quarantine' {
    Connect-EXO
    $s = if ($SenderAddress) { $SenderAddress } else { Ask 'Sender address or domain (blank = any)' '' }
    $r = if ($Recipient) { $Recipient } else { Ask 'Recipient address (blank = any)' '' }
    $d = [int](Ask 'Days back (max 30)' ([math]::Min($Days, 30)))
    Write-H 'Quarantined messages'
    $q = @{ StartReceivedDate = (Get-Date).AddDays(-$d); EndReceivedDate = (Get-Date); PageSize = 1000 }
    if ($r) { $q.RecipientAddress = $r }
    if ($s -and $s -match '@') { $q.SenderAddress = $s }
    $msgs = @(Get-QuarantineMessage @q -ErrorAction SilentlyContinue)
    if ($s -and $s -notmatch '@') { $msgs = @($msgs | Where-Object { $_.SenderAddress -like "*$s" }) }
    $msgs | Select-Object ReceivedTime, SenderAddress, @{n='Recipients';e={$_.RecipientAddress -join ', '}}, Subject, Type, PolicyName, ReleaseStatus | Format-Table -AutoSize -Wrap
    Write-Host "  $($msgs.Count) quarantined messages." -ForegroundColor Cyan
    Write-Host '  Type = why: Spam / Bulk (BCL - NOT overridden by an SCL -1 rule) / Phish / HighConfPhish / Malware / TransportRule.' -ForegroundColor DarkGray
    if ($msgs) {
        Save-Csv ($msgs | Select-Object ReceivedTime, SenderAddress, @{n='Recipients';e={$_.RecipientAddress -join ', '}}, Subject, Type, PolicyName, PolicyType, ReleaseStatus, Identity) 'Quarantine' | Out-Null
        $rel = Ask 'Release which? (message numbers e.g. 1,3 / ALL / blank = none)' ''
        if ($rel) {
            $set = if ($rel -eq 'ALL') { $msgs } else { $rel -split ',' | ForEach-Object { $msgs[[int]$_.Trim() - 1] } }
            $set = @($set | Where-Object { $_ -and $_.Type -notin 'Malware', 'HighConfPhish' })
            if ($set -and (AskYes "Release $($set.Count) message(s) to all original recipients (malware/high-confidence phish are never released here)")) {
                foreach ($m in $set) { try { Release-QuarantineMessage -Identity $m.Identity -ReleaseToAll -ErrorAction Stop; Write-Host "  Released: $($m.Subject)" -ForegroundColor Green } catch { Write-Host "  $($m.Subject): $($_.Exception.Message)" -ForegroundColor Red } }
            }
        }
    }
}

# ======================================================================== EXCHANGE: SENDER / MAIL FLOW DIAGNOSIS
'SenderDiag' {
    Connect-EXO
    $s = if ($SenderAddress) { $SenderAddress } else { Ask 'Sender address or domain to diagnose (e.g. quickbooks@notification.intuit.com or intuit.com)' }
    $dom = ($s -split '@')[-1]
    Write-H "Why is mail from $s being filtered?"
    Write-Host "  Transport rules mentioning $dom :" -ForegroundColor Yellow
    Get-TransportRule | Where-Object { ($_ | Out-String) -match [regex]::Escape($dom) } | Select-Object Name, State, Priority, SetSCL, @{n='Headers';e={ "$($_.SetHeaderName)=$($_.SetHeaderValue)" }}, Description | Format-List
    Write-Host '  Tenant Allow/Block List (senders):' -ForegroundColor Yellow
    Get-TenantAllowBlockListItems -ListType Sender -ErrorAction SilentlyContinue | Where-Object { $_.Value -like "*$dom*" } | Select-Object Value, Action, ExpirationDate, Notes | Format-Table -AutoSize
    Write-Host '  Inbound anti-spam policies (bulk threshold / allowed senders):' -ForegroundColor Yellow
    Get-HostedContentFilterPolicy | Select-Object Name, BulkThreshold, MarkAsSpamBulkMail, BulkSpamAction, @{n='AllowedSenderDomains';e={$_.AllowedSenderDomains -join ','}}, @{n='AllowedSenders';e={$_.AllowedSenders -join ','}} | Format-Table -AutoSize -Wrap
    Write-Host '  Anti-phishing impersonation exclusions:' -ForegroundColor Yellow
    Get-AntiPhishPolicy | Select-Object Name, Enabled, EnableTargetedDomainsProtection, EnableOrganizationDomainsProtection, EnableTargetedUserProtection, @{n='ExcludedDomains';e={$_.ExcludedDomains -join ','}}, @{n='ExcludedSenders';e={$_.ExcludedSenders -join ','}} | Format-Table -AutoSize -Wrap
    Write-Host '  Recent quarantine hits from this sender (14 days):' -ForegroundColor Yellow
    Get-QuarantineMessage -StartReceivedDate (Get-Date).AddDays(-14) -EndReceivedDate (Get-Date) -PageSize 1000 -ErrorAction SilentlyContinue | Where-Object { $_.SenderAddress -like "*$dom" } |
        Select-Object ReceivedTime, SenderAddress, Subject, Type, PolicyName | Format-Table -AutoSize -Wrap
    Write-Host @'

  How to read this:
   - Type Bulk -> Bulk Complaint Level (BCL), separate from SCL. A rule that sets SCL -1 does NOT stop bulk filtering.
     Fix: add a 2nd action to the rule - set header X-MS-Exchange-Organization-BulkStamping = 0 - or allow the sender in TABL.
   - Type Phish with impersonation -> add the sender's domain to the anti-phish policy's impersonation exclusions.
   - Type Spam -> TABL allow entry for the sender (Microsoft's preferred allow method), or a mail flow rule SCL -1.
#SDSI-ESC#'@ -ForegroundColor DarkGray
    Write-Host '  Fixes:  1 = TABL allow sender (45 days)  2 = Exclude domain from impersonation protection  3 = Add BulkStamping=0 action to a rule  blank = none'
    switch (Ask 'Choose' '') {
        '1' { if (AskYes "Add Tenant Allow List entry for $s (expires in 45 days)") { New-TenantAllowBlockListItems -ListType Sender -Allow -Entries $s -RemoveAfter 45 -Notes "Added by SDSI ToolKit $(Get-Date -Format d)" | Format-Table Value, Action, ExpirationDate } }
        '2' {
            $pol = Ask 'Anti-phish policy name' ((Get-AntiPhishPolicy | Where-Object { -not $_.IsDefault } | Select-Object -First 1).Name)
            if (-not $pol) { $pol = 'Office365 AntiPhish Default' }
            if (AskYes "Add $dom to ExcludedDomains on '$pol'") { Set-AntiPhishPolicy -Identity $pol -ExcludedDomains @{ Add = $dom }; Write-Host '  Done.' -ForegroundColor Green }
        }
        '3' {
            $rule = Ask 'Mail flow rule name to add the header action to' ''
            if ($rule -and (AskYes "Set header X-MS-Exchange-Organization-BulkStamping = 0 on rule '$rule'")) { Set-TransportRule -Identity $rule -SetHeaderName 'X-MS-Exchange-Organization-BulkStamping' -SetHeaderValue '0'; Write-Host '  Done.' -ForegroundColor Green }
        }
    }
}

# ======================================================================== DNS: SPF / DKIM / DMARC
'EmailAuth' {
    $domains = @()
    if ($Domain) { $domains = $Domain -split '[,; ]+' | Where-Object { $_ } }
    else {
        $in = Ask 'Domain(s) to check, comma separated (blank = all accepted domains via Exchange Online)' ''
        if ($in) { $domains = $in -split '[,; ]+' | Where-Object { $_ } } else { Connect-EXO; $domains = (Get-AcceptedDomain | Where-Object DomainName -notlike '*.onmicrosoft.com').DomainName }
    }
    $dkimCfg = @{}
    if (Get-Command Get-DkimSigningConfig -ErrorAction SilentlyContinue) { Get-DkimSigningConfig -ErrorAction SilentlyContinue | ForEach-Object { $dkimCfg[$_.Domain] = $_ } }
    $rows = foreach ($d in $domains) {
        $txt = { param($n) (Resolve-DnsName -Name $n -Type TXT -DnsOnly -ErrorAction SilentlyContinue | Where-Object { $_.Strings }).Strings -join '' }
        $mx = (Resolve-DnsName -Name $d -Type MX -DnsOnly -ErrorAction SilentlyContinue | Where-Object NameExchange | Sort-Object Preference | ForEach-Object { $_.NameExchange }) -join ', '
        $spfAll = @(Resolve-DnsName -Name $d -Type TXT -DnsOnly -ErrorAction SilentlyContinue | ForEach-Object { $_.Strings -join '' } | Where-Object { $_ -match '^v=spf1' })
        $spf = $spfAll -join ' || '
        $lookups = ([regex]::Matches($spf, '\b(include:|a\b|a:|mx\b|mx:|ptr|exists:|redirect=)')).Count
        $dmarc = & $txt "_dmarc.$d"
        $s1 = (Resolve-DnsName -Name "selector1._domainkey.$d" -Type CNAME -DnsOnly -ErrorAction SilentlyContinue).NameHost
        $s2 = (Resolve-DnsName -Name "selector2._domainkey.$d" -Type CNAME -DnsOnly -ErrorAction SilentlyContinue).NameHost
        $cfg = $dkimCfg[$d]
        $issues = @()
        if (-not $mx) { $issues += 'no MX' }
        if ($spfAll.Count -eq 0) { $issues += 'NO SPF' } elseif ($spfAll.Count -gt 1) { $issues += 'MULTIPLE SPF records (permerror)' }
        if ($lookups -gt 10) { $issues += "SPF ~$lookups DNS lookups (>10 = permerror)" }
        if ($spf -match '\+all') { $issues += 'SPF +all (anyone can send!)' }
        if (-not $dmarc) { $issues += 'NO DMARC' } elseif ($dmarc -match 'p=none') { $issues += 'DMARC p=none (monitor only)' }
        if ($mx -match 'mail\.protection\.outlook\.com|outlook' -or $cfg) {
            if (-not $s1 -and -not $s2) { $issues += 'M365 DKIM CNAMEs missing' }
            if ($cfg -and -not $cfg.Enabled) { $issues += 'M365 DKIM signing DISABLED' }
        }
        [pscustomobject]@{ Domain = $d; MX = $mx; SPF = $spf; SPFLookups = $lookups; DMARC = $dmarc; DKIM_Selector1 = $s1; DKIM_Selector2 = $s2; DKIM_M365Enabled = $(if ($cfg) { $cfg.Enabled } else { 'n/a' }); Issues = ($issues -join '; ') }
    }
    Write-H 'Email authentication (MX / SPF / DKIM / DMARC)'
    $rows | Format-List
    Save-Csv $rows 'EmailAuth' | Out-Null
    Write-Host '  After a DKIM key change, bounces at strict receivers (e.g. comcast.net) usually mean the new selector CNAMEs/keys are not published or signing was enabled before DNS propagated.' -ForegroundColor DarkGray
    Write-Host '  Third-party senders (scanners, marketing platforms, QuickBooks...) must be in SPF (or sign with DKIM aligned to your domain) or DMARC will quarantine them.' -ForegroundColor DarkGray
}

# ======================================================================== EXCHANGE: DIRECT SEND / CONNECTORS
'DirectSend' {
    Connect-EXO
    Write-H 'Direct Send & connectors'
    $org = Get-OrganizationConfig
    $rds = $org.PSObject.Properties['RejectDirectSend']
    Write-Host ("  RejectDirectSend: {0}" -f $(if ($rds) { $org.RejectDirectSend } else { 'not available in this tenant/module yet' }))
    Get-InboundConnector | Select-Object Name, Enabled, ConnectorType, @{n='SenderIPs';e={$_.SenderIPAddresses -join ','}}, @{n='SenderDomains';e={$_.SenderDomains -join ','}}, RestrictDomainsToIPAddresses, RequireTls, TlsSenderCertificateName | Format-Table -AutoSize -Wrap
    Get-OutboundConnector | Select-Object Name, Enabled, ConnectorType, @{n='SmartHosts';e={$_.SmartHosts -join ','}}, @{n='RecipientDomains';e={$_.RecipientDomains -join ','}} | Format-Table -AutoSize -Wrap
    Write-Host @'
  Scanners / apps that send AS your domain straight to <tenant>.mail.protection.outlook.com use "Direct Send".
  Safe order: 1) create an IP-restricted inbound connector for those devices' public IPs, 2) test scan-to-email,
  3) only then turn on RejectDirectSend (otherwise every scanner and app breaks at once).
#SDSI-ESC#'@ -ForegroundColor DarkGray
    Write-Host '  1 = Create inbound connector for scanner/app public IPs   2 = Turn RejectDirectSend ON   3 = Turn it OFF   blank = none'
    switch (Ask 'Choose' '') {
        '1' {
            $ips = Ask 'Public IP(s) of the scanners / app servers, comma separated' ''
            $name = Ask 'Connector name' 'Scanners and apps - IP restricted'
            if ($ips -and (AskYes "Create partner inbound connector '$name' for $ips")) {
                New-InboundConnector -Name $name -ConnectorType Partner -SenderDomains '*' -SenderIPAddresses ($ips -split '[,; ]+' | Where-Object { $_ }) -RestrictDomainsToIPAddresses $true -RequireTls $false -Enabled $true -Comment "Created by SDSI ToolKit $(Get-Date -Format d)" | Format-List Name, SenderIPAddresses, Enabled
            }
        }
        '2' { if ($rds -and (AskYes 'Set RejectDirectSend = TRUE (unauthenticated mail claiming your domain will be rejected)')) { Set-OrganizationConfig -RejectDirectSend $true; Write-Host '  Enabled.' -ForegroundColor Green } }
        '3' { if ($rds -and (AskYes 'Set RejectDirectSend = FALSE')) { Set-OrganizationConfig -RejectDirectSend $false; Write-Host '  Disabled.' -ForegroundColor Green } }
    }
}

# ======================================================================== EXCHANGE: MOBILE DEVICES
'MobileDevices' {
    Connect-EXO
    $u = Get-TargetUpn
    Write-H "Mobile devices for $u (ActiveSync / Outlook mobile)"
    $devs = @(Get-MobileDevice -Mailbox $u -ErrorAction SilentlyContinue)
    $rows = foreach ($d in $devs) {
        $st = Get-MobileDeviceStatistics -Identity $d.Identity -ErrorAction SilentlyContinue
        [pscustomobject]@{ Device = $d.FriendlyName; Model = $d.DeviceModel; OS = $d.DeviceOS; Type = $d.DeviceType; ClientType = $d.ClientType; Access = $d.DeviceAccessState
            FirstSync = $d.FirstSyncTime; LastSuccessSync = $st.LastSuccessSync; LastSyncAttempt = $st.LastSyncAttemptTime; WipeStatus = $st.Status; DeviceId = $d.DeviceId; Identity = $d.Identity }
    }
    $rows | Select-Object Device, Model, OS, ClientType, Access, LastSuccessSync, WipeStatus | Format-Table -AutoSize -Wrap
    if (-not $rows) { Write-Host '  No mobile devices.'; break }
    Save-Csv ($rows | Select-Object -ExcludeProperty Identity) 'MobileDevices' | Out-Null
    Write-Host '  A lost device only receives a wipe the next time it connects. LastSuccessSync shows if it is still online.' -ForegroundColor DarkGray
    Write-Host '  1 = Account-only wipe (removes company mail/data from the app, keeps personal data)   2 = Block the device   3 = FULL device wipe (factory reset!)   blank = none'
    $c = Ask 'Choose' ''
    if ($c -in '1', '2', '3') {
        $n = [int](Ask 'Device number from the list' '1'); $dev = @($rows)[$n - 1]
        switch ($c) {
            '1' { if (AskYes "ACCOUNT-ONLY wipe of $($dev.Model) for $u") { Clear-MobileDevice -Identity $dev.Identity -AccountOnly -Confirm:$false; Write-Host '  Wipe queued.' -ForegroundColor Green } }
            '2' { if (AskYes "Block device $($dev.DeviceId) for $u") { Set-CASMailbox -Identity $u -ActiveSyncBlockedDeviceIDs @{ Add = $dev.DeviceId }; Write-Host '  Blocked.' -ForegroundColor Green } }
            '3' { if (AskYes "FULL FACTORY WIPE of $($dev.Model) for $u - ALL data on the phone/tablet is erased") { Clear-MobileDevice -Identity $dev.Identity -Confirm:$false; Write-Host '  Full wipe queued.' -ForegroundColor Green } }
        }
    }
}

# ======================================================================== EXCHANGE: MAILBOX PERMISSIONS / SIZES
'MailboxPermissions' {
    Connect-EXO
    $mbs = if ($AllMailboxes) { Get-EXOMailbox -ResultSize Unlimited } else { @(Get-EXOMailbox -Identity (Get-TargetUpn)) }
    Write-H "Mailbox permissions ($(@($mbs).Count) mailbox(es))"
    $rows = foreach ($m in $mbs) {
        Get-EXOMailboxPermission -Identity $m.UserPrincipalName -ErrorAction SilentlyContinue | Where-Object { -not $_.IsInherited -and $_.User -notmatch 'NT AUTHORITY|S-1-5-' } |
            ForEach-Object { [pscustomobject]@{ Mailbox = $m.PrimarySmtpAddress; Type = 'FullAccess'; Who = $_.User; Rights = ($_.AccessRights -join ',') } }
        Get-EXORecipientPermission -Identity $m.UserPrincipalName -ErrorAction SilentlyContinue | Where-Object { $_.Trustee -notmatch 'NT AUTHORITY|S-1-5-' } |
            ForEach-Object { [pscustomobject]@{ Mailbox = $m.PrimarySmtpAddress; Type = 'SendAs'; Who = $_.Trustee; Rights = ($_.AccessRights -join ',') } }
        foreach ($sob in @($m.GrantSendOnBehalfTo)) { if ($sob) { [pscustomobject]@{ Mailbox = $m.PrimarySmtpAddress; Type = 'SendOnBehalf'; Who = $sob; Rights = 'SendOnBehalf' } } }
    }
    $rows | Format-Table -AutoSize
    if ($rows) { Save-Csv $rows 'MailboxPermissions' | Out-Null } else { Write-Host '  No delegated permissions.' -ForegroundColor Green }
}

'MailboxSizes' {
    Connect-EXO
    Write-H 'Mailbox sizes'
    $rows = Get-EXOMailbox -ResultSize Unlimited -Properties ArchiveStatus, ProhibitSendQuota, LitigationHoldEnabled, RetentionPolicy | ForEach-Object {
        $st = Get-EXOMailboxStatistics -Identity $_.UserPrincipalName -Properties LastLogonTime -ErrorAction SilentlyContinue
        $gb = if ($st.TotalItemSize) { [math]::Round(([double](($st.TotalItemSize.ToString() -replace '.*\(([\d,]+) bytes\).*', '$1') -replace ',', '')) / 1GB, 2) } else { 0 }
        [pscustomobject]@{ Mailbox = $_.PrimarySmtpAddress; Type = $_.RecipientTypeDetails; SizeGB = $gb; Items = $st.ItemCount; Quota = "$($_.ProhibitSendQuota)" -replace '\s*\(.*', ''; Archive = $_.ArchiveStatus; LitHold = $_.LitigationHoldEnabled; LastLogon = $st.LastLogonTime }
    }
    $rows | Sort-Object SizeGB -Descending | Select-Object -First 40 | Format-Table -AutoSize
    Save-Csv ($rows | Sort-Object SizeGB -Descending) 'MailboxSizes' | Out-Null
    Write-Host '  Over ~45 GB of a 50 GB quota: enable the archive (and auto-expanding archive) or clean up.' -ForegroundColor DarkGray
}

# ======================================================================== EXCHANGE: CALENDAR PERMISSIONS
'CalendarPermissions' {
    Connect-EXO
    Write-H 'Calendar permissions'
    Write-Host '  1. Grant / change a user''s access to one or more calendars (sharing invite adds it to their Outlook)'
    Write-Host '  2. View who has access to one or more calendars'
    Write-Host '  3. Remove a user''s access from one or more calendars'
    $mode = Ask 'Choose' '1'
    if ($mode -notin '1', '2', '3') { break }

    $ownersRaw = Ask 'Calendar OWNER mailbox(es) - separate several with commas, spaces or semicolons' $UserPrincipalName
    $owners = @("$ownersRaw" -split '[,;\s]+' | Where-Object { $_ } | Select-Object -Unique)
    if (-not $owners) { Write-Host '  No calendar owners entered.' -ForegroundColor Yellow; break }

    # The calendar folder name is localized (Calendrier, Kalender...), so look it up per mailbox.
    function Get-CalendarFolderId([string]$Owner) {
        $n = (Get-MailboxFolderStatistics -Identity $Owner -FolderScope Calendar -ErrorAction Stop | Where-Object { $_.FolderType -eq 'Calendar' } | Select-Object -First 1).Name
        if (-not $n) { $n = 'Calendar' }
        return "${Owner}:\$n"
    }
    function Get-CalendarRows([string[]]$Owners, [string]$OnlyUser) {
        foreach ($o in $Owners) {
            try {
                $id = Get-CalendarFolderId $o
                $perms = if ($OnlyUser) { Get-MailboxFolderPermission -Identity $id -User $OnlyUser -ErrorAction SilentlyContinue } else { Get-MailboxFolderPermission -Identity $id -ErrorAction Stop }
                foreach ($p in @($perms)) { if ($p) { [pscustomobject]@{ Owner = $o; User = "$($p.User)"; AccessRights = ($p.AccessRights -join ','); SharingFlags = ($p.SharingPermissionFlags -join ',') } } }
            } catch { [pscustomobject]@{ Owner = $o; User = ''; AccessRights = "ERROR: $($_.Exception.Message)"; SharingFlags = '' } }
        }
    }

    switch ($mode) {
        '1' {
            $delegate = Ask 'Give access TO (user UPN)' ''
            if (-not $delegate) { break }
            Write-Host '  Access level:'
            Write-Host '    1. AvailabilityOnly  - free/busy only'
            Write-Host '    2. LimitedDetails    - free/busy + subject + location'
            Write-Host '    3. Reviewer          - read everything (read-only)'
            Write-Host '    4. Editor            - read, create, change, delete'
            Write-Host '    5. Editor + Delegate - Editor, and also receives their meeting requests'
            $lvl = Ask 'Choose' '3'
            $rights = switch ($lvl) { '1' { 'AvailabilityOnly' } '2' { 'LimitedDetails' } '4' { 'Editor' } '5' { 'Editor' } default { 'Reviewer' } }
            $flags = if ($lvl -eq '5') { 'Delegate' } else { $null }
            if ($flags -and ((Ask 'Can the delegate also see PRIVATE items? Y/N' 'N') -match '^[Yy]')) { $flags = 'Delegate,CanViewPrivateItems' }
            $notify = (Ask 'Send a sharing invitation so the calendar shows up in their Outlook? Y/N' 'Y') -match '^[Yy]'
            if (-not (AskYes "Give $delegate '$rights$(if ($flags) { " + $flags" })' on $($owners.Count) calendar(s): $($owners -join ', ')")) { break }

            $rows = foreach ($o in $owners) {
                $result = ''
                try {
                    $id = Get-CalendarFolderId $o
                    $p = @{ Identity = $id; User = $delegate; AccessRights = $rights; ErrorAction = 'Stop' }
                    if ($notify) { $p.SendNotificationToUser = $true }
                    $existing = Get-MailboxFolderPermission -Identity $id -User $delegate -ErrorAction SilentlyContinue
                    if ($flags) { $p.SharingPermissionFlags = $flags }
                    elseif ($existing -and ($existing.SharingPermissionFlags -join '') -notmatch '^(None)?$') { $p.SharingPermissionFlags = 'None' }
                    if ($existing) { Set-MailboxFolderPermission @p | Out-Null; $result = "Updated (was $($existing.AccessRights -join ','))" }
                    else { Add-MailboxFolderPermission @p | Out-Null; $result = 'Added' }
                    Write-Host ("  {0,-8} {1}" -f $(if ($existing) { 'UPDATED' } else { 'ADDED' }), $o) -ForegroundColor Green
                } catch {
                    $result = "FAILED: $($_.Exception.Message)"
                    Write-Host ("  FAILED   {0} : {1}" -f $o, $_.Exception.Message) -ForegroundColor Red
                }
                [pscustomobject]@{ Owner = $o; User = $delegate; AccessRights = $rights; SharingFlags = "$flags"; InviteSent = $notify; Result = $result }
            }
            Write-H "Check: $delegate on each calendar"
            Get-CalendarRows $owners $delegate | Format-Table -AutoSize
            Save-Csv $rows "CalendarPermissions_Grant_$($delegate -replace '[^\w]','_')" | Out-Null
            if ($notify) {
                Write-Host "  $delegate gets one sharing email per calendar (usually within a few minutes, up to ~30). Accept adds it under Shared Calendars." -ForegroundColor Cyan
                Write-Host '  Not arrived? Check Junk / Other, or add it directly: Outlook > Calendar > Add Calendar > From Address Book.' -ForegroundColor DarkGray
            } else {
                Write-Host '  No invite sent - the user adds each one in Outlook: Calendar > Add Calendar > From Address Book.' -ForegroundColor Cyan
            }
        }
        '2' {
            Write-H "Calendar permissions on $($owners.Count) calendar(s)"
            $rows = @(Get-CalendarRows $owners '')
            $rows | Format-Table -AutoSize
            Write-Host '  Default = everyone in the organization; Anonymous = external / unauthenticated.' -ForegroundColor DarkGray
            if ($rows) { Save-Csv $rows 'CalendarPermissions' | Out-Null }
        }
        '3' {
            $delegate = Ask 'Remove access for (user UPN)' ''
            if (-not $delegate) { break }
            if (-not (AskYes "Remove $delegate's access from $($owners.Count) calendar(s): $($owners -join ', ')")) { break }
            $rows = foreach ($o in $owners) {
                $result = ''
                try {
                    $id = Get-CalendarFolderId $o
                    if (Get-MailboxFolderPermission -Identity $id -User $delegate -ErrorAction SilentlyContinue) {
                        Remove-MailboxFolderPermission -Identity $id -User $delegate -Confirm:$false -ErrorAction Stop
                        $result = 'Removed'; Write-Host "  REMOVED  $o" -ForegroundColor Green
                    } else { $result = 'No access to remove'; Write-Host "  NONE     $o" -ForegroundColor DarkGray }
                } catch { $result = "FAILED: $($_.Exception.Message)"; Write-Host "  FAILED   $o : $($_.Exception.Message)" -ForegroundColor Red }
                [pscustomobject]@{ Owner = $o; User = $delegate; Result = $result }
            }
            Save-Csv $rows "CalendarPermissions_Remove_$($delegate -replace '[^\w]','_')" | Out-Null
            Write-Host '  The shared calendar may stay listed in their Outlook until they remove it (right-click > Delete Calendar).' -ForegroundColor DarkGray
        }
    }
}

# ======================================================================== EXCHANGE: AUDIT LOG
'AuditSearch' {
    Connect-EXO
    $cfg = Get-AdminAuditLogConfig
    Write-Host "  Unified audit log ingestion enabled: $($cfg.UnifiedAuditLogIngestionEnabled)" -ForegroundColor $(if ($cfg.UnifiedAuditLogIngestionEnabled) { 'Green' } else { 'Red' })
    $u = Ask 'User(s) (comma separated, blank = all users)' "$UserPrincipalName"
    $ops = Ask 'Operations (comma separated, blank = all; e.g. MailItemsAccessed,Send,New-InboxRule,FileDownloaded,UserLoggedIn)' ''
    $free = Ask 'Free text to match in the record (IP address, file name...; blank = none)' ''
    $d = [int](Ask 'Days back (max 180)' ([math]::Min($Days, 180)))
    Write-H 'Searching the unified audit log'
    $q = @{ StartDate = (Get-Date).AddDays(-$d); EndDate = (Get-Date); ResultSize = 5000; SessionCommand = 'ReturnLargeSet'; SessionId = [guid]::NewGuid().ToString() }
    if ($u) { $q.UserIds = $u -split '[,; ]+' | Where-Object { $_ } }
    if ($ops) { $q.Operations = $ops -split '[,; ]+' | Where-Object { $_ } }
    if ($free) { $q.FreeText = $free }
    $all = New-Object System.Collections.Generic.List[object]
    do {
        $page = @(Search-UnifiedAuditLog @q -ErrorAction SilentlyContinue)
        $page | ForEach-Object { $all.Add($_) }
        Write-Host "  ...$($all.Count) records" -ForegroundColor DarkGray
    } while ($page.Count -eq 5000 -and $all.Count -lt 50000)
    $rows = $all | Sort-Object CreationDate | ForEach-Object {
        $a = $_.AuditData | ConvertFrom-Json
        [pscustomobject]@{ Time = $_.CreationDate.ToLocalTime(); User = $_.UserIds; Operation = $_.Operations; Workload = $a.Workload; ClientIP = $a.ClientIP; Object = $a.ObjectId; Result = $a.ResultStatus; AuditData = $_.AuditData }
    }
    $rows | Select-Object -Last 40 Time, User, Operation, ClientIP, Object | Format-Table -AutoSize -Wrap
    if ($rows) { Save-Csv $rows 'AuditLog' | Out-Null; $rows | Group-Object Operation | Sort-Object Count -Descending | Select-Object -First 15 Count, Name | Format-Table -AutoSize } else { Write-Host '  No records.' }
}

# ======================================================================== CONTAIN COMPROMISED ACCOUNT
'ContainGraph' {
    $u = Get-TargetUpn
    Connect-Graph @('User.ReadWrite.All', 'Directory.AccessAsUser.All', 'UserAuthenticationMethod.Read.All', 'AuditLog.Read.All', 'DelegatedPermissionGrant.ReadWrite.All')
    $usr = Invoke-Graph "v1.0/users/$u`?`$select=id,displayName,userPrincipalName,accountEnabled,onPremisesSyncEnabled,lastPasswordChangeDateTime" -NoPaging | Select-Object -First 1
    Write-H "Contain: $($usr.displayName) <$($usr.userPrincipalName)>"
    Write-Host ("  Enabled: {0}   Synced from on-prem AD: {1}   Last password change: {2}" -f $usr.accountEnabled, [bool]$usr.onPremisesSyncEnabled, $usr.lastPasswordChangeDateTime)
    $log = New-Object System.Collections.Generic.List[object]
    function Step([string]$n, [scriptblock]$sb) { try { & $sb; $log.Add([pscustomobject]@{ Step = $n; Result = 'Done' }); Write-Host "  [OK] $n" -ForegroundColor Green } catch { $log.Add([pscustomobject]@{ Step = $n; Result = $_.Exception.Message }); Write-Host "  [FAIL] $n : $($_.Exception.Message)" -ForegroundColor Red } }

    if ($usr.onPremisesSyncEnabled) { Write-Host '  NOTE: synced user - disable the account and reset the password in ON-PREM AD too (or the next sync re-enables it).' -ForegroundColor Yellow }
    if (AskYes 'Block sign-in') { Step 'Block sign-in' { Invoke-GraphWrite PATCH "v1.0/users/$($usr.id)" @{ accountEnabled = $false } } }
    if (AskYes 'Revoke all sessions / refresh tokens (signs the user out everywhere)') { Step 'Revoke sessions' { Invoke-GraphWrite POST "v1.0/users/$($usr.id)/revokeSignInSessions" $null } }
    if (-not $usr.onPremisesSyncEnabled) {
        if (AskYes 'Reset password to a random value (must change at next sign-in)') {
            $pw = New-RandomPassword
            Step 'Reset password' { Invoke-GraphWrite PATCH "v1.0/users/$($usr.id)" @{ passwordProfile = @{ password = $pw; forceChangePasswordNextSignIn = $true } } }
            Write-Host "  New temporary password (shown ONCE, not saved): $pw" -ForegroundColor Magenta
        }
    } elseif (Get-Module -ListAvailable ActiveDirectory) {
        if (AskYes 'Reset the ON-PREM AD password (this machine has the AD module)') {
            $pw = New-RandomPassword
            Step 'Reset AD password' { Import-Module ActiveDirectory; $sam = (Get-ADUser -Filter "UserPrincipalName -eq '$($usr.userPrincipalName)'").SamAccountName; Set-ADAccountPassword -Identity $sam -Reset -NewPassword (ConvertTo-SecureString $pw -AsPlainText -Force); Set-ADUser -Identity $sam -ChangePasswordAtLogon $true }
            Write-Host "  New temporary AD password (shown ONCE, not saved): $pw" -ForegroundColor Magenta
        }
    }
    Write-H 'MFA / authentication methods (attackers often register their own)'
    $methods = Invoke-Graph "v1.0/users/$($usr.id)/authentication/methods"
    $methods | ForEach-Object { [pscustomobject]@{ Type = ($_.'@odata.type' -replace '#microsoft.graph.', ''); Detail = "$($_.displayName)$($_.phoneNumber)$($_.emailAddress)$($_.deviceTag)"; Created = $_.createdDateTime; Id = $_.id } } | Format-Table -AutoSize -Wrap
    Write-Host '  Remove anything the user does not recognise in Entra > Users > Authentication methods (or require re-registration).' -ForegroundColor DarkGray
    Write-H 'Delegated app consents (OAuth) granted by this user'
    $grants = Invoke-Graph "v1.0/users/$($usr.id)/oauth2PermissionGrants"
    $sps = @{}
    $rows = foreach ($g in $grants) { if (-not $sps[$g.clientId]) { $sps[$g.clientId] = (Invoke-Graph "v1.0/servicePrincipals/$($g.clientId)?`$select=displayName,appOwnerOrganizationId" -NoPaging | Select-Object -First 1) }; [pscustomobject]@{ App = $sps[$g.clientId].displayName; Scopes = $g.scope; GrantId = $g.id } }
    $rows | Format-Table -AutoSize -Wrap
    foreach ($r in $rows) { if ($r.Scopes -match 'Mail\.|Files\.|offline_access|full_access' -and (AskYes "Remove consent for app '$($r.App)' ($($r.Scopes))")) { Step "Remove consent $($r.App)" { Invoke-GraphWrite DELETE "v1.0/oauth2PermissionGrants/$($r.GrantId)" $null } } }
    Write-H 'Last 10 sign-ins'
    try { Invoke-Graph "v1.0/auditLogs/signIns?`$filter=userId eq '$($usr.id)'&`$top=10" -NoPaging | Select-Object @{n='Time';e={$_.createdDateTime}}, appDisplayName, ipAddress, @{n='Location';e={"$($_.location.city), $($_.location.countryOrRegion)"}}, @{n='Status';e={$_.status.errorCode}}, clientAppUsed | Format-Table -AutoSize } catch { Write-Host '  Sign-in logs need Entra ID P1.' -ForegroundColor DarkGray }
    Save-Csv $log "Contain_Graph_$($u -replace '[^\w]','_')" | Out-Null
    Write-Host '  Next: run "Contain - Exchange side" to remove forwarding / malicious rules / send restriction.' -ForegroundColor Cyan
}

'ContainExchange' {
    $u = Get-TargetUpn
    Connect-EXO
    Write-H "Contain (Exchange): $u"
    $log = New-Object System.Collections.Generic.List[object]
    function Step([string]$n, [scriptblock]$sb) { try { & $sb; $log.Add([pscustomobject]@{ Step = $n; Result = 'Done' }); Write-Host "  [OK] $n" -ForegroundColor Green } catch { $log.Add([pscustomobject]@{ Step = $n; Result = $_.Exception.Message }); Write-Host "  [FAIL] $n : $($_.Exception.Message)" -ForegroundColor Red } }
    $mb = Get-Mailbox -Identity $u
    if ($mb.ForwardingSmtpAddress -or $mb.ForwardingAddress) {
        Write-Host "  Mailbox forwarding: $($mb.ForwardingSmtpAddress) $($mb.ForwardingAddress) (keep copy: $($mb.DeliverToMailboxAndForward))" -ForegroundColor Yellow
        if (AskYes 'Remove mailbox forwarding') { Step 'Remove forwarding' { Set-Mailbox -Identity $u -ForwardingSmtpAddress $null -ForwardingAddress $null -DeliverToMailboxAndForward $false } }
    } else { Write-Host '  No mailbox-level forwarding.' -ForegroundColor Green }
    $rules = @(Get-InboxRule -Mailbox $u -IncludeHidden -ErrorAction SilentlyContinue)
    foreach ($r in $rules) {
        $why = & $SuspiciousRule $r
        Write-Host ("  Rule '{0}' enabled={1} {2}" -f $r.Name, $r.Enabled, $(if ($why) { "<-- $why" })) -ForegroundColor $(if ($why) { 'Yellow' } else { 'White' })
        if ($why -and $r.Enabled -and (AskYes "Disable rule '$($r.Name)'")) { Step "Disable rule $($r.Name)" { Disable-InboxRule -Identity $r.Identity -Confirm:$false } }
    }
    $blocked = Get-BlockedSenderAddress -SenderAddress $u -ErrorAction SilentlyContinue
    if ($blocked) {
        Write-Host '  Microsoft has RESTRICTED this user from sending (outbound spam detected).' -ForegroundColor Yellow
        if (AskYes 'Remove the send restriction (ONLY after password reset + sessions revoked)') { Step 'Unblock sending' { Remove-BlockedSenderAddress -SenderAddress $u } }
    } else { Write-Host '  User is not on the restricted-senders list.' -ForegroundColor Green }
    $perm = Get-EXOMailboxPermission -Identity $u | Where-Object { -not $_.IsInherited -and $_.User -notmatch 'NT AUTHORITY|S-1-5-' }
    if ($perm) { Write-Host '  Delegates with Full Access (verify each is expected):' -ForegroundColor Yellow; $perm | Format-Table User, AccessRights -AutoSize }
    Write-Host '  Recent sent items count (24h) for scale of any spam blast:' -ForegroundColor DarkGray
    try { $sent = @(Get-MessageTraceV2 -SenderAddress $u -StartDate (Get-Date).AddDays(-1) -EndDate (Get-Date) -ResultSize 5000 -ErrorAction Stop); Write-Host "  $($sent.Count) messages sent in the last 24 hours." } catch { }
    Save-Csv $log "Contain_EXO_$($u -replace '[^\w]','_')" | Out-Null
}

# ======================================================================== GRAPH: LICENSES
'LicenseReport' {
    Connect-Graph @('User.Read.All', 'Organization.Read.All', 'AuditLog.Read.All')
    $names = Get-LicenseNameMap
    Write-H 'Tenant subscriptions'
    $skus = Invoke-Graph 'v1.0/subscribedSkus'
    $skuRows = $skus | ForEach-Object { [pscustomobject]@{ License = $(if ($names[$_.skuId]) { $names[$_.skuId] } else { $_.skuPartNumber }); SkuPartNumber = $_.skuPartNumber; Purchased = $_.prepaidUnits.enabled; Assigned = $_.consumedUnits; Available = ($_.prepaidUnits.enabled - $_.consumedUnits); Status = $_.capabilityStatus } }
    $skuRows | Sort-Object License | Format-Table -AutoSize
    Write-H 'Users and licenses'
    $sel = 'id,displayName,userPrincipalName,accountEnabled,createdDateTime,assignedLicenses,userType,onPremisesSyncEnabled'
    try { $users = Invoke-Graph "v1.0/users?`$select=$sel,signInActivity&`$top=999"; $hasSignIn = $true }
    catch { $users = Invoke-Graph "v1.0/users?`$select=$sel&`$top=999"; $hasSignIn = $false; Write-Host '  (Last sign-in needs Entra ID P1 - column left blank)' -ForegroundColor DarkGray }
    $rows = $users | Where-Object { $_.userType -ne 'Guest' } | ForEach-Object {
        $lic = @($_.assignedLicenses | ForEach-Object { if ($names[$_.skuId]) { $names[$_.skuId] } else { ($skus | Where-Object skuId -eq $_.skuId).skuPartNumber } })
        [pscustomobject]@{ DisplayName = $_.displayName; UPN = $_.userPrincipalName; Enabled = $_.accountEnabled; Synced = [bool]$_.onPremisesSyncEnabled
            Licenses = $(if ($lic) { $lic -join ', ' } else { 'Unlicensed' }); LastSignIn = $(if ($hasSignIn) { $_.signInActivity.lastSignInDateTime }); Created = $_.createdDateTime }
    }
    $rows | Sort-Object Licenses | Format-Table DisplayName, UPN, Enabled, Licenses, LastSignIn -AutoSize -Wrap
    $waste = @($rows | Where-Object { -not $_.Enabled -and $_.Licenses -ne 'Unlicensed' })
    if ($waste) { Write-Host "  $($waste.Count) DISABLED users still hold licenses (money being wasted):" -ForegroundColor Yellow; $waste | Format-Table DisplayName, Licenses -AutoSize }
    Save-Csv $skuRows 'LicenseSubscriptions' | Out-Null
    Save-Csv $rows 'LicenseUsers' | Out-Null
}

'LicenseAssign' {
    Connect-Graph @('User.ReadWrite.All', 'Group.ReadWrite.All', 'Organization.Read.All', 'Directory.ReadWrite.All')
    $names = Get-LicenseNameMap
    $skus = @(Invoke-Graph 'v1.0/subscribedSkus')
    for ($i = 0; $i -lt $skus.Count; $i++) { $s = $skus[$i]; Write-Host ("  {0,2}. {1,-55} available {2}" -f ($i + 1), $(if ($names[$s.skuId]) { $names[$s.skuId] } else { $s.skuPartNumber }), ($s.prepaidUnits.enabled - $s.consumedUnits)) }
    $sku = $skus[[int](Ask 'License number' '1') - 1]
    $mode = Ask 'A = assign to user(s)   G = assign to a GROUP (group-based licensing, best for synced users)   R = REMOVE direct assignment from a group''s members' 'A'
    switch ($mode.ToUpper()) {
        'G' {
            $gName = Ask 'Group display name' ''
            $g = Invoke-Graph "v1.0/groups?`$filter=displayName eq '$($gName -replace "'", "''")'" -NoPaging | Select-Object -First 1
            if (-not $g) { throw "Group '$gName' not found." }
            if (AskYes "Assign $($sku.skuPartNumber) to group '$($g.displayName)' - every member gets it automatically") { Invoke-GraphWrite POST "v1.0/groups/$($g.id)/assignLicense" @{ addLicenses = @(@{ skuId = $sku.skuId; disabledPlans = @() }); removeLicenses = @() }; Write-Host '  Done. Members are licensed within a few minutes (users need a Usage Location).' -ForegroundColor Green }
        }
        'R' {
            $gName = Ask 'Group display name (users whose DIRECT assignment should be removed)' ''
            $g = Invoke-Graph "v1.0/groups?`$filter=displayName eq '$($gName -replace "'", "''")'" -NoPaging | Select-Object -First 1
            $members = Invoke-Graph "v1.0/groups/$($g.id)/members/microsoft.graph.user?`$select=id,userPrincipalName,licenseAssignmentStates"
            foreach ($m in $members) {
                $st = $m.licenseAssignmentStates | Where-Object { $_.skuId -eq $sku.skuId }
                if (-not $st) { continue }
                if ($st | Where-Object { -not $_.assignedByGroup }) {
                    if (AskYes "Remove DIRECT $($sku.skuPartNumber) from $($m.userPrincipalName)") { Invoke-GraphWrite POST "v1.0/users/$($m.id)/assignLicense" @{ addLicenses = @(); removeLicenses = @($sku.skuId) }; Write-Host '  Removed.' -ForegroundColor Green }
                } else { Write-Host "  $($m.userPrincipalName): assigned by a group - remove them from that group instead." -ForegroundColor DarkYellow }
            }
        }
        default {
            $list = Ask 'UPN(s) comma separated, or path to a CSV with a UserPrincipalName column' "$UserPrincipalName"
            $upns = if ($list -and (Test-Path $list)) { (Import-Csv $list).UserPrincipalName } else { $list -split '[,; ]+' | Where-Object { $_ } }
            $loc = Ask 'Usage location for users missing one (2-letter country code)' 'US'
            if (AskYes "Assign $($sku.skuPartNumber) to $(@($upns).Count) user(s)") {
                foreach ($up in $upns) {
                    try {
                        $usr = Invoke-Graph "v1.0/users/$up`?`$select=id,usageLocation" -NoPaging | Select-Object -First 1
                        if (-not $usr.usageLocation) { Invoke-GraphWrite PATCH "v1.0/users/$($usr.id)" @{ usageLocation = $loc } }
                        Invoke-GraphWrite POST "v1.0/users/$($usr.id)/assignLicense" @{ addLicenses = @(@{ skuId = $sku.skuId; disabledPlans = @() }); removeLicenses = @() } | Out-Null
                        Write-Host "  $up : licensed" -ForegroundColor Green
                    } catch { Write-Host "  $up : $($_.Exception.Message)" -ForegroundColor Red }
                }
            }
        }
    }
}

# ======================================================================== GRAPH: NEW USER
'NewUser' {
    Connect-Graph @('User.ReadWrite.All', 'Domain.Read.All', 'Organization.Read.All', 'Group.ReadWrite.All')
    $first = Ask 'First name' ''; $last = Ask 'Last name' ''
    if (-not $first -or -not $last) { throw 'First and last name are required.' }
    $doms = @(Invoke-Graph 'v1.0/domains' | Where-Object isVerified)
    for ($i = 0; $i -lt $doms.Count; $i++) { Write-Host ("  {0}. {1}{2}" -f ($i + 1), $doms[$i].id, $(if ($doms[$i].isDefault) { ' (default)' })) }
    $dom = $doms[[int](Ask 'Domain number' ([array]::IndexOf(@($doms.isDefault), $true) + 1)) - 1].id
    $defAlias = (("{0}.{1}" -f $first, $last).ToLower()) -replace '[^a-z0-9\.\-_]', ''
    $alias = Ask 'Username (before the @)' $defAlias
    $display = Ask 'Display name' "$first $last"
    $title = Ask 'Job title (optional)' ''; $dept = Ask 'Department (optional)' ''
    $loc = Ask 'Usage location' 'US'
    $pw = New-RandomPassword
    $upn = "$alias@$dom"
    if (-not (AskYes "Create $display <$upn>")) { break }
    $body = @{ accountEnabled = $true; displayName = $display; givenName = $first; surname = $last; mailNickname = ($alias -replace '[^A-Za-z0-9]', ''); userPrincipalName = $upn; usageLocation = $loc; passwordProfile = @{ password = $pw; forceChangePasswordNextSignIn = $true } }
    if ($title) { $body.jobTitle = $title }; if ($dept) { $body.department = $dept }
    $new = Invoke-GraphWrite POST 'v1.0/users' $body
    Write-Host "  Created $upn" -ForegroundColor Green
    Write-Host "  Temporary password (shown ONCE, not saved): $pw" -ForegroundColor Magenta
    $names = Get-LicenseNameMap
    $skus = @(Invoke-Graph 'v1.0/subscribedSkus' | Where-Object { ($_.prepaidUnits.enabled - $_.consumedUnits) -gt 0 })
    if ($skus) {
        for ($i = 0; $i -lt $skus.Count; $i++) { Write-Host ("  {0}. {1} (available {2})" -f ($i + 1), $(if ($names[$skus[$i].skuId]) { $names[$skus[$i].skuId] } else { $skus[$i].skuPartNumber }), ($skus[$i].prepaidUnits.enabled - $skus[$i].consumedUnits)) }
        $p = Ask 'License to assign (number, blank = none)' ''
        if ($p) { Invoke-GraphWrite POST "v1.0/users/$($new.id)/assignLicense" @{ addLicenses = @(@{ skuId = $skus[[int]$p - 1].skuId; disabledPlans = @() }); removeLicenses = @() } | Out-Null; Write-Host '  Licensed.' -ForegroundColor Green }
    }
    $grp = Ask 'Add to groups (display names, comma separated, blank = none)' ''
    foreach ($gn in ($grp -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })) {
        try { $g = Invoke-Graph "v1.0/groups?`$filter=displayName eq '$($gn -replace "'", "''")'" -NoPaging | Select-Object -First 1; Invoke-GraphWrite POST "v1.0/groups/$($g.id)/members/`$ref" @{ '@odata.id' = "https://graph.microsoft.com/v1.0/directoryObjects/$($new.id)" }; Write-Host "  Added to $gn" -ForegroundColor Green } catch { Write-Host "  $gn : $($_.Exception.Message)" -ForegroundColor Red }
    }
}

# ======================================================================== GRAPH: IDENTITY REPORTS
'MfaReport' {
    Connect-Graph @('AuditLog.Read.All', 'UserAuthenticationMethod.Read.All', 'User.Read.All')
    Write-H 'MFA registration'
    try {
        $rows = Invoke-Graph 'v1.0/reports/authenticationMethods/userRegistrationDetails' | ForEach-Object {
            [pscustomobject]@{ UPN = $_.userPrincipalName; Name = $_.userDisplayName; Admin = $_.isAdmin; MfaRegistered = $_.isMfaRegistered; MfaCapable = $_.isMfaCapable; Passwordless = $_.isPasswordlessCapable; Methods = ($_.methodsRegistered -join ', '); Default = $_.userPreferredMethodForSecondaryAuthentication }
        }
    } catch {
        Write-Host '  Registration report needs Entra ID P1 - falling back to per-user method lookup (slower).' -ForegroundColor DarkGray
        $rows = Invoke-Graph "v1.0/users?`$select=id,userPrincipalName,displayName,accountEnabled,userType&`$top=999" | Where-Object { $_.accountEnabled -and $_.userType -eq 'Member' } | ForEach-Object {
            $m = @(Invoke-Graph "v1.0/users/$($_.id)/authentication/methods" | ForEach-Object { $_.'@odata.type' -replace '#microsoft.graph.|AuthenticationMethod', '' } | Where-Object { $_ -ne 'password' })
            [pscustomobject]@{ UPN = $_.userPrincipalName; Name = $_.displayName; Admin = $null; MfaRegistered = ($m.Count -gt 0); MfaCapable = ($m.Count -gt 0); Passwordless = $null; Methods = ($m -join ', '); Default = $null }
        }
    }
    $no = @($rows | Where-Object { -not $_.MfaRegistered })
    $rows | Sort-Object MfaRegistered, UPN | Format-Table UPN, Admin, MfaRegistered, Methods -AutoSize -Wrap
    Write-Host "  $($no.Count) of $(@($rows).Count) users have NO MFA method registered." -ForegroundColor $(if ($no) { 'Yellow' } else { 'Green' })
    $adm = @($no | Where-Object Admin); if ($adm) { Write-Host "  ADMINS WITHOUT MFA: $($adm.UPN -join ', ')" -ForegroundColor Red }
    Save-Csv $rows 'MfaRegistration' | Out-Null
}

'StaleAccounts' {
    Connect-Graph @('User.Read.All', 'AuditLog.Read.All')
    $d = [int](Ask 'Flag accounts with no sign-in for (days)' ([math]::Max($Days, 90)))
    Write-H "Accounts inactive for $d+ days, guests, and disabled-but-licensed"
    try { $users = Invoke-Graph "v1.0/users?`$select=displayName,userPrincipalName,accountEnabled,userType,createdDateTime,assignedLicenses,signInActivity&`$top=999" }
    catch { throw 'Sign-in activity needs Entra ID P1 (and AuditLog.Read.All).' }
    $cut = (Get-Date).AddDays(-$d)
    $rows = $users | ForEach-Object {
        $last = $_.signInActivity.lastSignInDateTime; $lastNI = $_.signInActivity.lastNonInteractiveSignInDateTime
        $newest = @($last, $lastNI) | Where-Object { $_ } | ForEach-Object { [datetime]$_ } | Sort-Object -Descending | Select-Object -First 1
        [pscustomobject]@{ Name = $_.displayName; UPN = $_.userPrincipalName; Type = $_.userType; Enabled = $_.accountEnabled; Licensed = (@($_.assignedLicenses).Count -gt 0); LastSignIn = $newest; Created = $_.createdDateTime
            Flag = $(if (-not $newest -and [datetime]$_.createdDateTime -lt $cut) { 'Never signed in' } elseif ($newest -and $newest -lt $cut) { "Inactive $([int]((Get-Date) - $newest).TotalDays)d" } elseif (-not $_.accountEnabled -and @($_.assignedLicenses).Count) { 'Disabled but licensed' }) }
    }
    $flag = $rows | Where-Object Flag
    $flag | Sort-Object Type, LastSignIn | Format-Table Name, UPN, Type, Enabled, Licensed, LastSignIn, Flag -AutoSize -Wrap
    Write-Host "  $(@($flag).Count) accounts flagged ($(@($flag | Where-Object Type -eq 'Guest').Count) guests)." -ForegroundColor Yellow
    Save-Csv $rows 'AccountActivity' | Out-Null
}

'SignIns' {
    $u = Get-TargetUpn
    Connect-Graph @('AuditLog.Read.All', 'Directory.Read.All')
    Write-H "Sign-ins for $u (last $Days days)"
    $since = (Get-Date).AddDays(-[math]::Min($Days, 30)).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    try { $s = Invoke-Graph "v1.0/auditLogs/signIns?`$filter=userPrincipalName eq '$u' and createdDateTime ge $since&`$top=500" }
    catch { throw 'Sign-in logs need Entra ID P1.' }
    $rows = $s | ForEach-Object { [pscustomobject]@{ Time = ([datetime]$_.createdDateTime).ToLocalTime(); App = $_.appDisplayName; IP = $_.ipAddress; Location = "$($_.location.city), $($_.location.state), $($_.location.countryOrRegion)"; Result = $(if ($_.status.errorCode -eq 0) { 'Success' } else { "Fail $($_.status.errorCode): $($_.status.failureReason)" }); ClientApp = $_.clientAppUsed; Device = "$($_.deviceDetail.operatingSystem) $($_.deviceDetail.browser)"; CA = $_.conditionalAccessStatus; Risk = $_.riskLevelDuringSignIn } }
    $rows | Select-Object -First 40 Time, App, IP, Location, Result, ClientApp | Format-Table -AutoSize -Wrap
    Write-Host '  Countries / IPs seen:' -ForegroundColor Yellow
    $rows | Group-Object { ($_.Location -split ', ')[-1] } | Sort-Object Count -Descending | Select-Object Count, Name | Format-Table -AutoSize
    $legacy = @($rows | Where-Object { $_.ClientApp -match 'IMAP|POP|SMTP|Exchange ActiveSync|Other clients|Authenticated SMTP|MAPI' })
    if ($legacy) { Write-Host "  $($legacy.Count) legacy-protocol sign-ins (IMAP/POP/SMTP...) - common in password-spray attacks." -ForegroundColor Yellow }
    Save-Csv $rows "SignIns_$($u -replace '[^\w]','_')" | Out-Null
}

'AdminRoles' {
    Connect-Graph @('RoleManagement.Read.Directory', 'User.Read.All', 'AuditLog.Read.All')
    Write-H 'Admin role members'
    $roles = Invoke-Graph "v1.0/directoryRoles?`$expand=members"
    $rows = foreach ($r in $roles) { foreach ($m in $r.members) { [pscustomobject]@{ Role = $r.displayName; Member = "$($m.displayName)"; UPN = "$($m.userPrincipalName)"; Type = ($m.'@odata.type' -replace '#microsoft.graph.', '') } } }
    $rows | Sort-Object Role | Format-Table -AutoSize
    $ga = @($rows | Where-Object Role -eq 'Global Administrator')
    Write-Host "  Global Administrators: $($ga.Count) (Microsoft recommends 2-4, cloud-only, with phishing-resistant MFA)" -ForegroundColor $(if ($ga.Count -gt 4 -or $ga.Count -lt 2) { 'Yellow' } else { 'Green' })
    Save-Csv $rows 'AdminRoles' | Out-Null
}

# ======================================================================== GRAPH: APPS & CONSENT
'AppConsent' {
    Connect-Graph @('Policy.Read.All', 'Application.Read.All', 'Directory.Read.All', 'DelegatedPermissionGrant.Read.All', 'ConsentRequest.Read.All')
    Write-H 'User consent settings'
    $ap = Invoke-Graph 'v1.0/policies/authorizationPolicy' -NoPaging | Select-Object -First 1
    $pol = @($ap.defaultUserRolePermissions.permissionGrantPoliciesAssigned)
    Write-Host ("  Users can consent to apps: {0}" -f $(if (-not $pol) { 'NO (admin consent required)' } elseif ($pol -match 'legacy') { 'YES - any app (risky)' } else { "limited ($($pol -join ', '))" }))
    Write-Host ("  Users can register apps: {0}" -f $ap.defaultUserRolePermissions.allowedToCreateApps)
    $acr = Invoke-Graph 'v1.0/policies/adminConsentRequestPolicy' -NoPaging | Select-Object -First 1
    Write-Host ("  Admin consent request workflow enabled: {0}" -f $acr.isEnabled)
    try {
        $req = Invoke-Graph "v1.0/identityGovernance/appConsent/appConsentRequests?`$filter=userConsentRequests/any(u:u/status eq 'InProgress')"
        if ($req) { Write-Host '  Pending admin consent requests:' -ForegroundColor Yellow; $req | Select-Object appDisplayName, appId | Format-Table -AutoSize }
    } catch { }
    Write-H 'Admin-consented (tenant-wide) delegated permissions'
    $grants = Invoke-Graph 'v1.0/oauth2PermissionGrants'
    $spCache = @{}
    $risky = 'Mail\.(Read|ReadWrite|Send)|MailboxSettings\.ReadWrite|Files\.ReadWrite\.All|Sites\.(ReadWrite|FullControl)\.All|Directory\.ReadWrite\.All|User\.ReadWrite\.All|full_access_as_user|EWS\.AccessAsUser\.All|Contacts\.ReadWrite'
    $rows = foreach ($g in $grants) {
        if (-not $spCache[$g.clientId]) { $spCache[$g.clientId] = Invoke-Graph "v1.0/servicePrincipals/$($g.clientId)?`$select=displayName,appId,appOwnerOrganizationId,publisherName,verifiedPublisher" -NoPaging | Select-Object -First 1 }
        $sp = $spCache[$g.clientId]
        [pscustomobject]@{ App = $sp.displayName; Publisher = "$($sp.verifiedPublisher.displayName)$($sp.publisherName)"; AppId = $sp.appId; ConsentType = $(if ($g.consentType -eq 'AllPrincipals') { 'Admin (all users)' } else { 'User' }); Scopes = $g.scope.Trim(); HighRisk = [bool]($g.scope -match $risky) }
    }
    $rows | Sort-Object HighRisk -Descending | Format-Table App, Publisher, ConsentType, HighRisk, Scopes -AutoSize -Wrap
    Save-Csv $rows 'AppConsents' | Out-Null
    $app = Ask 'Build an admin-consent link for an app? Enter its name or AppId (blank = skip)' ''
    if ($app) {
        $sp = if ($app -match '^[0-9a-f-]{36}$') { Invoke-Graph "v1.0/servicePrincipals?`$filter=appId eq '$app'" -NoPaging | Select-Object -First 1 } else { Invoke-Graph "v1.0/servicePrincipals?`$filter=startswith(displayName,'$($app -replace "'", "''")')" -NoPaging | Select-Object -First 1 }
        $appId = if ($sp) { $sp.appId } elseif ($app -match '^[0-9a-f-]{36}$') { $app } else { $null }
        $tid = (Get-MgContext).TenantId
        if ($appId) {
            Write-Host "  Tenant-wide admin consent URL (open as a Global Admin / Cloud App Admin OF THIS TENANT):" -ForegroundColor Cyan
            Write-Host "  https://login.microsoftonline.com/$tid/adminconsent?client_id=$appId" -ForegroundColor Green
            Write-Host '  If consent "doesn''t stick": sign in with an account homed in this tenant (not a guest/partner), and check the' -ForegroundColor DarkGray
            Write-Host '  app''s Enterprise App > Properties: "Enabled for users to sign in" = Yes, "Assignment required" as intended.' -ForegroundColor DarkGray
        } else { Write-Host '  App not found in this tenant yet - get its Application (client) ID from the vendor.' -ForegroundColor Yellow }
    }
}

'AppSecrets' {
    Connect-Graph @('Application.Read.All')
    $d = [int](Ask 'Show secrets/certificates expiring within (days)' ([math]::Max($Days, 60)))
    Write-H "App registration secrets & certificates expiring within $d days (or already expired)"
    $apps = Invoke-Graph "v1.0/applications?`$select=displayName,appId,passwordCredentials,keyCredentials&`$top=999"
    $cut = (Get-Date).AddDays($d)
    $rows = foreach ($a in $apps) {
        foreach ($c in @($a.passwordCredentials)) { if ($c) { [pscustomobject]@{ App = $a.displayName; AppId = $a.appId; Kind = 'Client secret'; Name = $c.displayName; Expires = ([datetime]$c.endDateTime).ToLocalTime() } } }
        foreach ($c in @($a.keyCredentials)) { if ($c) { [pscustomobject]@{ App = $a.displayName; AppId = $a.appId; Kind = 'Certificate'; Name = $c.displayName; Expires = ([datetime]$c.endDateTime).ToLocalTime() } } }
    }
    $soon = $rows | Where-Object { $_.Expires -lt $cut } | Sort-Object Expires
    $soon | Select-Object App, Kind, Name, Expires, @{n='DaysLeft';e={[int]($_.Expires - (Get-Date)).TotalDays}} | Format-Table -AutoSize
    Write-Host "  $(@($soon).Count) expiring/expired of $(@($rows).Count) total credentials. Rotate before expiry (e.g. room-scheduling panels, scanners, backup apps stop working the day it expires)." -ForegroundColor $(if ($soon) { 'Yellow' } else { 'Green' })
    Save-Csv ($rows | Sort-Object Expires) 'AppCredentials' | Out-Null
}

# ======================================================================== GRAPH: INTUNE
'IntuneDevices' {
    Connect-Graph @('DeviceManagementManagedDevices.Read.All', 'BitlockerKey.ReadBasic.All', 'Device.Read.All')
    Write-H 'Intune managed devices'
    $devs = Invoke-Graph "v1.0/deviceManagement/managedDevices?`$select=deviceName,operatingSystem,osVersion,complianceState,lastSyncDateTime,userPrincipalName,azureADDeviceId,managementAgent,model,manufacturer,serialNumber,isEncrypted,enrolledDateTime"
    $keys = @{}
    try { Invoke-Graph 'v1.0/informationProtection/bitlocker/recoveryKeys' -Headers @{ 'ocp-client-name' = 'SDSI-ToolKit'; 'ocp-client-version' = '2.0' } | ForEach-Object { $keys[$_.deviceId] = $true } } catch { Write-Host "  BitLocker key lookup failed: $($_.Exception.Message)" -ForegroundColor DarkYellow }
    $rows = $devs | ForEach-Object {
        [pscustomobject]@{ Device = $_.deviceName; User = $_.userPrincipalName; OS = "$($_.operatingSystem) $($_.osVersion)"; Model = "$($_.manufacturer) $($_.model)"; Serial = $_.serialNumber; Compliance = $_.complianceState; Encrypted = $_.isEncrypted
            BitLockerKeyInEntra = $(if ($_.operatingSystem -eq 'Windows') { [bool]$keys[$_.azureADDeviceId] } else { 'n/a' }); LastSync = $(if ($_.lastSyncDateTime) { ([datetime]$_.lastSyncDateTime).ToLocalTime() }); StaleDays = $(if ($_.lastSyncDateTime) { [int]((Get-Date) - [datetime]$_.lastSyncDateTime).TotalDays }) }
    }
    $rows | Sort-Object StaleDays -Descending | Format-Table Device, User, OS, Compliance, BitLockerKeyInEntra, LastSync, StaleDays -AutoSize -Wrap
    $noKey = @($rows | Where-Object { $_.BitLockerKeyInEntra -eq $false })
    $stale = @($rows | Where-Object { $_.StaleDays -gt 30 })
    $nonc = @($rows | Where-Object { $_.Compliance -eq 'noncompliant' })
    Write-Host ("  {0} devices | {1} Windows devices WITHOUT a BitLocker key in Entra | {2} not synced in 30+ days | {3} non-compliant" -f @($rows).Count, $noKey.Count, $stale.Count, $nonc.Count) -ForegroundColor Yellow
    Write-Host '  Missing keys: on the device run the ToolKit option "Back up BitLocker key to Entra ID", or push it via an Intune script.' -ForegroundColor DarkGray
    Save-Csv $rows 'IntuneDevices' | Out-Null
}

# ======================================================================== ONEDRIVE / SHAREPOINT
'OneDrivePermissions' {
    $u = Get-TargetUpn
    Connect-Graph @('Files.Read.All', 'Sites.Read.All', 'User.Read.All')
    $path = Ask 'Folder or file path inside their OneDrive (e.g. Documents/Finance, blank = root)' ''
    $item = if ($path) { Invoke-Graph "v1.0/users/$u/drive/root:/$($path.Trim('/'))" -NoPaging | Select-Object -First 1 } else { Invoke-Graph "v1.0/users/$u/drive/root" -NoPaging | Select-Object -First 1 }
    Write-H "Sharing on $u : /$path"
    $perm = Invoke-Graph "v1.0/drives/$($item.parentReference.driveId)/items/$($item.id)/permissions"
    if (-not $item.parentReference.driveId) { $drive = Invoke-Graph "v1.0/users/$u/drive" -NoPaging | Select-Object -First 1; $perm = Invoke-Graph "v1.0/drives/$($drive.id)/items/$($item.id)/permissions" }
    $rows = $perm | ForEach-Object { [pscustomobject]@{ Roles = ($_.roles -join ','); GrantedTo = "$($_.grantedToV2.user.displayName)$($_.grantedToV2.siteUser.displayName)$($_.grantedToV2.group.displayName)"; Email = "$($_.grantedToV2.user.email)$($_.invitation.email)"; LinkScope = $_.link.scope; LinkType = $_.link.type; Expires = $_.expirationDateTime; Inherited = [bool]$_.inheritedFrom } }
    $rows | Format-Table -AutoSize -Wrap
    $anon = @($rows | Where-Object LinkScope -eq 'anonymous'); if ($anon) { Write-Host "  $($anon.Count) 'Anyone with the link' sharing link(s)!" -ForegroundColor Yellow }
    Save-Csv $rows "OneDrivePermissions_$($u -replace '[^\w]','_')" | Out-Null
}

'RetentionExclude' {
    Connect-IPPS
    Write-H 'Retention policies'
    $pols = @(Get-RetentionCompliancePolicy)
    for ($i = 0; $i -lt $pols.Count; $i++) { Write-Host ("  {0}. {1}  (SharePoint: {2})" -f ($i + 1), $pols[$i].Name, (($pols[$i].SharePointLocation | ForEach-Object { $_.Name }) -join ', ')) }
    if (-not $pols) { Write-Host '  No retention policies.'; break }
    $p = $pols[[int](Ask 'Policy number' '1') - 1]
    $site = Ask 'SharePoint site URL to EXCLUDE from this policy' ''
    if ($site -and (AskYes "Exclude $site from retention policy '$($p.Name)'")) { Set-RetentionCompliancePolicy -Identity $p.Name -AddSharePointLocationException $site; Write-Host '  Done (can take up to 24h to apply).' -ForegroundColor Green }
}

default { Write-Host "Unknown action '$Action'." -ForegroundColor Red; exit 2 }
}
#endregion

try { if (Get-Command Disconnect-ExchangeOnline -ErrorAction SilentlyContinue) { Disconnect-ExchangeOnline -Confirm:$false -ErrorAction SilentlyContinue | Out-Null } } catch { }
try { if (Get-Command Disconnect-MgGraph -ErrorAction SilentlyContinue) { Disconnect-MgGraph -ErrorAction SilentlyContinue | Out-Null } } catch { }
Write-Host "`nReports: $OutputPath" -ForegroundColor DarkGray
'@

# ======================= New-RemediationPlan.ps1 =======================
$Script:Payloads['New-RemediationPlan'] = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    M365 Remediation Plan Generator - turns a prior posture audit into a fix-it report.

.DESCRIPTION
    Reads the JSON export produced by Invoke-M365PostureAudit.ps1 and generates two
    documents covering every "Not Compliant" check from that audit:

      1. A technical HTML report with exact PowerShell/Graph remediation commands
         (or manual portal steps where no single cmdlet exists), grouped by category
         and sorted by user impact.
      2. A client-facing HTML summary in plain language: what's wrong, why it matters,
         what staff will notice, with no PowerShell syntax -- suitable to hand to a
         non-technical stakeholder as a project plan.

    THIS SCRIPT DOES NOT CHANGE ANYTHING. It only reads the audit JSON and writes two
    new HTML files. No connection to the tenant is made; you do not need to be signed
    in to anything to run this script.

.PARAMETER AuditJsonPath
    Path to the JSON file produced by Invoke-M365PostureAudit.ps1
    (e.g. M365_Posture_Audit_ClientName_2026-06-18_104827.json)

.PARAMETER OutputPath
    Folder to save the two remediation reports to. Defaults to the current directory.

.EXAMPLE
    .\New-RemediationPlan.ps1 -AuditJsonPath ".\M365_Posture_Audit_Sigma_Data_Systems_Inc_2026-06-18_104827.json"
#>

[CmdletBinding()]
param(
    [Parameter(Mandatory)]
    [string]$AuditJsonPath,

    [string]$OutputPath = (Get-Location).Path
)

$ErrorActionPreference = 'Stop'
$ScriptRoot = $PSScriptRoot
if (-not $ScriptRoot) { $ScriptRoot = Split-Path -Parent $MyInvocation.MyCommand.Path }

# ----------------------------------------------------------------------------
# 1. Load the audit results
# ----------------------------------------------------------------------------
if (-not (Test-Path $AuditJsonPath)) {
    Write-Host "Cannot find audit JSON file at: $AuditJsonPath" -ForegroundColor Red
    exit 1
}

Write-Host "`n=== M365 Remediation Plan Generator ===" -ForegroundColor Cyan
Write-Host "Loading audit results from: $AuditJsonPath" -ForegroundColor Gray

$auditData = Get-Content $AuditJsonPath -Raw | ConvertFrom-Json

$tenantName = $auditData.tenantName
$auditDate = $auditData.auditDate
$postureScore = $auditData.postureScore
$allResults = $auditData.results

$notCompliant = $allResults | Where-Object { $_.Status -eq 'Not Compliant' }

Write-Host "Tenant: $tenantName" -ForegroundColor Gray
Write-Host "Audit date: $auditDate" -ForegroundColor Gray
Write-Host "Posture score at time of audit: $postureScore%" -ForegroundColor Gray
Write-Host "Not Compliant checks to remediate: $($notCompliant.Count)" -ForegroundColor Gray

if ($notCompliant.Count -eq 0) {
    Write-Host "`nNo Not Compliant checks found in this audit. Nothing to generate." -ForegroundColor Green
    exit 0
}

# ----------------------------------------------------------------------------
# 2. Load the checks data file for additional remediation detail not stored
#    in the audit export (readMethod, full rationale, etc.)
# ----------------------------------------------------------------------------
$checksPath = Join-Path $ScriptRoot 'data\all-checks.json'
$CheckDefinitions = @{}
if (Test-Path $checksPath) {
    $allCheckDefs = Get-Content $checksPath -Raw | ConvertFrom-Json
    foreach ($def in $allCheckDefs) {
        $CheckDefinitions[$def.id] = $def
    }
} else {
    Write-Host "Warning: could not find data\all-checks.json next to this script. Some detail fields may be limited." -ForegroundColor Yellow
}

# ----------------------------------------------------------------------------
# 3. Remediation guidance derivation
# ----------------------------------------------------------------------------
function Get-RemediationType {
    <#
        Classifies how a check should be remediated, based on its category and the
        shape of its remediationSummary text. Returns one of:
          'Cmdlet'        - remediationSummary contains a directly runnable PowerShell cmdlet
          'ConditionalAccess' - needs a CA policy created (multi-step, no single cmdlet)
          'DNS'           - needs a DNS record change (SPF/DKIM/DMARC)
          'Portal'        - needs a manual change in the Entra/M365 admin portal, no API/cmdlet path
          'Manual'        - catch-all for anything else needing human judgement/process
    #>
    param($Check)

    $dnsIds = @('list-approved-sender-ips','spf-policies','dkim','dmarc-second-level-domains','dmarc-message-rejection','dmarc-point-of-contact')
    if ($dnsIds -contains $Check.id) { return 'DNS' }

    if ($Check.category -eq 'Conditional Access') { return 'ConditionalAccess' }

    if ($Check.remediationSummary -match '(Set-|New-|Add-|Update-|Remove-)\w+') {
        return 'Cmdlet'
    }

    if ($Check.confidence -eq 'Low' -or $Check.Confidence -eq 'Low') { return 'Portal' }

    return 'Manual'
}

function Get-EntraPortalPath {
    <#
        Best-effort mapping of a check's category to the relevant Entra/M365 admin
        center location, for manual remediation steps. This is a starting point for
        the technician, not a guarantee the menu path is pixel-exact in every tenant
        (Microsoft reorganizes admin center navigation periodically).
    #>
    param($Check)

    switch ($Check.category) {
        'Conditional Access' { return 'Entra admin center > Protection > Conditional Access > Policies' }
        'Identity'           { return 'Entra admin center > Protection > Authentication methods (or Identity > Users / Roles, depending on the setting)' }
        'Exchange/Defender'  { return 'Microsoft 365 Defender portal > Email & collaboration > Policies & rules, or Exchange admin center > Mail flow' }
        'SharePoint/Teams'   { return 'SharePoint admin center > Policies > Sharing, or Teams admin center > Org-wide settings' }
        'Licensing'          { return 'Microsoft 365 admin center > Billing > Licenses' }
        default              { return 'Microsoft 365 admin center' }
    }
}

# ----------------------------------------------------------------------------
# 4. Build the remediation item list
# ----------------------------------------------------------------------------
$impactOrder = @{ 'High' = 0; 'Medium' = 1; 'Low' = 2; 'None' = 3 }

$remediationItems = foreach ($result in $notCompliant) {
    $def = $CheckDefinitions[$result.Id]
    if (-not $def) {
        # Fall back to whatever the audit export captured directly if the data file
        # is unavailable or the check id has since changed.
        $def = $result
    }

    $remType = Get-RemediationType -Check $def
    $portalPath = Get-EntraPortalPath -Check $def

    [PSCustomObject]@{
        Id                  = $result.Id
        Name                = $result.Name
        Category            = $result.Category
        Detail              = $result.Detail
        MinLicense          = $result.MinLicense
        LicenseStatus       = $result.LicenseStatus
        CanRemediate        = $result.CanRemediate
        UserImpact          = $result.UserImpact
        UserImpactSummary   = $result.UserImpactSummary
        Rationale           = $def.rationale
        RemediationSummary  = $def.remediationSummary
        RemediationType     = $remType
        PortalPath          = $portalPath
        ImpactSortOrder     = $impactOrder[$result.UserImpact]
    }
}

$remediationItems = $remediationItems | Sort-Object Category, ImpactSortOrder, Name

Write-Host "`nRemediation breakdown by type:" -ForegroundColor Gray
$remediationItems | Group-Object RemediationType | ForEach-Object {
    Write-Host "  $($_.Name): $($_.Count)" -ForegroundColor Gray
}

# ----------------------------------------------------------------------------
# 5. Shared HTML helpers
# ----------------------------------------------------------------------------
Add-Type -AssemblyName System.Web

function ConvertTo-HtmlSafe {
    param([string]$Text)
    if (-not $Text) { return "" }
    return [System.Web.HttpUtility]::HtmlEncode($Text)
}

function Get-ImpactBadgeClass {
    param([string]$Impact)
    switch ($Impact) {
        'None'   { return 'impact-none' }
        'Low'    { return 'impact-low' }
        'Medium' { return 'impact-medium' }
        'High'   { return 'impact-high' }
        default  { return 'impact-low' }
    }
}

function Get-LicenseBadge {
    param([string]$LicenseStatus)
    switch ($LicenseStatus) {
        'Licensed'     { return "<span class='lic-ok'>&#10003; Licensed -- ready to remediate</span>" }
        'Not Licensed' { return "<span class='lic-missing'>&#10007; Not licensed -- requires upsell/upgrade first</span>" }
        default        { return "<span class='lic-unknown'>? License requirement unclear -- verify manually</span>" }
    }
}

$sharedCss = @"
<style>
    :root {
        --ink: #1c2330; --ink-soft: #4b5468; --line: #e2e5eb; --bg: #f7f8fa; --card: #ffffff;
        --green: #1e8e5a; --green-bg: #e7f6ee; --red: #c0392b; --red-bg: #fbeae8;
        --amber: #b8860b; --amber-bg: #fbf3e0; --gray: #6b7280; --gray-bg: #eef0f3; --accent: #2452a3;
    }
    * { box-sizing: border-box; }
    body { margin: 0; font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--ink); line-height: 1.5; }
    .wrap { max-width: 1280px; margin: 0 auto; padding: 32px 24px 80px; }
    header.report-header { margin-bottom: 28px; }
    .title-block h1 { font-size: 26px; margin: 0 0 4px; letter-spacing: -0.01em; }
    .title-block .subtitle { color: var(--ink-soft); font-size: 14px; }
    .note-box { background: var(--card); border: 1px solid var(--line); border-left: 4px solid var(--accent); border-radius: 6px; padding: 14px 18px; font-size: 13.5px; color: var(--ink-soft); margin-bottom: 28px; }
    .summary-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 32px; }
    .summary-card { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 16px 18px; }
    .summary-card .num { font-size: 26px; font-weight: 600; line-height: 1; }
    .summary-card .label { font-size: 12.5px; color: var(--ink-soft); margin-top: 6px; }
    h2.category-heading { font-size: 16px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--accent); margin: 36px 0 14px; padding-bottom: 8px; border-bottom: 2px solid var(--line); }
    .item-card { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 18px 22px; margin-bottom: 16px; }
    .item-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; flex-wrap: wrap; margin-bottom: 10px; }
    .item-title { font-size: 16px; font-weight: 600; }
    .item-detail { color: var(--ink-soft); font-size: 13.5px; margin-bottom: 10px; }
    .item-section { margin-top: 12px; }
    .item-section .section-label { font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-soft); margin-bottom: 4px; font-weight: 600; }
    .code-block { background: #1c2330; color: #e7ecf3; border-radius: 6px; padding: 12px 16px; font-family: 'Cascadia Code', Consolas, 'Courier New', monospace; font-size: 12.5px; overflow-x: auto; white-space: pre-wrap; }
    .step-list { margin: 4px 0 0 0; padding-left: 20px; font-size: 13.5px; color: var(--ink); }
    .step-list li { margin-bottom: 4px; }
    .badge { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 11.5px; font-weight: 600; white-space: nowrap; }
    .impact-none   { background: var(--gray-bg); color: var(--gray); }
    .impact-low    { background: var(--green-bg); color: var(--green); }
    .impact-medium { background: var(--amber-bg); color: var(--amber); }
    .impact-high   { background: var(--red-bg); color: var(--red); }
    .type-badge { background: var(--gray-bg); color: var(--ink-soft); }
    .lic-ok { color: var(--green); font-size: 12.5px; font-weight: 600; }
    .lic-missing { color: var(--red); font-size: 12.5px; font-weight: 600; }
    .lic-unknown { color: var(--gray); font-size: 12.5px; font-weight: 600; }
    footer { margin-top: 40px; font-size: 12px; color: var(--gray); text-align: center; }
</style>
"@

# ----------------------------------------------------------------------------
# 6. Technical HTML report
# ----------------------------------------------------------------------------
function New-TechnicalReport {
    param($Items, [string]$TenantDisplayName, [string]$AuditDateText, [int]$Score)

    $reportDate = Get-Date -Format "MMMM dd, yyyy"
    $categories = $Items | Select-Object -ExpandProperty Category -Unique

    $highImpactCount = ($Items | Where-Object { $_.UserImpact -eq 'High' }).Count
    $blockedCount = ($Items | Where-Object { $_.LicenseStatus -eq 'Not Licensed' }).Count
    $readyCount = ($Items | Where-Object { $_.LicenseStatus -eq 'Licensed' }).Count

    $body = New-Object System.Text.StringBuilder

    foreach ($cat in $categories) {
        [void]$body.Append("<h2 class='category-heading'>$(ConvertTo-HtmlSafe $cat)</h2>`n")
        $catItems = $Items | Where-Object { $_.Category -eq $cat }

        foreach ($item in $catItems) {
            $impactClass = Get-ImpactBadgeClass -Impact $item.UserImpact
            $licenseBadge = Get-LicenseBadge -LicenseStatus $item.LicenseStatus

            $remediationHtml = switch ($item.RemediationType) {
                'Cmdlet' {
                    @"
                    <div class="item-section">
                        <div class="section-label">PowerShell Remediation</div>
                        <div class="code-block">$(ConvertTo-HtmlSafe $item.RemediationSummary)</div>
                        <div style="font-size:12px;color:var(--ink-soft);margin-top:6px;">Run this in the appropriate connected session (Exchange Online, Graph, or SharePoint Online depending on the cmdlet). Test in a non-production scenario or off-hours where the user impact rating below is Medium or High.</div>
                    </div>
"@
                }
                'ConditionalAccess' {
                    @"
                    <div class="item-section">
                        <div class="section-label">Manual Steps (Conditional Access)</div>
                        <ol class="step-list">
                            <li>Go to $(ConvertTo-HtmlSafe $item.PortalPath)</li>
                            <li>Create a new policy (or edit an existing one covering this scenario)</li>
                            <li>Configure: $(ConvertTo-HtmlSafe $item.RemediationSummary)</li>
                            <li><strong>Always exclude your break-glass account</strong> before enabling</li>
                            <li>Set the policy to "Report-only" mode first if you want to validate impact before enforcing</li>
                        </ol>
                    </div>
"@
                }
                'DNS' {
                    @"
                    <div class="item-section">
                        <div class="section-label">DNS Change Required</div>
                        <div class="code-block">$(ConvertTo-HtmlSafe $item.RemediationSummary)</div>
                        <div style="font-size:12px;color:var(--ink-soft);margin-top:6px;">This is a DNS record change at the domain registrar/DNS host, not a PowerShell command. Changes can take time to propagate; verify with a DNS lookup tool before considering this resolved.</div>
                    </div>
"@
                }
                'Portal' {
                    @"
                    <div class="item-section">
                        <div class="section-label">Manual Verification &amp; Fix (Portal-only setting)</div>
                        <div style="font-size:13.5px;">$(ConvertTo-HtmlSafe $item.RemediationSummary)</div>
                        <div style="font-size:12px;color:var(--ink-soft);margin-top:6px;">Suggested location: $(ConvertTo-HtmlSafe $item.PortalPath). This setting doesn't have a reliable PowerShell/Graph GA endpoint, so the audit flagged it as low-confidence -- confirm current state manually before and after applying the fix.</div>
                    </div>
"@
                }
                default {
                    @"
                    <div class="item-section">
                        <div class="section-label">Remediation</div>
                        <div style="font-size:13.5px;">$(ConvertTo-HtmlSafe $item.RemediationSummary)</div>
                        <div style="font-size:12px;color:var(--ink-soft);margin-top:6px;">Suggested location: $(ConvertTo-HtmlSafe $item.PortalPath)</div>
                    </div>
"@
                }
            }

            [void]$body.Append(@"
            <div class="item-card">
                <div class="item-header">
                    <div class="item-title">$(ConvertTo-HtmlSafe $item.Name)</div>
                    <div>
                        <span class="badge $impactClass">User impact: $(ConvertTo-HtmlSafe $item.UserImpact)</span>
                        <span class="badge type-badge">$(ConvertTo-HtmlSafe $item.RemediationType)</span>
                    </div>
                </div>
                <div class="item-detail">$(ConvertTo-HtmlSafe $item.Detail)</div>
                <div class="item-section">
                    <div class="section-label">Why this matters</div>
                    <div style="font-size:13.5px;color:var(--ink-soft);">$(ConvertTo-HtmlSafe $item.Rationale)</div>
                </div>
                <div class="item-section">
                    <div class="section-label">Licensing</div>
                    <div style="font-size:13px;">Requires: $(ConvertTo-HtmlSafe $item.MinLicense) &nbsp; $licenseBadge</div>
                </div>
                $remediationHtml
                <div class="item-section">
                    <div class="section-label">What staff will notice</div>
                    <div style="font-size:13.5px;color:var(--ink-soft);">$(ConvertTo-HtmlSafe $item.UserImpactSummary)</div>
                </div>
            </div>
"@)
        }
    }

    $html = @"
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>M365 Remediation Plan - $(ConvertTo-HtmlSafe $TenantDisplayName)</title>
$sharedCss
</head>
<body>
<div class="wrap">
    <header class="report-header">
        <div class="title-block">
            <h1>M365 Remediation Plan (Technical)</h1>
            <div class="subtitle">$(ConvertTo-HtmlSafe $TenantDisplayName) &middot; Based on audit from $(ConvertTo-HtmlSafe $AuditDateText) &middot; Generated $reportDate</div>
        </div>
    </header>

    <div class="note-box">
        This plan covers every check that was <strong>Not Compliant</strong> as of the referenced audit.
        Nothing on this page has been executed -- it is reference documentation only. Re-run the audit
        after applying fixes to confirm they took effect and to catch anything this plan missed.
    </div>

    <div class="summary-grid">
        <div class="summary-card"><div class="num" style="color:var(--red)">$($Items.Count)</div><div class="label">Total gaps to fix</div></div>
        <div class="summary-card"><div class="num" style="color:var(--accent)">$readyCount</div><div class="label">Ready now (licensed)</div></div>
        <div class="summary-card"><div class="num" style="color:var(--amber)">$blockedCount</div><div class="label">Blocked by licensing</div></div>
        <div class="summary-card"><div class="num" style="color:var(--red)">$highImpactCount</div><div class="label">High user-impact (plan carefully)</div></div>
    </div>

    $($body.ToString())

    <footer>Generated by an internal remediation planning script &middot; $reportDate</footer>
</div>
</body>
</html>
"@

    return $html
}

# ----------------------------------------------------------------------------
# 7. Client-facing summary report (plain language, no PowerShell)
# ----------------------------------------------------------------------------
function Get-PlainLanguageAction {
    <#
        Translates a remediation type into a plain-English description of what kind
        of work is involved, without any technical syntax -- for the client summary.
    #>
    param([string]$RemediationType)
    switch ($RemediationType) {
        'Cmdlet'            { return "A configuration change in Microsoft 365 admin tools. Quick to apply once scheduled." }
        'ConditionalAccess' { return "A new security policy needs to be created and carefully rolled out, ideally tested in monitor-only mode first." }
        'DNS'               { return "A change to your domain's DNS records. Usually done once and takes effect within a few hours to a day." }
        'Portal'            { return "A setting change made directly in the Microsoft 365 admin portal." }
        default             { return "A configuration or process change in Microsoft 365." }
    }
}

function New-ClientSummaryReport {
    param($Items, [string]$TenantDisplayName, [string]$AuditDateText)

    $reportDate = Get-Date -Format "MMMM dd, yyyy"

    $highImpact = $Items | Where-Object { $_.UserImpact -eq 'High' }
    $mediumImpact = $Items | Where-Object { $_.UserImpact -eq 'Medium' }
    $lowNoImpact = $Items | Where-Object { $_.UserImpact -in @('Low','None') }
    $blockedByLicense = $Items | Where-Object { $_.LicenseStatus -eq 'Not Licensed' }

    function Build-ClientSection {
        param($SectionItems, [string]$SectionTitle, [string]$SectionIntro)

        if ($SectionItems.Count -eq 0) { return "" }

        $rows = New-Object System.Text.StringBuilder
        foreach ($item in $SectionItems) {
            $action = Get-PlainLanguageAction -RemediationType $item.RemediationType
            $licenseNote = if ($item.LicenseStatus -eq 'Not Licensed') {
                "<div class='lic-flag'>Requires a license upgrade ($([System.Web.HttpUtility]::HtmlEncode($item.MinLicense))) before this can be fixed.</div>"
            } else { "" }

            [void]$rows.Append(@"
            <div class="client-item">
                <div class="client-item-title">$([System.Web.HttpUtility]::HtmlEncode($item.Name))</div>
                <div class="client-item-why">$([System.Web.HttpUtility]::HtmlEncode($item.Rationale))</div>
                <div class="client-item-row"><strong>What this involves:</strong> $([System.Web.HttpUtility]::HtmlEncode($action))</div>
                <div class="client-item-row"><strong>What your team will notice:</strong> $([System.Web.HttpUtility]::HtmlEncode($item.UserImpactSummary))</div>
                $licenseNote
            </div>
"@)
        }

        return @"
        <h2 class="client-section-heading">$SectionTitle <span class="count-badge">$($SectionItems.Count)</span></h2>
        <p class="client-section-intro">$SectionIntro</p>
        $($rows.ToString())
"@
    }

    $highSection = Build-ClientSection -SectionItems $highImpact -SectionTitle "Plan Carefully &mdash; Will Be Noticeable" -SectionIntro "These improve security meaningfully, but will change something your staff sees or does day-to-day. We recommend scheduling these with advance notice to your team, often with a pilot group first."
    $mediumSection = Build-ClientSection -SectionItems $mediumImpact -SectionTitle "Moderate Changes" -SectionIntro "These may cause minor, occasional friction for a small number of staff, but are generally safe to schedule without a big rollout plan."
    $lowSection = Build-ClientSection -SectionItems $lowNoImpact -SectionTitle "Quick Wins &mdash; Low or No Visible Impact" -SectionIntro "These close real security gaps and your staff is unlikely to notice anything changed. Good candidates to fix first."

    $html = @"
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Security Improvement Plan - $([System.Web.HttpUtility]::HtmlEncode($TenantDisplayName))</title>
<style>
    :root { --ink: #1c2330; --ink-soft: #4b5468; --line: #e2e5eb; --bg: #f7f8fa; --card: #ffffff; --accent: #2452a3; --amber: #b8860b; --amber-bg: #fbf3e0; }
    * { box-sizing: border-box; }
    body { margin: 0; font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif; background: var(--bg); color: var(--ink); line-height: 1.6; }
    .wrap { max-width: 880px; margin: 0 auto; padding: 40px 24px 80px; }
    h1 { font-size: 28px; margin: 0 0 6px; }
    .subtitle { color: var(--ink-soft); font-size: 14px; margin-bottom: 28px; }
    .intro-box { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 20px 24px; margin-bottom: 32px; font-size: 14.5px; }
    .client-section-heading { font-size: 19px; margin: 40px 0 6px; display: flex; align-items: center; gap: 10px; }
    .count-badge { background: var(--accent); color: white; border-radius: 999px; font-size: 13px; padding: 2px 10px; font-weight: 600; }
    .client-section-intro { color: var(--ink-soft); font-size: 14px; margin-bottom: 18px; }
    .client-item { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 16px 20px; margin-bottom: 12px; }
    .client-item-title { font-size: 15.5px; font-weight: 600; margin-bottom: 6px; }
    .client-item-why { color: var(--ink-soft); font-size: 13.5px; margin-bottom: 8px; }
    .client-item-row { font-size: 13.5px; margin-bottom: 4px; }
    .lic-flag { margin-top: 8px; background: var(--amber-bg); color: var(--amber); font-size: 12.5px; font-weight: 600; padding: 6px 10px; border-radius: 6px; display: inline-block; }
    footer { margin-top: 50px; font-size: 12px; color: var(--ink-soft); text-align: center; }
</style>
</head>
<body>
<div class="wrap">
    <h1>Security Improvement Plan</h1>
    <div class="subtitle">Prepared for $([System.Web.HttpUtility]::HtmlEncode($TenantDisplayName)) &middot; Based on our review on $([System.Web.HttpUtility]::HtmlEncode($AuditDateText)) &middot; $reportDate</div>

    <div class="intro-box">
        We reviewed your Microsoft 365 environment against industry-standard security benchmarks.
        This document summarizes the improvement opportunities we found, organized by how much
        they'll affect your team's day-to-day experience &mdash; so we can plan the rollout together
        rather than surprise anyone. Items are explained in plain language; the technical
        implementation details are tracked separately on our end.
    </div>

    $highSection
    $mediumSection
    $lowSection

    <footer>Prepared as a follow-up to your Microsoft 365 security review &middot; $reportDate</footer>
</div>
</body>
</html>
"@

    return $html
}

# ----------------------------------------------------------------------------
# 8. Generate and save both reports
# ----------------------------------------------------------------------------
Write-Host "`nGenerating reports..." -ForegroundColor Cyan

$technicalHtml = New-TechnicalReport -Items $remediationItems -TenantDisplayName $tenantName -AuditDateText $auditDate -Score $postureScore
$clientHtml = New-ClientSummaryReport -Items $remediationItems -TenantDisplayName $tenantName -AuditDateText $auditDate

$safeFileName = ($tenantName -replace '[^\w\-]', '_')
$timestamp = Get-Date -Format 'yyyy-MM-dd_HHmmss'

$technicalPath = Join-Path $OutputPath "M365_Remediation_Technical_${safeFileName}_${timestamp}.html"
$clientPath = Join-Path $OutputPath "M365_Remediation_ClientSummary_${safeFileName}_${timestamp}.html"

$technicalHtml | Out-File -FilePath $technicalPath -Encoding UTF8
$clientHtml | Out-File -FilePath $clientPath -Encoding UTF8

Write-Host "`nTechnical remediation report saved to: $technicalPath" -ForegroundColor Green
Write-Host "Client-facing summary saved to: $clientPath" -ForegroundColor Green

Write-Host "`nNeither report changed anything in the tenant -- both are documentation only." -ForegroundColor Gray

Write-Host "`nOpening both reports..." -ForegroundColor Cyan
try { Invoke-Item $technicalPath } catch { Write-Host "Could not auto-open the technical report. Find it at: $technicalPath" -ForegroundColor Yellow }
try { Invoke-Item $clientPath } catch { Write-Host "Could not auto-open the client summary. Find it at: $clientPath" -ForegroundColor Yellow }
'@

# ======================= Remove-Bloatware.ps1 =======================
$Script:Payloads['Remove-Bloatware'] = @'
# ==============================================================================
# Remove-Bloatware.ps1
# Removes common OEM and Microsoft bloatware apps during OOBE / imaging
#
# RMM COMPATIBLE (N-able, Datto, ConnectWise, etc.)
#   - No interactive prompts
#   - No Read-Host or ReadKey calls
#   - Exits with code 0 (success) or 1 (errors occurred)
#   - All output via Write-Output for RMM stdout capture
#   - Execution policy bypass handled via launch flag or inline set
#   - Safe to run as SYSTEM account
# ==============================================================================

# Allow script to run regardless of execution policy (RMM sets this at launch,
# but setting it here too makes the script self-contained)
param(
    [string]$OutputPath = "C:\temp"
)

Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force

$ErrorActionPreference = 'SilentlyContinue'

# ==============================================================================
# LOGGING SETUP
# ==============================================================================
$LogDir  = $OutputPath
$LogFile = "$LogDir\Remove-Bloatware_$(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss').log"

if (-not (Test-Path $LogDir)) {
    New-Item -ItemType Directory -Path $LogDir -Force | Out-Null
}

function Write-Log {
    param(
        [string]$Message,
        [string]$Level = "INFO"
    )
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $line      = "[$timestamp] [$Level] $Message"

    # Write to log file
    Add-Content -Path $LogFile -Value $line

    # Write to stdout — RMM tools capture this
    Write-Output $line
}

# ==============================================================================
# APP LIST
# ==============================================================================
$bloatwareApps = @(
    # Microsoft bloat
    "Microsoft.BingFinance"
    "Microsoft.BingFoodAndDrink"
    "Microsoft.BingHealthAndFitness"
    "Microsoft.BingNews"
    "Microsoft.BingSports"
    "Microsoft.BingTranslator"
    "Microsoft.BingTravel"
    "Microsoft.BingWeather"
    "Microsoft.Getstarted"
    "Microsoft.GamingApp"
    "Microsoft.MicrosoftSolitaireCollection"
    "Microsoft.WindowsMaps"
    "Microsoft.XboxApp"
    "Microsoft.XboxGameOverlay"
    "Microsoft.XboxGamingOverlay"
    "Microsoft.XboxIdentityProvider"
    "Microsoft.XboxSpeechToTextOverlay"
    "Microsoft.ZuneVideo"
    "Microsoft.ZuneMusic"
    "Microsoft.People"
    "Microsoft.Todos"
    "Microsoft.PowerAutomateDesktop"
    "Microsoft.MixedReality.Portal"
    "Microsoft.Microsoft3DViewer"
    "Microsoft.SkypeApp"
    "Microsoft.Teams"
    "MicrosoftTeams"
    "Microsoft.Messaging"
    "Microsoft.Office.OneNote"

    # Games / Entertainment
    "Amazon.com.Amazon"
    "Asphalt8Airborne"
    "king.com.BubbleWitch3Saga"
    "CaesarsSlotsFreeCasino"
    "king.com.CandyCrushSaga"
    "king.com.CandyCrushSodaSaga"
    "COOKINGFEVER"
    "CyberLinkMediaSuiteEssentials"
    "Disney"
    "DisneyMagicKingdoms"
    "Duolingo-LearnLanguagesforFree"
    "FarmVille2CountryEscape"
    "HiddenCity"
    "HULULLC.HULUPLUS"
    "MarchofEmpires"
    "Netflix"
    "NYTCrossword"
    "PandoraMediaInc"
    "AmazonVideo.PrimeVideo"
    "RoyalRevolt"
    "Shazam"
    "SlingTV"
    "TikTok"
    "TuneInRadio"
    "Twitter"
    "Viber"
    "WinZipUniversal"
    "XING"

    # Social / News
    "Facebook"
    "Instagram"
    "LinkedInforWindows"
    "iHeartRadio"
    "fitbit"

    # OEM specific (HP, Dell, Lenovo)
    "HPJumpStarts"
    "HPPCHardwareDiagnosticsWindows"
    "HPPowerManager"
    "HPPrivacySettings"
    "HPSupportAssistant"
    "HPSureShieldAI"
    "HPSystemInformation"
    "HPQuickDrop"
    "HPWorkWell"
    "myHP"
    "HPDesktopSupportUtilities"
    "HPProgrammableKey"
    "DellDigitalDelivery"
    "DellSupportAssistAgent"
    "DellCommandUpdate"
    "LenovoCompanion"
    "LenovoSettingsforEnterprise"
    "LenovoUtility"
    "E2GHSoftware.McAfeeSecurity"
    "McAfeeSecurityforWindowsServer"
    "NortonSecurity"
)

# ==============================================================================
# MAIN
# ==============================================================================
Write-Log "======================================================================"
Write-Log " Bloatware Removal Script - START"
Write-Log " Machine:  $env:COMPUTERNAME"
Write-Log " User:     $env:USERNAME"
Write-Log " OS:       $([System.Environment]::OSVersion.VersionString)"
Write-Log " Log file: $LogFile"
Write-Log "======================================================================"
Write-Log "$($bloatwareApps.Count) apps selected for removal"

$removed  = 0
$notFound = 0
$errors   = 0

foreach ($app in $bloatwareApps) {
    try {
        $pkg = Get-AppxPackage -Name "*$app*" -AllUsers

        if ($pkg) {
            $pkg | Remove-AppxPackage -AllUsers
            Write-Log "[REMOVED]  AppxPackage: $app"
            $removed++
        } else {
            Write-Log "[SKIPPED]  Not found: $app"
            $notFound++
        }

        # Strip provisioned package so it won't reinstall for new user profiles
        $provPkg = Get-AppxProvisionedPackage -Online |
                   Where-Object { $_.DisplayName -like "*$app*" }
        if ($provPkg) {
            $provPkg | Remove-AppxProvisionedPackage -Online | Out-Null
            Write-Log "[REMOVED]  Provisioned package: $app"
        }

    } catch {
        Write-Log "[ERROR]    Failed to remove $app - $_"
        $errors++
    }
}

Write-Log "======================================================================"
Write-Log " RESULTS: $removed removed | $notFound not found | $errors errors"
Write-Log "======================================================================"

# Restart Explorer to apply changes — safe to do headlessly
try {
    Write-Log "Restarting Windows Explorer to apply changes..."
    Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
    Start-Process explorer
    Write-Log "Explorer restarted successfully."
} catch {
    Write-Log "[ERROR] Failed to restart Explorer: $_"
}

Write-Log "Script completed. Log saved to: $LogFile"

# ==============================================================================
# EXIT CODE — RMM uses this to determine pass/fail
#   0 = success (even if some apps were not found — that is expected)
#   1 = one or more removal errors occurred
# ==============================================================================
if ($errors -gt 0) {
    Write-Log "Exiting with code 1 ($errors error(s) encountered)."
    exit 1
} else {
    Write-Log "Exiting with code 0 (no errors)."
    exit 0
}
'@

# ======================= Remove-MobileLeases.ps1 =======================
$Script:Payloads['Remove-MobileLeases'] = @'
# ============================================================
# Remove-MobileLeases.ps1
# Audits DHCP mobile device leases then removes them
#
# USAGE:
#   .\Remove-MobileLeases.ps1              # Interactive menu
#   .\Remove-MobileLeases.ps1 -O           # Remove offline leases only (no prompt)
#   .\Remove-MobileLeases.ps1 -A           # Remove all mobile leases (no prompt)
#   .\Remove-MobileLeases.ps1 -AuditOnly   # Just audit, no removal at all
#
# Designed to run via N-Central against the local machine it is
# deployed on. If this box is not itself the DHCP server, pass
# -DHCPServer explicitly to override.
# ============================================================

param(
    [switch]$A,          # Remove all mobile leases without prompting
    [switch]$O,          # Remove offline-only leases without prompting
    [switch]$AuditOnly,  # Audit and export CSV only, no removal
    [string]$DHCPServer = $env:COMPUTERNAME,  # Defaults to the local machine
    [string]$OutputDir  = "C:\temp"
)

# --- CONFIGURATION ---
$AuditFile     = "$OutputDir\MobileLeases_Audit.csv"
$RemovedFile   = "$OutputDir\MobileLeases_Removed.csv"
$LogFile       = "$OutputDir\MobileLeases_Log.txt"

$MobilePattern = 'android|iphone|ipad|apple|watch|galaxy|samsung|pixel|motorola|moto|nokia|oneplus|huawei|xiaomi|oppo'

# --- SETUP ---
if (-not (Test-Path $OutputDir)) {
    New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
}

function Write-Log {
    param([string]$Message, [string]$Level = "INFO")
    $Timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $Line = "[$Timestamp] [$Level] $Message"
    Write-Host $Line
    Add-Content -Path $LogFile -Value $Line
}

Write-Log "========================================="
Write-Log "Mobile Lease Audit and Removal Started"
Write-Log "DHCP Server: $DHCPServer"

if     ($AuditOnly) { Write-Log "Mode: Audit Only" }
elseif ($A)         { Write-Log "Mode: Remove ALL (non-interactive)" }
elseif ($O)         { Write-Log "Mode: Remove Offline Only (non-interactive)" }
else                { Write-Log "Mode: Interactive" }

Write-Log "========================================="

# --- STEP 1: AUTO-DETECT ALL SCOPES ON THE DHCP SERVER ---
Write-Log "Querying DHCP scopes on $DHCPServer..."

try {
    $Scopes = @(Get-DhcpServerv4Scope -ComputerName $DHCPServer -ErrorAction Stop)
} catch {
    Write-Log "ERROR: Failed to query scopes on $DHCPServer - $_" "ERROR"
    exit 1
}

if ($Scopes.Count -eq 0) {
    Write-Log "No DHCP scopes found on $DHCPServer. Exiting." "ERROR"
    exit 1
}

Write-Log "Found $($Scopes.Count) scope(s): $($Scopes.ScopeId -join ', ')"

# --- STEP 2: FETCH LEASES ACROSS ALL SCOPES ---
$AllLeases = foreach ($Scope in $Scopes) {
    Write-Log "Fetching leases for scope $($Scope.ScopeId) ($($Scope.Name))..."
    try {
        Get-DhcpServerv4Lease -ComputerName $DHCPServer -ScopeId $Scope.ScopeId -ErrorAction Stop
    } catch {
        Write-Log "WARNING: Failed to fetch leases for scope $($Scope.ScopeId) - $_" "WARN"
    }
}

Write-Log "Total leases across all scopes: $($AllLeases.Count)"

# --- STEP 3: FILTER MOBILE DEVICES ---
$MobileLeases = $AllLeases | Where-Object {
    $_.AddressState -notlike '*reservation*' -and
    $_.HostName     -match $MobilePattern
}

Write-Log "Mobile device leases found: $($MobileLeases.Count)"

if ($MobileLeases.Count -eq 0) {
    Write-Log "No mobile device leases found. Nothing to do."
    exit 0
}

# --- STEP 4: AUDIT EXPORT ---
$MobileLeases |
    Select-Object ScopeId, IPAddress, HostName, ClientId, AddressState, LeaseExpiryTime |
    Export-Csv -Path $AuditFile -NoTypeInformation -Force

Write-Log "Audit exported to $AuditFile"

if ($AuditOnly) {
    Write-Log "AuditOnly mode - skipping removal. Done."
    exit 0
}

# --- STEP 5: DETERMINE WHICH LEASES TO REMOVE ---
if ($A) {
    $ToRemove = $MobileLeases
}
elseif ($O) {
    $ToRemove = $MobileLeases | Where-Object { $_.AddressState -match 'Offline|Expired|Inactive' }
}
else {
    # Interactive menu
    Write-Host ""
    Write-Host "Mobile leases found:"
    $MobileLeases | Format-Table ScopeId, IPAddress, HostName, AddressState -AutoSize
    Write-Host ""
    Write-Host "Select an option:"
    Write-Host "  1) Remove ALL mobile leases"
    Write-Host "  2) Remove OFFLINE mobile leases only"
    Write-Host "  3) Cancel (no removal)"
    $Choice = Read-Host "Enter choice (1-3)"

    switch ($Choice) {
        '1' { $ToRemove = $MobileLeases }
        '2' { $ToRemove = $MobileLeases | Where-Object { $_.AddressState -match 'Offline|Expired|Inactive' } }
        default {
            Write-Log "User cancelled removal. Done."
            exit 0
        }
    }
}

if (-not $ToRemove -or $ToRemove.Count -eq 0) {
    Write-Log "No leases matched removal criteria. Done."
    exit 0
}

# --- STEP 6: REMOVE LEASES ---
$Removed = foreach ($Lease in $ToRemove) {
    try {
        Remove-DhcpServerv4Lease -ComputerName $DHCPServer -IPAddress $Lease.IPAddress -ErrorAction Stop
        Write-Log "Removed lease: $($Lease.IPAddress) ($($Lease.HostName)) - scope $($Lease.ScopeId)"
        $Lease
    } catch {
        Write-Log "ERROR: Failed to remove $($Lease.IPAddress) - $_" "ERROR"
    }
}

if ($Removed) {
    $Removed |
        Select-Object ScopeId, IPAddress, HostName, ClientId, AddressState, LeaseExpiryTime |
        Export-Csv -Path $RemovedFile -NoTypeInformation -Force
    Write-Log "Removed lease log exported to $RemovedFile"
}

Write-Log "Mobile Lease Audit and Removal Completed. Removed $($Removed.Count) of $($ToRemove.Count) targeted leases."
Write-Log "========================================="
'@

# ======================= Resolve-DiskSpace.ps1 =======================
$Script:Payloads['Resolve-DiskSpace'] = @'
#Requires -RunAsAdministrator
<#
.SYNOPSIS
    Disk Space Analyzer and Resolver for Windows Servers

.DESCRIPTION
    Scans all local drives, identifies space consumers, and safely resolves
    common disk space issues with full logging and dry-run support.

.PARAMETER Servers
    One or more server names to target. Defaults to localhost.

.PARAMETER ThresholdPercent
    Alert threshold for free space percentage. Default is 20%.

.PARAMETER DryRun
    Preview actions without making any changes.

.PARAMETER LogPath
    Path to write the log file. Defaults to script directory.

.PARAMETER SkipActions
    Comma-separated list of actions to skip.
    Options: WinSxS, SoftwareDistribution, Temp, IISLogs, Dumps, EventLogs, RecycleBin, HyperVSnapshots

.EXAMPLE
    # Local dry run
    .\Resolve-DiskSpace.ps1 -DryRun

.EXAMPLE
    # Target multiple remote servers
    .\Resolve-DiskSpace.ps1 -Servers "SRV01","SRV02" -ThresholdPercent 15

.EXAMPLE
    # Skip snapshot cleanup and event log trimming
    .\Resolve-DiskSpace.ps1 -SkipActions "HyperVSnapshots","EventLogs"
#>

[CmdletBinding(SupportsShouldProcess)]
param(
    [string[]]$Servers       = @("localhost"),
    [int]$ThresholdPercent   = 20,
    [switch]$DryRun,
    [string]$LogPath         = "C:\temp\DiskCleanup_$(Get-Date -Format 'yyyyMMdd_HHmmss').log",
    [string[]]$SkipActions   = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Continue"

#region -- Helpers ------------------------------------------------------------

function Write-Log {
    param([string]$Message, [string]$Level = "INFO")
    $ts   = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $line = "[$ts] [$Level] $Message"
    switch ($Level) {
        "INFO"    { Write-Host $line -ForegroundColor Cyan }
        "SUCCESS" { Write-Host $line -ForegroundColor Green }
        "WARN"    { Write-Host $line -ForegroundColor Yellow }
        "ERROR"   { Write-Host $line -ForegroundColor Red }
        "ACTION"  { Write-Host $line -ForegroundColor Magenta }
        "DRYRUN"  { Write-Host $line -ForegroundColor DarkCyan }
        default   { Write-Host $line }
    }
    Add-Content -Path $LogPath -Value $line -ErrorAction SilentlyContinue
}

function Format-Bytes {
    param([long]$Bytes)
    if     ($Bytes -ge 1GB) { "{0:N2} GB" -f ($Bytes / 1GB) }
    elseif ($Bytes -ge 1MB) { "{0:N2} MB" -f ($Bytes / 1MB) }
    elseif ($Bytes -ge 1KB) { "{0:N2} KB" -f ($Bytes / 1KB) }
    else                    { "$Bytes B" }
}

function Should-Skip {
    param([string]$ActionName)
    return ($SkipActions -contains $ActionName)
}

# Invoke a scriptblock locally or via PSRemoting
function Invoke-Target {
    param(
        [string]$Server,
        [scriptblock]$ScriptBlock,
        [object[]]$ArgumentList = @()
    )
    if ($Server -in @("localhost","127.0.0.1",$env:COMPUTERNAME)) {
        & $ScriptBlock @ArgumentList
    } else {
        Invoke-Command -ComputerName $Server -ScriptBlock $ScriptBlock -ArgumentList $ArgumentList -ErrorAction Stop
    }
}

#endregion

#region -- Drive Analysis -----------------------------------------------------

function Get-DriveReport {
    param([string]$Server)
    Write-Log "[$Server] Scanning drives..." "INFO"

    $drives = @(Invoke-Target $Server {
        Get-PSDrive -PSProvider FileSystem |
        Where-Object { $_.Used -ne $null -and ($_.Used + $_.Free) -gt 0 } |
        Select-Object Name, Root,
            @{N="TotalGB"; E={[math]::Round(($_.Used + $_.Free)/1GB, 2)}},
            @{N="UsedGB";  E={[math]::Round($_.Used/1GB, 2)}},
            @{N="FreeGB";  E={[math]::Round($_.Free/1GB, 2)}},
            @{N="FreePct"; E={[math]::Round(($_.Free / ($_.Used + $_.Free)) * 100, 1)}}
    })

    foreach ($d in $drives) {
        $status = if ($d.FreePct -lt 10) { "ERROR" }
                  elseif ($d.FreePct -lt $ThresholdPercent) { "WARN" }
                  else { "INFO" }
        Write-Log ("[$Server] Drive {0}: {1} free of {2} ({3}% free)" -f
            $d.Root, $d.FreeGB, $d.TotalGB, $d.FreePct) $status
    }
    return $drives
}

function Get-TopSpaceConsumers {
    param([string]$Server, [string]$Drive = "C:\")
    Write-Log "[$Server] Finding top space consumers on $Drive ..." "INFO"

    $results = @(Invoke-Target $Server {
        param($root)
        $items = @()

        # Top-level folder sizes
        Get-ChildItem $root -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $measured = Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue |
                        Measure-Object Length -Sum -ErrorAction SilentlyContinue
            $size = if ($measured -and $measured.Sum) { [long]$measured.Sum } else { 0 }
            if ($size -gt 0) {
                $items += [PSCustomObject]@{ Path = $_.FullName; SizeBytes = $size }
            }
        }
        $items | Sort-Object SizeBytes -Descending | Select-Object -First 15
    } -ArgumentList $Drive)

    Write-Log "[$Server] Top consumers on $Drive :" "INFO"
    foreach ($r in $results) {
        Write-Log ("  {0,-55} {1}" -f $r.Path, (Format-Bytes $r.SizeBytes)) "INFO"
    }
    return $results
}

#endregion

#region -- Cleanup Actions ----------------------------------------------------

function Invoke-WinSxSCleanup {
    param([string]$Server)
    if (Should-Skip "WinSxS") { Write-Log "[$Server] Skipping WinSxS cleanup." "WARN"; return 0 }

    Write-Log "[$Server] Running DISM component store cleanup (WinSxS)..." "ACTION"
    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would run: DISM /Online /Cleanup-Image /StartComponentCleanup /ResetBase" "DRYRUN"
        return 0
    }

    $result = Invoke-Target $Server {
        $before = (Get-Item "C:\Windows\WinSxS" -ErrorAction SilentlyContinue |
                   Get-ChildItem -Recurse -ErrorAction SilentlyContinue |
                   Measure-Object Length -Sum).Sum

        $output = & dism.exe /Online /Cleanup-Image /StartComponentCleanup /ResetBase 2>&1
        $exitCode = $LASTEXITCODE

        $after = (Get-Item "C:\Windows\WinSxS" -ErrorAction SilentlyContinue |
                  Get-ChildItem -Recurse -ErrorAction SilentlyContinue |
                  Measure-Object Length -Sum).Sum

        [PSCustomObject]@{
            Output   = $output -join "`n"
            ExitCode = $exitCode
            Saved    = [math]::Max(0, $before - $after)
        }
    }

    if ($result.ExitCode -eq 0) {
        Write-Log "[$Server] WinSxS cleanup complete. Saved approx $(Format-Bytes $result.Saved)." "SUCCESS"
    } else {
        Write-Log "[$Server] DISM returned exit code $($result.ExitCode). Output: $($result.Output)" "WARN"
    }
    return $result.Saved
}

function Invoke-SoftwareDistributionCleanup {
    param([string]$Server)
    if (Should-Skip "SoftwareDistribution") { Write-Log "[$Server] Skipping SoftwareDistribution." "WARN"; return 0 }

    Write-Log "[$Server] Clearing Windows Update download cache..." "ACTION"

    $result = Invoke-Target $Server {
        param($dryRun)
        $path = "C:\Windows\SoftwareDistribution\Download"
        $m    = Get-ChildItem $path -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum -ErrorAction SilentlyContinue
        $size = if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }

        if (-not $dryRun) {
            Stop-Service -Name wuauserv, bits -Force -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 2
            Remove-Item "$path\*" -Recurse -Force -ErrorAction SilentlyContinue
            Start-Service -Name wuauserv, bits -ErrorAction SilentlyContinue
        }
        return $size
    } -ArgumentList $DryRun

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would clear SoftwareDistribution\Download (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] SoftwareDistribution cleared. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-TempCleanup {
    param([string]$Server)
    if (Should-Skip "Temp") { Write-Log "[$Server] Skipping Temp cleanup." "WARN"; return 0 }

    Write-Log "[$Server] Cleaning temp folders..." "ACTION"

    $result = Invoke-Target $Server {
        param($dryRun)
        $paths = @(
            "C:\Windows\Temp",
            "$env:TEMP",
            "$env:SystemRoot\Logs\CBS"
        )
        $totalSize = 0
        foreach ($p in $paths) {
            if (Test-Path $p) {
                $m    = Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum -ErrorAction SilentlyContinue
                $size = if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }
                $totalSize += $size
                if (-not $dryRun) {
                    Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue |
                        Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-1) } |
                        Remove-Item -Force -ErrorAction SilentlyContinue
                }
            }
        }
        return $totalSize
    } -ArgumentList $DryRun

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would clean temp folders (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] Temp folders cleaned. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-IISLogCleanup {
    param([string]$Server, [int]$RetainDays = 30)
    if (Should-Skip "IISLogs") { Write-Log "[$Server] Skipping IIS log cleanup." "WARN"; return 0 }

    $result = Invoke-Target $Server {
        param($dryRun, $days)
        $iisLogRoot = "C:\inetpub\logs"
        if (-not (Test-Path $iisLogRoot)) { return 0 }

        $cutoff   = (Get-Date).AddDays(-$days)
        $oldLogs  = Get-ChildItem $iisLogRoot -Recurse -Include "*.log" -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.LastWriteTime -lt $cutoff }
        $m         = $oldLogs | Measure-Object Length -Sum -ErrorAction SilentlyContinue
        $totalSize = if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }

        if (-not $dryRun) {
            $oldLogs | Remove-Item -Force -ErrorAction SilentlyContinue
        }
        return $totalSize
    } -ArgumentList $DryRun, $RetainDays

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would remove IIS logs older than $RetainDays days (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] IIS logs cleaned. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-DumpCleanup {
    param([string]$Server, [int]$RetainDays = 30)
    if (Should-Skip "Dumps") { Write-Log "[$Server] Skipping dump cleanup." "WARN"; return 0 }

    Write-Log "[$Server] Removing crash dumps older than $RetainDays days (recent dumps are kept as evidence)..." "ACTION"

    $result = Invoke-Target $Server {
        param($dryRun, $retainDays)
        $cutoff = (Get-Date).AddDays(-$retainDays)
        $dumpPaths = @(
            "C:\Windows\Minidump",
            "C:\Windows\MEMORY.DMP",
            "C:\Windows\LiveKernelReports"
        )
        $totalSize = 0
        foreach ($p in $dumpPaths) {
            if (Test-Path $p) {
                $old = @(Get-ChildItem $p -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt $cutoff })
                $m = $old | Measure-Object Length -Sum -ErrorAction SilentlyContinue
                $totalSize += if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }
                if (-not $dryRun) { $old | Remove-Item -Force -ErrorAction SilentlyContinue }
            }
        }
        return $totalSize
    } -ArgumentList $DryRun, $RetainDays

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would remove crash dumps older than $RetainDays days (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] Crash dumps removed. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-EventLogCleanup {
    param([string]$Server, [int]$RetainDays = 90)
    if (Should-Skip "EventLogs") { Write-Log "[$Server] Skipping Event Log cleanup." "WARN"; return 0 }

    Write-Log "[$Server] Trimming event logs older than $RetainDays days..." "ACTION"

    $result = Invoke-Target $Server {
        param($dryRun, $days)
        $cutoff   = (Get-Date).AddDays(-$days)
        $logPaths = @("C:\Windows\System32\winevt\Logs")
        $totalSize = 0

        foreach ($logPath in $logPaths) {
            $oldLogs = Get-ChildItem $logPath -Filter "*.evtx" -ErrorAction SilentlyContinue |
                       Where-Object { $_.LastWriteTime -lt $cutoff -and $_.Length -gt 1MB }
            $m = $oldLogs | Measure-Object Length -Sum -ErrorAction SilentlyContinue
            $totalSize += if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }

            if (-not $dryRun) {
                foreach ($log in $oldLogs) {
                    try {
                        [System.Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog(
                            [System.IO.Path]::GetFileNameWithoutExtension($log.Name)
                        )
                    } catch {
                        # Log may be in use or non-clearable; skip silently
                    }
                }
            }
        }
        return $totalSize
    } -ArgumentList $DryRun, $RetainDays

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would trim event logs (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] Event logs trimmed. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-RecycleBinCleanup {
    param([string]$Server)
    if (Should-Skip "RecycleBin") { Write-Log "[$Server] Skipping Recycle Bin." "WARN"; return 0 }

    $result = Invoke-Target $Server {
        param($dryRun)
        $shell = New-Object -ComObject Shell.Application
        $bin   = $shell.Namespace(0xA)
        $m     = $bin.Items() | Measure-Object -Property Size -Sum -ErrorAction SilentlyContinue
        $size  = if ($m -and $m.Sum) { [long]$m.Sum } else { 0 }

        if (-not $dryRun) {
            Clear-RecycleBin -Force -ErrorAction SilentlyContinue
        }
        return [long]$size
    } -ArgumentList $DryRun

    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Would empty Recycle Bin (~$(Format-Bytes $result))." "DRYRUN"
    } else {
        Write-Log "[$Server] Recycle Bin emptied. Freed ~$(Format-Bytes $result)." "SUCCESS"
    }
    return $result
}

function Invoke-HyperVSnapshotReport {
    param([string]$Server)
    if (Should-Skip "HyperVSnapshots") { Write-Log "[$Server] Skipping Hyper-V snapshot check." "WARN"; return }

    $snapshots = Invoke-Target $Server {
        if (-not (Get-Module -ListAvailable -Name Hyper-V)) { return $null }
        Import-Module Hyper-V -ErrorAction SilentlyContinue
        @(Get-VM -ErrorAction SilentlyContinue | Get-VMSnapshot -ErrorAction SilentlyContinue |
            Select-Object VMName, Name, CreationTime,
                @{N="AgeDays"; E={[math]::Round(((Get-Date) - $_.CreationTime).TotalDays,1)}})
    }

    if ($null -eq $snapshots) {
        Write-Log "[$Server] Hyper-V not installed or no VMs found." "INFO"
        return
    }

    if ($snapshots.Count -eq 0) {
        Write-Log "[$Server] No Hyper-V snapshots found." "SUCCESS"
        return
    }

    Write-Log "[$Server] [!] Found $($snapshots.Count) Hyper-V snapshot(s) - review manually:" "WARN"
    foreach ($s in $snapshots) {
        Write-Log ("  VM: {0,-25} Snapshot: {1,-30} Age: {2} days" -f
            $s.VMName, $s.Name, $s.AgeDays) "WARN"
    }
    Write-Log "[$Server] Remove snapshots manually via Hyper-V Manager or: Get-VM | Get-VMSnapshot | Remove-VMSnapshot" "WARN"
}

#endregion

#region -- Main Orchestration -------------------------------------------------

function Invoke-ServerCleanup {
    param([string]$Server)

    $separator = "=" * 70
    Write-Log $separator "INFO"
    Write-Log "[$Server] Starting disk space analysis and cleanup" "INFO"
    if ($DryRun) { Write-Log "[$Server] *** DRY RUN MODE - No changes will be made ***" "WARN" }
    Write-Log $separator "INFO"

    # -- Step 1: Analyze current state --------------------------------------
    $drives = Get-DriveReport -Server $Server
    $criticalDrives = @($drives | Where-Object { $_.FreePct -lt $ThresholdPercent })

    if ($criticalDrives.Count -eq 0) {
        Write-Log "[$Server] All drives above ${ThresholdPercent}% free threshold. Running light maintenance only." "SUCCESS"
    } else {
        Write-Log "[$Server] $($criticalDrives.Count) drive(s) below threshold. Running full cleanup." "WARN"
        foreach ($d in $criticalDrives) {
            Get-TopSpaceConsumers -Server $Server -Drive $d.Root | Out-Null
        }
    }

    # -- Step 2: Run cleanup actions ----------------------------------------
    $totalSaved = 0
    $totalSaved += Invoke-WinSxSCleanup              -Server $Server
    $totalSaved += Invoke-SoftwareDistributionCleanup -Server $Server
    $totalSaved += Invoke-TempCleanup                 -Server $Server
    $totalSaved += Invoke-IISLogCleanup               -Server $Server -RetainDays 30
    $totalSaved += Invoke-DumpCleanup                 -Server $Server
    $totalSaved += Invoke-EventLogCleanup             -Server $Server -RetainDays 90
    $totalSaved += Invoke-RecycleBinCleanup           -Server $Server
    Invoke-HyperVSnapshotReport                       -Server $Server

    # -- Step 3: Post-cleanup report ----------------------------------------
    Write-Log $separator "INFO"
    Write-Log "[$Server] POST-CLEANUP DRIVE STATUS:" "INFO"
    Get-DriveReport -Server $Server | Out-Null

    $savedStr = Format-Bytes $totalSaved
    if ($DryRun) {
        Write-Log "[$Server] [DRYRUN] Estimated space that would be freed: $savedStr" "DRYRUN"
    } else {
        Write-Log "[$Server] Cleanup complete. Total freed this run: ~$savedStr" "SUCCESS"
    }
    Write-Log $separator "INFO"
}

#endregion

#region -- Entry Point --------------------------------------------------------

Write-Log "Disk Space Resolver - Log: $LogPath" "INFO"
Write-Log "Targets: $($Servers -join ', ')  |  Threshold: ${ThresholdPercent}%  |  DryRun: $DryRun" "INFO"

foreach ($server in $Servers) {
    try {
        Invoke-ServerCleanup -Server $server
    } catch {
        Write-Log "[$server] Fatal error: $_" "ERROR"
    }
}

Write-Log "All servers processed. Full log saved to: $LogPath" "SUCCESS"

#endregion
'@

# ======================= Setup-GraphAppRegistration.ps1 =======================
$Script:Payloads['Setup-GraphAppRegistration'] = @'
<#
.SYNOPSIS
    ONE-TIME SETUP. Registers an Entra ID app for unattended license-assignment automation,
    creates a self-signed certificate for auth, and grants admin consent for the required
    Microsoft Graph APPLICATION permissions - all programmatically, no portal clicking needed.

.DESCRIPTION
    Run this ONCE, interactively, as a Global Administrator (or Privileged Role Administrator +
    Application Administrator). After this completes, the licensing script authenticates with
    the certificate and never needs interactive consent again.

    What it does:
      1. Creates an App Registration ("M365-License-Automation" by default).
      2. Creates a matching Service Principal (Enterprise App).
      3. Generates a self-signed cert, installs it in CurrentUser\My, and uploads the public
         key to the app registration.
      4. Grants admin consent by directly assigning the required Microsoft Graph app roles
         to the new service principal - this IS what "grant admin consent" does under the hood,
         so no separate portal step is required.
      5. Prints the AppId / TenantId / Thumbprint you'll plug into the licensing script.

.NOTES
    Requires: an account with Global Administrator (or equivalent) rights, since assigning
    application permissions to a service principal is itself a privileged action.
#>

[CmdletBinding()]
param(
    [string]$AppDisplayName = "M365-License-Automation",
    [int]$CertValidityYears = 2
)

$ErrorActionPreference = "Stop"

# ---------------------------------------------------------------------------
# 0. Force TLS 1.2. Older Windows/.NET Framework defaults (TLS 1.0/1.1) will
#    fail silently-ish against PowerShell Gallery with "unable to resolve
#    package source" even though raw TCP connectivity looks fine.
# ---------------------------------------------------------------------------
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

# ---------------------------------------------------------------------------
# 1. Ensure required Graph SDK modules are present, then connect interactively
#    with the (elevated) permissions needed to set this up. This is the ONLY
#    interactive/admin-consent step you'll ever do for this app.
# ---------------------------------------------------------------------------
$requiredModules = @("Microsoft.Graph.Authentication", "Microsoft.Graph.Applications", "Microsoft.Graph.Identity.DirectoryManagement")
foreach ($mod in $requiredModules) {
    if (-not (Get-Module -ListAvailable -Name $mod)) {
        Write-Host "Installing module $mod ..."
        Install-Module $mod -Scope CurrentUser -Force -AllowClobber
    }
    Import-Module $mod -Force
}

Connect-MgGraph -Scopes "Application.ReadWrite.All", "AppRoleAssignment.ReadWrite.All", "Directory.ReadWrite.All"

$tenantId = (Get-MgOrganization).Id
Write-Host "Connected to tenant $tenantId"

# ---------------------------------------------------------------------------
# 1. Create the app registration + service principal
# ---------------------------------------------------------------------------
Write-Host "Creating app registration '$AppDisplayName'..."
$app = New-MgApplication -DisplayName $AppDisplayName -SignInAudience "AzureADMyOrg"
$sp  = New-MgServicePrincipal -AppId $app.AppId

Write-Host "  AppId (Client ID): $($app.AppId)"
Write-Host "  Object ID (App):   $($app.Id)"
Write-Host "  Service Principal: $($sp.Id)"

# ---------------------------------------------------------------------------
# 2. Generate a self-signed certificate and attach the public key to the app
# ---------------------------------------------------------------------------
Write-Host "Generating self-signed certificate (valid $CertValidityYears years)..."
$cert = New-SelfSignedCertificate `
    -Subject "CN=$AppDisplayName" `
    -CertStoreLocation "Cert:\CurrentUser\My" `
    -KeyExportPolicy Exportable `
    -KeySpec Signature `
    -KeyLength 2048 `
    -NotAfter (Get-Date).AddYears($CertValidityYears)

$certBytes = $cert.GetRawCertData()
$certBase64 = [System.Convert]::ToBase64String($certBytes)

Update-MgApplication -ApplicationId $app.Id -KeyCredentials @(
    @{
        Type  = "AsymmetricX509Cert"
        Usage = "Verify"
        Key   = $certBytes
    }
)

Write-Host "  Certificate thumbprint: $($cert.Thumbprint)"
Write-Host "  (Installed in Cert:\CurrentUser\My on this machine - export/import it to wherever the licensing script will run.)"

# ---------------------------------------------------------------------------
# 3. Grant admin consent programmatically: assign the required Graph APPLICATION
#    permissions directly to the service principal. This has the same effect as
#    clicking "Grant admin consent" in the Azure portal.
# ---------------------------------------------------------------------------
$graphAppId = "00000003-0000-0000-c000-000000000000"  # Well-known Microsoft Graph AppId
$graphSp = Get-MgServicePrincipal -Filter "appId eq '$graphAppId'"

$requiredPermissions = @("User.ReadWrite.All", "Group.ReadWrite.All", "Organization.Read.All")

foreach ($permName in $requiredPermissions) {
    $appRole = $graphSp.AppRoles | Where-Object { $_.Value -eq $permName -and $_.AllowedMemberTypes -contains "Application" }
    if (-not $appRole) {
        Write-Warning "Could not find app role '$permName' on Microsoft Graph - skipping."
        continue
    }

    Write-Host "Granting application permission: $permName"
    New-MgServicePrincipalAppRoleAssignment `
        -ServicePrincipalId $sp.Id `
        -PrincipalId $sp.Id `
        -ResourceId $graphSp.Id `
        -AppRoleId $appRole.Id | Out-Null
}

Write-Host "`n================= SETUP COMPLETE ================="
Write-Host "Save these values - the licensing script needs them:"
Write-Host "  TenantId:              $tenantId"
Write-Host "  AppId (Client ID):     $($app.AppId)"
Write-Host "  Certificate Thumbprint: $($cert.Thumbprint)"
Write-Host "===================================================="
Write-Host "`nNo further admin consent is required. The licensing script will authenticate"
Write-Host "unattended using this AppId + certificate from now on."
'@

# ======================= Troubleshoot-Win11Upgrade.ps1 =======================
$Script:Payloads['Troubleshoot-Win11Upgrade'] = @'
<#
.SYNOPSIS
    Single-shot Windows 10 -> 11 upgrade diagnostic/repair tool for running as an
    N-central Automation Manager script task (pick from the dropdown, fill in the
    -Action parameter, execute). Mirrors win11-upgrade-cheatsheet.html - each
    -Action value is one of the cheat sheet's numbered checks, run once, printed,
    done.

.DESCRIPTION
    Sigma Data Systems / N-central Windows 11 upgrade troubleshooting tool.

    N-central's script-task execution runs a script once, captures whatever it
    prints, and returns - there is no live console attached, so nothing here
    can pause and wait for you to type something mid-run. Every check is
    therefore selected up front via -Action, and anything that would normally
    need a confirmation or a passphrase typed at a prompt instead takes that as
    a parameter you fill in on the same execution:
      - State-changing actions (5.2, 5.4, 7.1) require -Confirm
        or they just describe what they would do and exit without doing it.

    Run with -ListActions (no other parameters needed) to print the full menu
    of -Action values and what each one does/checks - use this the first time,
    or any time you forget the numbering:

        powershell.exe -ExecutionPolicy Bypass -File Troubleshoot-Win11Upgrade.ps1 -ListActions

    Categories 1-4 (build number, process/CPU activity, SetupDiag, the upgrade
    log itself) are entirely read-only. Categories 5-7 (disk space, repair tools) change something on the device and need -Confirm.

.PARAMETER Action
    Which check/action to run - matches the cheat sheet's numbering exactly.
    Run with -ListActions to see the full list with descriptions. Default "S"
    (quick status - build number, process/CPU, log freshness, SetupDiag, all
    in one shot) so running with no parameters at all still gives something
    useful.

.PARAMETER ListActions
    Prints the list of valid -Action values and what each does, then exits.
    Nothing else runs when this is set.

.PARAMETER Confirm
    Required for any state-changing action (5.2, 5.4, 7.1). Without
    it, those actions print what they WOULD do and exit without doing it.

.PARAMETER TailLines
    Number of lines to tail for the log-reading actions (2.3, 4.1). Default 40.

.PARAMETER MinFreeDiskGB
    Target free space in GB for the disk-cleanup actions (5.1, 5.2). Default
    32 for the check-only pass (5.1), 45 for the real pass (5.2), matching the
    cheat sheet's own examples - pass this explicitly to use a different target.

.PARAMETER LogPath
    Path to the main upgrade script's log file (used by action 4.1). Default
    matches Win10-to-Win11-Upgrade.ps1's own default.

.PARAMETER DiskCleanupScriptPath
    Path to Disk-Space-Cleanup.ps1 on this device (used by actions 5.1/5.2).

.PARAMETER RestoreWatcherScriptPath
    Path to Restore-Win11Watcher.ps1 on this device (used by action 7.1).

.PARAMETER WizTreePath
    Path to the portable WizTree64.exe disk-space analyzer on this device (used
    by action 5.3). Deployed by the main script as a companion tool, same as
    the other four - see Win10-to-Win11-Upgrade.ps1's own notes on it (free
    edition, personal use only per its EULA).

.PARAMETER WizTreeTopCount
    How many of the largest folders to print for action 5.3. Default 25.

.PARAMETER DellCleanupScriptPath
    Path to Clear-DellSARemediationCache.ps1 (used by action 5.4). The ToolKit
    menu supplies this automatically.

#>

[CmdletBinding()]
param(
    [ValidateSet('S','1.1','2.1','2.2','2.3','2.4','3.1','3.2','3.3','4.1','5.1','5.2','5.3','5.4','7.1')]
    [string]$Action = 'S',
    [switch]$ListActions,
    [switch]$Confirm,
    [int]$TailLines = 40,
    [int]$MinFreeDiskGB,
    [string]$LogPath = "C:\ProgramData\SigmaDataInc\Win11Upgrade\upgrade.log",
    [string]$DiskCleanupScriptPath = "C:\temp\Disk-Space-Cleanup.ps1",
    [string]$RestoreWatcherScriptPath = "C:\ProgramData\SigmaDataInc\Win11Upgrade\Restore-Win11Watcher.ps1",
    [string]$WizTreePath = "C:\ProgramData\SigmaDataInc\Win11Upgrade\WizTree64.exe",
    [int]$WizTreeTopCount = 25,
    [string]$DellCleanupScriptPath = "C:\ProgramData\SigmaDataInc\Win11Upgrade\Clear-DellSARemediationCache.ps1"
)

$SetupDiagPath = "C:\Windows\Logs\SetupDiag\SetupDiagResults.xml"
$SetupActLogPath = 'C:\$WINDOWS.~BT\Sources\Panther\setupact.log'


# ----------------------------------------------------------------------------
# Shared helpers
# ----------------------------------------------------------------------------

function Write-Divider {
    Write-Host ("-" * 78) -ForegroundColor DarkGray
}

function Write-LookFor([string]$Text) {
    Write-Host ("  LOOK FOR: " + $Text) -ForegroundColor DarkCyan
}

function Write-NeedsConfirm([string]$Description) {
    Write-Host ""
    Write-Host ("This action would " + $Description) -ForegroundColor Yellow
    Write-Host "Re-run with -Confirm to actually do it. Nothing has been changed." -ForegroundColor Yellow
}

$script:ActionMenu = @(
    [PSCustomObject]@{ Action = 'S';   Category = 'Quick status'; Changes = $false; Description = 'One-shot: build number, process/CPU activity, setupact.log freshness, SetupDiag presence.' }
    [PSCustomObject]@{ Action = '1.1'; Category = '1) Is it on Windows 11 yet?'; Changes = $false; Description = 'Current build number. 19045 = still Win10. 22000+ = Win11, done.' }
    [PSCustomObject]@{ Action = '2.1'; Category = '2) Is it working, or stuck?'; Changes = $false; Description = 'Are the upgrade processes alive, and using CPU?' }
    [PSCustomObject]@{ Action = '2.2'; Category = '2) Is it working, or stuck?'; Changes = $false; Description = "When did Setup's own log (setupact.log) last get written to?" }
    [PSCustomObject]@{ Action = '2.3'; Category = '2) Is it working, or stuck?'; Changes = $false; Description = 'What is it doing right now - tail setupact.log (-TailLines, default 40).' }
    [PSCustomObject]@{ Action = '2.4'; Category = '2) Is it working, or stuck?'; Changes = $false; Description = 'Are DismHost / MoUsoCoreWorker just routine WU noise?' }
    [PSCustomObject]@{ Action = '3.1'; Category = '3) Did a sub-attempt fail?'; Changes = $false; Description = 'Has SetupDiag logged anything at all? (Test-Path only)' }
    [PSCustomObject]@{ Action = '3.2'; Category = '3) Did a sub-attempt fail?'; Changes = $false; Description = 'Is that a fresh failure, or the same old one? (LastWriteTime)' }
    [PSCustomObject]@{ Action = '3.3'; Category = '3) Did a sub-attempt fail?'; Changes = $false; Description = 'What exactly went wrong - full SetupDiagResults.xml.' }
    [PSCustomObject]@{ Action = '4.1'; Category = '4) What has the script itself seen?'; Changes = $false; Description = 'Tail the upgrade.log (-TailLines, default 40).' }
    [PSCustomObject]@{ Action = '5.1'; Category = '5) Disk space'; Changes = $false; Description = 'Disk-Space-Cleanup.ps1 -CheckOnly (-MinFreeDiskGB, default 32). Zero deletions.' }
    [PSCustomObject]@{ Action = '5.2'; Category = '5) Disk space'; Changes = $true;  Description = 'Disk-Space-Cleanup.ps1 real run -Force (-MinFreeDiskGB, default 45). NEEDS -Confirm.' }
    [PSCustomObject]@{ Action = '5.3'; Category = '5) Disk space'; Changes = $false; Description = 'WizTree silent export (-WizTreeTopCount, default 25) - WHERE the space actually is, not just how much is reclaimable.' }
    [PSCustomObject]@{ Action = '5.4'; Category = '5) Disk space'; Changes = $true;  Description = 'Clear-DellSARemediationCache.ps1 (run from the toolkit) - stops Dell SupportAssist/SARemediation and empties its OS Recovery snapshot cache. Often 100+ GB, invisible to 5.1/5.2. NEEDS -Confirm.' }
    [PSCustomObject]@{ Action = '7.1'; Category = '7) Repair tools'; Changes = $true;  Description = 'Run Restore-Win11Watcher.ps1 - re-attach a fresh watcher. NEEDS -Confirm.' }
)

function Show-ActionList {
    Write-Divider
    Write-Host "AVAILABLE -Action VALUES" -ForegroundColor Cyan
    Write-Divider
    $script:ActionMenu | Group-Object Category | ForEach-Object {
        Write-Host $_.Name -ForegroundColor Cyan
        foreach ($item in $_.Group) {
            $tag = if ($item.Changes) { "[CHANGES DEVICE]" } else { "[read-only]" }
            Write-Host ("   " + $item.Action.PadRight(4) + " " + $tag.PadRight(17) + " " + $item.Description)
        }
        Write-Host ""
    }
    Write-Divider
}

# ----------------------------------------------------------------------------
# Quick status (Action S)
# ----------------------------------------------------------------------------

function Invoke-QuickStatus {
    Write-Divider
    Write-Host "QUICK STATUS" -ForegroundColor Cyan
    Write-Divider

    $build = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'CurrentBuildNumber' -ErrorAction SilentlyContinue).CurrentBuildNumber
    Write-Host ("Build number: " + $build)

    if ($build -and ([int]$build -ge 22000)) {
        Write-Host "  -> Windows 11 - upgrade is complete." -ForegroundColor Green
        Write-Divider
        return
    }

    Write-Host "  -> Still Windows 10 (or build unknown) - checking activity..." -ForegroundColor Yellow
    Write-Host ""

    $procs = Get-Process -Name SetupHost, Windows10UpgraderApp, Windows11InstallationAssistant -ErrorAction SilentlyContinue
    if ($procs) {
        Write-Host "Upgrade processes running:"
        $procs | Select-Object Name, Id, CPU, StartTime | Format-Table -AutoSize | Out-String | Write-Host
        Write-LookFor "Re-run this action in a minute or two - climbing CPU seconds = genuinely working."
    } else {
        Write-Host "No upgrade processes currently running." -ForegroundColor Yellow
    }

    Write-Host ""
    $logFile = Get-Item -Path $SetupActLogPath -ErrorAction SilentlyContinue
    if ($logFile) {
        $minutesAgo = [math]::Round(((Get-Date) - $logFile.LastWriteTime).TotalMinutes, 1)
        Write-Host ("setupact.log last written: " + $logFile.LastWriteTime + "  (" + $minutesAgo + " minute(s) ago)")
        if ($minutesAgo -le 3) {
            Write-Host "  -> Recently written - alive." -ForegroundColor Green
        } elseif ((-not $procs) -and ($minutesAgo -ge 10)) {
            Write-Host "  -> No CPU movement AND the log has been quiet for 10+ minutes - treat this as a real stall." -ForegroundColor Red
        } else {
            Write-Host "  -> In between - not necessarily stalled, re-check in a few minutes." -ForegroundColor Yellow
        }
    } else {
        Write-Host "setupact.log not found (nothing currently staged, or it was already cleaned up)." -ForegroundColor DarkGray
    }

    Write-Host ""
    if (Test-Path $SetupDiagPath) {
        $diagItem = Get-Item -Path $SetupDiagPath -ErrorAction SilentlyContinue
        Write-Host ("SetupDiagResults.xml present - last written " + $diagItem.LastWriteTime) -ForegroundColor Yellow
        Write-LookFor "Existing does not mean dead - Setup can auto-restart on its own. See actions 3.1-3.3 for the full picture."
    } else {
        Write-Host "No SetupDiagResults.xml - no sub-attempt has failed (yet)." -ForegroundColor DarkGray
    }

    Write-Divider
}

# ----------------------------------------------------------------------------
# Dispatch
# ----------------------------------------------------------------------------

if ($ListActions) {
    Show-ActionList
    exit 0
}

switch ($Action) {

    'S' { Invoke-QuickStatus }

    '1.1' {
        $build = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name 'CurrentBuildNumber' -ErrorAction SilentlyContinue).CurrentBuildNumber
        Write-Host ("Current build number: " + $build)
        Write-LookFor "19045 = still Windows 10. 22000+ = Windows 11, done."
    }

    '2.1' {
        $procs = Get-Process -Name SetupHost, Windows10UpgraderApp, Windows11InstallationAssistant -ErrorAction SilentlyContinue
        if ($procs) { $procs | Select-Object Name, Id, CPU, StartTime | Format-Table -AutoSize | Out-String | Write-Host }
        else { Write-Host "(no matching processes running)" -ForegroundColor Yellow }
        Write-LookFor "CPU seconds climbing between two runs of this action = genuinely working. Empty result = nothing running right now (not necessarily bad - check 3.1-3.3)."
    }

    '2.2' {
        $logFile = Get-Item -Path $SetupActLogPath -ErrorAction SilentlyContinue
        if ($logFile) {
            $minutesAgo = ((Get-Date) - $logFile.LastWriteTime).TotalMinutes
            Write-Host ("LastWriteTime: " + $logFile.LastWriteTime)
            Write-Host ("MinutesSinceUpdate: " + [math]::Round($minutesAgo, 2))
        } else {
            Write-Host "(setupact.log not found)" -ForegroundColor Yellow
        }
        Write-LookFor "Under ~2-3 minutes = alive. 10+ minutes with no CPU movement either (see 2.1) = treat as a real stall."
    }

    '2.3' {
        if (Test-Path $SetupActLogPath) {
            Get-Content -Path $SetupActLogPath -Tail $TailLines | Write-Host
        } else {
            Write-Host "(setupact.log not found)" -ForegroundColor Yellow
        }
        Write-LookFor "Verbose but informative - package expansion, delta application (DPX phases), driver staging. All-Info lines with no errors is normal even during a slow phase."
    }

    '2.4' {
        $procs = Get-Process -Name DismHost, MoUsoCoreWorker -ErrorAction SilentlyContinue
        if ($procs) { $procs | Select-Object Name, Id, CPU, StartTime | Format-Table -AutoSize | Out-String | Write-Host }
        else { Write-Host "(no matching processes running)" -ForegroundColor Yellow }
        Write-LookFor "Long uptime with near-zero CPU (fractions of a second) = idle, unrelated background Windows Update chatter, not upgrade work."
    }

    '3.1' {
        Write-Host (Test-Path $SetupDiagPath)
        Write-LookFor "True alone isn't alarming - could be stale. Check 3.2 next."
    }

    '3.2' {
        $diagItem = Get-Item -Path $SetupDiagPath -ErrorAction SilentlyContinue
        if ($diagItem) { Write-Host ("LastWriteTime: " + $diagItem.LastWriteTime) }
        else { Write-Host "(SetupDiagResults.xml not found)" -ForegroundColor Yellow }
        Write-LookFor "Compare against the last time you checked. Unchanged timestamp = still the old one, nothing new happened."
    }

    '3.3' {
        if (Test-Path $SetupDiagPath) {
            Get-Content -Path $SetupDiagPath -Raw | Write-Host
        } else {
            Write-Host "(SetupDiagResults.xml not found)" -ForegroundColor Yellow
        }
        Write-LookFor 'ProfileName, FailureData, Remediation - e.g. DiskSpaceBlockInDownLevel names the exact MB needed. "No Match Found" means check 2.1/2.2 next to see if it already recovered on its own.'
    }

    '4.1' {
        if (Test-Path $LogPath) { Get-Content -Path $LogPath -Tail $TailLines | Write-Host }
        else { Write-Host "(log not found at $LogPath)" -ForegroundColor Yellow }
        Write-LookFor "Look for [Watcher], [S1-Reenable], and [ERROR]/[WARN] lines."
    }

    '5.1' {
        if (-not (Test-Path $DiskCleanupScriptPath)) {
            Write-Host ("Disk-Space-Cleanup.ps1 not found at " + $DiskCleanupScriptPath) -ForegroundColor Red
            break
        }
        $target = if ($MinFreeDiskGB -gt 0) { $MinFreeDiskGB } else { 32 }
        & powershell.exe -ExecutionPolicy Bypass -File $DiskCleanupScriptPath -CheckOnly -MinFreeDiskGB $target
    }

    '5.2' {
        if (-not (Test-Path $DiskCleanupScriptPath)) {
            Write-Host ("Disk-Space-Cleanup.ps1 not found at " + $DiskCleanupScriptPath) -ForegroundColor Red
            break
        }
        $target = if ($MinFreeDiskGB -gt 0) { $MinFreeDiskGB } else { 45 }
        if (-not $Confirm) {
            Write-NeedsConfirm "run a REAL cleanup pass targeting ${target}GB free (deletes temp/cache/log files, forces the standard tier even if the target is already met via -Force)."
            break
        }
        & powershell.exe -ExecutionPolicy Bypass -File $DiskCleanupScriptPath -MinFreeDiskGB $target -Force
    }

    '5.3' {
        if (-not (Test-Path $WizTreePath)) {
            Write-Host ("WizTree64.exe not found at " + $WizTreePath + " - the main upgrade script deploys it as a companion tool; re-run it, or check -WizTreePath.") -ForegroundColor Red
            break
        }
        $exportFile = Join-Path $env:TEMP ("wiztree_export_{0}.csv" -f ([guid]::NewGuid()))
        Write-Host "Running WizTree silent export against C:\ - can take a minute or two on a large/full drive..."
        $p = $null
        try {
            $p = Start-Process -FilePath $WizTreePath -ArgumentList @("C:\", "/export=`"$exportFile`"", "/exportfolders=1", "/exportfiles=0", "/admin=1") -Wait -PassThru -WindowStyle Hidden
        } catch {
            Write-Host ("WizTree64.exe call failed: " + $_.Exception.Message) -ForegroundColor Red
            break
        }
        if (-not (Test-Path $exportFile)) {
            Write-Host ("WizTree did not produce an export file (exit code " + $(if ($p) { $p.ExitCode } else { "n/a" }) + ") - it may need an interactive desktop session under this account. Try running it directly (double-click) during Take Control instead.") -ForegroundColor Red
            break
        }
        $rows = Import-Csv -Path $exportFile -ErrorAction SilentlyContinue
        if (-not $rows) {
            Write-Host "Export file was empty or unreadable." -ForegroundColor Red
            Remove-Item -Path $exportFile -Force -ErrorAction SilentlyContinue
            break
        }
        # Column names aren't hardcoded - WizTree's export schema isn't guaranteed
        # stable across versions, so the size/path columns are detected by pattern
        # rather than assumed.
        $propNames = $rows[0].PSObject.Properties.Name
        $sizeCol = $propNames | Where-Object { $_ -match '(?i)^size$' } | Select-Object -First 1
        if (-not $sizeCol) { $sizeCol = $propNames | Where-Object { $_ -match '(?i)size' } | Select-Object -First 1 }
        $nameCol = $propNames | Where-Object { $_ -match '(?i)(file name|filename|^name$|path)' } | Select-Object -First 1
        if (-not $sizeCol -or -not $nameCol) {
            Write-Host ("Could not identify size/name columns in the export. Columns found: " + ($propNames -join ', ')) -ForegroundColor Red
            Write-Host "Raw export file left at $exportFile for manual review."
            break
        }
        $top = $rows | Sort-Object { [int64]$_.$sizeCol } -Descending | Select-Object -First $WizTreeTopCount
        Write-Host ""
        Write-Host ("Top " + $WizTreeTopCount + " largest items on C:\ (WizTree MFT-based scan):")
        $top | Select-Object @{n='SizeGB';e={[math]::Round([int64]$_.$sizeCol / 1GB, 2)}}, @{n='Path';e={$_.$nameCol}} | Format-Table -AutoSize | Out-String | Write-Host
        Remove-Item -Path $exportFile -Force -ErrorAction SilentlyContinue
        Write-LookFor "Run 5.1 first for the itemized reclaimable-space report; this shows WHERE the space actually is instead of what's safely deletable."
    }

    '5.4' {
        if (-not $Confirm) {
            Write-NeedsConfirm "stop Dell SupportAssist/SARemediation services and permanently clear the Dell OS Recovery snapshot cache at C:\ProgramData\Dell\SARemediation\SystemRepair\Snapshots\ (often 100+ GB, invisible to normal temp-file cleanup - see 5.1/5.2)."
            break
        }
        if (-not (Test-Path $DellCleanupScriptPath)) {
            Write-Host ("Clear-DellSARemediationCache.ps1 not found at " + $DellCleanupScriptPath) -ForegroundColor Red
            break
        }
        # -Confirm:$false suppresses the nested script's own ShouldProcess prompts -
        # this action already gated the decision above, and N-central has no
        # console attached to answer an interactive confirm prompt.
        & powershell.exe -ExecutionPolicy Bypass -File $DellCleanupScriptPath -Confirm:$false
    }



    '7.1' {
        if (-not (Test-Path $RestoreWatcherScriptPath)) {
            Write-Host ("Restore-Win11Watcher.ps1 not found at " + $RestoreWatcherScriptPath) -ForegroundColor Red
            break
        }
        if (-not $Confirm) {
            Write-NeedsConfirm "re-register the watcher task from Restore-Win11Watcher.ps1."
            break
        }
        & powershell.exe -ExecutionPolicy Bypass -File $RestoreWatcherScriptPath
    }

}
'@

# ======================= repairwu2016.ps1 =======================
$Script:Payloads['repairwu2016'] = @'
<#
.SYNOPSIS
    Repairs Windows Update on Windows Server 2016 when updates fail with
    error 0x8024002e (or similar update-client/cache related failures).

.DESCRIPTION
    - Checks/fixes the NETLOGON service (a confirmed root cause of 0x8024002e
      on Server 2016 when Group Policy processing gets stuck).
    - Forces a Group Policy refresh.
    - Stops the Windows Update-related services.
    - Backs up (renames, does not delete) SoftwareDistribution and catroot2.
    - Resets service security descriptors for BITS/wuauserv.
    - Re-registers the DLLs the Windows Update client depends on.
    - Resets Winsock/WinHTTP proxy settings.
    - Restarts services and runs DISM + SFC integrity checks.

    Run this from an elevated PowerShell prompt (Run as Administrator).
    A reboot afterward is strongly recommended before checking for updates again.

.NOTES
    Nothing here is destructive — SoftwareDistribution/catroot2 are renamed
    with a timestamp, not deleted, so nothing is lost if this doesn't help.
#>

#Requires -RunAsAdministrator
param(
    [string]$OutputPath = "C:\temp"
)
if (-not (Test-Path $OutputPath)) { New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null }

$logFile = "$OutputPath\WindowsUpdateRepair_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"
Start-Transcript -Path $logFile -Append

Write-Host "=== Windows Update Repair Script ===" -ForegroundColor Cyan
Write-Host "Log file: $logFile`n"

# 1. Check and fix NETLOGON service (confirmed cause of 0x8024002e on Server 2016
#    when it's set to Manual and Group Policy can't process, breaking WU downstream)
Write-Host "[1/8] Checking NETLOGON service..." -ForegroundColor Yellow
$netlogon = Get-Service -Name Netlogon -ErrorAction SilentlyContinue
if ($netlogon) {
    if ($netlogon.StartType -ne 'Automatic') {
        Write-Host "  NETLOGON start type is '$($netlogon.StartType)' - setting to Automatic."
        Set-Service -Name Netlogon -StartupType Automatic
    } else {
        Write-Host "  NETLOGON already set to Automatic."
    }
    if ($netlogon.Status -ne 'Running') {
        Write-Host "  Starting NETLOGON service..."
        Start-Service -Name Netlogon -ErrorAction SilentlyContinue
    } else {
        Write-Host "  NETLOGON is already running."
    }
} else {
    Write-Host "  NETLOGON service not found (server may not be domain-joined - skipping)." -ForegroundColor DarkGray
}

# 2. Force a Group Policy update in case GP processing was stuck
Write-Host "`n[2/8] Forcing Group Policy update..." -ForegroundColor Yellow
gpupdate /force | Out-Null
Write-Host "  Done."

# 3. Stop Windows Update-related services
Write-Host "`n[3/8] Stopping Windows Update services..." -ForegroundColor Yellow
$services = @('wuauserv', 'cryptSvc', 'bits', 'msiserver', 'TrustedInstaller', 'appidsvc')
foreach ($svc in $services) {
    try {
        Stop-Service -Name $svc -Force -ErrorAction Stop
        Write-Host "  Stopped $svc"
    } catch {
        Write-Host "  Could not stop $svc (may already be stopped or not present)" -ForegroundColor DarkGray
    }
}

# 4. Rename (not delete) SoftwareDistribution and catroot2
Write-Host "`n[4/8] Backing up SoftwareDistribution and catroot2 folders..." -ForegroundColor Yellow
$timestamp = Get-Date -Format 'yyyyMMddHHmmss'
$paths = @(
    @{ Path = "$env:windir\SoftwareDistribution"; NewName = "SoftwareDistribution.bak_$timestamp" },
    @{ Path = "$env:windir\System32\catroot2";     NewName = "catroot2.bak_$timestamp" }
)
foreach ($p in $paths) {
    if (Test-Path $p.Path) {
        try {
            Rename-Item -Path $p.Path -NewName $p.NewName -Force -ErrorAction Stop
            Write-Host "  Renamed $($p.Path) -> $($p.NewName)"
        } catch {
            Write-Host "  Could not rename $($p.Path): $_" -ForegroundColor DarkGray
        }
    } else {
        Write-Host "  $($p.Path) not found, skipping." -ForegroundColor DarkGray
    }
}

# 5. Reset service security descriptors for BITS and wuauserv (common cause of silent WU failures)
Write-Host "`n[5/8] Resetting service security descriptors..." -ForegroundColor Yellow
sc.exe sdset bits "D:(A;;CCLCSWRPWPDTLOCRRC;;;SY)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCLCSWLOCRRC;;;AU)(A;;CCLCSWRPWPDTLOCRRC;;;PU)" | Out-Null
sc.exe sdset wuauserv "D:(A;;CCLCSWRPWPDTLOCRRC;;;SY)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCLCSWLOCRRC;;;AU)(A;;CCLCSWRPWPDTLOCRRC;;;PU)" | Out-Null
Write-Host "  Done."

# 6. Re-register the DLLs the Windows Update client depends on
Write-Host "`n[6/8] Re-registering Windows Update DLLs..." -ForegroundColor Yellow
$dlls = @(
    'atl.dll', 'urlmon.dll', 'mshtml.dll', 'shdocvw.dll', 'browseui.dll', 'jscript.dll',
    'vbscript.dll', 'scrrun.dll', 'msxml.dll', 'msxml3.dll', 'msxml6.dll', 'actxprxy.dll',
    'softpub.dll', 'wintrust.dll', 'dssenh.dll', 'rsaenh.dll', 'gpkcsp.dll', 'sccbase.dll',
    'slbcsp.dll', 'cryptdlg.dll', 'oleaut32.dll', 'ole32.dll', 'shell32.dll', 'initpki.dll',
    'wuapi.dll', 'wuaueng.dll', 'wups.dll', 'wups2.dll', 'wuwebv.dll', 'wucltui.dll', 'wudriver.dll'
)
foreach ($dll in $dlls) {
    regsvr32.exe /s $dll
}
Write-Host "  Done."

# 7. Reset Winsock / WinHTTP proxy (network stack issues can silently break BITS downloads)
Write-Host "`n[7/8] Resetting network stack (Winsock/WinHTTP proxy)..." -ForegroundColor Yellow
netsh winsock reset | Out-Null
netsh winhttp reset proxy | Out-Null
Write-Host "  Done. (Winsock reset fully applies after reboot.)"

# 8. Restart services
Write-Host "`n[8/8] Restarting services..." -ForegroundColor Yellow
foreach ($svc in $services) {
    try {
        Start-Service -Name $svc -ErrorAction Stop
        Write-Host "  Started $svc"
    } catch {
        Write-Host "  Could not start $svc" -ForegroundColor DarkGray
    }
}

Write-Host "`n=== Running DISM and SFC integrity checks (this can take several minutes) ===" -ForegroundColor Cyan
DISM /Online /Cleanup-Image /RestoreHealth
sfc /scannow

Write-Host "`n=== Repair steps complete ===" -ForegroundColor Cyan
Write-Host "A REBOOT IS STRONGLY RECOMMENDED before checking for updates again." -ForegroundColor Red
Write-Host "After reboot, open Settings > Update & Security > Windows Update and click 'Check for updates,'"
Write-Host "or run: (New-Object -ComObject Microsoft.Update.AutoUpdate).DetectNow()"
Write-Host "`nLog saved to: $logFile"

Stop-Transcript
'@

