# ======================= data/license-sku-map.json =======================
$Script:Payloads['data/license-sku-map.json'] = @'
{
  "_comment": "Maps the friendly 'minLicense' values used in checks to the actual Microsoft Graph skuPartNumber strings that satisfy them. A tenant satisfies a requirement if it has ANY ONE of the SKUs listed (or a bundle SKU containing the equivalent service plan). NOTE: the script's Test-LicenseSatisfied function normalizes SKU strings before comparing (strips whitespace/underscores/casing), so it tolerates cosmetic spacing differences in how a tenant's SKU string is formatted. HOWEVER, normalization cannot bridge genuinely different strings for the same product -- e.g. the classic abbreviation 'SPB' and the newer literal product-name string 'Microsoft_365_Business_Premium_(no Teams)' both refer to Microsoft 365 Business Premium, but must BOTH be listed explicitly wherever that product's entitlements apply (see the 'M365 Defender' and 'Entra ID P1' entries below for the pattern). Microsoft introduced these '(no Teams)' SKU strings in 2024 for Business Basic/Standard/Premium and Enterprise E1/E3/E5; if a tenant shows an unfamiliar SKU and a check incorrectly reports 'Not Licensed', check whether it's a '(no Teams)' or other renamed variant of a SKU already in this file, and add it as an explicit synonym. This list covers the most common SKUs; Microsoft adds/renames SKUs periodically, so treat this as a starting point to maintain over time.",

  "M365 Basic": [
    "EXCHANGESTANDARD", "EXCHANGEENTERPRISE",
    "O365_BUSINESS_ESSENTIALS", "O365_BUSINESS_PREMIUM", "O365_BUSINESS",
    "SPB", "SPE_E3", "SPE_E5", "SPE_F1",
    "ENTERPRISEPACK", "ENTERPRISEPREMIUM", "ENTERPRISEPACKLRG",
    "STANDARDPACK", "DESKLESSPACK", "M365_F1", "M365_F2",
    "SMB_BUSINESS_ESSENTIALS", "SMB_BUSINESS_PREMIUM",
    "Microsoft_365_Business_Premium_(no Teams)",
    "Microsoft_365_Business_Basic_(no Teams)",
    "Microsoft_365_Business_Standard_(no Teams)"
  ],

  "M365 Defender": [
    "ATP_ENTERPRISE",
    "THREAT_INTELLIGENCE",
    "ENTERPRISEPREMIUM",
    "SPE_E5",
    "SPE_E3_USGOV_DOD",
    "M365_E5_SUITE_COMPONENTS",
    "IDENTITY_THREAT_PROTECTION",
    "DEFENDER_ENDPOINT_P1",
    "ATP_ENTERPRISE_FACULTY",
    "SPB",
    "Microsoft_365_Business_Premium_(no Teams)"
  ],

  "Entra ID P1": [
    "AAD_PREMIUM",
    "EMS",
    "ENTERPRISEPACK",
    "ENTERPRISEPREMIUM",
    "SPE_E3",
    "SPE_E5",
    "M365_F1",
    "AAD_PREMIUM_P1_GOV",
    "SPB",
    "Microsoft_365_Business_Premium_(no Teams)"
  ],

  "Entra ID P2": [
    "AAD_PREMIUM_P2",
    "EMSPREMIUM",
    "ENTERPRISEPREMIUM",
    "SPE_E5",
    "IDENTITY_THREAT_PROTECTION"
  ],

  "Entra Workload ID": [
    "WORKLOAD_IDENTITY_PREMIUM",
    "ENTERPRISEPREMIUM",
    "SPE_E5"
  ]
}
'@
#endregion

#region -------------------------------------------------------------- Main

if ($SelfTest) {
    if (-not (Test-IsAdmin)) { Write-Host 'WARNING: not elevated - many checks will report access errors.' -ForegroundColor Yellow }
    Ensure-Dir $Script:OutRoot | Out-Null; Ensure-Dir $Script:WorkDir | Out-Null
    try { Invoke-SelfTest } finally { Remove-Item -LiteralPath $Script:WorkDir -Recurse -Force -ErrorAction SilentlyContinue }
    return
}

if (-not (Test-IsAdmin)) {
    Write-Host 'This toolkit is not running elevated - most diagnostics need Administrator rights.' -ForegroundColor Yellow
    if ($PSCommandPath -and (Read-YesNo 'Relaunch as Administrator now?' $true)) {
        Start-Process -FilePath $Script:PSExe -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$PSCommandPath`"", '-OutputRoot', "`"$Script:OutRoot`"")
        return
    }
}

Ensure-Dir $Script:OutRoot | Out-Null
Ensure-Dir $Script:WorkDir | Out-Null
try {
    while ($true) {
        Show-Menu
        $choice = (Read-Host "`nSelect an option").Trim().ToUpper()
        switch ($choice) {
            'Q' { return }
            'O' { Set-OutputRoot; Pause-Menu; continue }
            'R' { Start-Process explorer.exe $Script:OutRoot; continue }
            'X' { Export-AllTools; Pause-Menu; continue }
            'B' { $Script:View = 'HOME'; continue }
            'ALL' { $Script:View = 'ALL'; continue }
            'L2' { $Script:ToolLinks.GetEnumerator() | ForEach-Object { Write-Host ("  {0,-42} {1}" -f $_.Key, $_.Value) }; Pause-Menu; continue }
            'T' {
                Write-Host '  Self-test runs every READ-ONLY option with default answers (nothing is changed).'
                $Script:IncludeSlowRun = Read-YesNo 'Include slow checks (event export, largest folders, inventory, ~10-30 min)?' $false
                $Script:IncludeNetRun  = Read-YesNo 'Include checks that download Sysinternals/NirSoft/SetupDiag?' $false
                $IncludeSlow = $Script:IncludeSlowRun; $IncludeDownloads = $Script:IncludeNetRun
                $Script:Auto = $true; try { Invoke-SelfTest } finally { $Script:Auto = $false }
                Pause-Menu; continue
            }
            default {
                $sec = $Script:Menu | Where-Object { $_.Section -and $_.Letter -eq $choice } | Select-Object -First 1
                if ($sec) { $Script:View = $sec.Letter; continue }
                $item = $Script:Menu | Where-Object { $_.Key -eq $choice } | Select-Object -First 1
                if (-not $item) { Write-Host '  Not a valid option.' -ForegroundColor Red; Start-Sleep -Seconds 1; continue }
                try { & $item.Action }
                catch { Write-Host "  ERROR: $($_.Exception.Message)" -ForegroundColor Red }
                Write-Host "`n  Reports/logs: $Script:OutRoot" -ForegroundColor DarkGray
                Pause-Menu
            }
        }
    }
} finally {
    Remove-Item -LiteralPath $Script:WorkDir -Recurse -Force -ErrorAction SilentlyContinue
}

#endregion
